  Voice_100335_AwakerVoiceContent = {
    Text = "রক্ষক, আমি কবে আবার মিথাগ কবরস্থানে যেতে পারব? সেখানে শুয়ে থাকা মহান আত্মারা নিশ্চয়ই আমাকে মহৎ সব ভাবনা দেবে! চিন্তা কোরো না, আমি প্রতিশ্রুতি দিচ্ছি, আর কখনও কাছ থেকে দেখার জন্য ওই লাশগুলো খুঁড়ে তুলব না..."
