  Voice_100339_AwakerVoiceContent = {
    Text = "আহ, অপূর্ব এক কালো রং! আগে আমি ছবির জন্য অনেক ডিজলিউশন তরল ব্যবহার করতাম, কিন্তু সেই সব কাজই হারিয়ে গেছে। প্রাচীন মহাবিশ্বের রং, আমার ছবি গ্রাস করেছে, চিরতরে পৃথিবীর স্মৃতি থেকে মুছে গেছে... এটাই কি আরও ভালো নয়?!"
