  },
  Voice_100371_AwakerVoiceContent = {
    Text = "ওহ! ওই ধারালো চোয়ালটা দেখো! ওই দীপ্তিময় চোখদুটি! আর একেবারে আদর্শ অনুপাতের দেহ... তার উপর তোমার আত্মার বিশাল, নক্ষত্রখচিত আকাশটা ভেসে উঠছে... আমি চিত্রকর পিকম্যান! তোমাকে আমার মডেল হিসেবে আঁকার সর্বোচ্চ সম্মানটা কি আমি পেতে পারি?"
  },
  Voice_100371_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_100372_AwakerVoiceContent = {
    Text = "আমার শিল্প উন্মাদনা আর অস্থিরতা নিয়ে, কিন্তু ওই হামেল্নের সুরগুলো টানটান, যেন কবরস্থানের সমাধিফলক। তবু কোনো এক অদ্ভুত কারণে, সেই শৃঙ্খলাবদ্ধ নোটগুলোর ভেতরেই আমি সবসময় মহাবিশ্বের সবচেয়ে ভয়াবহ বিশৃঙ্খলা দেখি..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "চ্যাট: হামেল্ন সম্পর্কে"
  },
  Voice_100372_UnlockDesc = {
    Text = "জাগরণকারী \"সাঙ্গা\" প্রাপ্তির পর উন্মোচিত হবে।"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "দেখুন, রক্ষক! ক্যানভাসে বন্দী সেই শাশ্বত, উন্মাদ দৃশ্য! কত সুন্দর, কত ধ্বংসাত্মক! এই উন্মাদনা আর পেইন থেকেই যে জন্ম নেয়, সেটাই তো শিল্প..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_100373_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "আহ! আ-আমি দুঃখিত, রক্ষক... আমি আপনার ভেতরে কিছু দেখি... অতলের চেয়েও ভয়ংকর, আর তবু আরও মোহনীয়..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_100374_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "আমি বুঝি না। কেউ কেন ঘুল হওয়ার সুযোগ ফিরিয়ে দেবে?! এই রক্তাক্ত, উন্মাদ সৌন্দর্য তো কোনো বড় বাড়ির বিরক্তিকর মানুষের চেয়ে অনেক বেশি মজার, তাই না?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_100376_AwakerVoiceContent = {Text = "হা!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "শাস্তি！"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "শাস্তি！"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "স্বীকার করি, ওর চুরি করার একধরনের কাঁচা দক্ষতা আছে, কিন্তু আমার মতো ভদ্রমহিলার এমন নীচ কৌশলের কোনো প্রয়োজন নেই। আমি যদি কোনো কিছুর কামনা করি, তবে আমি শুধু ওদেরকে সেটি 「স্বেচ্ছায়」 এগিয়ে দিতে বাধ্য করি।"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_117791_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "হাহাহা! সব, সবই আমার! মিথাগের সব ক্যান্ডি আমারই! কীসের জন্য প্রতীক্ষা করছ? আমার পিছু নাও, মহান ক্যান্ডি ডাইনির! আমরা এখনই লন্ডিনিয়ামের প্রতিটি ক্যান্ডির দোকান জয় করতে যাচ্ছি!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_117792_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "ক্যান্ডি নেই? তাহলে এই ডাইনীকে বাধ্য হয়ে সত্যিই গম্ভীর হতে হবে!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "ওরা ভেতরে পুর ভরে কীভাবে? কোথাও কোনো সেলাই বা সূচের ছিদ্রই তো খুঁজে পাই না! ইচ্ছে করে এই ক্যান্ডি উদ্ভাবকেরা মিথাগ-এর কর্মী হোক, আর প্রতিদিন আমার জন্য নতুন এক মিষ্টান্ন আবিষ্কার করুক!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "ডাইনির সঙ্গে ঝামেলা করার দুঃসাহস কোরো না!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "আগে আমার মনে হতো ক্যান্ডি কেকের তুলনায় খুবই সাদামাটা, যথেষ্ট মার্জিত নয়। কিন্তু এখন মনে হচ্ছে এই রঙিন প্লাস্টিকের মোড়কে মোড়া ছোট্ট জিনিসগুলোকে আমি হেলাফেলা করেছি। এদের সংরক্ষণকাল কত দীর্ঘ! ইচ্ছে মতো মজুত করতে পারি, পুরো ঘরটাই ক্যান্ডিতে ভরে ফেলতে পারি!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "তুমি নতুন ক্যান্ডি পেয়েছ? দেখি তো... ছিঃ, এই রিং পপটা কত হাস্যকর দেখাচ্ছে! ডিমের সমান সাইজের এক \"হীরার\" আংটি? দাঁড়াও! আমাকে আংটি উপহার বলতে তুমি ঠিক কী বোঝাতে চাইছ? সঙ্গে সঙ্গে সব ব্যাখ্যা করো!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_117797_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "শুনেছি ডাইনিদের থাকে এক রহস্যময় কালো বিড়াল। কিন্তু ওই জঘন্য ক্যাম্পাসের ভবঘুরে বিড়ালটা আমার মতো মার্জিত ভদ্রমহিলার জন্য ভীষণ লজ্জাজনক। ঠিক হলো তাহলে। এই {Male=catboy,Female=catgirl} হেডব্যান্ডটা পরে নাও। তোমাকেই আমি বানাব আমার ছোট্ট কালো বিড়াল।"
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_117798_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "মৃত্যু প্রতিরোধ অর্থহীন।"
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "ব্লীইইহ্!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "সত্যিই কি কোথাও ডাইনি আছে? যদি তারা জনমানবহীন অরণ্যে থাকে, তবে তাদের রান্না, ঘর পরিষ্কার আর মিষ্টান্ন বানানোর দায়িত্ব কে নেয়? যদি বিকেলের চা-আড্ডা আয়োজনই করতে না পারো, তবে সেই জীবনের মানেটাই বা কী? ভাবলেই আমার ঘৃণা লাগে।"
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_117801_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "ডাইনিটি চলে আসছে!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "তোমার কাছে এখনো চকলেট আছে? চমৎকার, সবই আমাকে দাও। কী? তোমার জিনিসই তো আমার জিনিস; এটাই তো স্বাভাবিক, তাই না?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_117803_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "আমি কোন মিষ্টিটা সবচেয়ে বেশি পছন্দ করি? একটু ভাবি… হ্যাজেলনাট ব্রিটল-এর গন্ধ দারুণ, ক্যারামেল চকলেট ভীষণ সুস্বাদু, ওই স্ট্রবেরি আর আঙুর-স্বাদের গামিগুলোর টেক্সচারও বেশ মজার, আর একটা মল্ট সুগার আছে যেটা অনেক লম্বা করে টানা যায়, আর যার রং মধুর মতো অপূর্ব… না, আমি কোনোভাবেই বেছে নেব না। প্রতিটি মিষ্টিরই নিজস্ব এক অদ্বিতীয় আকর্ষণ আছে! যাই হোক, আমার কাছে কুমড়ো-ঝুড়ি তো অনেক আছে, সবই আমি নিয়ে নেব!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_117804_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "আমার বর্তমান জীবনের লক্ষ্য হলো পৃথিবীর প্রতিটি ক্যান্ডি খেয়ে ফেলা। ভাবলেই যে অগণিত ক্যান্ডি কোথাও না কোথাও আমার প্রতীক্ষা করছে... সেটাই আমার বিছানা ছেড়ে ওঠার একমাত্র কারণ। কেক, বলছ? কেক হলো আমার জীবনের অন্য লক্ষ্য।"
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_117805_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "তার চেহারা দেখে ভুল কোরো না! তুলু দেখতে বাচ্চার মতো, কিন্তু সে প্রায় কবরেরই বাসিন্দা। জীবিত মানুষের আনন্দের কোনো কিছুরই তার প্রয়োজন নেই, ক্যান্ডি তো দূরের কথা। তাই, তার জন্য বরাদ্দ সব ক্যান্ডি... তোমার উচিত সেগুলো সব আমার হাতে তুলে দেওয়া। একমাত্র আমিই সেগুলোর প্রকৃত মূল্যায়ন করতে পারব।"
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_117806_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "আমি যদি ডাইনি হতাম, তবে আমার প্রাসাদ অবশ্যই বিলাসিতার চূড়ান্ত উদাহরণ হতো। আমি দশজন মহারথী রাঁধুনি ভাড়া করতাম, যারা প্রতিদিন আমার জন্য নতুন কেক আর ক্যান্ডি বানাত... তুমি বলছ, তাতে আমি ডাইনি নয়, রাজকুমারী হয়ে যেতাম? তাতে কী? আমি হব রাজকুমারী ডাইনি!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_117807_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "এই শোনো! তাড়াতাড়ি গিয়ে আমার জন্য নানা ধরনের টুথপেস্ট নিয়ে এসো! না, আমি এত ক্যান্ডি খাইনি! আর আমার কোনো ক্যাভিটি নেই! শুধু... ঘুমোতে গেলেই দাঁতটা একটু ব্যথা করে..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "চ্যাট: মিষ্টি নিয়ে"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "মিথাগের রেস্তোরাঁর নিয়মকানুন প্রায়ই বিরক্তিকর, কিন্তু তাদের পেস্ট্রি বানানোর দক্ষতা... হুম, কেমন যেন অল্পের উপর দিয়ে পাস করে, বলা যায়।"
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "এই পৃথিবী ভরা অন্ধকার, ঘৃণ্য জিনিসে। এর শেষ নিয়ে দুশ্চিন্তা করার বদলে, সেই সময়টা বরং শেষ হওয়ার আগেই আরও কিছু ক্যান্ডি খেয়ে নেওয়াই ভালো।"
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_117811_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "আর নেই নরম ল্যাম্বস্কিনের কার্পেট, কালো মুক্তোর গলার হার, কিংবা সুদূর প্রাচ্যের সিল্কের পায়জামা… তবু প্রতিদিন ঘুম ভাঙে যদি এমন এক ঘরে, যেখানে চারদিকে শুধু মিষ্টি, আর ঝুড়িগুলো উপচে পড়ছে… হয়তো এটাই প্রকৃত সুখের রূপ… এই যে, মুখের ওই বোকা হাসিটা মুছে ফেলো! যদি চিরকাল আমাকে সেবা করতে চাও, তবে তোমার এখনো অনেক কাজ বাকি!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_117812_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "ওই ঘৃণ্য মিথাগ-এর লোকগুলো, কী সাহসে আমার ক্যান্ডির পথ রুদ্ধ করে! দেখলে তো? শেষ পর্যন্ত আমিই তো সেগুলো পেলাম!"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "আমার ক্যান্ডি চাই তোমার? হুঁঃ। আজ আমি একটু দয়ালু মেজাজে আছি, তাই হয়তো একটা টুকরো তোমাকে দিতেও পারি... যদি ভদ্রভাবে কাকুতি-মিনতি করে চাও, অবশ্যই।"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "তুমি একে কীভাবে “ডাকাতি” বলো? আমি তো কেবল এক ভদ্রমহিলার সম্ভ্রান্ত অধিকার প্রয়োগ করছি!"
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "ধার্মিক ক্যান্ডি ডাইনী এসে গেছে! সব হারানো মিষ্টি তাদের প্রকৃত, গৌরবময় মালিকের কাছে প্রত্যাবর্তন করবে!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "অভিশাপ তোমায়, কৃপণ জিনিস! তোমার মুখ আমি মনে রাখব..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "ওই ছোট্ট ইঁদুরটা প্রকাশ্যে ক্যান্ডি চুরি করতে পারে, আর আমি পারি না কেন? এটা তো ভদ্রমহিলার সঙ্গে প্রকাশ্য বৈষম্য! চরম অসম্মান!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "ক্যান্ডি নেই? তাহলে এই ডাইনীকে বাধ্য হয়ে সত্যিই গম্ভীর হতে হবে!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "নাও, কিছু ক্যান্ডি খাও!"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "তুমি তো ওই ভয়ংকর ওয়েটারদের চেয়েও অনেক বেশি যত্নশীল—আমার জন্য আলাদা করে ক্যান্ডি সঞ্চয়ও করেছ। এভাবেই চালিয়ে যাও, আমার একান্ত দাস।"
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_117821_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "ব্লীইইহ্!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "এটা অনেক বেশি!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "আমাকে থামাচ্ছ কেন? আমার বিশ্বস্ত ভৃত্য হিসেবে, তোমার তো সক্রিয়ভাবে আমাকে সাহায্য করা উচিত সব ক্যান্ডি লু... মানে, সংগ্রহ করতে!"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "থামো! এটা ডাকাতি! বুদ্ধিমানের মতো আচরণ করে সব ক্যান্ডি আমার হাতে তুলে দাও, নইলে... হুঁঃ।"
  },
  Voice_117825_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_117826_AwakerVoiceContent = {
    Text = "নরম, কঠিন, কড়মড়ে, ঝুরঝুরে, দুধেল, ফলের, বাদামি, চকলেটি... আহ, এত রকমফের এখনো যে আমার জিহ্বায় ওঠেনি! ঠিক করলাম: মিথাগকে হ্যালোউইনকে সাপ্তাহিক ছুটিতে পরিণত করতেই হবে!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "মহা ডাইনীই বিজয়ী হবে! মহান ক্যান্ডি-দেবতা আমাকে রক্ষা করেন, আর আমি, বিনিময়ে, সব ক্যান্ডিকে রক্ষা করি! আহাহাহা!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "মৃত্যু প্রতিরোধ অর্থহীন।"
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "শেষ পর্যন্ত সব মিষ্টিই আমার হবে!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "ও বাচ্চাটা ভয়ংকর রকম বাধ্য। বিনা কথায় সব ক্যান্ডি এগিয়ে দেয়... যা আসলে আমাকে সামান্য অপরাধবোধে ফেলে। ক্‌হাঁক! বলতে চাই, যেহেতু সে এত বুদ্ধিমান, তাই দয়ালু ডাইনি স্বাভাবিকভাবেই তার জন্য কিছু ক্যান্ডি রেখে যাবে... সামান্য পুরস্কার হিসেবে!"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "চ্যাট: লিলি সম্পর্কে"
  },
  Voice_117831_UnlockDesc = {
    Text = "\"জাগরণ\" \"Lily\" অর্জনের পর আনলক হবে"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "ডাইনির সঙ্গে ঝামেলা করার দুঃসাহস কোরো না!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "এখন আমি আনুষ্ঠানিকভাবে ক্ষিপ্ত!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "শেষ পর্যন্ত সব মিষ্টিই আমার হবে!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "কি? এই ধরনের মার্শম্যালোও নাকি ভাজা যায়? কিন্তু এতে তো গরম আর আঠালো হয়ে যাবে... সত্যিই কি সুস্বাদু হয়? আমাকে চেখে দেখতে দাও... আচ্ছা, একটুখানি কামড় দেব। যদি আমাকে ঠকানোর সাহস করো... হুঁ?! এই নরম আর কড়মড়ে গঠনটা তো আসলেই অসাধারণ!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_117835_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "মায়াস্বপ্ন, উলটপালট... এ-ই তো ভাগ্যের যন্ত্রপাতি!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "মায়াস্বপ্ন, উলটপালট... এ-ই তো ভাগ্যের যন্ত্রপাতি!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "তাহলে আমার সত্যিকারের সত্তা তোমাকে ভয় দেখায় না, কারণ তুমি নাকি “সত্যিকারের আতঙ্ক” দেখেছ? হুঁ... ধূর্ত জবাব। কিন্তু তাতে আমার... তোমাকে আরও বেশি করে টুকরো টুকরো করে দেখতে ইচ্ছে করছে।"
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_123312_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "তোমার চোখে পৃথিবীটা কেমন? সত্যিকারের আতঙ্কের সীমানা কোথায়? শুধু বলে দিও না; আমি তোমার সঙ্গে গিয়ে নিজ হাতে তা অনুভব করতে চাই, অনুভব করতে চাই সব উন্মাদনা, মৃত্যু আর আতঙ্ক! হ্যাঁ, আমি ঠিক করে ফেলেছি! আমার কৌতূহল মিটে না যাওয়া পর্যন্ত আমি তোমার পাশ ছাড়ব না!"
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_123313_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "একজন নিয়ন্ত্রণহীন উন্মাদ? একদম ঠিক ধরেছ! এটা আমার জগৎ নয়; কোনো বিরক্তিকর আইন বা নিয়মাবলী আমাকে বেঁধে রাখতে পারে না... এখানে, আমি যা চাই তাই করি। তাই সাবধানে থেকো, রক্ষক, কখন যে কোনো উন্মাদ তোমায় কামড়ে দেবে, তা তুমি জানো না।"
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_123314_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "আমার মানসিক স্বাস্থ্যের জন্য গভীর আলাপ চাও? আরে, আমাকে একটু রেহাই দাও। যদি একঘেয়েমিতে ডুবতেই হয়, অন্তত দ্রুত সেরে ফেলি।"
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_123315_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "আমি নাকি তোমার জিজ্ঞাসার জবাব দিতে গিয়ে স্বাভাবিক থাকার ভান করছি? হেহ, ধরেই ফেলেছ। তো, তুমি কি প্রস্তুত, আমি আসলে কী—তা দেখার জন্য?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_123316_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "তোমার মাথাটা থাক না আর কাঁধের ওপরে।"
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "এবার সকলে যার অপেক্ষায়—শাইনিং☆টর্নেডো!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "এটা আমার হওয়ার কথা ছিল না..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "শাইনিং☆ক্রাশ!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "তুমি এই বিকৃত, ভয়াবহ পৃথিবীটাকে বাঁচাতে চাও? দারুণ পাগলাটে এক মৃত্যুপথ বেছে নিয়েছ। দেখা যাক, কত দূর পর্যন্ত যেতে পারো।"
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "আমার কুঠারের স্বাদ নিতে চাও, সোনামণিরা? ভয় পেও না, এটা আসছে..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "রক্ষক, আমার মনে হয় আমি একটা আলো দেখেছি... এ বার কি কাজ হয়েছে...? ভাবছি, আমার সহকর্মীরা কেমন আছে? তারা যেন আমার জন্য কাজের পাহাড় ফেলে না রাখে; আমি কিন্তু অতিরিক্ত সময় কাজ করব না।"
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_123776_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "এই আচার অনুষ্ঠান আমাকে স্বদেশে পাঠাবে? নিশ্চিত? আমরা কতবার চেষ্টা করেছি...? আচ্ছা, চেষ্টা করে তো ক্ষতি নেই, তাই না।"
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_123777_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "হাহা, এ-ই তো আসল জীবন! একঘেয়ে দৈনন্দিন পেষণার চেয়ে অনেক ভালো!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_123779_AwakerVoiceContent = {Text = "হা!"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "এটা আমার হওয়ার কথা ছিল না..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "শাইনিং☆সুপারনোভা—ব্লাস্ট!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "এবার সকলে যার অপেক্ষায়—শাইনিং☆টর্নেডো!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "মনে হচ্ছে যেন আবার কুয়াশার ভেতরে পা রাখছি। কথা যখন উঠলই, কুয়াশার ভেতরের ছোট ছোট প্রাণীগুলোকে ইতিমধ্যেই মিস করছি। দুঃখের বিষয়, আর তাদের ওপর আমার খারাপ মেজাজ ঝাড়তে পারব না।"
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_123783_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "ঘৃণা? তা বলব না। আমি শুধু চাই, একদিন যেন সেই ক্লান্তিকর মিটিংগুলো, সামাজিক বাধ্যবাধকতা আর সর্বজনীন মূল্যবোধগুলো উধাও! হয়ে যায়।"
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "এই তো... আমি আমার 「সত্যিকারের সত্তা」-র আরও কাছে চলে আসছি। আমি তা অনুভব করতে পারছি..."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "আহ... তো কাজ হয়নি। এমনটাই আশা করেছিলাম। জীবন উত্থান-পতনে ভরা—আসলে, বেশিরভাগই পতন... একদিন গিয়ে অভ্যেস হয়ে যায়। তবু, চেষ্টা করার জন্য ধন্যবাদ।"
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_123786_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "ডিজলিউশন সম্পর্কে আমার জ্ঞান ঠিক ততটাই যতটা আমার নিজের শহরের কুয়াশা বিপর্যয় সম্পর্কে—অর্থাৎ কিছুই না। কিন্তু ঠিক এই কারণেই তো ওগুলো এত মুগ্ধকর, তাই না?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "নাম মুশেট, অনুসন্ধান কর্মকর্তা... ওহ ঠিক, আমি আর A.U.G.E.-এর অগ্রদূত নই। নিজেকে আবার পরিচয় করিয়ে দিই—আমি মুশেট, একেবারে মিষ্টি, স্নিগ্ধ বালিকা।"
  },
  Voice_123788_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_123789_AwakerVoiceContent = {
    Text = "দূরে সরে যাও!"
  },
  Voice_123789_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "এখানে আমরা মানুষের জনবসতির খুব কাছাকাছি; বিরক্তিকর বয়স্ক লোকজন চারদিকে ভিড় করে আছে... কখনও ভেবেছ, স্কুলটাকে জনমানবহীন গভীর পর্বতমালায় সরিয়ে নেওয়ার কথা?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "এই অন্য জগতে আটকে পড়ার অনুভূতিটা ধীরে ধীরে ভালো লাগতে শুরু করেছে! শক্তিশালী জাগরণকারীরা, ভয়াবহ ডিজলিউশন, আর রহস্যময় দেবতারা! আহ, নিত্যদিনের তুচ্ছতা থেকে এত দূরে থাকার নিখাদ উন্মাদ আনন্দ!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "এইটুকুই? আমি তো সবে মজা পেতে শুরু করেছি! চল, পরেরটা কে, যার মাথা যাবে?"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "লোকজন বলে, একবার ব্যর্থ হওয়া তোমাকে সংজ্ঞায়িত করে না... আমি একমত নই! আমার কুঠারই সংজ্ঞা দেবে, তাই গলাটা সোজা রাখো!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "নতুন মিশন? পরের বার ভদ্রতার ভান বাদ দাও; এখন আমরা সেই সব 「সামাজিক আচার অনুষ্ঠান」 পালন করার অনেকটাই ঊর্ধ্বে উঠে গেছি।"
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "অন্যদের জন্য নিজেকে উৎসর্গ করা? কী বোকামি! ভীষণ ক্ষুব্ধ করে। কাউকেই এরকম দাবি করার অধিকার দেওয়া হয়নি, এমনকি কোনো দেবতাকেও না।"
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "চ্যাট: সালভাদোর সম্পর্কে"
  },
  Voice_123797_UnlockDesc = {
    Text = "জাগরণকারী \"সালভাদোর\" অর্জনের পর আনলক হবে"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "হুঁ, মন্দ না..."
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "শেষমেশ, আর ভান করতে হচ্ছে না... এখন, চল একটু <Italic:আসল> মজা করি।"
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "আচার অনুষ্ঠানটা এখনো শেষ হয়নি? আমি সত্যিই ফিরে যেতে চাই। ইদানীং ভীষণ ইচ্ছে করছে র‍্যাভেনলগ স্টিউড মাছ আর ধোঁয়া ওঠা হেজেলনাট কাভা চা খেতে। যদিও, এখানে সিলন দ্বীপের কালো চা আর আন্দালুসিয়ান চুরোসও মন্দ না।"
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_123800_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "তাহলে তুমি এখনো আমাকে গড়ে চলেছ। ভয় পাচ্ছ না, কোনো একদিন আমি নিয়ন্ত্রণ হারিয়ে ফেলতে পারি? মজা করলাম... হা হা!"
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "জানো, কিছুদিন এখানে থেকে যাওয়াটা ততটা খারাপও মনে হচ্ছে না। এখানে যা কিছু ঘটবে, সব মনে রাখব, লিখে রাখব, আর ওদের সঙ্গে স্বদেশে ভাগ করে নেব। শিরোনামটা কেমন হয় <Italic:মুশেটের পরজগতের অভিযান>? শুনতে কিন্তু বেশ লাগে, তাই না?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_123802_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "স্বীকার করছি, সে বেশ মিষ্টি... হ্যাঁ, ক্যাম্পাসের ভবঘুরে প্রাণীগুলোকে তাড়া করে মারামারি করার সময় ওকে ভীষণ আদুরে লাগে।"
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_123803_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "আমি এখনো এখানে আটকে আছি, কিন্তু আচ্ছা, আরও শক্তিশালী হওয়া তো সবসময়ই ভালো।"
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "একজন পরিচারিকা? আমিও তো একসময় ছিলাম। সময় করে একদিন যুদ্ধের ময়দানে ওকে আমার ভ্যাকুয়াম ক্লিনার চালানোর কায়দা দেখাতে হবে!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কারেন প্রসঙ্গে"
  },
  Voice_123805_UnlockDesc = {
    Text = "জাগরণকারী 「ক্যারেন」 অর্জনের পর আনলক হবে"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "হাহা, এ-ই তো আসল জীবন! একঘেয়ে দৈনন্দিন পেষণার চেয়ে অনেক ভালো!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "এক স্ট্রাইক, এক হত্যা।"
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "আমার কুঠারের সামনে সুন্দর করে সার বেঁধে দাঁড়াও!"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "বিলীন হও!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "ভাবো না, ব্যথিত হয়ো না; অন্ধের মতো শোনো, বোবার মতো মান্য করো, কারণ নশ্বর দেহের শৃঙ্খল শুধু বোঝা মাত্র!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "ভাবো না, ব্যথিত হয়ো না; অন্ধের মতো শোনো, বোবার মতো মান্য করো, কারণ নশ্বর দেহের শৃঙ্খল শুধু বোঝা মাত্র!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "তুমি জানতে চাও কেন তাঁদের করোটাগুলো এত ফাঁকা? হুঁ, হয়তো এটাই কেবল তাঁদের স্বভাব।"
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "কোনো রোষ পুষে রেখো না, কোনো বিদ্বেষ রেখো না, কারণ সবই তো শূন্যতা।"
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "এমন মনোযোগ আমাকে আরও বেশি করে তোমাকে উত্যক্ত করতে ইচ্ছে জাগায়।"
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_126951_AwakerVoiceContent = {Text = "ইশ!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "তুমি কি আমার কাছে আরও গভীর সৌন্দর্য প্রত্যাশা করো, না আরও গভীর আতঙ্ক?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "একদা এক রাজকুমারী জন্মেছিল ভোগের আনন্দ থেকে। তার পোশাক সোনার সুতোয় বোনা, তার ত্বক হাতির দাঁতের মতো, আগরকাঠের সুগন্ধ তাকে ঘিরে ভেসে বেড়াত, আর তার দৃষ্টির সামান্য ঝাড়ুতেই চুরি হয়ে যেত একেকটি আত্মা।"
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_126953_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "অল্পদিনেই সে এই খেলায় ক্লান্ত হয়ে পড়ল। তার ভক্তরা শুধু একই নাটক বারবার মঞ্চস্থ করত—কামনা থেকে জন্ম নেওয়া প্রেমে, কিংবা প্রেম থেকে জন্ম নেওয়া কামনায় গ্রাসিত হয়ে। তাদের বোকামি—বিশ্বাসঘাতকতা আর হারানোর বেদনা নিয়ে তাদের হাহাকার—তাকে বিরক্ত করত। তাদের অশ্রুও, তাকে বিরক্ত করত।"
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_126954_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "এত তুচ্ছ, সাধারণ মনের দৃষ্টি আমার কাছে চরম যন্ত্রণা।"
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "সেই রেড লেডি, আমাকে কয়েকবার সালোঁর আমন্ত্রণপত্র পাঠিয়েছিলেন।\nবিদেশি মিষ্টান্নের স্বাদ মন্দ ছিল না, তবে……\nউনি আমাকে আগেই জানালে ভালো হতো যে, তাঁর প্রাসাদে 'জলখাবার' আর 'পরিচারক' — এ দুটো একই জিনিস নয়।"
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সোরেল প্রসঙ্গে"
  },
  Voice_126956_UnlockDesc = {
    Text = "\"জাগরণ\" \"সোরেল\" অর্জনের পর আনলক হবে"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "এটা কি ভালোবাসা নয়, তাহলে ঘেরাও হলে কেন ভয় পান? এটা কি ঘৃণা নয়, তাহলে যখন আর কখনো ফেরা যাবে না তখন কেন অশ্রু ঝরে?\nআহা, এখন কি আপনি আমার ছায়াকেও ভয় পাচ্ছেন? সাদা ম্যাগনোলিয়ার সুগন্ধ কি ইতিমধ্যে আপনার কাছে এক অবোধ্য মিষ্টি আঁষটে গন্ধে পরিণত হয়েছে?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_126958_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_126959_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_126959_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "ওহ? তুমি জানতে চাও কেন তাদের বাহুর নিচে ওই দাগগুলো ছিল? তোমার কি একে একটুও মনোরঞ্জক মনে হয় না?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্ফীত অনুগ্রহের আদেশ"
  },
  Voice_126961_AwakerVoiceContent = {Text = "ইশ!"},
  Voice_126961_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "এ ধরনের সামান্য বিনোদনই আমার বেশি পছন্দ, আমার ভক্তদের নিবেদিত কবিতার চেয়ে।"
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "প্রথমে তাঁদের ভঙ্গিমা, তারপর তাঁদের আকার, ক্রমে এমন হলো যে তাঁদেরও জুটল এক জোড়া... না, বরং শেষ পর্যন্ত যা স্মরণীয় রইল, তা শুধু এক জোড়া সুন্দর, আত্মা-হরণকারী চোখ—আমার চোখেরই অনুরূপ।"
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_126964_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "এই দাসী আজ সত্যিই অসহ্য একঘেয়েমিতে ভুগছে, আপনার কি এমন কোনো ইচ্ছা নেই যা পূরণ করা দরকার?\nসত্যিই দুঃখের বিষয়, শুধুমাত্র কিছু তুচ্ছ উদ্দেশ্যে, অনেকেই কাস্তে তুলে নিতে রাজি, এই দাসীর জন্য রক্তের নৈবেদ্য উৎসর্গ করতে।\nকিন্তু যদি আপনি হন তাহলে……"
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_126965_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "ইয়ংরং-এর দল কেন আমার পাশে থাকে, আর কেনই বা এটি গঠিত হয়েছিল? মজার প্রশ্ন। আপনারও কি এমন কেউ ছিল যাকে চেয়েও পাননি, এমন কোনো অনুশোচনা যেখানে আপনার সামর্থ্য ছিল না?\n\nউম, দেখে মনে হচ্ছে নেই, কী দুঃখের।\n\nসেই চরম প্রতিকূলতায় ছটফট করার অভিব্যক্তি, যদি আপনার মুখে ফুটে উঠত, তাহলে নিশ্চয়ই অনেক~ অনেক মজার হতো।"
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_126966_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...তুমি যদি এভাবে অনধিকার প্রবেশ চালিয়ে যাও, তবে তোমার জন্য আমি যে মুখোশ পরি, তা আর এত মনোরম নাও থাকতে পারে।"
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "আমি প্রায় সম্পূর্ণই ভুলে গেছি তার কাহিনি, তবু তা ছিল উল্লাসের, ছিল নিষ্ঠুরতার—একটি কাহিনি যা শুরু হয়েছিল পরিত্যাগ আর প্রতিশোধ দিয়ে, আর শেষ হয়েছিল উৎসর্গ ও অন্ধ আনুগত্যে।"
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_126968_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "আমাকে মনোরঞ্জন করো। পেইন আর আতঙ্কে একে অপরকে হত্যা করো!"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...অন্তত এটুকু, আমাকে সামান্য হলেও আগ্রহের স্ফুলিঙ্গ দেয়।"
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "প্রত্যেকেই এই দাসীর পাখার নিচে তাদের সবচেয়ে প্রিয় মানুষের মুখ দেখতে পায়। এই দাসী এই শক্তি দুর্বলদের ধার দেয়, তীক্ষ্ণ অস্ত্র হিসেবে, এতেই আনন্দ পায়।\nকিন্তু হয়তো, এই দাসী শুধু বলছে, হয়তো।\nযদি আপনি এতে মুগ্ধ হতে চান, তবে এই দাসী সত্যিকারের, পরম আনন্দ অনুভব করবে।"
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_126971_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "চিন্তা করবেন না, আপনি তাঁদের সেই সাধারণ মানুষদের থেকে আলাদা।\nশ্‌, আমার পেছনে তাকাবেন না, অদৃশ্য স্পর্শকে উপেক্ষা করুন——আমার চোখের দিকে তাকান।"
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_126972_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "হেহে... তোমাদের মধ্যে কেউ কি সাহস করো আমার আসল রূপ দর্শন করতে?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "বেশ শব্দ হচ্ছে।"
  },
  Voice_126975_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "কী হলো? আবার আমার পাখার দিকে তাকিয়ে মুগ্ধ হয়ে গেছেন?\nহুহু, পাখার আড়ালে আপনি যার মুখ দেখতে চান, আমি সেই রূপই ধারণ করব আপনার জন্য……আসুন, আরেকটু কাছে আসুন——\nএই, চান না? এত ঠান্ডা কথা বলছেন, অথচ চেহারাটা কিন্তু বেশ মিষ্টি লাগছে……"
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_126976_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "আমার স্বপ্নহীন দেশে তুমি কী খুঁজছ?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "কোনো রোষ পুষে রেখো না, কোনো বিদ্বেষ রেখো না, কারণ সবই তো শূন্যতা।"
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "তোমার ঔদ্ধত্য সংযত করো।"
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_126980_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_126980_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "আমারও একসময় এমন একটি সুন্দর, বাধ্য ছোট্ট মেয়ে ছিল।\nচোখ-ধাঁধানো ফুলের কুঁড়ি, অবশ্যই তাকে কিছু কাঁটা দিতে হবে, ফুলদানিতে রাখা চলবে না।"
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "চ্যাট: লিলি সম্পর্কে"
  },
  Voice_126981_UnlockDesc = {
    Text = "\"জাগরণ\" \"Lily\" অর্জনের পর আনলক হবে"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "মনোরোগ চিকিৎসা দপ্তরের জন্য আমার আবেদনটি বিশ্ববিদ্যালয় এমন দৃঢ়ভাবে প্রত্যাখ্যান করল। কী অদ্ভুত; তাদের আপত্তি থাকতে পারে-ই বা কী?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "সবকিছু শেষ পর্যন্ত শূন্যতায় বিলীন হবে, তাহলে আমার সাথে আরেকটু আনন্দ খুঁজলে কী ক্ষতি?\nনিশ্চিন্ত থাকুন, যদি কোনোদিন আপনি আর প্রতিরোধ করতে না পারেন, আমি তাঁকে আপনাকে আগে কেড়ে নিতে দেব না।"
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "নীরস।"
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "আপনি সত্যিই এক অদ্ভুত মানুষ, ধ্বংস হতে চলা এই পৃথিবীতে এত সব বাহ্যিক বিষয় নিয়ে ব্যস্ত থাকছেন।\nএই দাসীরও কৌতূহল জেগে উঠতে বাধ্য হচ্ছে।"
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_126985_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "আর এক পা-ও এগোবে না!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "আমি শু, স্বপ্নহীন দেশের অধিষ্ঠাত্রী। যদি তোমার হৃদয়ে এমন কেউ থাকে, যাকে দেখার জন্য তুমি ব্যথিত, অথচ কখনোই তাকে পেতে পারো না, তবে আমি আমার পাখা নামিয়ে তোমাকে তার এক ঝলক দেখাব।"
  },
  Voice_126988_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_127088_AwakerVoiceContent = {
    Text = "সব প্রাণীর শাবকই বড্ড ঝামেলার।\nছোট, নরম, চেঁচামেচি করে, আর অজান্তেই চারপাশের সবকিছুকে নিজের ইশারায় নাচায়। আমি জমজমাট পরিবেশ পছন্দ করি, তবে এই ধরনের জমজমাট পরিবেশ সত্যিই পছন্দ নয়। অনুগ্রহ করে ওদের আমার থেকে দূরে রাখবেন।"
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "আমার ছোট্ট জুঁই ফুল, আমার আদরের সোনা, আমার মনের আনন্দে মেতে থাকা ঘরকন্নার খেলা~\nআহ, এগুলো শুধু ভালো মেজাজে বলা আবোলতাবোল, আপনাকে এসব নিয়ে মাথা ঘামাতে হবে না।"
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "পানলং রাজ্যের কিংবদন্তিতে, ময়ূর হলো এক সুন্দর ও জাঁকজমকপূর্ণ হিংস্র পশু।\nসুন্দর অথচ বিষাক্ত — শুনলেই বুকে কাঁপন ধরে, কিন্তু কুৎসিত অথচ দয়ালু হলে বিষয়টা বেশ নীরস হয়ে যায়।"
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "সব সাবাড়! চটাস চটাস!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "গড়গড় গড়গড়~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "কোলসি, আমি, খাব, একসাথে? একসাথে!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_129653_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "ঘূর্ণাবর্ত! ভীষণ শক্তিশালী!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "অতল! সর্পিল! সব শেষ, সবকিছু—সবই ঘূর্ণাবর্তে বিলীন!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_129656_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "ছোঁবে না! তুমি ভেদ করবে!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_129657_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "খোলস, ঝকঝকে! সুন্দর! তোমায় দিচ্ছি!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_129658_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "ঠান্ডা, ভয়ের। ভর্টিস, লুকানো!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডল সম্পর্কে"
  },
  Voice_129659_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ডল」 অর্জনের পর আনলক হবে"
  },
  Voice_129660_AwakerVoiceContent = {Text = "বাহ!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "শিকার! খারাপ! ভেদ! ভর্টিস, ওদের আঘাতপ্রাপ্ত করো, ভেদ করো!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "কি মজা! পরেরবার! আরও!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_129662_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "থপ থপ, ভালো! ভর্টিস, তুমি, থপ থপ!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "না, না! কোলসি, ভর্টিস রক্ষা করবে!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "আবার? আবার!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "হেহে, ঘূর্ণাবর্ত, খেলা করতে চাই!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "বড় ঢেউ আসছে!"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_129668_AwakerVoiceContent = {
    Text = "ব্যাং!"
  },
  Voice_129668_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_129669_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_129670_AwakerVoiceContent = {Text = "ইইক!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "আচার অনুষ্ঠান?! আমাকে নিয়ে চলো!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_129671_UnlockDesc = {
