  },
  Voice_129678_AwakerVoiceContent = {
    Text = "অতল! সর্পিল! সব শেষ, সবকিছু—সবই ঘূর্ণাবর্তে বিলীন!"
  },
  Voice_129678_AwakerVoiceTitle = {
