  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "তাড়াতাড়ি, তাড়াতাড়ি!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_129688_UnlockDesc = {
