  Voice_129690_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "বন্ধু! অনেক! ভালো লাগে!"
