  },
  Voice_129693_UnlockDesc = {
    Text = "\"জাগরণ\" \"নটিলা\" অর্জনের পর আনলক হবে"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "ঘূর্ণাবর্ত! শক্তিশালী!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "আমি! ঘূর্ণাবর্ত! ইয়াহু!"
  },
  Voice_129695_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_130511_AwakerVoiceContent = {Text = "উফ—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "ত্রুটি সংশোধন করা হবে।"
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "আপনি যে বিয়োগান্তক দৃশ্য দেখেছেন, তা অসংখ্য সম্ভাবনার মধ্যে কেবল এক ঝলক মাত্র। ভাগ্যের পর্দা সরিয়ে, আমি দেখেছি সেই ঘোর অন্ধকার মঞ্চ। আলো নিভে গেছে, দর্শক চলে গেছে, সমস্ত কিছু বিশৃঙ্খলার অতলে বিলীন হয়েছে। তবুও... সবকিছু শেষ হয়ে যায়নি। আমার সংকল্প এখনও অটুট, এই নিষ্ফল কঠোর পরিশ্রমকে ধরে রাখার জন্য যথেষ্ট, পরবর্তী আলোকরশ্মি প্রজ্বলিত হওয়ার অপেক্ষায়।"
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "মানুষের ভাগ্য সবই সুতোর টানে বাঁধা……কিন্তু আপনার ভাগ্য, এমন এক পাণ্ডুলিপি যা আমি পড়তে অক্ষম। আমি অপেক্ষায় আছি, আপনি এই পৃথিবীতে কেমন অসাধারণ তাৎক্ষণিক অভিনয় উপহার দেবেন?"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "প্রধান পুতুল, তোমার নিজের মঞ্চে উঠে এসো।"
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_133724_AwakerVoiceContent = {Text = "হুঁ?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "অতীতের সবকিছুই ছিল শুধু প্রস্তাবনা। আপনার আর আমার নতুন অধ্যায়, আপনার লেখার অপেক্ষায়, গোপনরক্ষক।"
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_133725_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "আপনি যদি কমেডি পছন্দ করেন, তাহলে 'আ মিডসামার নাইটস ড্রিম' একটি চমৎকার পছন্দ। আমি বিশেষভাবে পাকের সেই ধূর্ত প্রলাপগুলো পছন্দ করি—পরীদের হাসি-ঠাট্টার আড়ালে সবসময় লুকিয়ে থাকে ভাগ্যের অসাবধানে ফাঁস হওয়া গোপন বার্তা।"
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_133726_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "এর অনুসরণ করি।"
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "চরকা, এখানে ঘুরুক।"
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "হে ভাগ্যের করুণ বন্দী, তোমার নির্ধারিত রায় গ্রহণ করো।"
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "সর্ববিষয়ে অন্তর্দৃষ্টিসম্পন্ন দর্শকও নিজের নাটকে এক আনাড়ি অভিনেতা মাত্র। ভাগ্যের জাল নিয়ন্ত্রণ করেও শেষ পর্যন্ত সেই সুতোতেই বাঁধা পড়ে। এই নির্ধারিত পরিণতিতে, আমরা ভিন্ন ভিন্ন পথে হেঁটেছি, তবু কেউই সেই নিষ্ফল অন্বেষণ ত্যাগ করিনি। মূর্খতাই হোক, কিংবা অবিমৃশ্যকারিতা — আমি এমনই, আর সে-ও তাই।"
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তাওয়ে সম্পর্কে"
  },
  Voice_133730_UnlockDesc = {
    Text = "জাগরণকারী \"তাবিল\" অর্জনের পর আনলক হবে"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "অপ্রত্যাশিত মোড়?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "পর্দা ওঠা-নামার মাঝে আপনার সঙ্গসাথে পেয়ে কৃতজ্ঞ। ভবিষ্যতে, আমি অবশ্যই আপনার প্রত্যাশা পূরণ করব এবং আপনার জন্য আরও মনোমুগ্ধকর নাট্যরাত উপহার দেব।"
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_133732_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "এত প্রতিভাবান একজন গায়ক, ঈশ্বরপ্রদত্ত কণ্ঠস্বর, স্বচ্ছ অথচ উত্তপ্ত, যেন নিয়তির কণ্ঠ থেকে উৎসারিত…… যদি আমার থিয়েটারে আমন্ত্রণ জানাতে পারি, নিশ্চয়ই সবচেয়ে খুঁতখুঁতে দর্শকও বিস্মিত হবেন।"
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "আড্ডা: টিংকট সম্পর্কে"
  },
  Voice_133733_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"টিঙ্কট\" অর্জনের পর আনলক হবে"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "তুমি আর আমি, সেই দুটি অদৃশ্য ভাগ্যের সুতো, অনেক আগেই একে অপরের সাথে জড়িয়ে গেছে, অবিচ্ছেদ্য হয়ে বুনে তুলেছে একটি খাঁচা আর একটি পথ। আমি খাঁচার সীমানা দেখতে পাই না, পথের শেষও দেখতে পাই না। এই গল্পের এটাই সবচেয়ে মুগ্ধকর অংশ।"
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_133734_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "ভাগ্যের সুতো, ইতিমধ্যেই ঝুলে পড়েছে।"
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "সে প্রায়ই আমার থিয়েটারে এসে বসে……কিন্তু আমি জানি, সে নাটক দেখতে আসে না, বরং এই মঞ্চকে ব্যবহার করে নিজের রুচি ও ব্যক্তিত্বের প্রতিফলন ঘটায়। তবে এত অসাধারণ অভিনয় দক্ষতা, শুধু দর্শক হয়ে থাকলে সত্যিই আফসোসের। এটা তো স্পটলাইটের নিচে প্রস্ফুটিত হওয়ার কথা, দর্শক আসনের ছায়ায় লুকিয়ে থাকার নয়।"
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সোরেল প্রসঙ্গে"
  },
  Voice_133736_UnlockDesc = {
    Text = "\"জাগরণ\" \"সোরেল\" অর্জনের পর আনলক হবে"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "আমি একবার তার বাদন শুনেছিলাম, সেই মনোমুগ্ধকর সুর, যা আত্মাকে কাঁপিয়ে দেয়…… হয়তো, আমার নতুন নাটকের জন্য তাকে নিয়তির এক সিম্ফনি রচনা করতে আমন্ত্রণ জানানো উচিত?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "চ্যাট: হামেল্ন সম্পর্কে"
  },
  Voice_133737_UnlockDesc = {
    Text = "জাগরণকারী \"সাঙ্গা\" প্রাপ্তির পর উন্মোচিত হবে।"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "আরেকটি পরিপূর্ণ গল্পের পর্দা নামল।"
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "অন্তহীন ভাগ্যের জাল, আমি ইতিমধ্যে এর সম্পূর্ণ রূপ দেখেছি।"
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "যদি আপনি অনুমতি দেন……আমি আপনার এবং আমার জন্য একটি দ্বৈত নাটক রচনা করতে চাই, যা শুধুমাত্র আমাদের দুজনের। দর্শকের প্রয়োজন নেই, মহড়ারও দরকার নেই……আমি শুধু প্রত্যাশায় আছি, যখন আপনি আলোর নিচে দাঁড়াবেন, তখন সেই সুতো যা আমি স্পষ্ট দেখতে পাই না, তা কী বিস্ময়কর ছন্দে নৃত্য করবে।"
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_133740_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "হতভাগ্য নর্তকী, আমি তার নৃত্যের পদক্ষেপ প্রত্যক্ষ করেছি। সেটা ছিল ধ্বংসের দ্বারপ্রান্তে দাঁড়ানো এক সৌন্দর্য — প্রতিটি ঘূর্ণনে সবুজ অগ্নিশিখা জ্বলে উঠত, যেন ভাগ্যের সুতো পুড়িয়ে ফেলতে চায়, কিন্তু শেষপর্যন্ত সেই সুতোগুলোই তাকে ছিন্নভিন্ন করে সবচেয়ে করুণ ও মনোহর দৃশ্যপট রচনা করে। সুযোগ পেলে, আমি তার জন্য একটি নৃত্যনাটক রচনা করতে চাই — শুধুমাত্র তারই জন্য।"
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "আড্ডা: লিজ সম্পর্কে"
  },
  Voice_133741_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"লিজ\" অর্জনের পর আনলক হবে"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "এখানে বুনন, এখানে পরিমাপ, এখানে বিচার।"
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "শান্ত হও……"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "আরেকটি সুতো, স্পষ্ট হয়ে উঠল।"
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "পর্দা তোমার জন্য উন্মোচিত হয়েছে, নিয়তির পাণ্ডুলিপি শুরু হওয়ার অপেক্ষায়। বলো আমাকে, তুমি কোন নির্ধারিত পথে পা রাখতে চাও? বিষাদের পরিসমাপ্তি, নাকি আনন্দের সূচনা?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_133745_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "আমি সত্যিই এই প্রতিদিনের বুননে মগ্ন ছিলাম……পুনরাবৃত্ত ও নিস্তব্ধ টানের মধ্যে, অসংখ্য কাহিনীর শুরু ও শেষ আগে থেকেই দেখতে পেতাম, সকল নিয়তির পরিসমাপ্তি নীরবে প্রত্যক্ষ করতাম, যেন নিয়তির ঊর্ধ্বে উঠে গেছি। তবু, ভাগ্যের জাল এড়ানোর উপায় নেই, কেবল দর্শক হয়ে থাকলে শেষমেশ নিঃসঙ্গতাই অবশিষ্ট থাকে। তাই, আমি মঞ্চে পা রাখলাম, অভিনয়ের মধ্য দিয়ে, নিজ হাতে বোনা অথচ কখনো নিজে অনুভব করিনি এমন সুখ-দুঃখের স্বাদ নিলাম।"
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_133747_AwakerVoiceContent = {Text = "উফ..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_133748_AwakerVoiceContent = {
    Text = "হেহ..."
  },
  Voice_133748_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "এখানে বুনন, এখানে পরিমাপ, এখানে বিচার।"
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "ভাগ্যের ফিসফিস, আরও কাছে এসেছে।"
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "থিয়েটারে একটি নতুন রোমান্টিক কমেডি মঞ্চস্থ হচ্ছে, আমি নিয়তির আসনে আপনার জন্য একটি খালি জায়গা রেখে দিয়েছি। প্রতিটি নিয়তি-জড়িত দীর্ঘ রাতে, আমি আপনার সাথে সাক্ষাতের তারার আলোর অপেক্ষায় নীরবে বসে থাকব।"
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_133751_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "ভাগ্যের সুতো এভাবে নাড়াতে এতটা মরিয়া হয়ে উঠেছেন……আপনিও কি নিজের অধ্যায়টি উঁকি দিয়ে দেখতে চান?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "ভবিষ্যৎ এসে গেছে।"
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "যদি আপনি ট্র্যাজেডির প্রাসাদে পা রাখতে চান, তবে অনুমতি দিন আমাকে আপনার সামনে 'আন্তিগোনে' উপস্থাপন করতে। ঐশ্বরিক বিধান ও মর্ত্যলোকের দ্বন্দ্বের মাঝে, তার প্রতিটি পদক্ষেপ পড়েছিল নিয়তির বোনা সুতোর উপর, যতক্ষণ না সে প্রস্তর সমাধির গভীর ছায়ায় প্রবেশ করেছিল। এই শৃঙ্খল থেকে মুক্তি নেই বলেই, তার ক্ষুদ্র দেহ থেকে উৎসারিত সেই ইচ্ছাশক্তি দীর্ঘ রাতের নিঃসঙ্গ শিখার মতো এতটাই উজ্জ্বল।"
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_133754_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "অনির্দিষ্ট পরিণতি থেকে, কার্যকারণের জাল থেকে পালানো যায় না……"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "সুতোর উপরে, আমি রংধনুর অসংখ্য বর্ণচ্ছটা প্রবাহিত হতে দেখি——এটি অন্তহীন জালের সংযোগ তৈরি করে, সীমাহীন জগৎ বিস্তৃত করে, অসীম সম্ভাবনার প্রসার ঘটায়, এবং শেষ পর্যন্ত পৃথিবীর সবচেয়ে মনোরম ও বর্ণময় নকশা বুনে তোলে। দেবতা হোক বা মানুষ, বীর হোক বা খলনায়ক, সকলেই সেই সূক্ষ্ম সুতোর দ্বারা পরিচালিত, নিয়তির দৃষ্টির নিচে নির্দ্বিধায় নিজের পরিণতির দিকে ছুটে চলে।"
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "আমি ভেবেছিলাম এই জগতে এমন কোনো পছন্দ নেই যা আমাকে আর অবাক করতে পারে……নাটকের প্রতি আপনার রুচি, আমাকে সত্যিই মুগ্ধ করেছে।"
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_133757_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "ভাগ্যের সুতো সবসময় অন্ধকারে সংযুক্ত থাকে……আপনি এই সুতোয় নাড়া দিয়েছেন, আর আমাকেও চমকে দিয়েছেন।"
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_133758_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "আমি কখনোই একঘেয়ে, ছাঁচে ঢালা পরিবেশনা দেখতে চাই না। থিয়েটারে যাওয়ার মানেই হলো সেই অনন্য মুহূর্তের সাক্ষী হওয়া যা কখনো হুবহু পুনরাবৃত্তি করা যায় না। যদি প্রতিটি পরিবেশনা শুধুই যান্ত্রিক পুনরাবৃত্তি হয়, তাহলে মঞ্চ পরিণত হয় এক জাঁকজমকপূর্ণ খাঁচায়, আর নাটক দেখা হয়ে দাঁড়ায় পূর্বনির্ধারিত পরিণতির প্রতি ক্লান্ত তীর্থযাত্রা। এমন পরিবেশনা যতই জমকালো হোক, তার আত্মা হারিয়ে যায়। আপনি এ বিষয়ে কী মনে করেন?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "ভাগ্যের সুতো আমার হাতের তালুতে সুশৃঙ্খলভাবে প্রবাহিত হচ্ছিল……যতক্ষণ না আপনার আগমন তাদের গতিপথে অপ্রত্যাশিত তরঙ্গ সৃষ্টি করল।"
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_133760_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "হে ভাগ্যের করুণ বন্দী, তোমার নির্ধারিত রায় গ্রহণ করো।"
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "আমি অন্তহীন সুতোর মাঝে, একমাত্র গতিপথ বুনে চলি।"
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "ভাগ্যের মঞ্চের উপরে, সকল প্রাণী নিজ নিজ কার্যকারণের মধ্যে নীরবে অপেক্ষা করছে মঞ্চে আসার জন্য, সমস্ত সুখ-দুঃখ গিয়ারের ঘূর্ণনের মাঝে নিঃশব্দে রচিত হচ্ছে... পর্দা উঠেছে, গোপনরক্ষক, তোমার আর আমার মধ্যকার গল্প, এখন থেকেই শুরু হতে চলেছে।"
  },
  Voice_133763_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_133764_AwakerVoiceContent = {
    Text = "দ্বন্দ্ব এসে গেছে, আপনি কি জাল ছিন্নকারী বীর হবেন, নাকি ভাগ্যের অনুগত পার্শ্বচরিত্র?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "বৃথা প্রতিরোধ।"
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "ধন্যবাদ। আমি এই উপহারটা যত্ন করে রাখব।"
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "জাগ্রত সত্তার গঠন সম্পর্কে অনেক কিছু শিখেছি, এখন বিশেষজ্ঞ বলা যায়। কিন্তু সিলভার কোরের মধ্যে থাকা 「আত্মিকতা」 জিনিসটা, এখনও একটু বুঝতে পারছি না……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_139866_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "এটাই হলো, নতুন পৃথিবীর সূচনা……"
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "আমি এরকম কাজ করতে পারি। অন্য জীবের শরীর পুনর্গঠন করা, সমন্বয় করা……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_139868_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "কোথায় কীভাবে সমন্বয় করতে হবে, সেটা জীবের প্রজাতি অনুযায়ী আলাদা, তাই ভালো করে না শিখলে চলবে না।"
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_139869_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "ভয় লাগে না, আমার এই রূপ দেখে? এহ, একটু বিরক্তিকর……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "কাউকে আমাদের পথে বাধা দিতে দেব না"
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "আমি প্রস্তুত হয়ে গেছি।"
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "জীবজগৎ সত্যিই বৈচিত্র্যে ভরপুর। আরও জানতে চাই！"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "তুমি কি সায়ার সাথে খেলবে？"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_139876_AwakerVoiceContent = {
    Text = "স্কুইক!"
  },
  Voice_139876_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "এটাই হলো, নতুন পৃথিবীর সূচনা……"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "পেট ভরে গেছে, আপ্যায়নের জন্য ধন্যবাদ！"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "গোপনরক্ষক, তুমি কি কখনো কাউকে ভালোবেসেছ, কারো জন্য মন কেমন করেছ?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_139880_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_139881_AwakerVoiceContent = {
    Text = "উউউ।"
  },
  Voice_139881_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "এটাই কি সেই জায়গা?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "কষ্ট হয়েছে！ভালো কিছু পেয়েছো？"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "বিভিন্ন পরীক্ষা-নিরীক্ষার পর, মোটামুটি বুঝে গেছি। প্রতিটি জাগ্রত সত্তার ধারণ করা 「আত্মিকতা」 সম্পূর্ণ আলাদা। আর, আমার সিলভার কোরের আত্মিকতা মনে হয় 「ভালোবাসা」 নে।"
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_139884_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "কেমন, চমকে গেছো তো？"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "এটা তোমার জন্য, শেষ উপহার।"
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "「এই তারাগুলোর কোনো একটিতে, আমার ফুল ফুটে আছে……」 এভাবে বলেছিল।\nতুমিও মনে হয় এরকম কিছু বলেছিলে।"
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_139887_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "「সিলভার কোর」 নামের এই জিনিসটা, মনে হয় অনেক দূরের কোনো ইচ্ছার সাথে সংযুক্ত। সত্যিই অবিশ্বাস্য……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_139888_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "এটা তোমার জন্য, শেষ উপহার।"
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_139891_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "ছোট্ট রাজকুমার বলেছিল, গোলাপের প্রতি তার যত্নই গোলাপকে অনন্য করে তুলেছে…… তুমিও কি তাই মনে করো?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_139892_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "গতকাল, আমি লিলির বইয়ের তাকে 《ছোট্ট রাজকুমার》 নামে একটা বই দেখেছি। ওটা ধার নিয়ে এসেছি। আমার সাথে একসাথে পড়বে?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_139893_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "হুম, সিলভার কোরের গঠনও গবেষণা করেছি, জাগ্রত সত্তার মোটামুটি রূপরেখা ধীরে ধীরে বুঝতে পারছি।"
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_139895_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_139896_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_139897_AwakerVoiceContent = {
    Text = "হেয়ো!"
  },
  Voice_139897_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "অনেক কিছু শেখাবেন!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "হ্যালো！……এভাবে বলাটা কি ঠিক হলো？\nআমি সায়া। উম্……আমাকে মনে রাখবেন——"
  },
  Voice_139900_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_139901_AwakerVoiceContent = {
    Text = "ড্যান্ডেলিয়ন নামে একটা ফুল আছে, যেটা তার বীজকে বাতাসে ভাসিয়ে দেয়। তুলতুলে বীজগুলো বাতাসে ভেসে, নিজের জন্মভূমি থেকে অনেক অনেক দূরে চলে যায়, হয়তো এমন মরুভূমিতে পড়ে যেখানে একটা ঘাসও নেই। সেই সময়, সেই ছোট্ট একটা বীজ কী ভাবে……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_139901_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "যতবারই করি না কেন, এটা সবসময় মজার!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_139903_AwakerVoiceContent = {
    Text = "হেই——"
  },
  Voice_139903_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "বিপদ——"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "সুস্বাদু খাবার খুব পছন্দ! সায়ার প্রতি যারা সদয়, তাদেরও পছন্দ। সদয় ব্যবহার পেলে, সত্যিই খুব খুশি লাগে——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "ওই কি আমাকে জাগ্রত করা মানুষ? কেন যেন খুব উজ্জ্বল মনে হচ্ছে…… হুম~ তাহলে, তুমি কি তাকে তার দিদিকে খুঁজে পেতে সাহায্য করেছ?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "আড্ডা: টিংকট সম্পর্কে"
  },
  Voice_140534_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"টিঙ্কট\" অর্জনের পর আনলক হবে"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "যখনই সায়া গোপনরক্ষককে একা পেতে চায়, তখনই অনেক অদ্ভুত লোক ঘিরে ধরে এমন জায়গা। গোপন জগতে থাকার সময়টাই বেশি পছন্দ——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "আচ্ছা তাই। বুঝেছি！"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "গোপনরক্ষক, সংযোগ, জাগ্রত সত্তা, এই সম্পর্কটা তুমিই আমাকে বলেছিলে তাই না। দুজনের আত্মা একসাথে সংযুক্ত অনুভব করতে পারি…… রূপালি সুতোর মাধ্যমে? এরকম কিছু, হুম—— মনে হয় সবকিছুই বুঝতে কঠিন……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "মাংস দিয়ে বীজ বহন করে? হুম~ তাই নাকি। তার ভেড়াগুলোর প্রতি একটু আগ্রহ জাগছে।"
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "গল্পগুজব: থাইস প্রসঙ্গে"
  },
  Voice_140538_UnlockDesc = {
    Text = "\"জাগরণ\" \"থাইস\" অর্জনের পর আনলক হবে"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "এই পৃথিবীকে হুমকি দেওয়া কোনো সংকট, অস্তিত্বকে ধ্বংস করতে পারে এমন অন্ধকার, তাই তো? আমি জানি। প্রফেসর ডোরের কাছ থেকে অনেক কিছু শুনেছি।"
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "রুক্ষ মানুষ পছন্দ না। অস্বস্তি লাগে……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "তার জাতি, মনে হয় অন্য গোষ্ঠীদের থেকে কেড়ে নিয়েই নতুন গ্রহে বংশবিস্তারের সুযোগ পায়। হুম~ তাই নাকি……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "আড্ডা: উইনকোর সম্পর্কে"
  },
  Voice_140541_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "ভালো বাচ্চা।"
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_141964_AwakerVoiceContent = {Text = "এই!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: III"
  },
  Voice_141965_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_141965_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·পাঁচ"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "কতই না দুঃখজনক, যখন তুমি মন পরিবর্তন করবে, তুমি জানো আমাকে কোথায় খুঁজে পাবে।"
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_143501_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "ছাই..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "ত্বক、পেশী、স্নায়ু、হাড়, এগুলো সবই পুনর্গঠিত হবে, নতুনভাবে সুস্থ ও অক্ষত হবে, নতুনভাবে প্রাণশক্তিতে ভরে উঠবে।"
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_143503_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "সমুদ্রের সামনে, কোনো অজেয় শত্রু নেই!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "ভোজ, অনুসন্ধান, আশ্রয়?\nআমার কাছে প্রার্থনা করো, সবচেয়ে প্রাচীন সমুদ্রের জল তোমাকে আমার নাম বলবে।\nআমি অতল গহ্বরের অধিপতি, পন্টোস।"
  },
  Voice_143505_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_143506_AwakerVoiceContent = {
    Text = "হুহু, এপোয়ান্স-এ কাটানো সময়ের জন্য মন কাঁদছে কি…\nসেটা এই শরীরের ভেতরেই আছে, যেকোনো সময় তোমাকে ফিরে আসতে স্বাগত জানাচ্ছে।"
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "যদিও আমি সেটা করিনি, কোনো একদিন যদি তোমার কানে সমুদ্রের জল আর ডানার ঝাপটার শব্দ আসে, চিন্তা করো না, এটা স্বাভাবিক ব্যাপার।"
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "তোমার ইন্দ্রিয় উৎসর্গ করো, চিরকাল অতলে অনুতাপ করো!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "আমি প্রাণবন্ত তরুণদের পছন্দ করি, কিন্তু দুর্ভাগ্যবশত, মিথাগ উৎসবের উপর এত কঠোর নিয়ন্ত্রণ রাখে যে একটা ভালো শিকারের মাঠও নেই।\nআর তার ভেতরে আছে সেই নোংরা জিনিসটা, যে প্রকাশ্যে ঘুরে বেড়ানোর সাহস দেখায়, এমনকি অধ্যাপকের খেতাব পর্যন্ত ঝুলিয়ে রেখেছে।"
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_143510_AwakerVoiceContent = {Text = "উফ!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "আমি এত কিছু করলাম, তুমি এমনকি আমাকে আর একবার মামা বলে ডাকতেও রাজি নও, সত্যিই বিরক্তিকর।"
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "তাড়াহুড়ো করো না, সমুদ্রের গভীরতম অন্ধকার অবশ্যই তোমাদের গ্রাস করবে।"
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "হাঁটু গেড়ে বসো, এপোয়ান্সের খোরাক হয়ে যাও।"
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: III"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "আর যে সত্তা আমাকে বেছে নিয়েছে... শুধু এটুকুই বলা যায় যে সে একই সাথে বন্ধুত্বপূর্ণ এবং নিষ্ঠুর।\nকোথায় ফেলে দেবে সেটা সম্পূর্ণ মেজাজের উপর নির্ভর করে, বিপদ থেকে উদ্ধার করবেই, তবে সেই জায়গাটা আরেকটি বিপদ কিনা, সেটা এই 「যাত্রা」র ভাবার বিষয় নয়।\nকতটা মজার, কতটা অপ্রত্যাশিত, আমি এই ঐতিহ্য অব্যাহত রাখার কথা ভাবছি।"
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_143515_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "আমার সাথে এপোয়ান্সের একটি বিশেষ সংযোগ আছে, বরং বলা যায়, আমিই এপোয়ান্স, এপোয়ান্স আমার উপর নির্ভরশীল, আমার শরীরের মাধ্যমে বিদ্যমান।"
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "গল্পগুজব：এপোয়ান্স সম্পর্কে"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "মাথা তোলো, তোমার গলা বের করে দাও।"
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "স্মৃতি মুছে দেওয়া, অস্তিত্ব মুছে দেওয়া। পরিচিত মনে হচ্ছে… তুমি আমার মানে বুঝতে পারছ — উৎস ভিন্ন হলেও, মনে হয় তারা সবসময় আলোহীন স্থান থেকেই জন্ম নেয়।"
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "তোমরা এতটা বোকা হওয়া উচিত হয়নি যে আমার মহিমাকে লঙ্ঘন করবে।"
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "অত্যন্ত দুর্বল।"
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "এপোয়ান্সে, উৎসব কখনো থামে না, এপোয়ান্সের শত্রুরাও চিরকাল শান্তি পাবে না।"
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_143521_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "আহ, তোমার কম্পন আমি অনুভব করতে পারি, কিন্তু এর কোনো প্রয়োজন নেই, আমার তরুণ বন্ধু।\nসাধারণত্ব এবং ক্ষয়ে যাওয়ার ভয়কে গ্রহণ করো, আমার দিকে তাকাও, তুমি বুঝতে পারবে যে তোমার কাছে সবসময় আরেকটি বিকল্প আছে।"
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_143522_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "হ্যাঁ, আমি জানি সেই বিপর্যয় সে সরাসরি ঘটায়নি, শুধু আনন্দের পথে একটা দুর্ঘটনা ছিল, কিন্তু এটা স্পষ্টতই আমাকে তাকে আরও বেশি হত্যা করতে চাওয়ায়।\nসেই কালো কুয়াশাটা যেন একা না পড়ে, আর আমার হাতেও না পড়ে।"
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "সেই আঠালো মৎস্যমানবরা আমার বন্ধু নয়, বরং আমার শত্রু। অবাক হচ্ছো？ সমুদ্র আসলে কখনো তাদের ছিল না।"
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_143524_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "অনন্তকাল ধরে, এখানেই আটকে থাকো!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "প্রস্তুত তো, শিকারেরা!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "আধ্যাত্মিক শক্তি নতুন দেহের জন্ম দেয়, দেহে ভরে দেওয়া হয় তুচ্ছ জ্ঞান, তারপর সেই সুন্দর প্রাণবন্ত সত্তারা চিরকালের জন্য একটি জায়গায় একত্রিত হয়।\nআমি যা বলেছিলাম তা কি মনে আছে, সমুদ্রের গভীরতম স্থান সব কিছু ধারণ করে… সব কিছু ধরে রাখে।"
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_143527_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "দুঃস্বপ্ন, তাদের আটকাও।"
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "আশা করি এই ছোট্ট প্রাণীগুলো তোমাকে দেউলিয়া করে ফেলবে না, তুমি জানো, একটা বড় পরিবার পালন করা সত্যিই সহজ কাজ নয়।"
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "বহু বহু আগে, যখন স্থলভূমি এখনো সমুদ্রের উপর ভেসে ওঠেনি, তখন এই গ্রহে কিছু বিশেষ আত্মিক সত্তার জাগরণ হয়েছিল। শক্তিশালী、মহিমান্বিত、উঁকি দেওয়ার অযোগ্য।\nতাদের শত্রুভাবাপন্ন বা বন্ধুত্বপূর্ণ হিসেবে সংজ্ঞায়িত করা যায় না, মানুষ যেমন অতীতের অগণিত প্রাণীর মতো, তাদের কাছে তুচ্ছ, ধুলোর মতো মুছে ফেলা হবে, আবার ভূখণ্ডের সাথে সুরক্ষিতও করা হবে।"
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_143530_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "শুধু বার্ধক্যই সেই অ্যাডভেঞ্চার যা তোমাকে একা মোকাবেলা করতে হবে、তোমার সেরা বন্ধু এবং সবচেয়ে কঠিন শত্রু, এপোয়ান্সের আলো তাকে সম্পূর্ণরূপে তাড়িয়ে দেবে… শুধু কিছু তুচ্ছ নোট, তোমাকে সেগুলোর সাথে নোঙর করে রাখার দরকার নেই।"
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_143531_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "পলায়নের মায়া ত্যাগ করো।"
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "তুমি ধূসর ছাইয়ে পরিণত হবে।"
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_143534_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_143534_AwakerVoiceTitle = {
    Text = "স্ট্রাইক"
  },
  Voice_143535_AwakerVoiceContent = {
    Text = "বেশ চালাক কাজ করেছ, ছোট্ট বন্ধু, বাইরের দানবের ভক্তরা সবসময় এতটাই বোকা যে লাশ সমুদ্রে ছুঁড়ে ফেলে, সেটা কিন্তু উপহার হিসেবে গণ্য হয় না, তাই না?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "তোমাকে লক্ষ্য করা হয়েছে।"
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "স্বীকার করতে না চাইলেও, কোনো কোনো বিরল মুহূর্তে মনে হয় বার্ধক্য হয়তো সময়ের একমাত্র উপহার নয়, শুধু একটি প্রতীক।\nতাই আমি এটিকে আমার মধ্যে থাকার অনুমতি দিই। অবশ্যই—শুধু বাহ্যিক রূপে।"
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "প্রার্থনা কার্যকর, একটু ভাবো — এমনকি যদি পোকামাকড় তোমার সামনে রেউ অক্ষরে সারিবদ্ধ হয়, তুমিও পোকামাকড়ের আবেদনে সাড়া দেওয়ার কথা ভাবতে পারো।"
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_143539_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "হাহাহাহা、ঠিক আছে、এই অভিব্যক্তি করো না、আমার ছোট্ট বন্ধু।\nএটা শুধু কিছু তথাকথিত 「পুরনো দেবতাদের」 অনুসরণ করার ঐতিহ্য、তোমার জন্য、কোনো মূল্য বা শর্তের দরকার নেই、আমি চিরকাল তোমার পাশে থাকব।"
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_143540_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "হুহ, বাইরের দানবের সাথে হাত মেলানো ছোট দানব।\nকোনো বোকা আমাকে আর তাকে একই বেদিতে রেখেছে, এটা সত্যিই অপমানজনক!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_143554_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "শত্রুর শত্রু বন্ধু, সুযোগ পেলে আমি আমার চিরশত্রুর সবচেয়ে প্রিয় খেলনা কেড়ে নেওয়ার এই ভালো সওদায় আপত্তি করব না।"
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "চ্যাট: রাইকার সম্পর্কে"
  },
  Voice_143555_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"রাইকার\" অর্জনের পর আনলক হবে"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "ওহ？ এখানে আমার সাথে হাত মেলাতে চাও？ আমার কোনো আপত্তি নেই।"
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "আরও, আমাকে আরও শক্তি দাও!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "আমি অশুদ্ধ মানুষ পছন্দ করি না, কারণ অশুদ্ধতা সাধারণত দুর্বলতার ইঙ্গিত দেয়। কিন্তু তুমি একটি ব্যতিক্রম। আমি একসময় মনে করতাম, যে মানুষ অনেক কিছু বহন করে, সে আরও দূরে এগিয়ে যেতে পারে না। কিন্তু তুমি যে পথে হেঁটেছ, তা আমাকেও অবাক করে দিয়েছে… হয়তো, ভিন্ন পথে চলা মানুষই আরও বেশি লালন ও চ্যালেঞ্জের যোগ্য। তুমি কি তাই মনে করো না, 「প্রতিদ্বন্দ্বী」？"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "তারাকাশের ভ্রমণকারী তিমি, সব কিছু গ্রাস করো!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "আমার প্রতিদ্বন্দ্বী হতে পেরে গর্বিত হও!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "তারার সমুদ্র, ধ্বংসের সাক্ষ্য দাও!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "যথেষ্ট নয়, একেবারেই যথেষ্ট নয়…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_146165_AwakerVoiceContent = {
    Text = "হেঃ।"
  },
  Voice_146165_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_146166_AwakerVoiceContent = {
    Text = "হুম্ফ।"
  },
  Voice_146166_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "সবকিছুর বিলয়ে আমার কোনো মাথাব্যথা নেই, কিন্তু আমি তা শক্তি অন্বেষণের পথে বাধা হয়ে উঠতে দেব না।"
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "অনিবার্য বিলয়ের কারণে সব অস্তিত্বের অর্থ নিয়ে সন্দেহ করতে শুরু করা… এই ধরনের শিশুসুলভ নির্বোধ তর্কে অংশ নেওয়ার আমার কোনো আগ্রহ নেই। ধ্বংসে কিছু যায় আসে না, স্মরণ রাখারও প্রয়োজন নেই। শক্তি নিজেই অর্থ।"
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "গল্পগুজব：মেল্টডাউন·ডল সম্পর্কে"
  },
  Voice_146168_UnlockDesc = {
    Text = "জাগরণকারী 「ডল: ইনফার্নো」 অর্জনের পর আনলক হবে"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "তোমার চোখে, আমি এমন একটি ইচ্ছা দেখতে পাচ্ছি যা এখানকার নয়। এটি বিশুদ্ধ নয়, কিন্তু যথেষ্ট দৃঢ়। এসো, আমাকে প্রমাণ করো, কোন শক্তি ও আকাঙ্ক্ষার উপর ভর করে তুমি আমার সামনে দাঁড়িয়ে আছ।"
  },
  Voice_146169_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_146170_AwakerVoiceContent = {Text = "হা!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "আমার প্রতিদ্বন্দ্বী হতে পেরে গর্বিত হও!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "কেওসের পরিচিত সুবাস, বহুদিন পরে… এই মায়া থেকে জন্ম নেওয়ার মুহূর্ত থেকে শুরু করে, আমি যা খুঁজে চলেছি, তা কখনো পরিবর্তিত হয়নি।"
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_146172_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "আমাকে চ্যালেঞ্জ করতে চাও? আমি তোমার সাহসের প্রশংসা করি, এবং তোমাকে পরাজিত হওয়ার সম্মান দিতেও রাজি আছি। এটাই 「মিথাগ রক্ষক」-এর প্রতি আমার শ্রদ্ধা।"
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_146173_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "একটি মিথ্যা ইউটোপিয়ায় ভিড় করে আছে দুর্বল, কাপুরুষ আর আত্মপ্রতারক বোকার দল। তবে কিছু যায় আসে না, এখানে আমাকে সবচেয়ে উল্লাসজনক শত্রু দেওয়া হয়, এটুকুই যথেষ্ট।"
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "প্রচণ্ড শক্তি থাকা সত্ত্বেও, ভয়, অপরাধবোধ আর ক্লান্তির কারণে নিজের প্রতিভাকে দীর্ঘ স্বপ্নের ভেতরে বন্দী করে রাখা, সত্যিই কী অপচয়।"
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_146175_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "একেবারে দুর্বল।"
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "সিলমোহর কিছুটা শিথিল হয়েছে… তারার সমুদ্রের গভীর থেকে শক্তি উপরে উঠে আসছে। এই অনুভূতি আমি অনেকদিন অনুভব করিনি…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_146177_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "তারাকাশের ভ্রমণকারী তিমি, সব কিছু গ্রাস করো!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…সুখকর।"
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "আমি অগণিত বছর ধরে নক্ষত্রসমুদ্রে ভেসে বেড়িয়েছি, নিজের হাতে সেই সব অস্তিত্বকে অতলে পাঠিয়েছি যারা নিজেদের শক্তিশালী বলে দাবি করত। তোমার মধ্যে নিজস্ব বিশেষত্ব আছে, কিন্তু আমার পাশে দাঁড়াতে চাইলে আগে আমার সামনে মাথা উঁচু করে দাঁড়াতে শেখো। কাপুরুষ সঙ্গী আমার প্রয়োজন নেই।"
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_146180_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "সাহসী, কাপুরুষ, দৃঢ়, ভঙ্গুর… হুঁ, না, প্রতিদ্বন্দ্বী কেমন মানুষ তা নিয়ে আমার কোনো মাথাব্যথা নেই। যেকোনো সক্ষম প্রতিদ্বন্দ্বীই আমাকে আনন্দ দিতে পারে।"
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "দুর্বলতা। এই পৃথিবীতে অসংখ্য ঘৃণ্য জিনিস আছে, কিন্তু দুর্বলতা হলো সবচেয়ে নিকৃষ্ট পাপ। প্রত্যেকে তলোয়ার হাতে এই পৃথিবীতে আসে, শেষ পর্যন্ত পৌঁছানোর আগে কারো হাত শিথিল করার অধিকার নেই, পরাজয়ের চিন্তা নিয়ে নির্ধারিত রণক্ষেত্রে পা রাখার অধিকার নেই। এটা প্রতিদ্বন্দ্বীর প্রতি, এবং নিজের প্রতিও অপমান।"
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "ক্ষয়িষ্ণু তারার কঙ্কাল, জাগরণ হও——"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "হুহ… কী উল্লাসজনক প্রতিদ্বন্দ্বী। পরের বার, আমি আর হাত গুটিয়ে রাখব না।"
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "আমার হাড়গুলো আনন্দে কম্পন করছে… তুমি যে পরিশ্রম করেছ, তা আমি দেখেছি। এটাই প্রমাণ যে তুমি আমার পাশে দাঁড়ানোর যোগ্য, রক্ষক।"
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_146185_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "হুহ… তুমি বিষয়টা স্পষ্টভাবে দেখতে পাচ্ছ, রক্ষক। শক্তির শৃঙ্খল তো ভাঙার জন্যই তৈরি!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_146186_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_146187_AwakerVoiceContent = {Text = "হুঁ?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_146188_AwakerVoiceContent = {Text = "হুঁ?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "ঠিক সামনেই… আমার সারাজীবনের অন্বেষণ, সেই শক্তির শেষ প্রান্ত… সারাটা পথ আমাকে অনুসরণ করে, আমাকে এখানে নিয়ে আসা — সেটা তুমি। আমি অপেক্ষায় আছি, তোমার সাথে মিলে সেই চূড়ান্ত দিনের সাক্ষ্য দিতে!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_146189_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "হয়তো আগে আমার কথাগুলো একটু বেশিই তাড়াহুড়ো করে বলা হয়েছিল… তোমার বিকাশের গতি, আর তোমার মধ্যে লুকিয়ে থাকা সেই শক্তি, সবকিছুই আমার প্রত্যাশার বাইরে। আমি অনেক জীবন দেখেছি যারা সময়ের মধ্যে বিলয় হয়ে গেছে, কিন্তু তুমি… সত্যিই অসাধারণ। আমি জানতে চাই, তোমার মধ্যে থাকা সেই শক্তির রহস্য আসলে কোথা থেকে আসে?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_146190_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "নরকের দ্বার, আমার জন্য উন্মুক্ত হও!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "আহ, আমি দেখতে পাচ্ছি… শক্তির শেষ প্রান্ত বলে কিছু কখনো ছিলই না… প্রকৃত চ্যালেঞ্জ এখন আমার সামনে উন্মুক্ত হয়েছে! তুমিই আমাকে এখানে নিয়ে এসেছ, আমাকে সবকিছু স্পষ্টভাবে দেখিয়েছ। শীঘ্রই আমি একজন আরও নিখুঁত যোদ্ধাকে তোমার সামনে নিয়ে আসব। আশা করি সেই সময়, আমিও একটি আরও নিখুঁত তোমাকে দেখতে পাব, আমার 「প্রতিদ্বন্দ্বী」।"
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_146193_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "ছোট কৌশল।"
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "শক্তি অস্থিমজ্জায় ফুটছে!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "সম্পূর্ণ গ্রাস করো!"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "দয়া, দুর্বলতা, বিভ্রান্তি… তোমার চোখ অশুদ্ধিতে পরিপূর্ণ। যে মানুষ যথেষ্ট বিশুদ্ধ নয়, সে কখনো বুঝতে পারবে না শক্তি কাকে বলে।"
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_146197_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "প্রকৃত শক্তি, কখনোই প্রতিশোধ বা রক্ষার সাথে সম্পর্কিত নয়। শক্তি শুধুমাত্র শক্তিই, আমার অপর সত্তা কখনো এই সত্যটি 「সত্যিকার অর্থে」 বোঝেনি। এটিই সে যথেষ্ট শক্তিশালী না হওয়ার উৎস।"
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "গল্পগুজব：লোটান সম্পর্কে"
  },
  Voice_146198_UnlockDesc = {
    Text = "\"জাগরণ\" \"লোটান\" অর্জনের পর আনলক হবে"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "মনোযোগ দিয়ে শোনো, আমি শুধু একবারই বলব：\nআমি, লোটান, তোমাকে প্রহরার যোগ্য প্রতিদ্বন্দ্বী হিসেবে স্বীকার করছি।\nতুমি শীর্ষে পৌঁছানোর আগ পর্যন্ত, আমি তোমার সবচেয়ে বিশ্বস্ত তরবারি হয়ে থাকব। আমার প্রতিশ্রুতি ও আনুগত্য আবেগের সাথে সম্পর্কিত নয়। তুমি আমার সবচেয়ে আনন্দদায়ক প্রতিদ্বন্দ্বী, আমি কখনো তোমাকে পথের মাঝে পড়ে যেতে দেব না।"
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_146199_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "এসো, আমাকে হত্যা করো, অথবা, আমার হাতে নিহত হও।"
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "নরকের দ্বার, আমার জন্য উন্মুক্ত হও!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "হাড়ের তরবারির গতিপথে, সবকিছু ভেঙে পড়ে!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "শক্তি……কখনো শেষ হয় না!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_147493_AwakerVoiceContent = {Text = "—"},
  Voice_147493_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_147493_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(একটি ভাঙা ও মৃদু গানের সুর)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "দর্শক, আরও বেশি দর্শক চাই……"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "বালি……সাদা মরুভূমি……এখানে খুব বিপজ্জনক, তাড়াতাড়ি আমার সাথে চলো।"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_147496_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "আমার এখনও নতুন আবাসভূমির মানচিত্রটা মনে আছে, সব রঙিন ছিল, অসম্ভব সুন্দর। এটাই সেই জায়গা যেখানে আমাদের যাওয়া উচিত। আমরা গান গাইতে পারব, আমরা সুখ পেতে পারব।"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_147498_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_147499_AwakerVoiceContent = {Text = "—"},
  Voice_147499_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_147499_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_147500_AwakerVoiceContent = {
    Text = "হুম...?"
  },
  Voice_147500_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "ওটা হলো……তারকা গম্বুজের কণ্ঠস্বর……"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "তুমি আবার এসেছ। আগের মতোই, আমার পাশে বসো আর একসাথে অপেক্ষা করো। কীসের অপেক্ষা……? অপেক্ষা, শুধুই অপেক্ষা।"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "নিখুঁত রিহার্সাল, আমার মনে হয় আমি মঞ্চে ওঠার জন্য প্রস্তুত।"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_147503_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "পতিত হও।"
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "জনশূন্যতা ও মৃত্যুর উদ্দেশ্যে নিবেদিত।"
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "আমি পাগলও নই, আর কখনো দুঃখও অনুভব করিনি। অনুগ্রহ করে অযৌক্তিক গুজবে কান দেবেন না।"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "অদ্ভুত, মনে হচ্ছে তারা আমার গানকে খুব ভয় পাচ্ছে……"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_147508_AwakerVoiceContent = {
    Text = "শ্‌..."
  },
  Voice_147508_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "সত্যিই সুন্দর পারফরম্যান্স পোশাক, ঝলমলে, ঝলমলে……"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_147509_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_147510_AwakerVoiceContent = {Text = "—"},
  Voice_147510_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "আজও টিকে থাকা নক্ষত্রদের বর্ণচ্ছটা।"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_147512_AwakerVoiceContent = {
    Text = "গান গাও।"
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "সঠিক কণ্ঠস্বর প্রশিক্ষণ……? কিন্তু আমি তো আমার এখনকার কণ্ঠস্বর নিয়ে বেশ সন্তুষ্ট।"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_147513_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_147514_AwakerVoiceContent = {Text = "—"},
  Voice_147514_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "গলার স্বরে যেন কিছুটা পরিবর্তন এসেছে……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_147515_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "কেমন হলো, আমার গান কি ভালো লেগেছে?"
  },
  Voice_147516_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_147517_AwakerVoiceContent = {
    Text = "শান্তিতে ঘুমাও……"
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_147518_AwakerVoiceContent = {Text = "—"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_147519_AwakerVoiceContent = {
    Text = "ঠিক আছে।"
  },
  Voice_147519_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_147520_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "ধন্যবাদ……আমার কি ধন্যবাদ বলা উচিত?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "*হা-হা নিঃশ্বাস*..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "আলোয় উদ্ভাসিত হও।"
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "অনেকদিন পর এই অনুভূতি……অবশেষে আবার মঞ্চে ফিরে এলাম। ধন্যবাদ তোমাকে, গোপনরক্ষক।"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_147524_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "বিরক্ত করার জন্য ক্ষমা করবেন... আমাকে কি গাছ থেকে নামাতে পারবেন? আমার মনে নেই কেন আমি উপরে উঠেছিলাম, হয়তো মাথার উপরের মেঘগুলো কিছুটা স্মৃতিকাতর করে তুলেছিল..."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "আমার গোষ্ঠীর মানুষেরা কখনো আমাকে ছেড়ে যায়নি, তারা শুধু অনেক দূরে, অনেক দূরে চলে গেছে।"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার স্বজনদের সম্পর্কে"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "শুনতে পেয়েছ?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_147528_AwakerVoiceContent = {Text = "ওহ।"},
  Voice_147528_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "তুমি যেন সবসময় আমার চারপাশে ঘুরঘুর করো……আমি বুঝেছি, তুমি নিশ্চয়ই আমার একজন ভক্ত।"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_147529_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "লালালা... হুঁ? পৃথিবী-সমাপ্তির বিপর্যয় নেমে আসছে? বুঝলাম... কিন্তু আগে চুলটা ঠিক করি, তারপর গিয়ে টিঙ্কটকে খুঁজে আনতে হবে..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "শশশ……কথা বলো না, খারাপ লোক আসছে। তারা আমাকে আর দিদিকে ধরে নিয়ে যেতে চায়, আর আমাদের জাহাজেও উঠতে দিচ্ছে না……"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নিরাপত্তা সম্পর্কে"
  },
  Voice_147532_AwakerVoiceContent = {Text = "—"},
  Voice_147532_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_147532_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "যখন আমি জেগে উঠলাম, গ্রহটি ধ্বংস হচ্ছিল। আমি দেখলাম রাতের আকাশ টুকরো টুকরো হয়ে খসে পড়ছে, পৃথিবী যেন প্রবল ঝড়ে ফুলে ওঠা একটা ক্যানভাস — প্রথমে বিকৃত হলো, তারপর ছিঁড়ে গেল, চূর্ণবিচূর্ণ হয়ে গেল।"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_147533_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "এটা আমার স্বাক্ষরিত পোস্টার, পিকম্যান মহাশয় নিজে এঁকেছেন। তুমি এটা রাখো, %player%।"
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ফেইন্ট সম্পর্কে"
  },
  Voice_147534_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ফেইন্ট\" অর্জনের পর আনলক হবে"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "হুঁ হুঁ? খুব কৌতূহলী? ধর্মমাতার ভাণ্ডার তো যে কাউকে এমনি দেখানো যায় না। ভেতরে কী ঠাসা আছে জানতে চাইলে, এখনই পরী সম্প্রদায়ে যোগ দিয়ে ফেলো না কেন, হিহি?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "তুমি কারাবুর কথা বিশ্বাস করছ না? উঁউঁ, সত্যিই কি সবাইকে ধোঁকা দেওয়া এত কঠিন… আসলে আমি @1 রাজ্যের বোহেমন্ড ষষ্ঠের অবৈধ কন্যা, ছদ্মবেশে মানবজগতে লুকিয়ে আছি, শত্রুসেনার হাত থেকে বাঁচতে নিজেকে পরী বলে পরিচয় দিয়েছিলাম… আমি তো তোমাকে আমার সবচেয়ে গুরুত্বপূর্ণ রহস্যটাই বলে দিলাম, তুমি কি এখনও আমাকে বিশ্বাস করবে না?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_149668_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "অনেক ব্যথা~"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "অনেক বেশি ক্যান্ডি খেয়েছি? না না না, এটাই হলো ধর্মমাতার হাসি ধরে রাখার গোপন রহস্য, দাঁতে পোকা লাগার মতো ছোট্ট ব্যাপারে থেমে যাওয়া কি সম্ভব? ~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "এসো, এই পরীর পাশে এসে দাঁড়াও। কী? সবাই মিলে ভাগ করে নৈবেদ্য খাব?… ঠিক আছে, যদি এটাই মিথাগের নিয়ম হয়… তাহলে আমার… আমার কোনো আপত্তি নেই, এসো, সবাই মিলে আনন্দ করি!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_149671_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "আহারে, সত্যিই বেশ ভক্তিমান ছোট্ট মেষশাবক তো।"
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "আরেকটু বেশি দিলে তবেই পরী তোমাকে আশীর্বাদ করবে, জানো?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "তোমরা এখনও একটু কাঁচা~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "এবারের উপাসনা অনুষ্ঠান আগের চেয়ে অনেক বেশি জাঁকজমকপূর্ণ, নৈবেদ্যর সংখ্যাও আরও বেশি হতে হবে… আরে, অবশ্যই মানুষ বলি দেওয়া হবে না, আমি তো একজন দয়ালু পরী, অন্যদের ক্ষতি করার মতো কাজ আমি করব না~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_149676_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "রক্ষক, আপনি কি কারাবুর মনের কথা শুনতে প্রস্তুত?\nকারাবু কোথা থেকে এসেছে, সেটা আসলে মোটেই গুরুত্বপূর্ণ নয়। গুরুত্বপূর্ণ হলো, আপনি আমার জন্য ঈশ্বরের দেওয়া সবচেয়ে মূল্যবান উপহার, আর কারাবু সিদ্ধান্ত নিয়েছে চিরকাল, চিরকাল আপনার মতো মহান মানুষের পাশে থাকবে।\nআপনি মনে করছেন এটাও কোনো কৌশলের অংশ, যাতে আপনি আর তদন্ত না করেন? হিহি, আপনিই বলুন না?\nযাই হোক, মনের কথা বলার পুরস্কার হিসেবে, কারাবুকে একটা আপেল ফ্লেভারের জেলি ক্যান্ডি দেবেন কি?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_149677_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_149678_AwakerVoiceContent = {
    Text = "হিহি~"
  },
  Voice_149678_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "কোনো ব্যাপার না, পরের বার এই পরীকে রক্ষা করার দিকে মনোযোগ দিলে আর ব্যর্থ হবে না~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "আমাকে ধোঁকা দেওয়ার কথা ভেবো না!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "ওয়াও, এত এত উপহার… কেহেম, হুঁ হুঁ, বেশ ভালো করেছ, পুরস্কার পাওয়ার যোগ্য! এসো, পরী তোমাকে একটি পরীর চুম্বন দিচ্ছে! কী ভাবছ, অবশ্যই কপালে!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_149683_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "সকল ভক্তদের নিবেদনের জন্য ধন্যবাদ! বিচক্ষণ ধর্মমাতা মন্দিরে তোমার জন্যও একটি খাঁটি সোনার মূর্তি নির্মাণ করবেন। আহা, এই মূর্তিটি যাতে আপনার সেই শীতল ও সুন্দর দেহভঙ্গি ফুটিয়ে তুলতে পারে, তার জন্য আরও ভালো করে খোঁজাখুঁজি করতে হবে~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_149684_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "তুমি? … তুমি আমাদের গির্জার এখনো আলোকপ্রাপ্ত না হওয়া একজন সদস্য, কারাবু ধৈর্য ধরে অপেক্ষা করবে যেদিন তুমি জগতের সত্য উপলব্ধি করবে। সেদিন, মনে রেখো ধর্মগুরুর জন্য তোমার দেহ, আনুগত্য আর সম্পদ উৎসর্গ করতে হবে, হিহি।"
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "তালিকার সব কিছু……এত তাড়াতাড়ি জোগাড় হয়ে গেল? মিথাগের আর্থিক সামর্থ্য সত্যিই অতল গভীর……আগে জানলে আমি……হুঁ হুঁ? আমি কী বিড়বিড় করছি? শুধু লর্ড ডেক্সটারের উদারতার জন্য কৃতজ্ঞতা জানাচ্ছি, হিহি~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_149686_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "সবচেয়ে ঘৃণার জিনিস? অবশ্যই সেই সব জাদুকর যাদের চুক্তির কোনো মূল্যবোধ নেই। একটা গোপন কথা চুপিচুপি বলি, আসলে সব জাদুকরই বড় প্রতারক, তারা যা কিছু ভবিষ্যদ্বাণী আর অভিশাপ বলে সেগুলো সব তোমাকে নিঃস্ব করে দেওয়ার জন্য! আর সাবধান থাকার উপায়… শুধু তোমার সব অর্থকে পরীর আশীর্বাদে ঢেকে দিলেই হবে!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "প্রথম সাক্ষাৎ, আমি দূর থেকে আসা ফ্যাকাশে পরী, একটু জানতে আগ্রহী? পরীর আশীর্বাদ সদস্যপদের স্তর অনুযায়ী ভিন্ন মাত্রায় পাওয়া যায়, হিহি~"
  },
  Voice_149688_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_149689_AwakerVoiceContent = {
    Text = "আগের উপাসনা অনুষ্ঠানে, সাত স্তরের প্রার্থনা ও তিন স্তরের শপথের পাশাপাশি, ভক্তরা আমার জন্য বিশেষভাবে নতুন মন্দির নির্মাণ করত এবং প্রচুর নৈবেদ্য উৎসর্গ করত। এই নাও তালিকা!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_149689_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "এসো, যা কিছু ছেড়ে দিতে চাও সব গভীর তুষারে কবর দাও……"
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "শুনলাম তুমি আমার জন্মপরিচয় নিয়ে খোঁজখবর করছ, হিহি, এটা তো ধর্মমাতার গোপন রহস্য। তবে, যদি তুমি সত্যিই তদন্ত করতে চাও, তাহলে পরী সম্প্রদায়ে আমার নিজের লেখা জীবনী সংরক্ষিত আছে, মাত্র দশ লক্ষ সিলভার জমা দিলেই পড়তে পারবে, চেষ্টা করে দেখবে?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_149691_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "বেশ ভালোই তো, এখানে অনেক খুব প্রিয় বাচ্চা আছে আর এতটাই উদার জীবনযাত্রার ভাতা যে রীতিমতো অবাক করে দেয়। তাদের সাহায্যে, আমি দেরিতে হলেও পূর্বে যাওয়ার পথের খরচ জমাতে পারব…"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "গডমাদারকে প্রণাম করতে ভুলো না, হিহি।"
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "দুঃখিত, পরীর রাজ্য অত্যন্ত পবিত্র, অদ্ভুত নেকড়েমানুষদের স্বাগত জানানো সম্ভব নয়... বাতাসে মিথ্যার গন্ধ আছে বলছে? ওর নাক নিশ্চয়ই ঠিকমতো কাজ করছে না।"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "চ্যাট: রাইকার সম্পর্কে"
  },
  Voice_149694_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"রাইকার\" অর্জনের পর আনলক হবে"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "আরে, কেউ বলছে আমি নকল পরী... ধরা পড়ে গেলাম তাহলে, হিহি। আমি জানি তুমি এতে কিছু মনে করবে না, তাই না?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "গল্পগুজব·গুজব সম্পর্কে"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "উমম, সত্যিই সুস্বাদু~"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "নিশ্চিন্তে থাকো~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "পথভ্রষ্ট মেষশাবকেরা, এই পরী তোমাদের পাপ ধুয়ে দিতে এসেছে, হিহি~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "এখনও হাল ছাড়োনি? ঠিক আছে, তাহলে কারাবু নিজেই তোমাকে বলুক। আসলে কারাবু হলো পূর্বদেশের এক আকাশছোঁয়া তুষারপর্বতের অধিষ্ঠাত্রী দেবী উমাপতির কন্যা… হুঁ, তুমি বলছ সেই দেবীর কেবল দুই পুত্র আছে, কোনো কন্যা নেই? দেবতাদের সম্পর্কিত নথিতে সবসময় কিছু না কিছু ত্রুটি থাকেই।"
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_149699_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "ঝনঝন~ পরীর আলো এখন তোমার উপর পড়েছে, এগিয়ে যাও!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "আচ্ছা আচ্ছা, আর খোঁজাখুঁজি করো না, কেমন? এই অপমানজনক কাজটা ভদ্রভাবে বন্ধ করার পুরস্কার হিসেবে, আমি চুপিচুপি আমার সবচেয়ে মূল্যবান মিষ্টির অর্ধেক তোমাকে দিতে পারি। জেনে রাখো, পূর্বাভিযানের যুদ্ধক্ষেত্রে মিষ্টি মিষ্টি ক্যান্ডি কিন্তু বেশ দুর্লভ জিনিস।"
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_149701_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "কারাবুর আশীর্বাদ পৃথিবীর সব রোগ সারাতে পারে, অবশ্যই এই কালো মহামারীও সারাতে পারবে… অবশ্যই এটা সত্যি, শুধু তোমাকে যথেষ্ট ধার্মিক হতে হবে এবং কারাবুকে যথেষ্ট বিশ্বাস করতে হবে, হিহি।"
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_149703_AwakerVoiceContent = {
    Text = "বিরক্তিকর!"
  },
  Voice_149703_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "পরীর আলোকচ্ছটা~"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "সাত স্তরের প্রার্থনা, তিন স্তরের শপথ, এগুলো দিয়ে পরীর ক্ষমা অর্জন করো!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "অনুভব করো!"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "আরে, ওজিয়ার আপনাকে ভেতরে ঢুকতে দিল কীভাবে? সবাইকে আটকে রাখার কথা ছিল না কি? আপনি তার প্রভু...? এই অবিশ্বস্ত ছোট্ট ছেলেটা সত্যিই বিরক্তিকর, এই সমাবেশের জন্য আমি কত পরিশ্রম করে প্রস্তুতি নিয়েছি। তাহলে... পাওয়া নৈবেদ্য পঞ্চাশ-পঞ্চাশ ভাগ করে নিই, আর আপনি আমাকে ছেড়ে দিন, কী বলেন?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "গল্পগুজব：ওজিয়ার সম্পর্কে"
  },
  Voice_150104_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ওজিয়ার」 অর্জনের পর আনলক হবে"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "তাড়াতাড়ি, গুছিয়ে ফেল! রাস্তায় বেশি দেরি কোরো না।"
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "আমি ঘুমিয়ে থাকার সময় সে ধর্মসংঘে যোগ দিয়েছিল, তার সাথে আমার তেমন কোনো যোগাযোগ নেই।\nতবে, শুনেছি সে নিজে থেকেই এসেছিল। মানবদেহ ত্যাগ করে পুরোপুরি 'সাগরযাত্রী' হতে চেয়েছিল... হুঁ, শক্তির নেশায় মাথা খারাপ হওয়া আরেকটা বোকা।"
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কেকাস সম্পর্কে"
  },
  Voice_36679_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "গোলিয়াথ কোনোদিনই অনুগত পোষ্য ছিল না। মিরিয়াম কেন তাকে এত মূল্য দেয়, আমি বুঝি না… ওকে শেকলে না বাঁধা থাকলে, সে অনেক আগেই পালিয়ে গিয়ে তাকে বিশ্বাসঘাতকতা করত।"
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "চ্যাট: গোলিয়াথ সম্পর্কে"
  },
  Voice_36680_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "সমুদ্রযাত্রীরা জন্ম থেকেই এই রূপে থাকে না। মানুষের মাঝে লুকিয়ে থাকার জন্য, তাদের জীবনের প্রথমার্ধ মানুষের থেকে আলাদা কিছু নয়……\nতোমার সাবধান থাকা উচিত, হয়তো তোমার প্রিয় কেকের দোকানের মালিকও তাদেরই একজন, কে জানে?"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "চ্যাট: সাগরচারীদের সম্পর্কে"
  },
  Voice_36681_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "সেলেস্ট-এর বেসুরো সাগরের গাথা, দলনেতার স্বাক্ষরধর্মী ধোঁয়াটে মাছের স্ট্যু, সাগরের হাওয়ায় শক্ত আর মাছের গন্ধে ভরা কম্বল… টানটান আর বিপজ্জনক হলেও, সাগরে নির্বাসনের সেই কয়েক মাস আমি কখনো ভুলো না।"
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "গল্পগুজব: 「ভূতুড়ে জাহাজ」 প্রসঙ্গে"
  },
  Voice_36682_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "যদিও স্কুলে সবাইকে দেখে মনে হয় খুব ব্যস্ত, কিন্তু……\nকিন্তু এখানে, এমন এক প্রশান্তি অনুভব করি যা আগে কখনো করিনি।\nএকই লক্ষ্যে একসাথে জড়ো হয়ে, একসাথে সেই লক্ষ্যে এগিয়ে যাওয়ার অনুভূতি……হুম, মন্দ না বলতে হবে।"
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে II"
  },
  Voice_36683_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "বিছানা খুব শক্ত, আবহাওয়া খুব ঠান্ডা, বিকেলের লাল চা সবসময় ঘাসের জলের মতো বানানো হয়…… এই মহিলার এখানে পছন্দ না করার হাজারটা কারণ আছে।\nতবে, শুধু 'তুমি এখানে আছো' এই একটা কারণেই, আমি জোর করে থেকে যেতেও পারি না এমন নয়……"
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে III"
  },
  Voice_36684_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "ধন্য, ধন্যবাদ……এ? তোমাকে কেন ধন্যবাদ দিচ্ছি? এ, এটা কি বলতে হবে নাকি! অবশ্যই সমুদ্রে তুমি আমার জন্য যা কিছু করেছ তার জন্য……\nএকটু দাঁড়াও, তুই কেন হাসছিস? তুই এই আমাকে বোকা বানাতে চাইছিস, তাই না!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে II"
  },
  Voice_36685_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "আমি একসময় ভেবেছিলাম, আমার আর তার মধ্যে একটা পারিবারিক বন্ধন আছে……\nকিন্তু সব কিছু ঘটে যাওয়ার পর আমি বুঝতে পারলাম, হয়তো, সেই ক্ষণিকের উষ্ণতা শুরু থেকেই শুধু আমার একতরফা ভাবনা ছিল।\nতুমি তার সাথে কী করবে, সেটা তোমাদের ব্যাপার, শুধু তাকে আর আমার কাছে আসতে দিও না।"
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিরিয়াম প্রসঙ্গে II"
  },
  Voice_36686_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "কেমন অদ্ভুত……এই অনুভূতিটা সত্যিই খুব অদ্ভুত।\nহৃদয় স্পষ্টতই আর স্পন্দিত হচ্ছে না, তবুও শরীর এখনও উষ্ণ……এই, এদিকে এসো, আমার হাত ছুঁয়ে দেখো, বলো যে এটা কোনো বিভ্রম নয়।"
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "চ্যাট: 「জাগরণকারীরা」 সম্পর্কে"
  },
  Voice_36687_UnlockDesc = {
    Text = "প্রধান গল্পের ষষ্ঠ অধ্যায় সম্পন্ন করার পর আনলক হবে।"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "আমি হয়তো লিও রাজ্যে জন্মাইনি, কিন্তু মুক্তির মহাসভাগৃহেই আমি আমার দ্বিতীয় জীবন পেয়েছি। তবে কেন আমি এই স্থানকে আমার গৃহ বলে ভাবতে পারব না?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "চ্যাট: ঘর সম্পর্কে"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "অদৃশ্য মহামারী বহু বছর ধরে তাণ্ডব চালানোর পর, পিতৃদেবতা অবশেষে আমার প্রার্থনা শুনেছেন এবং আমাকে এই দুর্দশার বিরুদ্ধে লড়াই করার জন্য এই 「আশীর্বাদ」 প্রদান করেছেন। এটি সত্যিই জীবন দান করতে পারে, তবে এর একটি মূল্যও আছে।\nপ্রতিনিধি হিসেবে, যারা এই আশীর্বাদ গ্রহণ করেছে তাদের পক্ষে সেই মূল্য বহন করা আমার কর্তব্য।"
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "চ্যাট: তাঁর 「আশীর্বাদ」 সম্পর্কে"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "আমার কাছে, জাগ্রত সত্তার এই অবস্থা হলো পিতৃদেবতার কোলে আশ্রিত আত্মাদের প্রতি তাঁর আশীর্বাদ। এটি দ্বিতীয় জীবন, এবং অতীতের অপূর্ণতা পূরণ করার একটি সুযোগ।\nআমি পিতৃদেবতার কার্য চালিয়ে যাব, প্রতিনিধির দায়িত্ব পালন করব, এবং আরও বেশি দুঃখকষ্ট দূর করব।"
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "চ্যাট: 「জাগরণকারীরা」 সম্পর্কে"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "আমার ইচ্ছার প্রতি সম্মান দেখিয়ে এবং আমার গোপন কথা কমিটির কাছ থেকে গোপন রাখার জন্য আবারও তোমার কাছে কৃতজ্ঞতা জানাই, রক্ষক। আমি আশঙ্কা করি, তাদের হস্তক্ষেপ হলে জীবনের ধর্মসভায় আমার সেবা চালিয়ে যাওয়ার পথ আমার জন্য বন্ধ হয়ে যেত।"
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "চ্যাট: রক্ষক সম্পর্কে: II"
  },
  Voice_45156_UnlockDesc = {
    Text = "বিশেষ অভিযান রেকর্ড 「রক্তের রঙ」 ক্লিয়ার করার পর আনলক হবে"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "ওই বালকটি আন্তরিক, অবিচল ইচ্ছাশক্তিসম্পন্ন এবং দয়ালু, বিরল উজ্জ্বল এক আত্মা নিয়ে। আমার জীবনের প্রথম অধ্যায়ে শেষবার এমন এক সত্তার সঙ্গে দেখা হয়েছিল।"
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ওজিয়ার সম্পর্কে"
  },
  Voice_45157_UnlockDesc = {
    Text = "বিশেষ অভিযান রেকর্ড 「রক্তের রঙ」 ক্লিয়ার করার পর আনলক হবে"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "দৃষ্টি হারানো মানে এই নয় যে আমি অন্ধ হয়ে গেছি। পিতৃদেব আমার ওপর অন্ধকার নেমে এনেছেন বটে, কিন্তু সেই সঙ্গে তিনি আমাকে আত্মার ক্ষীণ আলোকরেখাও দেখার ক্ষমতা দিয়েছেন।"
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "চ্যাট: দৃষ্টিক্ষেত্র সম্পর্কে"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "সেই সময়ে আমি 「আশীর্বাদ」 লাভ করলেও, শেষ পর্যন্ত একজন সাধারণ মানুষই ছিলাম। কষ্টভোগীর সংখ্যা ছিল অগণিত, 「আশীর্বাদ」 প্রয়োজন এমন মানুষও ছিল অসংখ্য। আমি তাদের সবাইকে রক্ষা করতে চেয়েছিলাম, কিন্তু সফল হতে পারিনি।\nএটাই আমার সবচেয়ে বড় আক্ষেপ, এবং আমার চিরন্তন অপরাধবোধ।"
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "চ্যাট: তাঁর প্রথম জীবন সম্পর্কে"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "পবিত্র মন্দিরের অনেকেই মনে করেন, 《পবিত্র গ্রন্থ》-এ উল্লিখিত \"সাদা শিখা\" আসলে চাঁদের আলোকে বোঝায়: ফ্যাকাশে দূত চাঁদের আলো থেকে আবির্ভূত হবেন এবং আমাদের দুর্দশা থেকে মুক্তি দেবেন।\nকিন্তু আমি জানি, প্রকৃত শিখা হলো সেই আত্মা যা তোমার ও আমার হৃদয়ে জ্বলছে।"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "চ্যাট: 「ফ্যাকাশে শিখা」 সম্পর্কে"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "আসলে, আমার পরিচয় গোপন রাখা মহাযাজকের নির্দেশ ছিল। তিনি কারণ বিস্তারিত বলেননি, শুধু সতর্ক করেছিলেন: সবচেয়ে পবিত্র স্থানেও ছায়া লুকিয়ে থাকতে পারে, ভালো কাজ করতে গেলেও সতর্ক থাকা দরকার।\nঅবশ্যই, তোমার উপর আমার পূর্ণ আস্থা আছে।"
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "চ্যাট: পরিচয় গোপন রাখা সম্পর্কে"
  },
  Voice_45161_UnlockDesc = {
    Text = "বিশেষ অভিযান রেকর্ড 「রক্তের রঙ」 ক্লিয়ার করার পর আনলক হবে"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "আমার গান কি তোমার কোনো উপকারে এসেছে?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "ধুর, সে তো স্রেফ একটা ছেলে! তোমরা সবাই কেন তাকে এত সম্মান করো?! আমাকেও একই ভক্তি দেখাবে, বুঝেছ?!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_4909_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "শোনো, তুমি কি জানো অন্য জাগরণকারীরা সাধারণত কী করে? ভুল বোঝো না, আমি বন্ধু চাই না, আমি শুধু… আমি স্রেফ একটা পরিদর্শন করছি!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "গল্পগুজব: দৈনন্দিন জীবন প্রসঙ্গে"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "ধুর শালা! পরের বার, ওদের লাশগুলো মাকড়সাদের রাতের খাবার হিসেবে ছুড়ে দেব!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "আভা।"
  },
  Voice_4912_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_4913_AwakerVoiceContent = {
    Text = "ছন্দ।"
  },
  Voice_4913_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "বেশ সাহসী তুমি।"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "চল একটু ধীরে চলি... তোমার জন্য আমি কি কোনো কিছুই করতে পারি?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "কী স্পর্ধা তোমার!"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(গভীর আগ্রহের সাথে জিজ্ঞাসা)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "আমি কী ভালোবাসি? আমার শিশু, সেই দিব্য ভ্রূণ, যে আমাকে সম্মান এনে দিয়েছে, অবশ্যই। তুমি কি ভাবো, এমন কথা বলা আমার স্বভাববিরুদ্ধ?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "তোমার উদ্দেশ্য কী?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "মন্দ হলো না, তাই না? এবার, আমার পাওনা—কি? ভেবেছিলে নাকি এটা ফ্রি খাওয়ানো?!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "দূরে সরে যাও!"
  },
  Voice_4921_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "সতর্ক থাকো!"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "কী মহিমান্বিত বিজয়... এই মুহূর্তটিকে আমি চিরকালের জন্য খোদাই করে রাখব।"
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "আমি অনুভব করছি... অশুচিতার উৎসকে... আমাদের প্রকৃত রূপের আরও এক ধাপ কাছে... আহ্‌, আমি এই বিশ্বটাকেই ছিঁড়ে টুকরো টুকরো করে ফেলব!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_4924_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "আমরা... প্রস্তুতি শেষ করেছি। আদেশ দিন, রক্ষক।"
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_4925_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "{Male=স্যার,Female=ম্যাডাম}, আপনি সত্যিই দয়ালু। দুর্ভাগ্য, আমি তো এতই মূল্যহীন যে আপনাকে ফিরিয়ে দেওয়ার মতো কিছুই আমার নেই..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_4926_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "...আর একটু দূর গেলেই, আমি কি পুরোপুরি 「ওদের」 থেকে আলাদা হয়ে যাব?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_4927_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "হঁ? আমি এখনো বেঁচে আছি... তুমি... তুমি সত্যিই আমার অঙ্গ চুরি করবে না, বা আমাকে নিয়ে কোনো পরীক্ষা-নিরীক্ষা করবে না?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_4928_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "উইঙ্কলের নিজস্ব প্রজাতি জৈব মস্তিষ্কে অনুপ্রবেশ করতে পারে, যার ফলে আমার সঙ্গে মিশে থাকা বহির ইচ্ছা তাকে ভয় পায়। কিন্তু এখন, সে কেবল একটি খোলের ভেতর বন্দী এক করুণ আত্মা মাত্র।"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উইঙ্কল প্রসঙ্গে"
  },
  Voice_4929_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "সবকিছু। আমি সবকিছুই ভালোবাসি। সকলে যখন টেবিল ঘিরে বসে খাওয়া আর প্রার্থনা করে, কিংবা রক্ষক মিশনে বাইরে থাকলে, আপনার বিজয়ী প্রত্যাবর্তনের প্রতীক্ষা—যে সময়টা বাতাস ভরে থাকে আনন্দে... আমি কি সত্যিই এমন সুখ পাওয়ার যোগ্য?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "তলিয়ে যাও।"
  },
  Voice_4931_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "বিকশিত হও।"
  },
  Voice_4932_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "「বিশ্বাস」, 「অন্ধ আনুগত্য」, 「দাস」, 「স্নেহ」, 「সম্মান」... ভাষা মডিউল পুনর্গঠন ও শিক্ষণ চলছে। অনুগ্রহ করে, রক্ষক, আমাকে পথ দেখান।"
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_4933_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "এরিকা বর্তমানে স্ট্যান্ডবাই মোডে আছে। দেহের কুলিং সম্পূর্ণ হতে আরও 1 ঘণ্টা 15 মিনিট লাগবে। <Del:To turn Erica on, offer your beating heart> জরুরি চালু করবেন? ... অনুমতি যাচাই চলছে... রক্ষকের সর্বোচ্চ কর্তৃত্ব নিশ্চিত হয়েছে। হ্যালো, রক্ষক।"
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_4934_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "তদন্ত মিশনের গড় বিপদ সূচক ৭, গড় চিকিৎসা ব্যয় আলকেমি সাপ্লিমেন্ট ৮ বোতল, গড় মৃতদেহ পরবর্তী প্রক্রিয়াকরণ সময় দশ ঘণ্টা।\nসিদ্ধান্ত: গোপনরক্ষকদের কাজ অত্যন্ত বিপজ্জনক, অভিযানের সময় অনুগ্রহ করে নিরাপত্তার দিকে খেয়াল রাখুন।"
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_4935_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "শিক্ষক রেকর্ড অনুসন্ধান: এরিকা লেফিল্ড, সিলভার মেকাট্রনিক্স ও অটোমেশন লেকচারার, মৃত—এটা কি আপনি খুঁজছিলেন না? ঠিক আছে, 「এরিকা」 কীওয়ার্ড পুনরায় অনুসন্ধান করা হচ্ছে।"
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_4936_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "আপনাকে যদি কোনো তথ্য খুঁজে দেখতে হয়, অনুগ্রহ করে ফাইলের পূর্ণ নাম প্রদান করুন। অস্পষ্ট অনুসন্ধান ফাংশনটি বর্তমানে সংগ্রহযোগ্য নয়।"
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_4937_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_4939_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_4941_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "চার্জ সম্পন্ন, বিস্ফোরণের জন্য প্রস্তুত।"
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "চার্জ সম্পন্ন, বিস্ফোরণের জন্য প্রস্তুত।"
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "আবার এমন তুচ্ছ ব্যাপারে আমার বিশ্রাম ভঙ্গ কোরো না।"
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "যেমন করে আমি টিঙ্কটকে রক্ষা করেছি, তেমনি তোমাকেও রক্ষা করব।"
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "আমি কোনো গুরুত্বপূর্ণ ব্যক্তি নই, কেবল অসংখ্য ভক্ত আত্মার ভিড়ের একজন মাত্র। আমি আমার জীবন উৎসর্গ করেছি সেই মহিমান্বিত সত্তার উদ্দেশে, আর একটিমাত্র দৃষ্টির অনুগ্রহ লাভের জন্য আমি কখনোই আমার সবকিছু উৎসর্গ করা থামাব না।"
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত প্রসঙ্গে"
  },
  Voice_4946_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "আমার দিকে চেয়ে থাকো!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "আমার দিকে চেয়ে থাকো!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "…তাদের উন্মত্ততা যতক্ষণ না আমাকে জাগিয়ে তোলে, ততক্ষণ কিছুই যায় আসে না। একই কক্ষে থাকা সহ্য করা যায়।"
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "চ্যাট: সাগরচারীদের সম্পর্কে"
  },
  Voice_4949_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」, 「গোলিয়াথ」, 「কেকাস」, 「সাঙ্গা」 বা 「ফারোস」–এর যেকোনো একটিকে অর্জনের পর আনলক হবে।"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "আমি ওই অন্ধকার অনুভূতিটা ঘৃণা করি, যেন আমার হৃদয়টা ফাঁপা করে তুলে নেওয়া হয়েছে। অপূর্ণতার সেই অনুভূতি আমার পুরো দেহকাঠামো জুড়ে চুলকানি ধরিয়ে দেয়..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "না, না, না, করো না! ওটা নিয়ে কথা বলো না..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_4953_AwakerVoiceContent = {Text = "হা!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_4954_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_4954_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "যারা দেবতাদের রিয়েল্মের পতন ঘোষণা করে, সেই ইতিহাসবিদরা তাদের অনুমানে ক্লান্তিকর... তবু নিছক শব্দ তো অর্থহীন ফেনা; গৌরবময় পুনরুত্থানকে কেউই থামাতে পারবে না।"
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "আসলে… তোমাকে একটা রহস্য বলি। আমি আমার বর্তমান মোটরসাইকেলটা নিয়ে পুরোপুরি সন্তুষ্ট নই—এটা না যে আমি ওটাকে অপছন্দ করি! শুধু মনে হয়, যেন কিছু একটা এখনো অপূর্ণ…"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_4957_AwakerVoiceContent = {Text = "হা!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_4958_AwakerVoiceContent = {
    Text = "চাক্!"
  },
  Voice_4958_AwakerVoiceTitle = {
    Text = "দক্ষতা·2: উন্মাদনা"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "দুঃখিত... আমি এটা ঘটতে চাইনি..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "দক্ষতা·2: বিষণ্ণতা"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(কৌতূহলী ফিসফিসানি)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2 সালে, মি. ওয়ার্ড·ফিলিপস, মি. ক্লার্কাস এবং মিস টাওইল একসঙ্গে মিথাগ কলেজ প্রতিষ্ঠা করেন। দীর্ঘ বিকাশের পর, তা <Del:this damned prison> মিথাগ বিশ্ববিদ্যালয়ে পরিণত হয়।"
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "ন্যায়বিচার, আনুগত্য, স্থিতিস্থাপক মনোবল, শৃঙ্খলা। বহু আগেই এগুলো আমার হৃদয়ে খোদাই হয়ে গেছে।"
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "আপনি যে দায়িত্ব আমার উপর অর্পণ করেছেন, আমি তা যথাযথভাবে সম্পন্ন করব।"
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "কেমন দায়িত্বজ্ঞানহীন বাবা-মা তাদের কন্যার নাম রাখে গর্গনের মাথা দিয়ে গড়া এক চরিত্রের ঢালের নামে? ...তার তো কোনো বাবা-মা নেই? হুঁ... এই কথোপকথনটা আমাদের মধ্যেই থাক।"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আইগিস প্রসঙ্গে"
  },
  Voice_4964_UnlockDesc = {
    Text = "\"জাগরণ\" \"আইগিস\" অর্জনের পর আনলক হবে"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "বোর লাগলে গোলকধাঁধায় এসে না-হয় আমাকে \"সঙ্গ দাও\"? শেষ পর্যন্ত, তোমার আশাহীন জীবন আর এই অন্তহীন গোলকধাঁধার মধ্যে তো কোনো পার্থক্যই নেই!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "চ্যাট: গোলকধাঁধা সম্পর্কে"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "ডল আশেপাশে থাকলে অনুসন্ধান কর্মকর্তাদের দক্ষতা ৭৮.৩১২% বৃদ্ধি পায়, কিন্তু আরও বেশি মানুষ আবেগগত মন্দায় ডুবে যায়। তার ভাষায়: \"কিছু লোক যদি মুখ বন্ধ রাখতে পারত, পৃথিবী আরও মসৃণভাবে চলত।\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডল সম্পর্কে"
  },
  Voice_4966_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ডল」 অর্জনের পর আনলক হবে"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "নেমে এসো!"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "কেমন ছিল সেটা?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "অভিযান কে না ভালোবাসে? অনাবিষ্কৃত রহস্যময় রিয়েল্মে ডুবে যাওয়া, অজানা জীব আবিষ্কার করা, আর নিজের গল্প নিজেই বুনে নেওয়া… কতই না রোমাঞ্চকর!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "চ্যাট: অভিযান সম্পর্কে"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "অভিবাদন। আমি Febvre-এর নিম্ফিয়া। আপনি আমাকে একটি নতুন দেহ দান করেছেন, যা আমাকে অবশেষে মুক্ত শ্বাস নিতে দিয়েছে... এই অনুগ্রহের প্রতিদান আমি কীভাবে দিতে পারি?"
  },
  Voice_4970_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_4971_AwakerVoiceContent = {
    Text = "মনে হচ্ছে, যারা নিজেদের আমার প্রভু বলে দাবি করত, তাদের বিলাপ আবারও শুনলাম। কতই না মনোরম।"
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_4971_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "আমি কি সবজি বাদ দিতে পারি? টিঙ্কট বলেছে খেতে বেছে বেছে খাওয়া ঠিক নয়, কিন্তু তাদের মূল বর্ণগুলো আমার ভালো লাগে না..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "সর্বপিতা একদা বলেছিলেন: “দুঃখ আমার সৃষ্টি নয়। হে আমার দূতেরা, তোমরা তা বহন করো এবং দ্রবীভূত করো, আর গড়ে তোলো এক দুঃখহীন ভূমি।” এই লক্ষ্যে আমি সবকিছু উৎসর্গ করতে প্রস্তুত। এমনকি আমার জীবনও।"
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_4973_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "সবকিছু গ্রাসকারী ডিজলিউশনের অভিশাপের সামনে অন্য সব দুঃখ ফ্যাকাশে হয়ে যায়। আমি যদি অন্যদের হয়ে এই অভিশাপ বহন করতে না-ও পারি, তবু তাদের পেইন লাঘব করতে আমি আমার সর্বোচ্চ চেষ্টা করব।"
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_4974_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "আমি কি এখন তাদের পেইন কিছুটা হলেও লাঘব করতে পারি, তাদের আত্মাকে সান্ত্বনা দিতে পারি?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_4975_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "অতএব, আমি সব দুঃখ নিজের কাঁধে তুলে নেব, যেন সব প্রাণের জন্য পেইনমুক্ত এক ভূমির পথ প্রশস্ত হয়।"
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_4976_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "আমার আত্মার গভীরে যে উষ্ণতা জেগে উঠেছে... এই উপহারের জন্য ধন্যবাদ, ফ্যাকাশে শিখা। এই শক্তি দিয়ে হয়তো আমি অবশেষে তাঁর দূত হিসেবে আমার দায়িত্ব পালন করতে পারব, আর তাঁর আরও বেশি বালকেরা‌কে রক্ষা করতে পারব।"
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_4977_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "আমি কি সত্যিই এ সব গ্রাস করতে পারব?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_4978_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "হুঁহ। তুমি যা দেখছ, তা মৃত্যু নয়। শুধু তোমার ভবিষ্যৎ। আমার। আর সকলে’র।"
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "টিঙ্কট... তার শোকগাথা শুনলেই আমার নাচতে ইচ্ছে করে..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "চ্যাট: টিঙ্কট সম্পর্কে"
  },
  Voice_4980_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"টিঙ্কট\" অর্জনের পর আনলক হবে"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "পার্থিব পরীক্ষাগুলো কি সত্যিই আমার রক্তধারার সম্ভাবনাকে জাগরণ করাতে পারে? তা, আমি কল্পনাও করিনি।"
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "অস্ত্রটা এখন হাতে আরও স্বচ্ছন্দ লাগছে।"
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "এতে আমার কৃতজ্ঞতা পাবে ভেবো না। আমার সম্ভ্রান্ত বংশপরম্পরা তা কখনোই মেনে নেবে না।"
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_4984_AwakerVoiceContent = {
    Text = "আঃ, উঃ!"
  },
  Voice_4984_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "ও লোকটা... এই, দাঁড়াও, আমাদের বাজিটা তো এখনো শেষ হয়নি, তাই না?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অন্যদের সম্পর্কে"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "আমি একাডেমির রেকর্ডারটা ভীষণ পছন্দ করি। যদি এমন একটা পোর্টেবল সংস্করণ বানাতে পারতাম, যা আমাকে রিয়েল-টাইমে মনে করিয়ে দিত আমি কী কী ভুলে গেছি…"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "হুঁ, পিঁপড়ের এক সমাবেশ... না, পিঁপড়েও নও—তোমাদের মতোরা তো কেবল রুটির কণা, তাঁর মৃত্তিকা বিদীর্ণ পুনর্জন্মের পুষ্টি মাত্র।"
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "রসদ এসে পৌঁছেছে।"
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "রসদ এসে পৌঁছেছে।"
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "হুম... আরও জোরে, আরও। হ্যাঁ, ঠিক এভাবেই..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "আমার রক্তধারার পূর্ণ জাগরণ ঘটার আগেই, বিজয় যেন অনায়াসেই এসে গেল।"
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "ওহ না, আমার টুপি বেঁকে গেছে... হুম, এভাবে কেমন? হ্যাঁ, একদম! নিখুঁত!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_4992_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"এমন ক্ষমতার অধিকারী আমি, সত্যিই কি এখনও মানুষ?\" যুদ্ধ প্রশিক্ষণ শুরু করার পর থেকে প্রতিদিন আমি নিজেকে এই প্রশ্ন করি। আমি এই পৃথিবীকে ভালোবাসি, যদিও এটি এতটাই ধূসর, কলুষিত আর নীরস, তবু তোমাদের অস্তিত্ব একে ধূলিকণার মাঝে হীরার মতো ঝলমলে করে তোলে।\nএকসময় আমি খুব ভয় পেতাম, শক্তি বাড়ার সাথে সাথে মানুষ হিসেবে আমার অবস্থান হয়তো বদলে যাবে……এখন, আমি কৃতজ্ঞ যে তুমি আমার পাশে আছো, আমাদের মধ্যকার এই সমঝোতা আমাকে মানবজগতের সাথে শক্ত করে বেঁধে রেখেছে। সামনের দিনগুলোতেও, তোমার কাছে সাহায্য চাইব, গোপনরক্ষক।"
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_4993_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "আহ... তোমার উদ্বেগ থাকা স্বাভাবিক। আমি বিষয়টা আগে ভেবে দেখিনি। তোমার সঙ্গী হিসেবে, শুরু থেকেই আমার সব ব্যাখ্যা করা উচিত ছিল। যেমন তুমি দেখছ, আমার মধ্যে কিছু অস্বাভাবিক বৈশিষ্ট্য আছে, যা সম্ভবত আমার অতীতের সঙ্গে জড়িত। কৌতূহলী না হয়ে থাকা অসম্ভব, তাই না? কিন্তু একাডেমির মতো একটি আশ্রয় আমার জন্য এক আশীর্বাদ, তাই আমি ভাগ্যের পর্দা সরিয়ে ফেলার সিদ্ধান্ত নিই না।"
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_4994_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "তুমি সেই মহিলার সাথে দেখা করেছ, তাই না? সেই সাদা ওড়না পরা জাগরিত সত্তা, সে এই বিশ্ববিদ্যালয় প্রতিষ্ঠার ভিত্তিগুলোর একটি……\nকিন্তু সত্যি বলতে, আমি তাকে পছন্দ করি না। সবকিছুকে তুচ্ছ মনে করা, যেন পুরো পৃথিবী নিয়ে তার কোনো মাথাব্যথা নেই — এই মনোভাব সত্যিই রাগ ধরিয়ে দেয়……আহ, তুমি বলছ আমি আর সে দেখতে একরকম? চলো তোমাকে ক্যাম্পাস হাসপাতালে নিয়ে যাই চোখ পরীক্ষা করাতে?"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_4995_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "তুমি কি আমার আর প্রফেসর ডেক্সটারের সম্পর্ক নিয়ে কৌতূহলী? এটা কোনো গোপন বিষয় নয়। উনি আমার পালক পিতা। আর আমার মা… আমি বড় হয়েছি এই স্কুলেই, সব শিক্ষকের যত্নে। তবে, তাদের মধ্যে আমি প্রফেসর ডলের সবচেয়ে কাছের।"
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_4996_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "জাগরণকারী বিষয়ক দপ্তরের প্রক্রিয়া হোক, বা ক্যান্টিনে ইন্ডিয়ান ফুড খাওয়ার তারিখ—মিথাগ সম্পর্কে যেকোনো জিজ্ঞাসা তুমি আমাকে করতে পারো। দুশ্চিন্তা কোরো না, তুমি আমাকে বিরক্ত করছ না। আমি কি এতটাই অমায়িক নই দেখায়?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_4997_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "আয়না, আয়না, সারা বিশ্বের শ্রেষ্ঠ জাদুকর কে? আমি? সেটাই তো সংশোধন!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_4998_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "মন্দ নয়।"
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "চমৎকার!"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "এটা... সত্যিই কাজ করেছে? আমি কি সত্যিই কোনো প্রকৃত সাহায্য করতে পেরেছি?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "নিষ্ফল!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(সহনশীলতা)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "এদিকে তাকাও!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "চলো, এটাকে আমাদের কোলাহলমুখর সুখের সাগর বানাই!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "আমাকে প্রহরী হয়ে তোমার সঙ্গে থাকতে হবে? যদি তোমার অনুসন্ধান ন্যায়সঙ্গত হয়, আমি তোমাকে সহায়তা করব।"
  },
  Voice_5007_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5008_AwakerVoiceContent = {
    Text = "অগ্নিশিখা আমাকে গ্রাস করবে না।"
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "অগ্নিশিখা আমাকে গ্রাস করবে না।"
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "ওহ... তুমি কি একটা আলিঙ্গন চাও?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "আমার গায়ের এই শৃঙ্খলগুলো দেখ—এগুলো অলংকার নয়, স্মারক। বিশ্বাসঘাতকতা আর অপমানের স্মারক।"
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "যদি একাডেমির অতীত সম্পর্কে জানতে চাও, আমি তোমাকে আর্কাইভে গিয়ে নথিপত্র ঘাঁটার পরামর্শ দেব।\nদয়া করে, একাডেমির পূর্বসূরি সহ, এটা কিন্তু ৩০০ বছরের দীর্ঘ ইতিহাস! তুমি কি সত্যিই চাও যে আমি বছর বছর ধরে সব বলে যাই?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "এটা কি প্ররোচনা? আমি যেকোনো সময় প্রস্তুত!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "গভীর সাগর তোমাকে চিরশান্তি দান করুক।"
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "গভীর সাগর তোমাকে চিরশান্তি দান করুক।"
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "নিমজ্জিত হও এবং দহনে পুড়ো! মৃত্যুর নৃত্য করো!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "এবার আমি উপস্থাপন করছি, অমর সবুজ শিখার মৃত্যু্র নৃত্য!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "ওই ভদ্রমহিলাকে দেখতে বাতিঘরের মতো লাগে... মায়ারাত্রি অনন্ত প্রলয়ের সমুদ্রযাত্রায় যদি আমি তার সেই ঝলমলে আলো দেখতে পেতাম, হয়তো আমি পথ হারাতাম না।"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "চ্যাট: ফারোস সম্পর্কে"
  },
  Voice_5018_UnlockDesc = {
    Text = "「জাগরণ「 「ফারোস「 অর্জনের পর আনলক হবে"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "আমাকে ল্যাব থেকে বের করতে চাইলে, নতুন রক্ষক, আগে নিজেকে তার যোগ্য প্রমাণ করো।"
  },
  Voice_5019_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5020_AwakerVoiceContent = {
    Text = "আমি প্রভু, তুমি দাস। যা কিছু আমার কামনা, তা সঙ্গে সঙ্গে আমার কাছে হাজির করতে হবে। কী? তুমি পুরস্কার আশা করছ? আচ্ছা, নাও, নিয়ে যাও!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "এবার আমি এই কলঙ্ক ধুয়ে ফেলব!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "দান করাই প্রাপ্তি।"
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "দান করাই প্রাপ্তি।"
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "আহত হবে তুমি।"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "আর কাছে আসবেন না!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "পূর্ণিমার সোনালি আলো আমাকে সবসময় মোহগ্রস্ত করে: তার নিচে সাগর সেই আলো ধরে ঝিকিমিকি করে, আর রহস্যময়, কোমল বাতাস বয়ে যায়, বুনে তোলে রোমান্টিক ও স্বপ্নলোকের মতো এক দৃষ্টিক্ষেত্র।"
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "আমাদের ঘর যদি ডিজলিউশন-এর শিকার না হতো, টিঙ্কট আর আমি আলাদা হয়ে যেতাম না... আমি ডিজলিউশনকে সবজির চেয়েও বেশি ঘৃণা করি।"
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "গন্তব্য যদি গোপন সম্পদও হয়, কিংবা শুধু একটি বন্দর—আমার কাছে তাতে কোনো পার্থক্য নেই। আমার একমাত্র উদ্দেশ্য তোমার নিরাপদ প্রত্যাবর্তন নিশ্চিত করা।"
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5031_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "দয়া করে প্যারাডাইসের পাখিদের গতিপথ অনুসরণ করো; অনুপ্রেরণার নীলে সামনেই অপেক্ষা করছে গন্তব্য।"
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5032_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "আমি প্রায়ই দিগন্তের দিকে তাকিয়ে থাকি, কল্পনা করি সেই দূর দেশের দৃশ্য—যার দিকে আমি ক্রমে এগিয়ে যাই, অথচ কখনোই নাগাল পাই না। যদি কোনোদিন সেই দিন আসে, দয়া করে আমার সঙ্গে সেখানে দেখতে চলো।"
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5033_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "তোমার অনুগ্রহের জন্য, এখন ক্রুদ্ধ সাগরও আর ততটা ভয়ঙ্কর মনে হয় না। আমি অবিচল ইচ্ছাশক্তি নিয়ে সেই সাগর পাড়ি দেব, তোমার জন্য আমার আশীর্বাদ পৌঁছে দিতে।"
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5034_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "মনে হচ্ছে আবারও বৈঠিয়ালদের গান শুনতে পাচ্ছি... আর টের পাচ্ছি ঘরের সেই পরিচিত গন্ধ।"
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5035_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "তুমি কি আমাকে উদ্ধার করতে এসেছ? এই ক্ষয়িষ্ণু পৃথিবী থেকে, আমার চোখে লেগে থাকা ঘৃণা থেকে, সেই অমর সবুজ শিখা থেকে..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "ধৃষ্ট দুর্বৃত্ত!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "এটিকে তোমার প্রতি আমার আনুগত্যের অঙ্গীকার বলেই জানো।"
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5038_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "শিখে নাও তোমার পাঠ!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "একটা ইঁদুর কী করতে পারে, সেটা এখন দেখাই তোমাকে!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "একটা ইঁদুর কী করতে পারে, সেটা এখন দেখাই তোমাকে!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "পাশা নিক্ষিপ্ত হয়েছে। এখন, দ্রুত এর সমাপ্তি ঘটাও!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "আমি আমার কৃতজ্ঞতার তালিকায় তোমার নাম লিখব। তোমার কারণেই এই অন্ধকার রক্তে কলুষিত পা আবারও পা রাখতে পেরেছে ব্যালের সেই অপূর্ব জগতে। আজ থেকে, দয়া করে আমার নৃত্য দেখো, রক্ষক।"
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5047_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "তুমি যতই লড়ো না কেন, নিয়তিকে অস্বীকার করতে পারবে না। কিন্তু সেই ক্ষণিক দীপ্তি জমাট বেঁধে থাকবে অনন্ত কালের জন্য।"
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5048_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "এই ব্যর্থদের সাথে আমরা কী করবো?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "আমার হৃদয়ে আর যদি কোনো আকাঙ্ক্ষা না-ও থাকে, তবু আমি রাজহাঁসের ভূমিকাই নৃত্য করে যাব।"
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5050_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "চোখ বুজে বলো, কী দেখো তুমি? নিষ্কলুষ চাঁদের আলো, এক শান্ত হ্রদ..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5051_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "আহ, ধ্বংস আর অমঙ্গলজনিত সেই মহাদুর্যোগ... কেন তা আমার আর আমার বোনের উপরই নেমে আসতে হলো?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "আমার স্নেহ গ্রহণ করো।"
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "আমার স্নেহ গ্রহণ করো।"
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "এখন আমি অনেকটাই স্বস্তি অনুভব করছি, আপনার দয়ার জন্য কৃতজ্ঞ।"
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "যদি তা আপনার পছন্দ হয়, তবে আমি কৃতজ্ঞতার নিঃস্বার্থ নিদর্শন হিসেবে একটি ফ্যাকাশে বেগুনি শাপলা আপনাকে অর্পণ করতে চাই।"
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "তুমি কি মনে করো, আমিও হয়তো আরও শক্তিশালী হয়ে উঠতে পারি?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "এবার শুরু হোক...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "এই আহত পা? ভাবিনি তুমিও এটা নিয়ে ভাববে। জীবিত থাকতে যুদ্ধক্ষেত্রে পেয়েছিলাম।\nচিন্তা করো না, জাগ্রত সত্তা হওয়ার পর, এটা আর আমার যুদ্ধে বাধা দেয় না।\nব্যথা? না, আমি এই ধরনের প্রশ্ন নিয়ে কখনো ভাবিনি।"
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5061_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "সিলভিয়া আমার মানসিক অবস্থার খোঁজ নিয়েছিলেন। তাকেই তো তুমি পাঠিয়েছিলে, তাই না? স্বীকার করছি, মায়াবী ব্যথা মাঝে মাঝে জ্বলে ওঠে। কিন্তু তা নিয়ে ভাবো না। আমি তোমার তলোয়ার, তোমার ধারালো ফলক। যতক্ষণ আমি ন্যায়বিচারের জন্য লড়তে পারি, ততক্ষণ সামান্য ব্যথার কোনো মূল্য নেই।"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5062_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "টি পার্টি, টি পার্টি! চল, টি পার্টি করি! সিলভিয়ার কাছ থেকে আমি অনেক চা পাতা আর নাস্তা পেয়েছি! হ্যাঁ, বিনিময়ে আমি ফাটারওয়্যাকেন নাচ দেখিয়েছি!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "আমার নিজেকে সম্বোধন? আপনি আমার ব্যক্তিগত বিষয়ে এতটা আগ্রহী?\nশুধু একটু গল্প করতে চান... ঠিক আছে।\nসেনাবাহিনীতে, আমরা লিঙ্গের কারণে সহযোদ্ধাদের সাথে ভিন্ন আচরণ করি না, শক্তি ও গতি যেমন, তেমনি চুলের ধরন ও সম্বোধনও তাই। সময়ের সাথে সাথে, এই ধরনের প্রকাশভঙ্গিতে অভ্যস্ত হয়ে গেছি।"
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5064_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "মজার... আমি শক্তি পেলে তোমাকে খণ্ডাংশ খণ্ডাংশ করে ছিঁড়ে মাছেদের খেতে দেব—এতে কি তোমার ভয় করে না?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "দেখছি, তুমি সত্যিই পরিশ্রম করছ, যেন আমার উপযুক্ত এক রক্ষক হতে পারো।"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "এবার একটু চেষ্টা করে দেখা যাক। হুঁঃ। আগে কয়েকটা দুর্বল গলার শিরা কেটে দেখা যায় না?"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "নৃত্য নির্মল। শব্দ ভুল বোঝাবুঝির জন্ম দিতে পারে, কিন্তু নৃত্যের পদক্ষেপ কখনোই তা করে না।"
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নৃত্য সম্পর্কে"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "আমি সাগরকে ঘৃণা করি, আর তার যথেষ্ট কারণও আছে। সাগর গ্রাস করেছে আমার সব প্রিয় জিনিস..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "ভুলে যাওয়া হোক বা হারিয়ে ফেলা—এইবার আমরা অবশ্যই প্রত্যাবর্তন করব!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "ভুলে যাওয়া হোক বা হারিয়ে ফেলা—এইবার আমরা অবশ্যই প্রত্যাবর্তন করব!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "দয়া করে, দয়া করে আর কাছে এসো না। এটা বিপজ্জনক... তোমার জন্য।"
  },
  Voice_5072_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5073_AwakerVoiceContent = {
    Text = "ইচ্ছে মতো আমাকে ছুঁয়ে দেখো... এগুলো রণক্ষেত্রে অর্জন করা দাগ, একজন পুরুষের সম্মানের ব্যাজ!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(পেইনের আর্তনাদ)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "আহ! আহ!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(একটি মৃদু, সংযত শ্বাসগ্রহণ)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(বিরক্তির গোঙানি)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "মনে হচ্ছে ভেতরে কিছু যেন ফুটতে শুরু করেছে। আত্মজাগরণে প্রবেশ করলে কি এমনই অনুভূতি হয়?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5078_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "এটা কি কোনো নতুন প্রযুক্তি? আমার কৃত্রিম অঙ্গটা অনেক হালকা লাগছে।"
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5079_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "লবণাক্ত সাগর-বাতাস আমাকে জানায়, আমার শ্বেত পাখির দেশ আর খুব দূরে নয়।"
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5080_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "এই আলোর অনুসরণে কি আমার প্রয়াত আত্মীয়রা স্বদেশের পথ খুঁজে পাবে?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5081_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "আমি দশ সহস্র বছর ধরে খুঁজে চলেছি; ক্ষণস্থায়ী এক শতাব্দী তার তুলনায় কিছুই নয়। তোমার জীবনের সমাপ্তি পর্যন্ত, আমি তোমাকে সহায়তা করে যাব।"
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5082_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "আমি শুধুমাত্র আমার স্বদেশের জন্যই উজ্জ্বল হবো। তোমার ব্যাপারে..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5083_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "আমি অনুভব করলাম হাওয়া, সূক্ষ্ম বালুকণা বয়ে আনছে আমার পায়ের উপর দিয়ে।"
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5084_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "তোমার শক্তিতে আমার অবদানের সীমা এখানেই শেষ। অতিরিক্ত লালসা কিন্তু ভালো কিছু নয়, জানো তো।"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5085_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "আমার কাছ থেকে তুমি বিনিময়ে কী আশা করছ? যুদ্ধের সময় তোমাকে শক্তি ধার দেওয়া ছাড়া আর কিছু?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5086_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "ভালবাসার খুলি, বিদ্বেষের খুলি, ঘৃণার খুলি, কামনার খুলি... ওহ, আবার এসেছ নাকি, প্রিয় অতিথি?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5087_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "এটা যেহেতু একটি লেনদেন, তাই তোমার উপহার আমি সোজাসুজি গ্রহণ করতে পারি না। আমার দোকান থেকে কিছু একটা নির্বাচন করতে চাও?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5088_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "আমি তোমাকে শেখাবো আনন্দ, উন্মত্ত উত্থানের সেই শিহরণ... বিনিময়ে, তুমি তোমার কামনাগুলো আমার সামনে উন্মোচন করবে।"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "চ্যাট: রক্ষক সম্পর্কে - 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "আমি প্রাচুর্যের মাতৃবৃক্ষ। প্রাচুর্যের মাতৃবৃক্ষই আমি। তার রস আমার শিরায় প্রবাহিত, তার ইচ্ছা আমার মনে হুইসপার করে..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "চ্যাট: প্রাচুর্যের মাতৃবৃক্ষ সম্পর্কে"
  },
  Voice_50899_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "তোমার বিশ্বাসঘাতকতার মূল্য চুকাও!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "আমি কীগ্রেভের ছায়ায় তোমার সমাধিফলকের এক ঝলক দেখেছিলাম... একদিন কি আমার মমি-করা দেহও এখানে বিশ্রাম নেবে? না? কী অপচয়ই না হবে।"
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "চ্যাট: কীগ্রেভ সম্পর্কে"
  },
  Voice_50900_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "ওই নেকড়ে-ছেলেটা... জানো তো? সে আর ওই এন-এর মধ্যে কিছু... বর্ণনাতীত ব্যাপার চলছে।"
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "চ্যাট: রাইকার সম্পর্কে"
  },
  Voice_50901_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"রাইকার\" অর্জনের পর আনলক হবে"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "আরও কাছে এসো। আমাকে তোষামোদকারীর আলিঙ্গনে নাও। আমাকে আস্বাদন করো... আমাকে কখনো ভুলো না।"
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "চ্যাট: রক্ষক সম্পর্কে - 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "সে অতিরিক্ত সাবধানী এক বালিকা। তাকে দোষ দিই কী করে—ওকে ছাড়া তো আমার স্বাধীনচেতা জাতি বহু আগেই বিলুপ্ত হয়ে যেত, তাই না?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "চ্যাট: আলভা সম্পর্কে"
  },
  Voice_50903_UnlockDesc = {
    Text = "「জাগরণ「 「Alva「 অর্জনের পর আনলক হবে"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "হলুদ বালু থেকে জন্মেছ, আর হলুদ বালুতেই প্রত্যাবর্তন করবে। এই ক্ষণস্থায়ী যাত্রায়, পথিমধ্যে কিছু স্মারক রেখে যাওয়া উচিত নয় কি? কিছু বীজ বপন করবে না?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "চ্যাট: মরুভূমি সম্পর্কে"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "সব কামনা জন্ম নেয় প্রেম থেকে; প্রেমই উর্বরতার সুউচ্চ বৃক্ষের পূর্ববর্তী বীজ।"
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "চ্যাট: কামনা সম্পর্কে"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "আহ হায়, এক ছোট্ট ইঁদুরটা ছুটে গেল... ওরা নিষিদ্ধ জিনিস কুটকুট করে খেতে ভীষণ ভালোবাসে, তাই না? কিন্তু এইটাকে তো এখনও অনেক বেশি কচি লাগছে।"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_50906_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "তারা আমার রক্ত, আমার বংশধারা বহন করেছিল, রেমুয়াহের বিকশিত জলে রূপান্তরিত হয়ে... এখন, প্রিয়তম, তোমাকেই নিশ্চিত করতে হবে যে আমার উত্তরাধিকার সহনশীলতা পায়।"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "চ্যাট: আরাম সম্পর্কে"
  },
  Voice_50907_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "মাকড়সা... ম্‌ম্‌~ আমি ওদের ভালোবাসি। জন্মের পর থেকেই হাঁটে, আর এমন উর্বর যে হিংসা জাগে..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাগ্রিপা প্রসঙ্গে"
  },
  Voice_50908_UnlockDesc = {
    Text = "\"জাগরণ\" \"অ্যাগ্রিপা\" অর্জনের পর আনলক হবে"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "যাদের শিরায় প্রবাহিত বৃক্ষের রক্ত, তারা আমার বালকেরা—তুমি, যে তার বীজ গ্রাসিত করেছ, অবশ্যই তাদের মধ্যেই পড়ো।"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "চ্যাট: বংশধরদের সম্পর্কে"
  },
  Voice_50909_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "আমার পণ্য? বলতে পারো, তোমার সব কামনা পূরণ করার মতো সবকিছুই আছে আমার কাছে... অবশ্যই, মূল্যের বিনিময়ে।"
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5090_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "আহ হায়, এ বার তো তার কাছে হেরে গেলাম... কিন্তু যেহেতু সে তোমাকেই বেছে নিয়েছে, তুমি পবিত্র বৃক্ষের রস পান করবে, আর আমার রক্ত ও বীজ নতুন এক জগতে বপন করে নিয়ে যাবে, তাই তো?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "চ্যাট: তাবিল সম্পর্কে"
  },
  Voice_50910_UnlockDesc = {
    Text = "「জাগরণ「 「রামোনা「 অর্জনের পর আনলক হবে"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "ওই যে, তিন ইওনের মধ্যে একজন—সে এক দানব, ধাঁধার আবরণে মোড়া। অনুগ্রহ করে তার মধুর কথায় নিজেকে ভাসিয়ে দিও না, নইলে আমার হৃদয় ভেঙে যাবে..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "চ্যাট: \"এন\" সম্পর্কে"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "সব সচেতন সত্তারই কামনা থাকে। এমনকি যন্ত্রেরও, তাই তো?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "গল্পগুজব: এরিকা প্রসঙ্গে"
  },
  Voice_50912_UnlockDesc = {
    Text = "\"জাগরণ\" \"এরিকা\" অর্জনের পর আনলক হবে"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "তোমার বিশ্বাসঘাতকতার মূল্য চুকাও!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "বিস্ময়পুরীতে স্বাগত জানাও!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(বিড়বিড়)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "খোদাইয়ের পেইন আর রূপান্তরের দহন—এই দুয়ের সঙ্গেই আমি ভীষণ পরিচিত। তবু চিরন্তন সৌন্দর্যের তুলনায় এগুলো সবই ফিকে হয়ে যায়।"
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5094_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "এই অনুচ্চারিত শব্দগুলো আমি আমার কাজের মধ্য দিয়ে তোমার কাছে পৌঁছে দেব।"
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5096_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "নিদ্রিত সার্বভৌম আমার কানে প্রলাপ বকে, গভীর সাগরের ধ্বংসাবশেষ আমার চোখের সামনে অবিরাম নতুন করে গড়ে ওঠে... অসংখ্য স্বপ্নলোকের দৃশ্য কি তবে সত্যি হয়ে উঠেছে?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5098_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "আমার জন্য এই স্টুডিওটা প্রস্তুত করার জন্য ধন্যবাদ। এখানে সবকিছুই রোদে ভেসে আছে; মনে হয় প্রতিটি কাজ, প্রতিটি খোদাইয়ের ছুরি সোনালি আলোয় জ্বলজ্বল করছে। আহ, বসন্ত সত্যিই সোনালি।"
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5099_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "আমাদের স্বভাব আলাদা হলেও, আমি সত্যিই সেই শিশুটিকে শ্রদ্ধা করি। তার মধ্যে আছে এমন এক সাহস, যা সব দুঃখ-কষ্ট আর সীমাবদ্ধতাকে অতিক্রম করে যায়। আমি যদি তার মতোই সাহসী আর দৃঢ় হতে পারতাম, হয়তো আমি সাগরে গিয়ে নিজের জীবন শেষ করার পথ বেছে নিতাম না..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_5100_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "লাল ম্যাডাম আমার পূর্বে সেবা করা কোনো প্রভুর মতো নন... না, তাকে অপছন্দ করি তা নয়; আমি শুধু... শুধু কখনও কখনও তার মুখোমুখি হওয়াটাই একটু কঠিন মনে হয়..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সোরেল প্রসঙ্গে"
  },
  Voice_5101_UnlockDesc = {
    Text = "\"জাগরণ\" \"সোরেল\" অর্জনের পর আনলক হবে"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "উন্মাদনাকে আলিঙ্গন করো!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "মরণাপন্ন ইঁদুর।"
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "বিনাশ করো!"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "তোমার আমার জন্য এটা করার দরকার নেই..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "আমার হৃদয় এক অতল গহ্বর, কোনোদিন পূর্ণ হবে না।"
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "ওটা আমার ভেতরে কোনো অনুভূতি জাগাতে পারেনি, কিন্তু... তবু আমি ভীষণ কৃতজ্ঞ।"
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "আহ... আপনি কি আমার সঙ্গে কথা বলছিলেন? ক্ষমা করবেন, আমি তো দণ্ডায়মান মাস্তুলে বাঁধা থাকার সময়কার দৃশ্যের স্মৃতিচারণে হারিয়ে গিয়েছিলাম। আপনার জিজ্ঞাসাটা আরেকবার বলবেন কি?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত প্রসঙ্গে"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "তুমিই আমার প্রভু... আমার মা।"
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "একটি সুযোগ!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "একটি সুযোগ!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "প্রস্তুত—"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5113_AwakerVoiceContent = {Text = "হা!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "হ্যাঁ, আরও জোরে!"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "এটাই আমার ভালোবাসার দহনজ্বালা!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "ডিজলিউশন... এ নিয়ে আমি অবাধে কথা বলতে পারি না। কিন্তু এটুকু জেনে রাখো: তোমার কল্পনার চেয়েও অনেক আগেই এর আবির্ভাব ঘটেছে।"
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "হাহ্—"
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5119_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_5119_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "চলো, রওনা হই।"
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "ওহ, আমাদের পুতুল রাজকুমারী আবার কাঁদছে। দুধের বোতলটা কি ঠিকমতো লাগছে না, নাকি ঘুমপাড়ানি গানটা যথেষ্ট কোমল নয়?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_5121_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "উহু... ওই জিনিসগুলোর মুখোমুখি হতে চাই না..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "এখন, তোমাকে প্রতিদান দেওয়ার পালা আমার।"
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "শক্তির উচ্ছ্বাস যেন দগ্ধ অগ্নিশিখা, যা আমার অস্থিমজ্জা পর্যন্ত পুড়িয়ে দেয়।"
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "আহ... দুঃখিত, দ-দয়া করে নড়বেন না!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "সেই উষ্ণতা, কত কাছে..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "প্রাঙ্গণের গোলাপগুলো পূর্ণ প্রস্ফুটিত।"
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "ভালো কাজ! এখনো কি এগিয়ে যাওয়ার মতো শক্তি তোমার আছে?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "একজন নাইটের ধারণা নিরাকার, আনুগত্য, বীরত্ব আর সদ্‌গুণ তাকে রূপ দেয়। আমার অস্ত্রও তেমনই, রক্ষার ইচ্ছা তাকে রূপ দিয়েছে: এক বর্শা আর একটি চরিত্রের ঢাল।"
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নাইট প্রসঙ্গে"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "জেনকিন, ডায়ানা, ম্যাক, টি’ইয়গ, ব্রাউন... উওআহ! দুঃখিত, আমি শুধু নিজেকেই বলছিলাম! আপনি জিজ্ঞেস করছেন, কেন আমি এই নামগুলো আওড়াচ্ছি? কারণ আমি ওদের কাউকেই ভুলে যেতে চাই না..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বন্ধু প্রসঙ্গে"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "দূর হও!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "এ অসহ্য!"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5133_AwakerVoiceContent = {
    Text = "হাহ্!"
  },
  Voice_5133_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5134_AwakerVoiceContent = {
    Text = "হাহ্!"
  },
  Voice_5134_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "আমাকে আহ্বান করার জন্য ধন্যবাদ। যদি কখনো এমন কোনো সময় আসে যখন আমার ভয়েসের প্রয়োজন হবে, তবে দয়া করে আগে থেকেই আমাকে জানিয়ে দেবে।"
  },
  Voice_5135_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5137_AwakerVoiceContent = {
    Text = "ওটা... ওটাই আমার শিরায় বয়ে চলা কালো আঠালো তরল, সেই চূড়ান্ত শক্তি, যা সব পেইনের আর্তনাদকে নীরবতায় ডুবিয়ে দেয়! 「আমি」 এই তরল থেকেই জন্মেছি, ধ্বংস করার জন্যই জন্মেছি! হাহাহা!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "কী খবর, জুয়া খেলতে চলবে নাকি? ...তদন্ত? আরে ধুর, এমন ভাগ্যের জোয়ারে ওটা তো একেবারে অপচয়..."
  },
  Voice_5138_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5139_AwakerVoiceContent = {
    Text = "তত্ত্বের ক্লাসগুলো বেশ বিরক্তিকর। আমি চুপিচুপি ক্লাসের পেছনে বসে তদন্তের নথি পড়ি। ডলকে কিন্তু এটা বলবে না। এটা আমাদের গোপন কথা, ঠিক আছে?"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "পরিণতির তিক্ততা আস্বাদন করো!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "পরিণতির তিক্ততা আস্বাদন করো!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "আমি কখনো জুলিয়েটকে দোষ দিইনি; সে তো শুধু কালো যন্ত্রণার এক শিকার মাত্র। কিন্তু... আমার মুখে এ কথা শুনতে সে যেন চায় না। তুমি কি আমার হয়ে তাকে এটা জানিয়ে দেবে, দূত?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "চ্যাট: জুলিয়েট সম্পর্কে"
  },
  Voice_5142_UnlockDesc = {
    Text = "ভয়েস এখনো যুক্ত করা হয়নি।"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "আরও ধীরে।"
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5144_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_5144_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "এই! আমার ড্রেসে হাত দিও না, কুঁচকে যাচ্ছে! ...আচ্ছা, এইবারের মতো মেনে নিলাম—আমি তো আর এতটা উদার নই, তবু।"
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "প্রয়োজন নেই!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5147_AwakerVoiceContent = {Text = "ছিঃ!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "যেদিন তুমি আমাকে অন্ধকার থেকে জাগিয়ে তুলেছিলে, সেদিন থেকেই আমি নিশ্চিত যে তুমি সবাইকে ডিজলিউশনের হতাশা থেকে রক্ষা করতে পারবে, আর তাদের পাপহীন ভূমিতে পৌঁছে দেবে। সেই দিনের অপেক্ষায় আমি আশাব্যঞ্জক হৃদয়ে প্রহর গুনি।"
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "চ্যাট: রক্ষক সম্পর্কে: I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "আমি গন্ধ পাচ্ছি... রক্তের গন্ধ।"
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "লক্ষ্য কোথায়? আমাকে জাগিয়ে তোলার কৃতজ্ঞতাস্বরূপ, আমি-ই ওদের দেখভাল করব—তোমার হয়ে।"
  },
  Voice_5150_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5151_AwakerVoiceContent = {
    Text = "আর বিলম্ব সহ্য করিতে পারে না আমার টুপি!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "এই খোলস তাঁর বাইরে আর কারও জন্য জাগ্রত হওয়ার কথা নয়... অথচ... তোমার উষ্ণতা..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "কী। লড়াই করতে চাও?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "অপবিত্রকারী..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "ক্ষমার অযোগ্য।"
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "এরিকা স্বাভাবিকভাবে কাজ করছে এবং মিথাগ বিশ্ববিদ্যালয়ের বৈদ্যুতিক সরঞ্জামের সঙ্গে ভালোভাবে সংযুক্ত। আপনাকে কি আমি ডরমিটরির আলো জ্বালিয়ে দেব?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "গল্পগুজব: এরিকা প্রসঙ্গে"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "আহ, খাবার সময় হয়ে গেছে। হেহে..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "ওই চওড়া-ধারওয়ালা বেগুনি টুপি পরা নারীটাকে স্টেজের কাছে আসতে দিও না! কোনো জিজ্ঞাসা নয়—ওকে দূরে রাখো, যদি না চাও আমার টুপির ভেতর থেকে আঠালো ধূসর মগজ গড়িয়ে পড়ুক!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "চ্যাট: ড্যাফোডিল সম্পর্কে"
  },
  Voice_5159_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ড্যাফোডিল\" অর্জনের পর আনলক হবে"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "তুমি সবসময়ই এমন? সকলে-কে বিশ্বাস করো, আর তাদের দিকেই পিঠ ফিরিয়ে দাঁড়াও? সরলমনা।"
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "ঘৃণা কিছুটা লাঘব হতে পারে, কিন্তু কখনোই মুছে যায় না।"
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "জাগরণকারী? হুঁম... হ্যাঁ, সকাল ৭টাই তো জাগার সেরা সময়! চল, কাল ভোরে ৭টায় সমুদ্রতটে শামুকের খোলস কুড়োতে যাই!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "চ্যাট: \"জাগরণকারীদের সম্পর্কে"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "এখন আমি তোমাকে অনন্ত জীবন দান করছি!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5164_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5165_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "দুঃখিত, যদি আমি আপনাকে কোনো ঝামেলায় ফেলে থাকি, আমি এখনই চলে যাচ্ছি!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5166_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "তুমি আমাকে আশ্রয় দিয়েছ, তার জন্য আমি কৃতজ্ঞ। কিন্তু ক্ষমা কোরো, আমি আর কখনোই মঞ্চের উপর দাঁড়ানোর যোগ্য নই।"
  },
  Voice_5167_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5168_AwakerVoiceContent = {
    Text = "আমাকে এখানে থাকতে দেওয়ার জন্য ধন্যবাদ। যদি কোনোভাবে এর প্রতিদান দিতে পারি, দয়া করে আইগিসকে জানাবেন। আপনি কি একটু চা নেবেন?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5168_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "এখানে এত উষ্ণ যে আর যেতে ইচ্ছে করে না। যখন আমি একা থাকি, তখন সবকিছু ভীষণ অন্ধকার, ঠান্ডা আর ভয়ানক..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5169_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "আইগিস... আমি কি সত্যিই জনতার কাছে ফিরে যেতে পারব? আমি এখনো প্রস্তুত নই, তবু তুমি আমাকে মেনে নিয়েছ... সে ক্ষেত্রে, দয়া করে আমাকে দেখাশোনা করে যেয়ো... রক্ষক।"
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5170_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "আহ... আমি সব মনে করতে পারছি! আমি... আমি সেই নোংরা মানব রক্তে আবদ্ধ হয়ে রূপান্তর সম্পূর্ণ করতে পারিনি! এটা কীভাবে সম্ভব? আমার ফুলকো কোথায়? ওগুলো নড়ছে না কেন?! কেন!"
  },
  Voice_5171_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5172_AwakerVoiceContent = {
    Text = "আমি পুড়িয়ে খাওয়া অক্টোপাস ভালোবাসি, সেদ্ধ অক্টোপাস, ভাজা অক্টোপাস... কেউ কেউ বলে আমি নাকি ধর্মদ্রোহ করছি। হা, ক্ষমা চাই, কিন্তু অক্টোপাস এতটাই সুস্বাদু যে, হাহাহা!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "কীটপতঙ্গ। নক্ষত্রপুঞ্জ। আমি... উভহাশ! হত্যা... আমাকে হত্যা করতে দাও!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5173_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "রক্তিম দেহ, ধুকপুক করা শুঁড়, বারবার খুলে-বন্ধ হওয়া মুখের অঙ্গপ্রত্যঙ্গ... অসাধারণ! আমি আর অপেক্ষা করতে পারছি না কারও গলা ছিঁড়ে ফেলার জন্য!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5174_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "হাহাহা, এটাই সেই অনুভূতি! আরও দাও... দ্বিগুণ না, দশ গুণ মাত্রা বাড়াও!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5175_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "আমি সহ্য করব।"
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "এই অদ্ভুত অনুভূতিটা... মন্দ না। ওই লেভান্টের জাদুকরের নাইটশেডের চেয়েও ভালো।"
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5177_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "সহচর? হুঁঃ... আমার ওসবের দরকার নেই। একই বোঝা আমি দ্বিতীয়বার বইব না।"
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5178_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "মনে করিয়ে দিই, আমাদের সহযোগিতা সম্পূর্ণই তোমার শক্তির ওপর নির্ভরশীল। তোমার শক্তি একবার ক্ষীণ হয়ে এলে, এই চুক্তি সঙ্গে সঙ্গে শেষ হবে, আর আমি বিন্দুমাত্র দ্বিধা না করে তোমার শিরশ্ছেদ করব।"
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5179_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "তোমার চোখে আমি আলো দেখি। ওই কামনা, ওই উচ্চাকাঙ্ক্ষা... তা জ্বলছে। স্বীকার করো, নশ্বর! আমরা একই জাতের।"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5180_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "অ্যালবাট্রস পাখির কথা জানো? তারা কখনো মানুষকে পাত্তা দেয় না, বরং প্রবল শক্তিতে ডানা ঝাপটে ঝড়ের মোকাবেলা করে। কিন্তু একবার মাটিতে নামিয়ে দিলে, চারদিকে ঠাট্টা-বিদ্রূপের মাঝে, সেই বিশাল ঝুলে-পড়া ডানাগুলোই বরং করুণ বাধা হয়ে দাঁড়ায়।\nএই গল্পে তেমন কোনো গভীর অর্থ নেই, শুধু তোমার সাথে থাকলে খুব স্বস্তি লাগে, তাই এমনিই বলছিলাম।"
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5181_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "হয়তো, সময় সত্যিই বদলে গেছে। আজকাল, দুর্বলরাও প্রবালপ্রাচীর পেরিয়ে, ঢেউয়ের উপর দাপট দেখিয়ে, নীলাকাশের রাজা হতে পারে।\nহে নশ্বর, আমি সেই দিনের অপেক্ষায় আছি যেদিন তুমি ইতিহাস পুনর্লিখন করবে। সেদিন, তোমার হাতের মহাতলোয়ার হতে পারা আমার জন্য হবে পরম সম্মান!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5182_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "রূপান্তর হার ভয়াবহভাবে কম। পুনঃপ্রশিক্ষণের জন্য কাল আমার অফিসে হাজির হবে।"
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "তুমি কি অন্য ডল? এর সঙ্গে দেখা করেছ? তথাকথিত 「পৃথিবীর সত্য」 সম্পূর্ণভাবে এক শান্ত মনকে ভেঙে চুরমার করে দিতে পারে। আমরা কি... তুমি আর আমি কি একই রকম হয়ে যাব?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "গল্পগুজব: @2 সম্পর্কে"
  },
  Voice_5184_UnlockDesc = {
    Text = "অ্যাওয়েকেনার@2 অর্জনের পর আনলক হবে"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "প্রভু... আমার আদেশ চাই। দয়া করে আমাকে আদেশ দিন।"
  },
  Voice_5185_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5186_AwakerVoiceContent = {
    Text = "যন্ত্রমানবের কার্যক্ষমতা বৃদ্ধি পেয়েছে।"
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "এহেহে!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "আরও বন্ধু!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "আরও বন্ধু!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "দুঃখিত, আমি দোলনা থেকে বেরোতে পারি না... এটা হয়তো সকলে’র দৃষ্টি আড়াল করবে, তাই আমি শ্রেণিকক্ষের একেবারে পেছনে থাকব।"
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "কি! তুমি একটাও আনতে পারোনি?! না কনস্ট্যান্টিনোপল-এর কার্পেট, না সিলন চা, না আন্দালুসিয়া চুরোস…? উফ, ওই নারী তো সবসময়ই এগুলো এত সহজে পেয়ে যায়! আমি ভেবেছিলাম এগুলো খুবই সাধারণ!"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "এখনও আমার আসল পাশবিক শক্তির এক ম্লান ছায়া মাত্র।"
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5194_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "কী তাড়াহুড়ো। আপনার মানের কারও জন্য এটা একটু অমার্জিতই বটে।"
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "এই জন্তুটা আমার ইচ্ছাশক্তির মাত্র এক খণ্ডাংশ। এর রূপ বদলাবে না হয়তো, কিন্তু আমার শক্তির কোনো সীমানা নেই।"
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5196_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "আঃ, আবারও সেই বিশৃঙ্খল মহাসাগরে। আমার পছন্দ হয়েছে।"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5197_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "ঠিক আছে। তুমি যথেষ্ট পরিশ্রম করেছ। তোমাকে সঙ্গী হিসেবে মেনে নেওয়ার মতো সহনশীলতা হয়তো আমার আছে।"
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5198_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "এই শক্তির প্রতিবন্ধকগুলো গুঁড়িয়ে দাও, যেমন আমি গোলকধাঁধার দেয়াল ভেঙে চুরমার করে দিতাম!"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5199_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "খাবার ছিঁড়ে ফেলা যাবে না, ক্যাফেটেরিয়ার সিট ভাঙা যাবে না... ঠিক আছে। লিলি আর করবে না।"
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5200_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "আমি কি তোমাকে মা বলে ডাকতে পারি?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5201_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "কোনো আদেশ আছে, মালিক?\n「ওগুলো নিয়ে বাইরে হাঁটবে না, সবাই ভয় পাবে」?\nলিলি বুঝেছে, লিলি এখনই ওগুলো লুকিয়ে রাখছে।"
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5202_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "তাহলে, জাগরণকারী হওয়া মানে এটাই অনুভব করা।"
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5203_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "মা, আমি কি তোমার পাশে শুতে পারি? একা থাকলে অন্ধকার, ভয়ংকর স্বপ্নলোক দেখি। আমার হাত-পা খুলে পড়ে যায়... ভীষণ, ভীষণ কষ্ট হয়..."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5204_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "আহ! আপনার দয়ার জন্য ধন্যবাদ, কারেন তো স্রেফ এক নগণ্য পরিচারিকা..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5205_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5206_AwakerVoiceContent = {
    Text = "হেহে..."
  },
  Voice_5206_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "আমাকে কিছু খোদাইয়ের উপকরণ জোগাড় করতে হবে, সম্ভব হলে একেবারে তাজা।"
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে নীরব থাকো।"
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "যারা নিজেদের মূর্খতায় একগুঁয়ে থাকে, তারা কেবলই নিষ্ফল কর্ম সম্পাদন করে।"
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5209_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "হোক। এ পর্যায়ে এসে, তোমার উদ্দেশ্য কিছুটা অনুধাবন করতে পারছি। এগিয়ে চলো।"
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5210_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "তোমার সংকল্প আমি দেখেছি। শূন্যে প্রত্যাবর্তনের আগে, এই সত্তা মানবজাতির উত্তরাধিকারীর ভাগ্য-বিরোধী সংগ্রামের সাক্ষী হবে। কিন্তু এখন... বিশ্রাম প্রয়োজন।"
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5211_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "স্বর্গের ইচ্ছা অনুসরণ করা কি মন্দ? তবে ভাগ্যের ইচ্ছার বিরোধিতা কেন?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5212_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "তোমার মনোবাঞ্ছা পূরণ করতে, তুমি এত কিছু আত্মত্যাগ করতেও প্রস্তুত…"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5213_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "উফ, বিরক্তিকর না? ওই নিয়ে আমাকে আর জ্বালিও না! ...আচ্ছা, যা খুশি করো। শেষ পর্যন্ত, এটা তো শুধু সময় কাটানোরই একটা উপায়।"
  },
  Voice_5214_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5215_AwakerVoiceContent = {
    Text = "ডিজলিউশন… ওই জঘন্য কালো জোয়ার আমার স্বপ্নে হানা দেয়। অসহনীয়।"
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "শক্তি এক দ্বিমুখী তরবারি। আমি কী করে তা না বুঝি? বুঝেছি, কিন্তু অনেক দেরিতে। একবার আমি হাত ছেড়ে দিলে, ওরা আমাকে টুকরো টুকরো করে ছিঁড়ে ফেলবে... যদি শুরু থেকেই তোমার মতো পরিষ্কার মস্তিষ্ক থাকত, তবে এমন করুণ পরিণতির মুখোমুখি হতে হতো না। কী? তুমি বলছ, এখন থেকে আমি নীতিনির্ধারকের লাউঞ্জে স্যালন আয়োজন করতে পারব?! এ তো... তোমার ব্যক্তিগত সেবক হয়ে থাকা ছাড়া আর কীভাবে তোমার ঋণ শোধ করতে পারি...?"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5216_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "আপনি বেশ অনমনীয় এক অতিথি। আপনার হাতে ধরা সেই বিশেষাধিকার আপনাকে দিয়ে ত্যাগ করাতে আমাকে কী করতে হবে? শক্তি কেবল বিপদই ডেকে আনে—এত সরল সত্য, নিশ্চয়ই আপনি তা বোঝেন?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5217_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "স্যালন শুরু হওয়ার আগে, আপনি কি একটি গল্প শুনতে চান? এক গ্রাম্য বালিকা কীভাবে শক্তির মুকুট ছিনিয়ে নিল সেই কাহিনি... কোথা থেকে শুরু করব? তার বাবা-মা যখন তাকে এক বৃদ্ধ লোকের সঙ্গে বিয়ে দিতে চেয়েছিল, সেখান থেকে? নাকি সেই অংশ থেকে, যখন সে সম্ভ্রান্ত উদ্যানের মাঝে বিকশিত হয়?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5218_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "আগে অতিথিরা আমাকে 「লাল ম্যাডাম」 বলে ডাকত। অবশ্যই, আপনি চাইলে আমাকে 「সোরেল」ও বলতে পারেন—শেষ পর্যন্ত, আপনি তো আমার সবচেয়ে বিশেষ অতিথি..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5219_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "গৃহকর্ত্রী হিসেবে, প্রতিটি অতিথির পরিতৃপ্তি নিশ্চিত করা আমার দায়িত্ব।"
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5220_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5221_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "প্রভু? আমার ভঙ্গিমায় কি কোনো ভুল আছে?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5223_AwakerVoiceContent = {Text = "ইশ!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "আহ, মন্দ ভাগ্য~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5225_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "আমি এই অনুভূতিটা মনে করতে পারছি—সেই গৌরবময় মুহূর্ত আবার আসছে..."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5226_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "এখনও আমার গিলস গজায়নি, কিন্তু আর তা নিয়ে অস্থিরতা অনুভব করি না। রক্ষক, আমি হব তোমার চরিত্রের ঢাল, আর আমার পাখনা দিয়ে তোমাকে রক্ষা করব।"
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5227_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "তুমি আমার জন্য এত কিছু বিনিয়োগ করেছ... সত্যিই তুমি অন্য মানুষদের চেয়ে বেশি রোগী। তুমি কি সত্যিই... আমাকে ঘৃণা করো না?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5228_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "কেন? আচার অনুষ্ঠান শেষ হওয়ার পরও আমার গিলস কেন গজাল না? রূপান্তর কি আবারও ব্যর্থ হলো?! ধিক্! ধিক্! ধিক্!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5229_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "ওই ভয়েসটা আবার আমাকে ডাকছে... অতল গভীর থেকে ভেসে আসা সেই অতীন্দ্রিয় শব্দ!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5230_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "ভুল! এখানে নাই তা!"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "সাঙ্গা, সিতে শহরের ভাস্কর, তোমার হাতে তার ছেনি তুলে দেয়। তুমি ত্রুটিপূর্ণ হতে পারো, তবু তুমি খোদাই করার যোগ্য।"
  },
  Voice_5232_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5238_AwakerVoiceContent = {
    Text = "এসো, অবাধ্য বাচ্চারা, সবাই কাছে এসো~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "প্রকৃত শিল্পকলার কোনো ব্যাখ্যার প্রয়োজন নাই।"
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "প্রকৃত শিল্পকলার কোনো ব্যাখ্যার প্রয়োজন নাই।"
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "আমি কীভাবে তোমাকে সাহায্য করতে পারি?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "রণশিঙা বাজাও!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "যেকোনো মূল্যে!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "আবারও সূর্যালোকে স্নান করার এই অনুভূতি... এত আরামদায়ক, এত উষ্ণ লাগে, তা আমি জানতামই না। চোখে জল এসে যায়।"
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5244_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "আমার কৃতজ্ঞতা প্রকাশের জন্য... আমার যন্ত্রণার অতল গভীরে তোমার জন্য একটি গোপন বেদি নির্মাণ করব।"
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5245_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "আমার প্রিয় ভাইয়ের মাংস আর আমার মাংস আরও নিখুঁতভাবে একাকার হয়ে যাচ্ছে..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5246_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "তুমি যা ভাবো, আমি তার চেয়ে অনেক বেশি সহনশীল। আমাকে ব্যবহার করার সময় আরও বেশি জোরে আঘাত করো। দয়া করে, নিজেকে আটকেও না।"
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5247_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "এটা কি শুধু আমারই ভুল ধারণা? নাকি... রক্তের প্রতি আমার লালসাটা কিছুটা কমে গেছে?"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5248_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "তোমার আগমনটার জন্য আমি অপেক্ষা করছিলাম, তোমার আনুষ্ঠানিক ভর্তি হওয়ার আগেই। মনে হচ্ছে আমরা বেশ ভালোই একসাথে কাজ করছি, তাই না? সঙ্গী।"
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "এ অত্যন্ত নিন্দনীয়।"
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5251_AwakerVoiceContent = {Text = "আহ!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5252_AwakerVoiceContent = {
    Text = "হাহাহা!"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "স্ট্রাইক: উন্মাদনা"
  },
  Voice_5253_AwakerVoiceContent = {
    Text = "হুম..."
  },
  Voice_5253_AwakerVoiceTitle = {
    Text = "স্ট্রাইক: বিষণ্ণতা"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "আমাকে যত খুশি আঘাত করো!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "আমি সত্যিই ভয় পাচ্ছি। না, আমি আপনাকে ভয় পাচ্ছি না, কিন্তু... আমি চিন্তিত, আবার যেন আপনাকে আতঙ্ক আর শোক না এনে দিই।"
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "এই যুগের রূপকথার বইগুলো বহু আগের পড়া বইগুলোর চেয়ে অনেক বেশি মনোমুগ্ধকর! ওহ, ওহ! প্রভু আমার, দয়া করে ভুল বুঝবেন না! আমি এখন আর শয্যাকালের গল্প শোনার মতো বয়সে নেই!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "আমাকে যত খুশি আঘাত করো!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "হুঁহ... আমি কি আপনাকে কোনো ঝামেলায় ফেলেছি?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "তুমি সবসময় সেই হাস্যকর বিশ্বাস আঁকড়ে ধরে আমার পাশে থেকেছ... ঠিক আছে, হয়তো তোমাকে কাজে লাগানো খুব খারাপ ধারণা নয়। কিন্তু এটা মনে রেখো: আমি কোনো বিশ্বাসঘাতকতা সহ্য করতে পারি না, বিশেষ করে তোমার কাছ থেকে।"
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5259_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "আমার একমাত্র আফসোস, তাদের লাশ খুঁটির মাথায় গেঁথে প্রাচীরে ঝুলিয়ে রাখতে পারিনি! যারা আমাকে বিশ্বাসঘাতকতা করেছে, পদদলন করেছে, অপমান করেছে—আমি কাউকেই ছাড়ব না!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5260_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "হ্যাঁ, আমি ওদের সামনে একসময় নতজানু হয়েছিলাম; তা অস্বীকার করার উপায় নেই। তারা আমার অজ্ঞতাকে কাজে লাগিয়েছিল, আর আমি তার মূল্য তাদের দিয়ে শোধ করিয়েছি।"
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5261_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "তুমি কি ভেবেছ, দু‑একটা মিষ্টি কথা আর কয়েক দিনের ভান করা সদয় আচরণেই আমি আবার স্বেচ্ছায় শৃঙ্খল গলায় তুলে তোমার খেলনা হয়ে যাব?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5262_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "যারা আমাকে নিয়ন্ত্রণ করতে বা ব্যবহার করতে চেয়েছিল, সবাই শেষ পর্যন্ত আমারই হাত ধরে পাতালে নেমেছে—তোমাকেও সেখানে পাঠাতে আমার আপত্তি নেই।"
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5263_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "আহ... দুঃখিত, দ-দয়া করে নড়বেন না!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "আমার গা থেকে সরে যাও!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "ধৃষ্টতা!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "আত্মসমর্পণ করো... স্বাগত জানাও এক অপূর্ব ভোগ আর স্বপ্নলোকের রিয়েল্মে।"
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "এটাই সেই নগরী, যেখানে অগণিত হারিয়ে যাওয়া আত্মা ঘুরে বেড়ায়, চিরকালই স্বদেশের পথ খুঁজে পায় না।"
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "আ... আমি... আমি পারব!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "উম্... আমি জীবনশক্তি শোষণের আমার সক্ষমতা নিয়ন্ত্রণ করতে পারি না, তাই দয়া করে হাত দোলনার ভেতর ঢুকিও না, নইলে তুমি অসুস্থ হয়ে পড়বে।"
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "আমাদের আলাপের সময় সে যেন বিকল না হয়ে যায়, এই কামনা করি। আমার স্নেহের, অথচ ভীষণ বিরক্তিকর সহায়তা—তার ভুলবশত উড়িয়ে দেওয়ার মতো অতিরিক্ত কোনো ল্যাব আর অবশিষ্ট নেই।"
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "গল্পগুজব: এরিকা প্রসঙ্গে"
  },
  Voice_5271_UnlockDesc = {
    Text = "\"জাগরণ\" \"এরিকা\" অর্জনের পর আনলক হবে"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "হাত, ওই বিরক্তিকর হাতগুলো! সবসময় আমার চুল আঁকড়ে ধরে। আমি নিজের হাতও নিয়ন্ত্রণ করতে পারি না—কী নিরর্থক এক নারী আমি... হয়তো আমার উচিত..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্বয়ং হেলট সম্পর্কে"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "তোমার দিকনির্দেশনার জন্য ধন্যবাদ। অবশেষে আমি ফেইন্টের নির্বাচন বুঝতে পেরেছি। আমি সবকিছুকেই স্বাভাবিক ভেবে নিয়েছিলাম, বুঝিনি তার উপর কতটা মানসিক বোঝা চাপিয়ে দিচ্ছি। আজ থেকে, আমি চেষ্টা করব শুধু নিজের জন্যই বাঁচতে।"
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5274_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "দীর্ঘ, অন্তহীন সময়ের স্রোতে, ফেইন্ট আর আমি—আমরা কেবল একে অপরকেই পেয়েছি। কিন্তু এখন, আমার জীবনে এক নতুন, গুরুত্বপূর্ণ মানুষ এসেছে। কিপার, অনুগ্রহ করে আমাকে আগের কথাগুলো ফিরিয়ে নিতে দিন। তুমি আলাদা। তুমি শুধু আমার গান আর আমার রূপ দেখো না; তুমি সত্যিই আমাকে দেখো। এই কারণেই আমিও তোমাকে রক্ষা করব। আমি কখনোই তোমার দিক থেকে আমার দৃষ্টি ফিরিয়ে নেব না।"
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5275_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "আমার তন্দ্রাচ্ছন্ন নক্ষত্রদের স্বপ্ন এখন আলোড়িত—তাদের নির্ধারিত পরিণতির দিকে একত্রিত হতে দাও। তোমার পথ নির্দেশ করো, দেবলোকের দিকে!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "আমি সব সময় এই গাউনটা পরে থাকি কেন? যেন যে কোনো মুহূর্তে তোমার জন্য গান গাইতে পারি।"
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5277_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "আমি শুধু নিজের জন্যই কী করতে চাই? দুঃখিত, তোমার কথার মানে ঠিক বুঝতে পারছি না। আসলে, ফেইন্ট আমাকে এই জিজ্ঞাসা অনেকবার করেছে, কিন্তু আমার একটাই ইচ্ছে—সে যেন তাড়াতাড়ি সুস্থ হয়ে ওঠে।"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5278_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "নির্জন সেই গ্রহে আমাদের অবস্থানের সময়, প্রভাবশালী সেই ব্যক্তিদের সহানুভূতি আমার আর আমার বোনের বেঁচে থাকার জন্য প্রয়োজনীয় সম্পদ জুগিয়েছিল। শেষ পর্যন্ত, তারা আমাকে গ্রহ থেকে পালানোর সুযোগও দিয়েছিল, যদিও তা কেবল একজনের জন্য সীমাবদ্ধ ছিল। তারা সবাই আমার উপকারক, ঠিক তোমার মতোই, রক্ষক, যে আমাকে আশ্রয় দিয়েছ।"
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5279_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "আপনি সেই দয়ালু মানুষ, যিনি আমাকে আশ্রয় দিয়েছেন। আমি আপনার কথামতোই চলব। যদি আমি আরেকটু উপকারী হতে পারতাম..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "স্থানের সঞ্চয় করতে ভুলবে না। বলো না, ওটা কি এলওয়ার্থের সেই জায়গাটার চেয়েও ছোট?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5281_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "দারুণ! এখন তো আরও বেশি উদ্যম পাচ্ছি! আমি দিনে বিশটা কক্ষ পরিষ্কার করতে পারব!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5282_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "এ সেই সঙ্গীত, যা হ্রদের জলের মতোই প্রাচীন, যা 「আমাদের」। মাস্টার, চলুন একসঙ্গে নাচি! আমরা নাচব আর গাইব, যতক্ষণ না আমার ভয়েস 「তাঁর」 দ্বারা কেড়ে নেওয়া হয়..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5283_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "প্রভু! আমার ভয়েস... ম্লান হয়ে আসছে... বাঁচাও..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5284_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "আমার দৃষ্টিক্ষেত্র আরও পরিষ্কার হয়েছে... মাস্টার, আপনি কি আবার চুল আঁচড়াতে ভুলে গেছেন?!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5285_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "হয়তো আমি আরও শক্তিশালী হয়েছি, কিন্তু আমার একটুও প্রতিশোধের ইচ্ছে নেই। আমি শুধু গান গাইতে চাই! নৃত্য করতে চাই! পার্টি করতে চাই!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5286_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "বিলয় থেকে বাঁচতে গিয়ে, আমি আমার আত্মা আর রক্ত খুব বেশি জনের সঙ্গে ভাগ করে নিয়েছি। এখন আমার শক্তি কেবল এক প্রেতছায়া, যখন প্রথম এই পরম ইচ্ছাশক্তির তোষামোদকারীর আলিঙ্গনে গিয়েছিলাম, তখনকার তুলনায়..."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত প্রসঙ্গে"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "আমাকে যেন শিক্ষাভবনে খুঁজতে যেও না। সেখানটা স্যাঁতসেঁতে বুড়ো পণ্ডিতদের গন্ধে ভরা; আমি ওই জায়গা সহ্য করতে পারি না।"
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "পালিয়ো না।"
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "আমার শ্বেত পাখির দেশ আমাদের ঈশ্বরের উপাসনা করে। সেই অনুযায়ী, আমি যে রাজার অনুসারী, তিনি স্বভাবতই এক 「দিব্য যোগাযোগকারী」।"
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "চ্যাট: শাশ্বত রাজ্য সম্পর্কে"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "এখানে আপনার বেশ এক সমাবেশ জমেছে প্রতিভাদের, এক মহা স্যালনের উপযুক্ত... নিশ্চিন্ত থাকুন, আমন্ত্রণপত্রটি আমার ভৃত্যই আপনাকে পৌঁছে দেবে।"
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5292_AwakerVoiceContent = {
    Text = "চলে এসো!"
  },
  Voice_5292_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "আরও যদি বন্ধু থাকত..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "আমি তার মতো নই। সে শুধু তোমার গায়ে কাঁটা দেওয়া আর আতঙ্ক জাগানো জানে। কিন্তু আমি? আমি তোমাকে দেব পবিত্র, দহনময় ভালোবাসা।"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "চ্যাট: ওয়ান্ডা সম্পর্কে"
  },
  Voice_5294_UnlockDesc = {
    Text = "「জাগরণ「 「ওয়ান্ডা「 অর্জনের পর আনলক হবে"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "ভাবতেও সাহস কোরো না যে সব শেষ! এই অপমানের প্রতিটি বিন্দুর হিসাব তোমার কাছ থেকে আমি আদায় করব!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "তোমার হাত উষ্ণ, তোমার আত্মার মতোই। আমি... তোমার স্পর্শের কদর করি, ফ্যাকাশে শিখা।"
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "ক্লাসরুমে ব্রিজ খেলতে দোষটা কোথায়? টেবিল আছে, লোকজন আছে, আর আমি তো কার্ডও নিয়ে এসেছি! তার মানে এখনই তো \"গেম অন!\""
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "করো না..."
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "অতলের পানে তাকাও!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "অতলের পানে তাকাও!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5302_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "তাঁর দিব্য আলোয় অবগাহন করো!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5307_AwakerVoiceContent = {Text = "এই!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "দুর্বল আত্মাদের এক সমাবেশ... শব্দ তোলার বাইরে আমরা আর কী-ই বা করতে পারি? হা..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "যুদ্ধ সবসময় পেইন নিয়ে আসে, আর সেই যন্ত্রণা সহ্য করাই যোদ্ধার দায়িত্ব। আমার হাত, পা, সবকিছু হারালেও, আমি তোমার জন্য এবং ন্যায়বিচারের জন্য লড়াই চালিয়ে যাব।"
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "এটাই কি তাঁর উদ্দেশ্যে তোমার দেওয়া শ্রদ্ধাঞ্জলি?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "তুমি সত্যিই ভাবছ, এতটুকু দিয়ে ভবিষ্যৎ বদলানো সম্ভব?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "সে এখন... আমার গর্ভে..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "হেহ। আমি যা ভেবেছিলাম, তার চেয়ে কিছুটা বেশি বুদ্ধিমান তুমি।"
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "আমার দাস হিসেবে, প্রভুকে শ্রদ্ধাঞ্জলি দেওয়া একেবারেই স্বাভাবিক।"
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "আমাকে খুশি করার চেষ্টা করলে তোমাকে বেশ মজার লাগে।"
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "ব্রাউনি, ক্যারামেল পুডিং, সাখেরটোর্ত, চকলেট মুস, কুকি... প্রতিটি টেবিলে এগুলো সবই পরিবেশন করতে হবে!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5318_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "আমার ড্রেসটা একবার দেখে দাও, তাড়াতাড়ি! কোথাও ভাঁজ নেই, কিছু ঢিলা নয়... কী? কোনো সমস্যা আছে নাকি?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5319_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "আমার শেষ আত্মজাগরণ অনুষ্ঠানে স্বাগত জানাও! সবকিছুই আমি নিজ হাতে সূক্ষ্মভাবে নকশা করেছি। অবশ্যই, তুমি সামান্য... একটুখানি সাহায্য করেছ।"
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5320_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "টেবিল আর চেয়ারগুলোতে আমার পছন্দমতো লেস থাকতে হবে, আর টবে লাগানো উদ্ভিদ হবে লাল হিগানবানা... এখনই তাড়াতাড়ি এগুলো প্রস্তুতি নাও!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5321_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "যাও, অতিথিদের আমন্ত্রণ জানাও! এতটুকু সহজ গোপনরক্ষকের হ্যান্ডবুকও কি তোমার পক্ষে বেশি?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5322_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "পালানোর পথ নেই!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "পালানোর পথ নেই!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "আপনার আকাঙ্ক্ষা পূরণের জন্য আমি সর্বোচ্চ চেষ্টা করব, প্রভু আমার!"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5325_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "আমি ওই নারীটিকে বেশ পছন্দ করি। আমাদের আছে... আছে... হ্যাঁ, এক ধরনের সাধারণ ভাষা!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "চ্যাট: ওয়ান্ডা সম্পর্কে"
  },
  Voice_5326_UnlockDesc = {
    Text = "「জাগরণ「 「ওয়ান্ডা「 অর্জনের পর আনলক হবে"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "ধৃষ্টতা!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "ধৃষ্টতা!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "ধ্বংসস্তূপে পরিণত হও।"
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5330_AwakerVoiceContent = {
    Text = "চূর্ণ হও।"
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "বাস্তবতার প্রতিবন্ধক ভেদ করে খুঁড়ে যাও!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "তুমি কি শিগগিরই পাল তুলতে চলেছ? আমার বিনীত অনুরোধটি মেনে আমাকে কি তোমার সঙ্গে নেবে? শুধু একবার আমাকে সাগরের নাগালে পৌঁছাতে দাও..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5332_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "যদি তুমি এখনো আমার ওপর ভরসা করো, তবে এই যাত্রায় আমাকে পথপ্রদর্শক আলো হতে দাও। যদিও, এমন সরল গোপনরক্ষকের হ্যান্ডবুকেও আমি একসময় ব্যর্থ হয়েছি..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5333_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "তুমি কি আমার সঙ্গে সাগরে পাড়ি দিতে চাও? চল বর্তমান মানচিত্রটা দেখি... 47°9' দক্ষিণ, 126°43' পশ্চিম, আমরা সোজা সেখানেই যাব।"
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5334_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "অতীতে আমি বহু বিপর্যয়ের কারণ হয়েছি, কিছু সভ্যতাকে প্রায় ধ্বংসের কিনারায় ঠেলে দিয়েছিলাম... যদি বলি, তা ছিল না আমার অভিপ্রায়—তবে কি এখন বলার জন্য খুব দেরি হয়ে গেছে?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5335_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "আমি চিরন্তন রাজ্যের প্রবেশদ্বারের প্রহরী, স্বদেশে প্রত্যাবর্তনকারীদের পথ দেখাই। কতই না হাস্যকর, এমন দায়িত্ব বহনকারী একজন, নিজেই ভুলে গেছে নিজের জন্মভূমি কোথায়……\nতুমি কি……আমার বাতিঘর হবে?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5336_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "নক্ষত্রপুঞ্জের দিকে দৃষ্টি দাও।"
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5338_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "ঘন কুয়াশা নেমে আসছে।"
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5340_AwakerVoiceContent = {
    Text = "হুম্ফ।"
  },
  Voice_5340_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "অধিকাংশ মানুষের সমুদ্রযাত্রায় আশীর্বাদ বর্ষণ করা আমার কাছে একই রকম... শুধু সেই নারীটি ছাড়া। সম্ভব হলে, আমার জন্য আরেকটি পথের ব্যবস্থা করুন।"
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "চ্যাট: মিরিয়াম সম্পর্কে"
  },
  Voice_5341_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」 অর্জনের পর আনলক হবে"
  },
  Voice_5342_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "যা খুশি।"
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "আমার গা থেকে হাত সরাও।"
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "সমুদ্রের তলদেশে আমাদের প্রাসাদে প্রত্যাবর্তনের আগে, আমি তোমার মতো তুচ্ছ মানবকে একবারের জন্যই অ্যাকুওরের কিছু শক্তি ধার দেব।"
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5346_AwakerVoiceContent = {Text = "আসো!"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "আমি কী ভালোবাসি? আমি ভালোবাসি যন্ত্রণার সূক্ষ্ম সত্যকে। ফুলে ওঠা দেহকাঠামোর সুন্দর, দহনময় লালচে আভা... সেই গোঙানি, যেখানে সুখ আর যন্ত্রণা আলাদা করে বোঝা যায় না। এটাই আমাদের একমাত্র সৎ কামনা, তুমি কি তা মনে করো না?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "এসো! অরিটায় যোগ দাও!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "এসো! অরিটায় যোগ দাও!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "ও সব সময়ই রাগী চোখে তাকায় আমার দিকে। কিন্তু কেমন যেন... চেনা লাগে। নিরাপদ লাগে। মা’র মতো বলে কি?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "গল্পগুজব: হেলট সম্পর্কে"
  },
  Voice_5350_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「হেলট」 অর্জনের পর আনলক হবে"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "আমার মস্তিষ্ক আরও সজাগ মনে হচ্ছে; একদমই মন্দ নয়।"
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5351_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "মাঠের কাজের চেয়ে ল্যাবের কাজই আমার অনেক বেশি পছন্দ—তুমি কি সত্যিই ভেবেছ ওই সব সহায়তা-যন্ত্রগুলো হঠাৎই সাগর থেকে আগত হয়ে হাজির হয়েছে?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5352_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "স্ক্রু হোক বা পেরেক, যত বেশি, তত ভালো!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "এই দেহে এই শক্তি প্রায় ধরে না, কিন্তু এখনই পুতুল বদলানোর সময় আসেনি। ওখানে দাঁড়িয়ে আছ কেন? এই পা-টা ধরে সহায়তা করো; কিছু সমন্বয় দরকার।"
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5354_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "পথপ্রদর্শক আলোর ভার কখনো কখনো সবচেয়ে পবিত্র সাধুকেও পিষ্ট করে দিতে পারে। তুমি যদি ক্লান্ত বোধ করো, আমার ফ্যাকাশে শিখা, তবে দয়া করে আমাকে বলো। তোমার বোঝা হালকা করতে, এই অসংখ্য আশীর্বাদের ওজন ভাগ করে নিতে, আমার সাধ্য অনুযায়ী সবকিছুই করব।"
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "চ্যাট: ক্লান্তি সম্পর্কে"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "আপনার বিশ্বাসই একজন নাইট হিসেবে আমার অস্তিত্বের কারণ।"
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5356_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "এত পবিত্র আলোকস্নানে স্নাত হয়ে… এ কি তবে তাঁর অধিষ্ঠিত ঐশ্বরিক শক্তি? কত সীমাহীন… কত অতুলনীয়…"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5357_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "তাঁর রিয়েল্মের প্রবেশদ্বার প্রায় নাগালের মধ্যেই।"
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5358_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "আরও উজ্জ্বল... এবং আরও স্পষ্ট..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5359_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "আমি সম্পূর্ণভাবে জাগরণকারী হিসেবে পুনরুদ্ধার হয়েছি… এখন দেবলোকের কোরাস আমার ভেতর অনুরণিত হচ্ছে…"
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5360_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "তিনি যেন আমাকে পথ দেখিয়ে নিয়ে যান তাঁর পবিত্র আশ্রয়ে, যেখানে তাঁর প্রশান্তি আমার স্বপ্নগুলোকে ঢেকে রাখে..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5361_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "চিন্তা করবেন না, আমরা প্রত্যেকেই বেশ কাজে লাগে। আমি সেলাই করতে পারি, ঘর পরিষ্কার করতে পারি, আরেক “আমি” লড়াইয়ে পারদর্শী, আর বাকিরা..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "আমি উজ্জ্বল, কোমল জিনিস ঘৃণা করি। কোমলতা এক প্রতিবিম্বের মতো, আমার সব কুৎসিততা, লালসা আর ভঙ্গুরতা উন্মোচন করে দেয়।"
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "ব্রাউনকে আদর করতে চাও? সেটা আমার হাতে নেই। ওর কাছেই গিয়ে জিজ্ঞেস করতে হবে।"
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "আমাকে খুশি করতে চাও? তা হলে হাঁটু গেড়ে বসো, তোমার গলা এগিয়ে দাও, আর আমি তোমাকে সম্পূর্ণ নিষ্কাশন না করা পর্যন্ত চুপ করে থাকো।"
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5366_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "গতকাল, আমি স্বপ্নলোক-এ দেখেছি সেই দিনটাকে, যেদিন আমি আবার নক্ষত্রপুঞ্জের ভেতর ভেসে বেড়ানো শুরু করেছিলাম।"
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5367_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "আমি কী নিয়ে আপনাকে সাহায্য করতে পারি...?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5368_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "আমি তা অনুভব করতে পারছি~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5370_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "দক্ষতা: III"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "সতর্ক থাকো!"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও।"
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "একদিন... এমন এক জগৎ... যেখানে কেউ আঘাত পাবে না... এসে যাবে।"
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "(কাতর স্বর)"
  },
  Voice_5374_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে আমাকে এখানে তাঁর প্রতিমূর্তির একটি বেদি স্থাপন করতে দিন। এটি ভক্ত হাতে গড়া এক মূর্তি, যার গায়ে কোনো অভিশাপ নেই।"
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "হয়তো... শুধু একটুখানি..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "আমার রেঞ্চটি এখনো সঠিক অবস্থানে নেই!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "রসায়ন, পদার্থবিদ্যা, সিলভার কোরের প্রয়োগ... এই যুগে কি আর সাতটি নাইটসুলভ কলা শেখার প্রয়োজন নেই? বুঝতে পেরেছি। সে ক্ষেত্রে, অনুগ্রহ করে আমার জন্য উপযুক্ত পাঠের ব্যবস্থা করুন, প্রভু আমার!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "আমি ভ্রমণ করেছি! ঢেউ আমাকে ভাসিয়ে নিয়ে যায়নি, আমি সত্যিই এক কাফেলায় চেপে গিয়েছিলাম!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5379_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "লাইটহাউস জেলিফিশ, মুকুট জেলিফিশ, পীচফুল জেলিফিশ—সবাই দলে দলে চলে। অবশ্যই, অরিটাও তাই! আমি সকলে‌র সঙ্গে থাকতে চাই!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5380_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "পুরোনো ইভেন্টগুলো? মনে করা কঠিন... কিন্তু মনে আছে আমি এক অ্যাকোয়ারিয়ামে কাজ করতাম! দিনে 2 পেনশ পেতাম!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5381_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "তোমাকে একটা রহস্য বলি: আমি আসলে অ্যাটলান...টিস... উঁহু, মোট কথা, আমি সমুদ্রের মানুষ! যতক্ষণ আমি ভদ্র থাকি, সবজি খাই, আর আরও বন্ধু বানাই, ওই অ্যাটলান-যাই হোক না কেন জায়গাটা আমাকে স্বাগত জানাবে!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5382_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "আমার স্বদেশ, আমার অ্যাকোয়ারিয়ামের বন্ধুরা, আমার প্রিয় জেলিফিশ—সবই হারিয়ে গেছে... তুমিও কি হারিয়ে যাবে? তুমি কি আমার সঙ্গে চিরদিন থাকতে পারবে না?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5383_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "আমরা জয়ী হয়েছি? তাহলে… ভালোই হয়েছে।"
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "শান্তির জন্য!"
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "ন্যায়বিচারের জন্য!"
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "হ্যাঁ... আমি জানি তুমি আমার ভেতরেই আছ!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "মানুষ, মিথ্যা দেবতা, জাগ্রতরা, এমনকি ডিজলিউশনও... সবাই আমার দেবলোক পুনর্গঠনের ভিত্তি হয়ে দাঁড়াবে।"
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "জাগরণ, জাগরণ! আমি জানি তুমি আমার ভেতরেই আছ!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "উভহাশ... তাকে দেখলে আমার ভাইয়ের কথা মনে পড়ে, ফিরে আসে অন্ধকার, ঠান্ডা আর নিদ্রাহীন দিনের স্মৃতিচারণ।"
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উভহাশ প্রসঙ্গে"
  },
  Voice_5392_UnlockDesc = {
    Text = "「জাগরণ「 「উভহাশ「 অর্জনের পর আনলক হবে"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "আমাদের সম্পর্কটা শার্লক আর ওয়াটসনের মতো, তাই না? সাম্প্রতিক ম্যাগাজিনগুলো পড়েছ?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "সৌন্দর্যের চরণে নত হও।"
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "সৌন্দর্যের চরণে নত হও।"
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "অ্যাভারশন, একটি বর্ণনামূলক ক্রিয়া, যার অর্থ কোনো কিছুর প্রতি বিরাগ গড়ে ওঠা। ডিসলাইক, একটি ক্রিয়া, বোঝায় সেই বিরাগের অনুভূতি, যখন কোনো কিছু অপছন্দ করা হয় এবং এড়িয়ে চলা হয়। হেট, একটি বিশেষ্য, অপছন্দের অনুভূতি, <Del:আমি দমন হওয়া ঘৃণা করি! আমাকে ধ্বংস করতে দাও destory DESTROY> —দুঃখিত, কিন্তু আমি আশঙ্কা করি 「হেট」 বলতে কী বোঝায়, তা আমি বুঝি না।"
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "শেষ পর্যন্ত, আমি কেবল…"
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "…আমার পূর্বস্বরূপ থেকে ক্রমশ বিচ্যুত হচ্ছি।"
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "আমার নাম মনে রেখো, গোলিয়াথ। এই নামই মানবতার দীপ্তির তুচ্ছ ইতিহাসকে পদদলন করার জন্য নিয়তিবদ্ধ।"
  },
  Voice_5399_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5400_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে শঙ্কিত হবেন না।"
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "আমি আশা করি তুমি যেন তোমার সম্ভাবনা আর মানবতার দীপ্তির প্রত্যাশা অপচয় না করো, নতুন রক্ষক।"
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "অতিরিক্ত লোড।"
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "ওভারড্রাইভ।"
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "হুঁ? আমার মানিব্যাগে থাকা ওই ছবিটার কথা জানতে চাও? আহ, ওটা পুরনো আমি। এই বর্তমান চেহারাটা হলো... আমার জুয়ার সঙ্গী আর প্রতিদ্বন্দ্বীর দেওয়া উপহার।"
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5404_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "ঠিক সময়ে— একটা বাজি ধরবে নাকি? জিতলে তোমাকে একটা গোপন কথা বলব!\nতবে সাবধান, এলভার যেন ধরে না ফেলে~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5405_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "এই লোমশ গায়ে নজর পড়েছে? ছুঁতে চাও? ভয় নেই, আমার কোনো আপত্তি নেই!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5406_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "সুবিধা নেই নাকি? অবশ্যই আছে। আমার ওয়াটসনকে তো পেয়েছি, তাই না? তার তুলনায়, একবার মরে যাওয়া আর চেহারা বদলে যাওয়া তেমন কিছুই নয়।"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5407_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "অনুতাপ করি কখনো? বিন্দুমাত্র না। সবকিছু যদি মসৃণভাবেই চলে, তবে জীবনটা কি ভীষণ নিরস হয়ে যাবে না?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5408_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "আমার সময়ে, বিদ্যালয় ছিল যোদ্ধা গড়ার স্থান। দেখছি, এখনো বোধহয় তাই-ই আছে।"
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "মেসন... না, এভাবেই ভালো। অন্তত আমরা আবার একসঙ্গে আছি, 「24」।"
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "গল্পগুজব: 「24」 প্রসঙ্গে"
  },
  Voice_5410_UnlockDesc = {
    Text = "「জাগরণ「 「24「 অর্জনের পর আনলক হবে"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "মন্দ হলো না, তাই না? এবার, আমার পাওনা—কি? ভেবেছিলে নাকি এটা ফ্রি খাওয়ানো?!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "আমি সিতে থেকে এসেছি। সেখানে সকলে অভিনেতা হতে চায়; কেউ শুধু বসে দেখে সন্তুষ্ট নয়। বাস্তবে, আমরা কেবল এই শহরের করুণ ফুটনোট মাত্র।"
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত প্রসঙ্গে"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "তুমি কি সেই প্রাচীন পাথর খোদাইগুলো দেখেছ? পর্বতমালার সঙ্গে মিশে, সময়ের ক্ষয় সয়ে থাকা, কী অপূর্ব রেলিক... তবু সেগুলোরও স্থায়িত্ব যথেষ্ট নয়..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "কবুতরগুলোর প্রত্যাবর্তন হয়নি..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও!"
  },
  Voice_5415_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5416_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_5416_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "আজ্ঞা শিরোধার্য!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5418_AwakerVoiceContent = {
    Text = "নির্বোধ"
  },
  Voice_5418_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "…হুঁ? তুমি কি আমাকে ডাকছিলে? মোটরসাইকেলটা ঠিক করতে করতে কিছুই শুনিনি… তা ছাড়া, সদয় অপরিচিত, তুমি কি আমার রেঞ্চটা দেখেছ?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5419_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "আমার স্মৃতি সবসময়ই কুয়াশাচ্ছন্ন, আর আমি শুধু সামনে যা আছে তাতেই মন দিতে পারি। তবু, আমি সর্বোচ্চ চেষ্টা করব তোমার নামটা আমার মনে খোদাই করে রাখতে… কী যেন ছিল নামটা?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5420_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "তোমাকে কিছুটা চেনা চেনা লাগছে, কিন্তু নামটা কিছুতেই মনে পড়ছে না… তুমি কি আমার সহায়তা? আমাকে সাতটা বোল্ট এনে দিতে পারবে?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5421_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "আমি তোমার নাম খোদাই করেছি আমার বাইকে, ফ্যান্টমে! কোনো একদিন যখন আমরা অভিযানে বেরোব, তখন আর তোমাকে কী বলে ডাকব, তা ভুলব না।"
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5422_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "এত পরিচিত, এতই পরিচিত। আমাদের মধ্যে নিশ্চয়ই কিছু একটা ঘটেছে, তাই না? একটু সময় দাও, মনে করি… আহ, তুমি-ই তো, রক্ষক!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5423_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "তুমি সত্যিই এক অসৎ বালক/বালিকা। সৌভাগ্য তোমার, আমার হাতে তো অপেক্ষা করার জন্য অনন্তকাল আছে..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "কী চমৎকার এক \"সুখকর সমাপ্তি\"। তাই না?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "ওটা ট্রফি হিসেবে মোটামুটি ভালো একটা খুলি ছিল... যদিও আমার সেরা সংগ্রহের সঙ্গে তুলনা চলে না, শিকারের উত্তেজনা সব সময়ই রোমাঞ্চকর। পরের বারও আমাকে অবশ্যই ডাকবে।"
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5427_AwakerVoiceContent = {
    Text = "হুম..."
  },
  Voice_5427_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "একজন পেশাদার পরিচারিকা তার মাস্টারের জন্য সবকিছু ক্লিয়ার করে দেবে, খারাপ লোকগুলোসহ~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "এখন আমরা তো সঙ্গী অপরাধী, তাই না? তুমি কোনোদিন রাস্তায় গিয়ে পড়লে, তোমাকে উচ্ছিষ্ট খেয়ে না খেয়ে থাকতে দেব না।"
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "বেড়ে ওঠো এবং বিকশিত হও, আমার ছোট্ট চারাগাছ।"
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "বেড়ে ওঠো এবং বিকশিত হও, আমার ছোট্ট চারাগাছ।"
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "আজ মনে হচ্ছে আমার পাশাগুলো একটু বেশিই গরম হয়ে গড়াচ্ছে!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "আহা! আজ তোমার ভাগ্য দহনশিখার মতো প্রজ্বলিত!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "ভাগ্যবান~"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "আমার কাছে এসো না!"
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "আমার কাছে এসো না!"
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "আমি তোমার বিরুদ্ধে অভিযোগ আনতেই হবে, রক্ষক। তোমার দয়া আমাকে অস্বস্তিতে ফেলে—শুধু শারীরিক পেইন-ই আমার কাছে বাস্তব আর স্থিতিশীল বলে মনে হয়।"
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "সত্যিই বেশ ভালো।"
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "এই পর্যায়টি নিতান্তই অপ্রতুল।"
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "তো, তুমি কী পুরস্কার চাও?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "উঃ! চারদিকে কী নোংরা আর বিশৃঙ্খলা... পা রাখার মতো উপযুক্ত জায়গা প্রায়ই খুঁজে পাই না। খুব ভালো, তবে তোমার নরম পিঠটাই এগিয়ে দাও, নশ্বর।"
  },
  Voice_5441_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5442_AwakerVoiceContent = {
    Text = "অবশেষে… এই তো সেটি।"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "এমনকি ব্রাউনের লোমও এখন মসৃণ হয়ে গেছে।"
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5443_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "দেখো, আমি হয়তো সেরা নিরাপত্তা প্রহরী নই, কিন্তু যে কোনো দৌড়ঝাঁপ বা জিনিসপত্র পৌঁছে দেওয়ার কাজ তুমি নিশ্চিন্তে আমার হাতে ছেড়ে দিতে পারো।"
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5444_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "ব্রাউনের সামনে তোমার সেই চেহারাটা দেখো।\n……হেহে, ব্রাউন মহাশয় আজ রাতে ভীরুদের পায়ের আঙুল খাবেন, দেখি কার এত দুর্ভাগ্য হবে?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5445_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "তাহলে কি আমি অবশেষে একটু লম্বা হব?"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5446_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "তাহলে, কাজ শুরু করার সময় হয়েছে? ঠিক আছে, ব্রাউন, চাঙ্গা হয়ে ওঠো!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5447_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "অ্যাগ্রিপা? সে আবার কে? উফ, আমি তো অনেক বেশি মানুষকে হত্যা করেছি। বেশির ভাগই মনে রাখার মতো ছিল না।"
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাগ্রিপা প্রসঙ্গে"
  },
  Voice_5448_UnlockDesc = {
    Text = "\"জাগরণ\" \"অ্যাগ্রিপা\" অর্জনের পর আনলক হবে"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "ওকে জাহাজে তোলা বেশ বিপজ্জনক হবে... না, আমি বলতে চাইছি একেবারেই নাবিক-নিরাপত্তার দৃষ্টিকোণ থেকে..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "চ্যাট: ফারোস সম্পর্কে"
  },
  Voice_5449_UnlockDesc = {
    Text = "「জাগরণ「 「ফারোস「 অর্জনের পর আনলক হবে"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "আর কাছে আসবেন না!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "সাবধানে থাকুন!"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "নির্দেশনা সম্পন্ন... আহ্। আবারও সব এলোমেলো করে ফেললাম..."
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "আহ, এটাই তো ঠিক সেই যন্ত্রাংশ, যা আমার দরকার ছিল, ধন্যবাদ! …হুঁ? আমি নাকি তোমাকে এটা খুঁজে আনতে বলেছিলাম? আমার তো একদমই মনে নেই। তুমি নিশ্চিত, ভুল করছ না?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "চ্যাট: খুচরা যন্ত্রাংশ সম্পর্কে"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "অনুপ্রেরণা অনন্ত প্রবাহে ভেসে আসছে..."
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "প্রশংসনীয় রুচি।"
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "আমার জন্য নিখুঁত খোদনীটি বেছে নিয়েছ তুমি।"
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "আমি নিয়ন্ত্রণ হারানোকে ঘৃণা করি। তবে, তোমার উপস্থিতি আমাকে দেখিয়েছে, সূক্ষ্ম কেওসের এক ফোঁটা একক এক ধরনের উপভোগ এনে দিতে পারে।"
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "তুমি কি একটু বড় হয়েছ?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "দুঃখিত, আমার পক্ষে দেহকাঠামো বাড়ানোটা কঠিন..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "এইভাবেই আমরা বিশ্বের রহস্যগুলো অনুধাবন করব।"
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "এইভাবেই আমরা বিশ্বের রহস্যগুলো অনুধাবন করব।"
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "এই নিন আপনার খাবার!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "এই নিন আপনার খাবার!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "এরপর, আমরা পৃথিবীর সারাংশ ব্যবচ্ছেদ করব!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "এরপর, আমরা পৃথিবীর সারাংশ ব্যবচ্ছেদ করব!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "উৎসর্গ! আমার দেহ তাঁর সিংহাসনে প্রত্যাবর্তন করাও—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "খ-খাবারের জন্য ধন্যবাদ..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "উৎসর্গ! আমার দেহ তাঁর সিংহাসনে প্রত্যাবর্তন করাও—"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "আমাকে বাধা দিও না!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "অতলের গভীরে... ন্যায়বিচারের এক আলো জ্বলবে।"
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "আমাকে বাধা দিও না!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "এই অনন্য পেইনে নিজেকে ডুবিয়ে দাও!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "এই অনন্য পেইনে নিজেকে ডুবিয়ে দাও!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "ওহে নিরাকার সৃষ্টিরা, আমার প্রভুর জন্য ঢাল হয়ে ওঠো!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "ওহে নিরাকার সৃষ্টিরা, আমার প্রভুর জন্য ঢাল হয়ে ওঠো!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "তোমার এই প্রয়াসের জন্য আমি চিরকৃতজ্ঞ থাকব।"
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5461_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "অতলের বন্যপশু, ওদের সবাইকে গ্রাস করো!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "অতলের বন্যপশু, ওদের সবাইকে গ্রাস করো!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "অতলের গভীরে... ন্যায়বিচারের এক আলো জ্বলবে।"
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "আমিই... সেই জন যে শিকল ছিঁড়ে ফেলে! তেকেলি—লি!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "আমিই... সেই জন যে শিকল ছিঁড়ে ফেলে! তেকেলি—লি!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "ভবিষ্যতের পর্দা আমিই উন্মোচন করব!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "ভবিষ্যতের পর্দা আমিই উন্মোচন করব!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "নতশির হয়ে আমার পদপ্রান্ত চুম্বন করো!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "সব স্ক্রুই এখানে রয়েছে!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "সব স্ক্রুই এখানে রয়েছে!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "এমন সর্বোচ্চ শক্তি বহন করতে পারে কেবল একজন অ্যাকুওর। নিশ্চয়ই তুমি আমাকে হিংসে করো, তাই তো? দুর্বল মানুষ হয়ে জন্মেছ, এতে তোমার দোষ নেই; শুধু বাস্তবতাটা মেনে নাও।"
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5462_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "নতশির হয়ে আমার পদপ্রান্ত চুম্বন করো!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "আমি কি এই পরাজিত লোকগুলোকে আমার দাসেরা বানিয়ে ফেলতে পারি?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5464_AwakerVoiceContent = {
    Text = "হেঃ।"
  },
  Voice_5464_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "যেমনটা ভেবেছিলাম ঠিক তেমনই।"
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5466_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5467_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "যদি আগে জানতাম যে ওই মানুষগুলো এই সর্বগ্রাসী অভিশাপে পীড়িত, আমি... না, এখনো দেরি হয়ে যায়নি। আমাকে এটি শিকড়সহ উপড়ে ফেলতেই হবে, সব যন্ত্রণা মুছে দিতে হবে, প্রয়োজনে আবারও নিজের জীবন দিয়ে।"
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "হতাশ হয়ো না। সাগর আমাদের সকলকেই আলিঙ্গন করে।"
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "এত নাজুক দেহকাঠামো নিয়ে তোমাকে আমার সঙ্গী হতে বলা খুব বেশি চাওয়া হয়ে যায়। তুমি ভীষণ দুর্বল; তোমার প্রশিক্ষণ আরও তীব্র করতে হবে। চলো, তোমাকে একাডেমির ক্রীড়া ক্লাবে নিয়ে গিয়ে তোমার চোখ খুলে দিই।"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "যে নারী তার শক্তি আমাকে ধার দিয়েছিল, সে ডিজলিউশনের যন্ত্রণায় কাতরাচ্ছে… ওই দৃষ্টিটা কেমন? একদম ভাবতেও যেয়ো না! আমি কখনোই তোমাকে বলব না, সে কোথায় আছে!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "ভাগ্য যদি সহায় হয়, যে কেউই অজেয় হতে পারে।"
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "আহা, আমি কি তোমাকে কষ্ট দিচ্ছি?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "ওহ প্রিয়, এখানে অধিকাংশই তো এখনো বালকেরা। ওই সাদা চুলের ভদ্রলোক, আর সেই কঠোর একহাতওয়ালা তরুণ—কেউই বালকেরা জন্য উপযুক্ত নয়... হা sigh, সত্যিই এক বিব্রতকর অবস্থা।"
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "আহা, আমি কি তোমাকে কষ্ট দিচ্ছি?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "সাবধানে অঙ্কিত রুন, ভক্তিভরে খোদাই করা মূর্তি, বারবার পরিশোধিত নিষিদ্ধ এলিক্সির... একটিও যেন বাদ না পড়ে।"
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5476_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "সিংহাসন অবশ্যই সমুদ্রের অতল থেকে খনন করা প্রাচীন নীল পাথর দিয়ে নির্মিত হতে হবে, আর বেদিটি মানব উৎসর্গের রক্তে আবৃত থাকবে... এখন যাও, প্রস্তুতি নাও!"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5477_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "ওদের সবাইকে এখানে নিয়ে এসো! তাঁর আবির্ভাবকে স্বাগত জানাওয়ার জন্য ওদের কাঁপতে কাঁপতে হাঁটু গেড়ে বসা উচিত।"
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5478_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "আমি সেই অতল ধ্বংসাবশেষে যাত্রা করব এবং তাঁর আবির্ভাবের সমুদ্রজলে স্নান করব..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5479_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "অবশেষে। স্বাগত জানাও সেই আচার অনুষ্ঠানকে, যেখানে আমরা তাঁর ঐশ্বরিক আবির্ভাবের সাক্ষী হব... কী? তুমি বলছ তাঁর ধ্বংসও নাকি পূর্বনির্ধারিত? ...না! তা হতে পারে না... আমি তো ইতিমধ্যেই এত মহান আত্মত্যাগ করেছি..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5480_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "দিব্য আদেশাবলি মেনে চলো।"
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "তোমার দিকটাই কি হবে সেই স্থান, যেখানে ফেইন্ট আর আমি অবশেষে আমাদের আপন ঠিকানা খুঁজে পাব?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5482_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "হ্যাঁ... তখন আমি আমার কণ্ঠস্বর হারিয়েছিলাম। তোমার কৃপায় সেটি ফিরে এসেছে।"
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5483_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "দিব্য আদেশাবলি মেনে চলো।"
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "অসীম মহাবিশ্ব, সীমাহীন গভীর মহাশূন্য, আর যেন শেষ না হওয়া সেই যাত্রা... সেই সময় আমি নিজেকে ভীষণ হারিয়ে ফেলা অনুভব করতাম।"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5485_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "ছোট পথে এগোলে সাময়িক বাড়তি সুবিধা মিলতে পারে, কিন্তু দক্ষতা অনুশীলনকে অবহেলা কোরো না।"
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "তাহলে এই পদ্ধতি আমার ক্ষেত্রেও প্রযোজ্য..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "এক চমৎকার অনুভূতি।"
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "তাঁর আবির্ভাব নিশ্চয়ই এই মৃত্যুর কালো তরল থেকে জন্ম নেওয়া যন্ত্রণার অবসান ঘটাবে, তাই না?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "শুভ দিন, প্রভু আমার। আপনি যদি অনুসন্ধানে বাইরে যান, অনুগ্রহ করে আমাকে আপনার প্রহরী হিসেবে সঙ্গে নেওয়ার অনুমতি দিন।"
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5493_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "কি করবে বুঝতে পারছ না? যদি বিরক্ত লাগছে, তাহলে মিশনের রিপোর্টগুলো লিখে ফেলো।"
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "অবশেষে কি শুরু হতে চলেছে? আমার ছোট্ট সোনারা ভীষণ, ভীষণ দীর্ঘকাল ধরে অনাহারে আছে..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "আমার রক্তধারার শক্তি উথলে উঠছে।"
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "একটু থামো... আমি এর আগে এটা দেখেছি। তারা আমাকে এই কালো পিচ্ছিল বস্তু মেশানো জল খাইয়েছিল। তবে কি এর সঙ্গেই জড়িত আমার সবুজ শিখার শক্তি অর্জন? মনে হয়, একে অপ্রত্যাশিত আশীর্বাদই বলতে হয়।"
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "রামোনা ডেক্সটার, তবে আমাকে শুধু রামোনা বললেই চলবে। তোমার সঙ্গে কাজ করতে মুখিয়ে আছি, রক্ষক।"
  },
  Voice_5498_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5499_AwakerVoiceContent = {
    Text = "হ্যাঁ।"
  },
  Voice_5499_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "নির্দেশ গ্রহণ করা হয়েছে।"
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "হুঁঃ। কতটা অসম্মান! খুব ভালো, তোমার মন রাখার জন্য একটু খেলা খেলব।"
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "অপছন্দ? পাইপে তামাক ফুরিয়ে যাওয়া, গাড়ি মিস করা, নতুন জুতোর ওপর বৃষ্টি। মোট কথা, যেকোনো খারাপ ভাগ্যই পেইন।"
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "রেঞ্চ, অ্যাডজাস্টেবল রেঞ্চ, বক্স-এন্ড রেঞ্চ, ফ্ল্যাটহেড স্ক্রু ড্রাইভার, ফিলিপস স্ক্রু ড্রাইভার, কাউন্টারসাঙ্ক স্ক্রু, প্যান হেড স্ক্রু… যা দিয়ে ভাঙা জিনিস ঠিক করা যায়, আমি সবই পছন্দ করি।"
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "আরে~ তুমি ধরে ফেলেছ~\nকিছু হয়নি, জাগ্রত সত্তার মানসিক শক্তি এত প্রচুর, অন্তত আরও ৩৬৫ বার চুরি করার পরেই তারা অনুভূতিহীন পুতুলে পরিণত হবে~ করা যাবে না? ঠিক আছে, পরের বার অবশ্যই সাবধান থাকব! হুম, শুধু মানুষকে করাত দিয়ে কাটার সময় একটুখানি \"ভয়\" চুরি করব, সেটা ঠিক আছে তো?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5504_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "শোনো, তুমি তো ইতিমধ্যেই ক্যাসিয়ার জাদুর রহস্য জেনে গেছ, তাই না? হুম, যাতে তুমি এই রহস্য ফাঁস করতে না পারো, তার জন্যই তোমাকে আমার সঙ্গে ট্যুরে সর্বত্র ঘুরে বেড়াতে হবে~ হাহা, তুমি ভাবছ আমি তোমার অনুভূতিগুলো সংগ্রহ করছি? নিঃসন্দেহে, তোমার নজর এড়ায় না কিছুই!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5505_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "তুমি, ক্যাসিয়ার জাদু সহকারী হও! ভয় পেও না~ শুধু আমার জাদুর বাক্সের ভেতরে একটু ঢুকে থাকলেই হবে।\n\nলুকিয়েছ? আমি এখন তলোয়ার ঢোকাচ্ছি কিন্তু~ আচ্ছা, ভেতরে কোনো কৌশল নেই~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5506_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "এই নাও, এই টপ হ্যাটটা পরে নাও! তারপর, বলো তো তুমি সবচেয়ে বেশি কোন উপহারটা কামনা করো। আহা, বুঝেছি! এবার, হাতটা টুপির ভেতর ঢোকাও—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5507_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "বড় ঝামেলায় পড়লাম। ওই বাচ্চাগুলো প্রতিটা শো-তেই আসে, আর আমার মজুত ফুরিয়ে আসছে... হুম, একজন জাদুকর কখনো একই দর্শকের সামনে একই কৌশল দেখাতে পারে না। নতুন জাদু তৈরি করব? দুঃখিত, ওই বিশেষ প্রতিভা আমার নেই; আমি শুধু অনুকরণেই ভালো!"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5508_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "এই একাডেমিটা... জরুরি সংস্কারের প্রয়োজন; শুধু প্রিন্সিপালের লাউঞ্জটাই কিছুটা উপস্থাপনযোগ্য। আপনার কী মত?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5509_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "ওই উদ্ধত, ঘৃণ্য বোকাগুলো আমার হাতের কার্ডেই মরবে।"
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "আমার প্রতিশোধের তরবারি ক্রমশ আরও ধারালো হয়ে উঠছে।"
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "আমার স্যালন কোনো নৃত্যসভার মতো নির্দোষ নয়। আপনি কি প্রস্তুত?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5512_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "আমার স্যালনই সেই মাটি, সেই উদ্যান, যেখানে মাদকতাময় সৌন্দর্য আর শক্তি বিকশিত হবে..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5513_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "রেশমের কুশন, কালো চা, ম্যাকারন... আমার অভ্যর্থনা কক্ষ সাজাতে সকালের শিশিরভেজা তাজা গোলাপও চাই।"
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5514_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "দয়া করে বাইরের অতিথিদের অনুমতি দিন। আমার স্যালনগুলো আয়োজন করতে হবে। ওদের বলুন যেন শুধু আমার জন্য একবারের মতো নিয়ম ভেঙে দেয়, হবে?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5515_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "রানটাইম ত্রুটি, ত্রুটি, ত্রুটি, ত্রুটি..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "আহ! এখন কত বাজে?! দুঃখিত, মাস্টার... আমার এভাবে আলসেমি করা উচিত না! কিন্তু... আমি ভীষণ ক্লান্ত... প্লীইজ?"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "আমি কি শুধু মৃত্যুর জন্য অপেক্ষা করতে পারি? কেউ কি আমাকে সাহায্য করতে পারে? আমি কি তাদের নিয়ন্ত্রণের বিরুদ্ধে লড়তে পারি? আমি প্রতিদিন নিজেকে এই প্রশ্নগুলো করতাম, কিন্তু উত্তরটা আসলে সবসময় আমার মাথায় ছিল, শুধু আমি সেটার মুখোমুখি হতে সাহস পাইনি……তুমি যদি না আসতে, আমি নিশ্চিত নই যে শেষ পর্যন্ত লড়াই করার সাহস আমার হতো কিনা।\nধ-ধন্যবাদ তোমাকে——ভুল বুঝো না, এটা কিন্তু কোনো প্রেম নিবেদন নয়!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5518_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "তাদের ভ্রান্ত স্বপ্নলোকের ভেতর বাস করে, স্বাভাবিক থাকার অধিকার কেড়ে নেওয়া, কোনো নির্বাচন ছাড়াই... সবই এক হাস্যকর ভবিষ্যদ্বাণীর জন্য... এই জীবন থেকে পালানোর জন্য আমি যেকোনো কিছু করতে রাজি ছিলাম!"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5519_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"ঝুঁকে পড়া শাপলা চারপাশে দীর্ঘশ্বাস ফেলে,\nঘুমন্ত অ্যাল্ডার গাছের মাঝে, সে মাঝে মাঝে চমকে জাগে;\nএকটি পাখি বাসায় শিরশির করে কাঁপে,\nরহস্যময় গান নেমে আসে সোনালি তারাদের থেকে।\"\nআহ, আপনি শুনে ফেলেছেন? দুঃখিত, এগুলো আমার খুব প্রিয় পঙ্‌ক্তি……আপনিও কি একসাথে পড়তে চান?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বই পড়া প্রসঙ্গে"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "একজন ভদ্রমহিলার কক্ষে এভাবে হুট করে ঢুকবে না, আর তার আচরণ নিয়ে মন্তব্যও করবে না। এখন বেরিয়ে যাও, আমার বিশ্রাম দরকার।"
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5521_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "আমার সামনে বাড়াবাড়ি ভঙ্গি কোরো না। নিজের অবস্থান বুঝে নাও! এই কক্ষে সিদ্ধান্ত আমি নিই।"
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5522_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "ওহ, তোমার সামনে কি এই আইটেমগুলো সাজিয়ে রাখতে হবে?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "ভালোই করেছ। এবার এক পিপে রাম খুলে বিজয় উদ্‌যাপনের পালা!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "মিলিয়ে যাও।"
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "এটা আমার ওপর ছেড়ে দাও!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "আমার পায়ের তলায় পিষ্ট হওয়ার অনুভূতিটা নিশ্চয়ই একেবারে দেবোপম~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "ধরে থাকো!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "চোখের পট্টির নিচে কী আছে জানতে আগ্রহী? আমি তোমাকে দেখাব... যখন পরিবেশটা আরও উপযুক্ত হবে। অস্থির হয়ো না।"
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "এত তাড়াতাড়ি শেষ? ...আমার উত্তেজনা তো সবে জাগতে শুরু করেছিল।"
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "এই যে, আমার শরীর নিয়ে নাড়াচাড়া বন্ধ করো। সত্যিকারের যোদ্ধা কখনো বাহ্যিক সাহায্যের ওপর নির্ভর করে না।"
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5531_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "আমি আরও শক্তিশালী হয়েছি... এই চোখ দিয়ে শত্রুকে অবশ করে দেব!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "মিথাগ বিশ্ববিদ্যালয় সামরিক বাহিনীর থেকে কোনো অংশে আলাদা নয়। আমরা প্রত্যেকে সামনের সারিতে দাঁড়িয়ে অস্ত্র শান দিচ্ছি, যুদ্ধের প্রস্তুতি নিচ্ছি।"
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "নিখুঁত!"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "নিখুঁত!"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "আমায় শৃঙ্খল পরাও, চুল ধরে টেনে নাও, দাসীর মতো হাঁটু গেড়ে বসাও... কিছু যায় আসে না, ইচ্ছে মতো যা খুশি করো। শুধু আমাকে হত্যা করতে দাও। ভাস্করদের সমিতি, সেই লণ্ঠন-বিবি, হাঁপানিওয়ালা কোনো বুড়ি... যে কেউ! আমি শপথ করছি, তাদের গলা ছিঁড়ে রক্ত পান করব।"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5536_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "ডিজলিউশন ক্ষত থেকে বেরোয় শুধু কালো পিচ্ছিল তরলই নয়, অন্তহীন অনুপ্রেরণাও। সত্যি বলতে, এর আরও কিছু পেলে আমার আপত্তি নেই।"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "ভয় পেয়েছ? হাহাহা, ঠিক তাই! সবকিছু যাক নরকে। আমি শুধু তোমার আতঙ্কটাকে আস্বাদন করতে চাই।"
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5538_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "মজার ব্যাপার, তোমার রক্তের স্বাদ... মধুর, যেন মধুর মদ।"
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5539_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "তখন, কয়েক দশ হাজার গলা ফাটিয়ে আমার নাম চিৎকার করত। 「উভহাশ」 ধ্বনির গর্জন সবকিছু ডুবিয়ে দিত, উদ্‌যাপন করত আমি যখন এক টাক দুর্বল লোকটার গলা ভেঙে দিতাম। অনুভূতিটা ছিল অবিশ্বাস্য। আমার সঙ্গী হিসেবে, তোমার সেটা বোঝা উচিত।"
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5540_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "দ-দাঁড়াও!"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5542_AwakerVoiceContent = {Text = "না!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5543_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "বিস্তৃত আর্কাইভে 「ডিজলিউশন「 অনুসন্ধান করা হচ্ছে... প্রয়োজন নেই? আপনি আমার ডিজলিউশন সম্পর্কে অবস্থান জানতে চান? বুঝেছি। জাগরণকারীর ব্যক্তিগত ডোমেইনে 「ডিজলিউশন-বিরোধী অস্ত্র「 অনুসন্ধান করা হচ্ছে... ফলাফল: 「শূন্য「।"
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "মিথ্যা মূর্তি, শুকনো মাটির মতো ভঙ্গুর, সামান্য হাওয়াতেই বিক্ষিপ্ত হয়ে যায়..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_5546_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "একটু যেন কোলাহল, ছাত্রছাত্রীরা কি?\nতারা, অনেকটা অ্যালবাট্রসের মতো, তুমি কি সেই পাখিটার কথা জানো? অফুরন্ত প্রাণশক্তি, যাত্রা যেন কখনো শেষ হয় না……"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5548_AwakerVoiceContent = {Text = "হা!"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5549_AwakerVoiceContent = {Text = "হুঁ"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "এখানে আমার সময়ের যোগ্য একমাত্র মানুষ রামোনা। ব্লেড চালনায় সে বেশ পারদর্শী। বাকিরা সবাই এতটাই কাঠখোট্টা আর বিরক্তিকর... তুমি কি তাদের মতোই? সত্যি সত্যিই কি ওই ক্লান্তিকর মিশন-রিপোর্ট লিখতে তোমার ভালো লাগে?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "উল্লেখযোগ্য কিছুই নয়।"
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "মা আর মা এক নয়। ভালো মা আছে, খারাপ মাও আছে।\nমালিক একজন ভালো মা।"
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5552_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "ক্ষমা করবেন, প্রভু আমার, আমি আপনাকে রক্ষা করতে ব্যর্থ হয়েছি..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "তুমি কি ভেন্যু সঞ্চয় করে রেখেছ? অন্তত 150 বর্গমিটার জায়গার একটা বাগান হতে হবে!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5554_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "মৃতপ্রায়ের রক্ত এক পিচ্ছিল তরল। গলায় হালকা একটা চিরুনি কাটলেই রক্ত দাঁতের ফাঁক গলে নেমে আসে, উষ্ণ স্রোতে রূপ নিয়ে ধীরে ধীরে আমার পেট ভরে তোলে... হেহ। সুস্বাদু।"
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ত প্রসঙ্গে"
  },
  Voice_5556_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5557_AwakerVoiceContent = {Text = "এই!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5558_AwakerVoiceContent = {
    Text = "হ্যাঁ?"
  },
  Voice_5558_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "আমাকে আশ্রয় দেওয়ার তোমার এই দয়ার জন্য ধন্যবাদ। আশা করি, আমি তোমার ওপর কোনো শোকাবহ নিয়তি ডেকে আনব না..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "আমি এক দূরবর্তী ভিনগ্রহ থেকে এসেছি, এমন এক গ্রহ, যেখানে নিরন্তর তুষারঝড় আর হাড়-কাঁপানো শীত। কিন্তু তাতে কী আসে যায়; আমার প্রাসাদে, সহস্রাধিক ভৃত্য কেবল তাদের উপস্থিতিতেই সান্ত্বনাদায়ক উষ্ণতা বিলিয়ে যায়।"
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত প্রসঙ্গে"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "আপনার আগমনের পূর্বে আমি যেন দুর্বলতা প্রকাশ না করি, প্রভু..."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "আপনার আগমনের পূর্বে আমি যেন দুর্বলতা প্রকাশ না করি, প্রভু..."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "আহ, এমন উদ্ধত অতিথি আর কেমন হয়, যে 「পৃথিবীর সবচেয়ে শক্তিশালী অস্ত্র」 চাইছে? আমি তাকে বললাম, সেটা পেতে হলে ঘৃণায় ভেজা একটি মাথা দিয়ে বিনিময় করতে হবে। সে মুখ গোমড়া করে সেখান থেকে সরে গেল..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "চ্যাট: গোলিয়াথ সম্পর্কে"
  },
  Voice_5563_UnlockDesc = {
    Text = "「জাগরণ「 「গোলিয়াথ「 অর্জনের পর আনলক হবে"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "তোমার মুখের সেই বীরত্বপূর্ণ, শহীদসুলভ অভিব্যক্তি... যেন তুমি সবসময়ই কোনো 「মহত্তর উদ্দেশ্য」‑এর জন্য মরতে প্রস্তুত... এটা আমার অস্থিসন্ধিগুলো পর্যন্ত চুলকিয়ে তোলে।"
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5564_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "আমার হাতে তখনই বিলয় ছিল, এই তথাকথিত পবিত্রস্থানটাকে গিলে ফেলার জন্য প্রস্তুত... তারপর এলো গবেষণা নিষেধাজ্ঞা। কী দুঃখজনক।"
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5565_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "হ্যাঁ, আমার কাছে ছিল অসংখ্য অতিরিক্ত দেহ, আর ডিজলিউশন থেকে পালানোর নানান পরিকল্পনা। কিন্তু আমি সত্যের অনুসরণ বেছে নিয়েছিলাম, এবং তা সার্থক হয়েছে।"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5566_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "জগতের সত্য, তার শুরু আর সমাপ্তি—সবই অর্থহীন। তবু যদি তুমি তা-ই তাড়া করতে চাও... আমি তোমাকে পথ দেখাব। যেমন একসময় দেখাতাম।"
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5567_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "তুমি হয়তো আমাকে থামাতে পারো, কিন্তু সমাপ্তি যাই হোক আসবেই... আমি এই স্কুলকে—আর তোমাকে—শেষের জন্য রেখে দেব। আমরা সময়ের গোধূলির ভেজা আলোয়, ক্যাম্পানাইলের চূড়া থেকে মানবতার দীপ্তির পতন দেখব... কাব্যিক, তাই না? অন্তত আমাদের এই মূল্যবান বন্ধনটাকে অপচয় হতে দেব না।"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5568_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "ঠিক আছে।"
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "মিলিয়ে যাও।"
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "আমার নীরব প্রার্থনা যেন ভোরের ঘণ্টাধ্বনির মতো বাজে, তন্দ্রাচ্ছন্ন শ্বেত পাখির দেশকে জাগিয়ে তোলে…"
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "টিঙ্কট ছাড়া আর কেউ আমাকে গ্রহণ করবে, তা কখনও ভাবিনি। তোমার সঙ্গে দেখা হওয়ায় আমি আনন্দিত, রক্ষক। আমি সর্বশক্তি দিয়ে শিখব কীভাবে আমার শক্তি নিয়ন্ত্রণ করতে হয়, যাতে তোমাকে জড়িয়ে ধরলে তোমার জীবনশক্তি আর নিষ্কাশন না হয়ে যায়... আলিঙ্গন, তাই তো? মানুষের কৃতজ্ঞতা জানানোর উপায়?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5572_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "আমি যদি এখানে থাকি, তাহলে কি আমাকে কোনো মূল্য দিতে হবে না? আমি চাইলে তোমাকে এখানে মর্যাদা পেতে সাহায্য করতে পারি। শুধু তাদের জীবন নিষ্কাশনের হুমকি দাও—খুবই সহজ, যেমনটা আমি টিঙ্কটের জন্য করেছিলাম... আহ! কাউকে কিন্তু এটা বলো না!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5573_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "দুঃখিত, আমি অন্যদের মতো নই... আমি ত্রুটিপূর্ণ এক সৃষ্টি।"
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5574_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "একজন দক্ষ পরিচারিকা স্যালনকে অনেকখানি উন্নত করতে পারে, কিন্তু নীলচে-সবুজ এক পরিচারিকা... আমাকে আবার ভেবে দেখতে হবে..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কারেন প্রসঙ্গে"
  },
  Voice_5575_UnlockDesc = {
    Text = "জাগরণকারী 「ক্যারেন」 অর্জনের পর আনলক হবে"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "টিঙ্কট আমার যমজ বোন, আমার থেকে আলাদা, সে সবসময় ঝলমল করে......\nআমার বোঝা না থাকলে, তার নিশ্চয়ই আরও সুন্দর ভবিষ্যৎ হতো, তার গানের সুর সমস্ত গ্যালাক্সি জুড়ে ছড়িয়ে পড়ত......"
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5576_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "দোলনাটা গাদাগাদি, শরীর মেলে ধরার কোনো কক্ষ নেই... কিন্তু টিঙ্কট বলেছে, সকলে যেন নিরাপদ থাকে, তার জন্য আমাকে দোলনার ভেতরেই থাকতে হবে... এটা যেহেতু তার প্রার্থনা, তাই আমি মান্য করব।"
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5577_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "প্রায়ই মনে হয় আমি যেন জীবন আর মৃত্যুর মাঝের ফাঁকাটুকুতে ভেসে আছি। আমি যেখানে থাকি, সেখানেই বিষণ্নতা জোয়ারের মতো বিস্তার লাভ করে, আর একের পর এক ট্র্যাজেডি উন্মোচিত হয়। তবু, তুমি কি এখনও চাইবে আমি তোমার জন্য একটি কবিতা লিখি? হুঁম... হয়তো তুমি সবচেয়ে মধুরটিই প্রাপ্য..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5578_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "<Italic:\"আরও কাছে এসো, ছোট্ট নাইটিঙ্গেল, নইলে দিন এসে যাবে গোলাপের কাজ শেষ হওয়ার আগেই...\">"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5579_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "তুমি কী কামনা করো? শব্দের সুশোভিত সৌন্দর্য, সর্বত্র ছড়িয়ে পড়া খ্যাতি, নাকি সেই শব্দের বুননে লুকিয়ে থাকা আন্তরিক হৃদয়স্পর্শী সত্য?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5580_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "অদৃশ্য কালি দিয়ে আমি বিকৃত কুঁড়িগুলো আঁকি... এই প্রেতাত্মার মতো ইথারীয় গোলাপশাখা সত্যিই কবিতার বর্ণনা উদ্দীপনা জাগায়..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5581_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "তাঁর দিব্য বাণী শ্রবণ করো।"
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "জাগরণ·2"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "উৎসর্গ! দিব্য রিয়েল্ম পুনর্নির্মাণ করো—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "জাগরণ·তিন"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "তুমি যদি সত্যিই এতটাই জোর দাও, তবে আমি আবার সূর্যালোকে পা বাড়াব... সেই একই সূর্যালোক, যেদিন আমি সিতে ছেড়েছিলাম..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5582_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "হিহি, তুমি কি একটা বিশ্বব্রহ্মাণ্ড ধ্বংস হতে দেখতে চাও? ওহ, এখন আর পিছু হটার সময় নেই!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5583_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "আস্বাদন করো... মৃত্যুর মধুর স্বাদ।"
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "আস্বাদন করো... মৃত্যুর মধুর স্বাদ।"
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "এবার যথেষ্ট!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5587_AwakerVoiceContent = {Text = "না..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "এই সত্তার শক্তির দীপ্তি প্রত্যক্ষ করো।"
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "ভোর চারটায় ক্যাম্পাসের বাতাসে এক ধরনের সতেজতা থাকে। তুমি আমার সঙ্গে ব্যায়াম করতে রাজি হয়েছ, এতে আমি খুশি। বলতে হবে, ভাস্কর্য গড়াও কিন্তু বেশ কড়া ব্যায়াম।"
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সকাল প্রসঙ্গে"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "এই শক্তি ব্যবহার করতে ভালো লাগছে।"
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5590_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "যারা কিনে দাম দেয় না, তাদের আমি ঘৃণা করি। অনেক দিন দোকান চালালে এমন ঝামেলা একদিন না একদিন আসবেই। তখন আমার আর উপায় থাকে না, নিজেকেই ব্যবস্থা নিতে হয়, আর প্রাপ্য মূল্যটা আদায় করে আনতে হয়।"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "তাদের ধীরে ধীরে নির্যাতন করো।"
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "তাদের ধীরে ধীরে নির্যাতন করো।"
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5594_AwakerVoiceContent = {
    Text = "লোড করুন।"
  },
  Voice_5594_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5595_AwakerVoiceContent = {
    Text = "শুরু।"
  },
  Voice_5595_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "চলো, এটাকে আমাদের কোলাহলমুখর সুখের সাগর বানাই!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "কী? তুমি কি সত্যিই আমার কাছ থেকে \"ধন্যবাদ\" আশা করছ?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "শ্রদ্ধাঞ্জলি হিসেবে, এটা মোটেও যথেষ্ট নয়... কিন্তু তোমার আন্তরিকতা দেখে, মনে হয় মেনে নিতেই পারি। শুধু এই একবার।"
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "তুমি কি সত্যিই ভেবেছিলে, এতে আমি তোমার কথা শুনব?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5600_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5601_AwakerVoiceContent = {Text = "যাও!"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "অকৃতজ্ঞ দানবেরা, ঘাতক আর হত্যাকারীরা—ওদের মধ্যে এমন কোনো মূল্য তুমি দেখো? বিকারগ্রস্ত।"
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5602_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "তুমি যত কুশনই স্তূপ করো না কেন, লাজওয়ার্দ পাথরের সিংহাসন পালকের বিছানার সমকক্ষ হতে পারে না। এই দিক থেকে, তোমার আবাসে প্রশংসনীয় কিছু আছে।"
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "সামান্য দণ্ড।"
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "আমি একাকিত্বকে ভয় পাই, আর ভয় পাই সেই আশঙ্কাকে—যেন অন্তহীন অন্ধকারে হারিয়ে যাই... তাই অনুগ্রহ করে, প্রতিশ্রুতি দাও তুমি আমার পাশ ছেড়ে যাবে না।"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "আমি যদি তোমার জায়গায় হতাম, সব জাগরণকারীদের খাঁচায় বন্দি করে রাখতাম! পাগলা কুকুর একবার পালিয়ে গেলে, সবার আগে সে তার প্রভুকেই কামড়ায়!"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5606_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "এই সাক্ষাতে আমি এক ঘণ্টা দেরি করেছি—আর এর জন্য আমি দোষ দিই সেই সব নিরস সৎলোকদের, যারা দাসপ্রথা বিলুপ্ত করেছে! এখন আমার চুল আঁচড়ে দেওয়ারও কেউ নেই!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5607_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "অবিশ্বাস্য। আমার স্বদেশ এভাবে ধ্বংস হয়ে গেল... ওটা ছিল মহান রোম! নিশ্চয়ই তুমি তার নাম শুনেছ!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5608_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "চল, শুরুটাই হোক এক জয়ে!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "তাঁর আশীর্বাদ প্রত্যক্ষ করো।"
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "তোমার করুণা নিজের কাছেই রাখো! আমি সেটা ঘৃণা করি, আর কারও সহানুভূতি আমার একেবারেই প্রয়োজন নেই! তুমি যদি এভাবে আমার দিকে তাকিয়ে যেতে থাকো, আমি তো তোমাকে নির্যাতন করার প্রলোভন সামলাতেই পারব না। তুমি নিশ্চয়ই চাও না যে সবকিছু নিয়ন্ত্রণের বাইরে চলে যাক, তাই তো? সুতরাং, ভালো দাসের মতো শোনো, মান্য করো, আর অনুগত হয়ে আমার গ্ল্যাডিয়েটর হয়ে যাও..."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5611_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "ওই প্রশ্নটা আমাকে আর কোরো না! আমি অসাবধান ছিলাম, গ্ল্যাডিয়েটরকে পালাতে দিয়েছি, আর আমার পুরো পরিবারকে মরতে হয়েছে! আমরা ভস্মে পরিণত হয়েছি, রোমান সাম্রাজ্যের মতো!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5612_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "বিভিন্ন প্রতিভাধর মহান ব্যক্তিদের তুলনায়, নিমফিয়া কেবল একজন সাধারণ মানুষ যে কোনো কৃতিত্ব অর্জন করেনি, কোনো মূল্যবান কিছু সৃষ্টি করেনি—এর চেয়ে সাধারণ আর কিছু হতে পারে না।\nআমাকে জাগ্রত করেছে... হয়তো কিছু ছোট্ট, নগণ্য ইচ্ছা..."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "আজও আমি স্কুলের নিয়মাবলী ভেঙেছি, ক্লাসে পাঁচ মিনিট দেরি করে এসে... অতএব, আমি আন্তরিকভাবে সর্বোচ্চ কঠোর শাস্তি প্রার্থনা করছি, যা সম্ভব হলে তোমার হাতেই কার্যকর হোক।"
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "যন্ত্রপাতিরও যত্ন দরকার। হাতের কাছে থাকা একগুচ্ছ টুলই তো একজন মেকানিকের আত্মা।"
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5615_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(উপহাসমূলক সহনশীলতা)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "এ রকম ঘটনা আর ঘটলে, তোমার বিরুদ্ধে শাস্তিমূলক পর্যবেক্ষণের আবেদন করব।"
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "আমার দায়িত্ব কেবল যুদ্ধের মধ্যেই সীমাবদ্ধ নয়। আর্কিয়ান যুগেও আমার কাজ ছিল, নিছক বসে থাকার বিলাসিতা ছিল না... শোনো, তুমি কি সত্যিই ভেবেছ আমি শুধু তলোয়ার ঘোরানো জানে এমন কোনো পাষণ্ড মাত্র?!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কাজ প্রসঙ্গে"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "মানুষ যখন আমার কাছে আসে, তারা সবসময় তাদের সবচেয়ে দুঃখের স্মৃতিচারণ মনে করে ফেলে এবং অশ্রু ধরে রাখতে পারে না। আমার মতো কেউ কি এখনও বেড়ে ওঠার আশা করতে পারে?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5619_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "এটা কেমন লাগছে?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "এই জায়গাটা সেই নোংরা, দুর্গন্ধময় নিউ গেট কারাগারের চেয়ে অনেক ভালো! সোফায় হেলান দিয়ে থাকা হোক, বা কোনো কোণে গুঁজে থাকা—সবই বেশ আরামদায়ক, তাই না?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "ব্রাউন...!"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "আমার স্ক্রুটি... কোথায় যে গেল..."
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "এই! এটা তো ঠকবাজি!"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "আমার স্ক্রুগুলো কোথায় হারালো?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "বহে চলো, হে নক্ষত্রের নদী..."
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "অরিটা হঠাৎ করে বন্ধুদের চলে যাওয়া পছন্দ করে না... কিন্তু, তারা যদি প্রত্যাবর্তন করে, আমি তাদের ক্ষমা করে দেব!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "যে নারী একা সাগর পাড়ি দেয়, সে সবসময় দেবকন্যা হয় না। সে সমান সম্ভাবনায় উন্মাদও হতে পারে। আমি মিরিয়ামকে দেবকন্যা ভেবেছিলাম, আর সেটাই ছিল বোকামি।"
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "চ্যাট: মিরিয়াম সম্পর্কে"
  },
  Voice_5629_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」 অর্জনের পর আনলক হবে"
  },
  Voice_5630_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_5630_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "আমি লুকিয়ে মিস ক্যাসিয়ার ম্যাজিক শো দেখেছি। তাঁর প্রদর্শনী দর্শকদের এত আনন্দ দেয়, অথচ আমি সবসময় নিয়ে আসি শোক... তুমি কি মনে করো, অশ্রু আর হাসি সমানভাবে মূল্যবান? হয়তো..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "চ্যাট: ক্যাসিয়া সম্পর্কে"
  },
  Voice_56313_UnlockDesc = {
    Text = "「জাগরণ「 「ক্যাসিয়া「 অর্জনের পর আনলক হবে"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "কবিতা, শিখা আর শোক—সবই একরকম; অগোচরে তারা তোমাকে গ্রাস করে ফেলে... তুমি যখন হুঁশে ফিরে তাকাও, তখন দেখো তুমি ইতিমধ্যেই নিমজ্জন হয়েছ কবিতার জগতে..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "অতীতের কবিতাগুলোকে তোমার হৃদয়ের অন্তর্লীন বাগানটিকে জাগরণ করতে দাও।"
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "কবিতা আর ফুল বোধহয় একই জিনিস, তাই না? দুটোই ক্ষণস্থায়ী, অথচ চিরন্তন। এই সীমাহীন জগতে তারা অতি ক্ষুদ্র এক পরিসরে ধরে রাখে সবচেয়ে ভোলার নয় এমন মুহূর্তগুলোকে... আমার মনে হয়, সকলে কোনো না কোনো সময় কোনো কবিতার সামনে নীরব হয়ে গেছে, যেমন তারা থেমে যায় কোনো ফুলের প্রস্ফুটন দেখার জন্য।"
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার কবিতা সংকলন সম্পর্কে"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "আমি প্রায় ভুলেই গিয়েছিলাম... এই ঋতুতে সিতে শহরে কী ধরনের ফুল ফোটে?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সিতে সম্পর্কে"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "তোমার উপস্থিতি আবারও আমার কলমের কালি জ্বালিয়ে তুলেছে, তাকে পুনঃপ্রবাহের মতো কোমল স্রোতে বইতে দিয়েছে। আমি তোমার কাহিনির জন্য কবিতা রচনা করে যেতে থাকব।"
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক সম্পর্কে - 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "ফুলের বিকশিত সৌন্দর্যের পাশে তাদের ঝরে পড়ার বেদনা সমান তীব্র। যতবারই শোক অনুভব করি না কেন, আমি থেমে তাদের জন্য শোকগাথা গাইতেই বাধ্য হই। যদি কেবল আঘাত পাওয়ার ভয়ে আমি তাদের দিকে তাকানোই বন্ধ করে দিই, তবে এই ফুলগুলোর জন্য তা কতই না মর্মান্তিক হবে..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার পেইন সম্পর্কে"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "এরিকা যখন 「ঘুমায়」 তখন এই শরীরের অভ্যন্তরীণ গঠন গবেষণা করার জন্য, উইঙ্কেল আমাকে রাতে তার অফিসে সুপ্তাবস্থায় যেতে বলেছেন।\nএরিকা সুপ্তাবস্থায় থাকলেও আংশিক চেতনা বজায় রাখেন — এই বিষয়টি কি তাকে জানানো উচিত?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উইঙ্কল প্রসঙ্গে"
  },
  Voice_5631_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "ম্যাডাম সোরেল সত্যিই অপূর্বা। তাঁর শক্তি আর আত্মবিশ্বাস, নিয়তির মুখোমুখি দাঁড়িয়ে তাঁর স্নিগ্ধ হাসি, আর উজ্জ্বল অথচ দৃঢ়চেতা জীবনশক্তি—সব মিলিয়ে তাঁকে দেখে আমার হিংসে হয়।"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সোরেল প্রসঙ্গে"
  },
  Voice_56320_UnlockDesc = {
    Text = "\"জাগরণ\" \"সোরেল\" অর্জনের পর আনলক হবে"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "গতকাল আমি একটি নতুন কবিতা লিখেছি, কিন্তু কাউকে এখনো দেখাইনি। খুব ভালো হয়নি, তবে... গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়, আপনি কি একবার দেখে নিতে রাজি হবেন?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "চ্যাট: রক্ষক সম্পর্কে - 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "মিথাগের ছাত্র কবিতা ক্লাব আমাকে তাদের উপদেষ্টা হতে বলছে... আমি রাজি হতে পারি না। আমি তাদের উদ্যমে জল ঢালতে চাই না, কিন্তু ভয় হয়, আমি কেবলই তাদের হতাশা আর নিরুৎসাহই উপহার দেব।"
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "এই পৃথিবীতে ঘৃণা করার মতো কিছুই নেই। সোনালি দিনগুলো প্রশংসার যোগ্য, বার্ধক্যের অবক্ষয় করুণা পাওয়ার দাবিদার; যৌবনের জাঁকজমক ঈর্ষণীয়, আর ছেঁড়া-ফাটা অবশিষ্টাংশ ডেকে আনে গভীর চিন্তন।"
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "প্রতিবার মিস নিম্ফিয়াকে দেখলে আমার জললিলির সেই ছবিটার কথা মনে পড়ে। তিনি বয়ে বেড়ান জললিলির নীরব তিক্ততা আর সুগন্ধ... ভাবি, তাঁর নিজস্ব জগৎটা আসলে কেমন দেখতে?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নিম্ফিয়া সম্পর্কে"
  },
  Voice_56324_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「নিম্ফিয়া」 অর্জনের পর আনলক হবে"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "আমি সবসময়ই নিজের চারপাশে “ভূত”-এর উপস্থিতি টের পাই, যেন কোনো অজ্ঞেয় ভর বা মোহ, যা ধীরে ধীরে আমার পৃথিবী সম্পর্কে সব আশা শুষে নিচ্ছে। কিন্তু যদি সত্যিই ভূত হয়, তবে দুধ আর পানি যে হাওয়ায় মিলিয়ে যায়, তার ব্যাখ্যা কীভাবে দেবে...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "গল্পগুজব: প্রেতাত্মা সম্পর্কে"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "ডিজলিউশন আমার দেহকে স্পর্শ করেনি; ওই কালো তরলগুলো নিছক কালি মাত্র। কিন্তু সত্যি বলতে, ডিজলিউশন না থাকলেও, শেষমেশ সবকিছুই তো মায়াস্বপ্নে পরিণত হয়, তাই না?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "কীগ্রেভে আমি এক সমাধিফলকে তোমার নাম দেখেছি... জীবনের স্মৃতিচারণ ছিল বেদনাদায়ক, কিন্তু আমি কখনোই সেগুলো ভুলে যেতে চাইনি। রক্ষকের কাছে, হারিয়ে যাওয়া সেই স্মৃতিচারণও নিশ্চয়ই সমান গোপন সম্পদ, তাই তো?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অতীত স্মৃতিচারণ সম্পর্কে"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "যদি সৌন্দর্যের স্তব করার জন্যই কবিতার অস্তিত্ব হয়, তবে তাঁর অস্তিত্ব নিজেই যেন এক কবিতা। তিনি যখন গান শুরু করেন, হঠাৎই আমি বুঝতে পারি প্রবীণরা যে বুলবুলির কণ্ঠের কথা বলতেন, তার অর্থ কী..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "চ্যাট: টিঙ্কট সম্পর্কে"
  },
  Voice_56328_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"টিঙ্কট\" অর্জনের পর আনলক হবে"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "ওই সুন্দর ব্যালেরিনা ভদ্রমহিলা... তাঁর পান্না-সবুজ শিখা একেবারেই অনিবার্য, যদিও তা মানুষকে ছাই করে পুড়িয়ে দেয়..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "গল্পগুজব: লিজ সম্পর্কে"
  },
  Voice_56329_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"লিজ\" অর্জনের পর আনলক হবে"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "তাহলে এখন থেকে সেপিরোটের বদলে আমি এটাই ভক্ষণ করব?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "সুস্বাদু। একেবারে সুস্বাদু।"
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "বিনিময়ে তুমি কী প্রার্থনা করো, প্রিয় অতিথি?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "তাড়াতাড়ি, গুছিয়ে ফেল! রাস্তায় বেশি দেরি কোরো না।"
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "অনিবার্য উৎসর্গ।"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(সহনশীলতার দমিয়ে রাখা গোঙানি)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "বর্তমান ইনপুট সম্পন্ন। বিদ্যুৎ প্রবাহিত করা হচ্ছে।"
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "লন্ডিনিয়ামের সেরা চোরের সঙ্গে লাগতে যেয়ো না!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "শুরু হোক এই উদ্বোধনী শ্রদ্ধাঞ্জলি!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "সহস্রমুখী মরীচিকা অবতীর্ণ হয়েছে!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "এটি ক্রমশ কাছে আসছে…"
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5638_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "নিমজ্জিত হও এবং দহনে পুড়ো! মৃত্যুর নৃত্য করো!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "এটাই সেই নগরী, যেখানে অগণিত হারিয়ে যাওয়া আত্মা ঘুরে বেড়ায়, চিরকালই স্বদেশের পথ খুঁজে পায় না।"
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "এটাই আমার শেষ সামান্য বদলানো শক্তি... তুমি এটা নিয়ে নাও!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "লন্ডিনিয়ামের সেরা চোরের সঙ্গে লাগতে যেয়ো না!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "শত্রু কি? আমাকে আক্রমণের নির্দেশ দিন।\nকালো তরল শত্রু……লিলিও কি শত্রু?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "এরিকা অটোমেটন, ধড় নম্বর EA307881, মোটর নম্বর MF311028। আপনার সেবায় উপস্থিত থাকতে পেরে আনন্দিত।"
  },
  Voice_5640_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5641_AwakerVoiceContent = {
    Text = "লড়াই করো! কাউকে আস্ত রাখবে না!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "শুভেচ্ছা, আমি... উহ্‌... আপনি কি আমার নামটি বলতে পারবেন?"
  },
  Voice_5642_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5643_AwakerVoiceContent = {
    Text = "স্কুলে আসার পর, অবশেষে আমি বুঝলাম যে ডিজলিউশন নামের যে রোগ আমাকে সংক্রমিত করেছিল, সেটা কী। আমি বেঁচে থাকতে থাকতে, আমার বাবা-মা সবসময় আমাকে সাগর থেকে দূরে রাখতেন, আর এখন মনে হচ্ছে এই সংক্রমণটা সত্যিই হয়তো সাগরের এত কাছে থাকার সঙ্গেই জড়িত..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "ঠিক আছে। আমি তোমাকে হতাশ করব না... কথা দিলাম।"
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "আহ, আমার দগ্ধ করা শ্বাস..."
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5646_AwakerVoiceContent = {
    Text = "যাও।"
  },
  Voice_5646_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "আবর্তিত হও।"
  },
  Voice_5647_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5648_AwakerVoiceContent = {Text = "এই!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "অবশেষে সেই দিন সমাগত..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5651_AwakerVoiceContent = {Text = "হা!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "আমি এখনো শেষ করিনি... কী বলো, তুমি উঠে দাঁড়াও, আর আমি আবারও তোমাকে হত্যা করি?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "রক্ষক, আমার তোমার সঙ্গে কথা বলা দরকার। আমরা চূড়ান্ত বিজয় অর্জনের আগে, কিছু লোকের এত অপব্যয়ী হওয়া উচিত নয়। মনে রেখো, আমি এমন লোকদের বিলাসী জীবনের জন্য যুদ্ধ করছি না!"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সোরেল প্রসঙ্গে"
  },
  Voice_5654_UnlockDesc = {
    Text = "\"জাগরণ\" \"সোরেল\" অর্জনের পর আনলক হবে"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "আমাকে যদি জিম্মি করে নিয়ে যাওয়া হয়, তবে আমার জন্য কী নিষ্ঠুর নিয়তি অপেক্ষা করছে?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5657_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_5657_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "হুঁহ... ভীষণ ঘুম পাচ্ছে। আমি বিশ্রাম নেওয়ার আগে, ঠিকঠাক কিছু রিফ্রেশমেন্ট প্রস্তুত করেছ তো?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "মা, তুমি কি ওদের আদর করতে চাও? বলে, ওদের গা নাকি খুব নরম।"
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5659_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "হিহিহি, লালাল্লা~ ঝাড়পোঁছ, ঝাড়পোঁছ, আমি ঝাড়পোঁছ ভালোবাসি, আমি ঝাড়পোঁছকে ভীষণ ভালোবাসি~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কাজ প্রসঙ্গে"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(পেইনে কাতরানো)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "হুঁম... মন্দ না।"
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(পেইনে কাতরানো)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(পেইনে কাতরানো)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "দহনশীল ক্রোধ!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "ডিজলিউশন থেকে পাগল হয়ে যেতে অনেককে দেখেছি। সত্যি বলতে, আমি নিজেই যথেষ্ট পাগল। বাজি ধরে বলতে পারি, ওই জিনিস আমার ওপর কোনো প্রভাব ফেলবে না।"
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "হেহ... হাহাহা!"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "উত্তম সরঞ্জামই সাফল্যের অর্ধেক!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "মনে হচ্ছে এ যেন এক মৃত্তিকা বিদীর্ণ পুনর্জন্ম।"
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "মন্দ নয়।"
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "এখন, আমার ব্লেড শক্তিতে গেয়ে উঠছে!"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "উপস্থিতি সামলানো, গবেষণার অগ্রগতি ধরে রাখা, আর শিক্ষাদানের কাজ সম্পন্ন করা—দেখছি উল্টো সময়-সংকোচন পরীক্ষাটাকে এখনই সর্বোচ্চ অগ্রাধিকার দিতে হবে।"
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5672_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "অভিযানে আনুষ্ঠানিকভাবে রওনা হওয়ার দিকে আর এক পা এগোলাম!"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "আমাকে যেন পানির কাছে যেতে দিও না, ঠিক আছে? আমি চাই না তোমার জন্য আমার এই সুস্বাদু, দহনময় ভালোবাসা... নিভে যাক।"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "অন্তিম মুহূর্ত পর্যন্ত লড়াই করো!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "তোমার সাহস সত্যিই প্রশংসনীয়। এই শুঁড়গুলোর দিকে তাকাও—ওদের বয়ে আনা উন্মাদনাকে কি তুমি ভয় পাও না?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5676_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5677_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_5677_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5678_AwakerVoiceContent = {Text = "আহ..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "দয়া করে থামুন!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "তুমি কি এটাকে ছুঁতে চাও? তোমার উপস্থিতির কারণেই আমার হৃদয় ধুকপুক করে।"
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5680_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "ওরা খুশিতে কিচিরমিচির করছে। ধন্যবাদ, প্রভু।"
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5681_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "বুকের মধ্যে কিছু একটা জেগে উঠছে……উষ্ণ, লিলি, লিলির চোখের জল প্রায়……\nমা, চলো একসাথে উদযাপন করি।"
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5682_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "তোমার পাশে আমি খুশি, মা।"
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5683_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "আর খেতে পারছি না…পেট ভর্তি।\nঅনুষ্ঠান শেষ হলে, লিলি কি আরও শক্তিশালী হবে?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5684_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "আমি সাগরকে ভালোবাসি। এটা কি বিদ্রূপ নয়? আমার যা কিছু ছিল, সবই এখন গভীর সাগরের তলায় ডুবে আছে..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "সাবধানে থাকুন!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "আমি কী ঘৃণা করি...? কিছুই না। তুমি কি ধুলোর কণা বা একটা পাতাকে ঘৃণা করবে?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "আমি দাসীর ভোজসভার নিমন্ত্রণ কয়েকবারই ফিরিয়ে দিয়েছি। তাকে একটু মনখারাপ লাগছিল... কিন্তু নিছক আনন্দের চেয়ে, আপনার নিরাপত্তাই, প্রভু আমার, অসীম বেশি গুরুত্বপূর্ণ!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কারেন প্রসঙ্গে"
  },
  Voice_5688_UnlockDesc = {
    Text = "জাগরণকারী 「ক্যারেন」 অর্জনের পর আনলক হবে"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "একজন প্রভুই হলো নাইটের অস্তিত্বের মূল কারণ, তাই অনুগ্রহ করে, নির্দ্বিধায় আমাকে আপনার আদেশ দিন!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "…এটার জন্য হয়তো একটা টর্ক রেঞ্চ লাগবে… হুঁ, দুঃখিত, তুমি কি একটু আগে আমাকে ডাকছিলে?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "কী স্পর্ধা তোমার!"
  },
  Voice_5692_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(একটি মার্জিত, চাপা যন্ত্রণার আর্তস্বর)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(সহনশীলতার দমিয়ে রাখা গোঙানি)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "যথেষ্ট হয়েছে।"
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "কোমল হও।"
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "উঃ, এখনও মনোনিবেশ করা বেশ কষ্টকর..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "সে রাতে প্রায়ই আমার কাছে থাকে, আমার এই মাথাটা কি খুব বেশি নজরকাড়া?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উইঙ্কল প্রসঙ্গে"
  },
  Voice_5698_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "আমি তো সবসময় ধ্বংসের আগমনের অপেক্ষায় থেকেছি, কখনোই \"মৃত্যু প্রতিরোধ\" ভাবিনি... তুমি কি আমার এই অগভীর আত্মাকে অতল পার হতে সাহায্য করবে? এমন এক জগতে যেখানে আমি অল্পের জন্য বেঁচে গেছি, সেখানেও তুমি আমাকে মুক্তি দাও..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5699_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "আমি যেহেতু তোমার অ্যাপোস্টল রূপে জাগরণ লাভ করেছি, তাই তোমার শান্তি আর আনন্দ ছাড়া আর কিছুই কামনা করি না, এটাই আমার প্রার্থনা... উঃ... আহ্... হ্যাঁ, হ্যাঁ, আমি কামনা করি টিকে থাকা, অধ্যবসায়, প্রজনন—আমাদের বেঁচে থাকতে হবে, বেঁচে থাকতেই হবে..."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5700_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "আমার প্রেমে নিজেকে হারিয়ে ফেলবে না? আমার তোষামোদকারীর আলিঙ্গনের উষ্ণতার জন্যই তো তুমি আমাকে জাগরণ করেছিলে, তাই না?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5701_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "হুঁ? তুমি কি আমার প্রতি সতর্ক—এই অজানা জীব নারীর প্রতি? খুব ভালো... আমি ছিলাম নিনেভের অপসারিত রানি, সেই শিনারবাসিনী যে নখর দিয়ে স্বর্গের দ্বার আঁচড়ে দিয়েছিল, আর সেই বালিকা যার চেতনা চুরি হয়ে গিয়েছিল ইউফ্রেটিসের পবিত্র ডালের তলায়... কোথা থেকে শুরু করব, আমার সতর্ক প্রিয়?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5702_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "তুমি সবসময় আমাকে এড়িয়ে চল কেন? লজ্জা পাচ্ছ? কত মিষ্টি, নিজের কামনার মুখোমুখি হতে এই অনীহা।"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5703_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "এই জায়গাটা একেবারে ভয়াবহ! কী সাহসে ওরা ভাবে আমি বিকেলের চায়ের টেবিল অন্য কারও সঙ্গে ভাগ করব! …তবে, ঘরে বানানো কুকিগুলো মন্দ নয়। রাতের খাবারের পর আমার ঘরে এক প্লেট পাঠিয়ে দেবে।"
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5705_AwakerVoiceContent = {
    Text = "হেয়ো!"
  },
  Voice_5705_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "ডিজলিউশন... হ্যাঁ, আমার স্বদেশের বিদ্যাপীঠগুলোতে এর নথি আছে, কিন্তু, উঁহু, আমি পড়তে ভীষণ ঘৃণা করি। কিছুই মনে নেই!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "তুমি কি চাও আমি আবারও পাল তোলো? আমি প্রস্তুত... যদি তুমি আমার অতীত ব্যর্থতাকে উপেক্ষা করতে পারো।"
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5708_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "অপছন্দ? অনেক। রাত অবধি খাটায় এমন বস, আত্মধার্মিক সন্ন্যাসিনী, গর্জন করা পেট, আর কাঁচের টুকরো গোঁজা কালো রুটি..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "সব আমার দোষ... সবকিছুর দোষ আমারই..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "এবার এর সমাপ্তি ঘটাব!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "মিস হান্নার কল্যাণে আমি কোরাসের মহড়া দেখতে পেরেছিলাম। স্তোত্রগান আর সমুদ্রগীতি একেবারেই ভিন্ন; সমুদ্রযাত্রায় আশীর্বাদ বর্ষণের এত বছরেও, এমন অনন্য সুর আমি কখনও শুনিনি..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "এটা হজম কর!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "এটা হজম কর!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "ওহ, ভয়ংকর!"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5716_AwakerVoiceContent = {Text = "উফ..."},
  Voice_5716_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "হ্যালো, আমার প্রিয় নতুন মাস্টার! আজকের মেনুতে আছে শামুকের পুডিং, ব্যাঙের স্টু, আর সবুজ শিখার মদ। কোনটা নেবেন?"
  },
  Voice_5717_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5718_AwakerVoiceContent = {
    Text = "ওটাই কি জেনেসিস ফর্ম বলে...? না, আমার কল্পনার সঙ্গে একটু ভিন্ন। কিন্তু আমি যদি ওরকম হতে পারতাম, তা হলে দারুণ হতো।"
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "গল্পগুজব: গভীর সাগর রক্তধারা প্রসঙ্গে"
  },
  Voice_5718_UnlockDesc = {
    Text = "জাগরণকারী 「টুলু」, 「মার্ফি」, 「মিরিয়াম」 বা 「গোলিয়াথ」–এর যেকোনো একটিকে অর্জনের পর আনলক হবে।"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "সঠিক মুহূর্তের অপেক্ষা করো।"
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "হে মেষশাবকেরা, পিতৃদেবের ইচ্ছাই তোমাদের মুক্তি দেবে।"
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "হে মেষশাবকেরা, পিতৃদেবের ইচ্ছাই তোমাদের মুক্তি দেবে।"
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5723_AwakerVoiceContent = {Text = "মর!"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5724_AwakerVoiceContent = {Text = "হা!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5725_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_5725_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5726_AwakerVoiceContent = {Text = "হা!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "সে এক করুণ নারী, নিয়তির হাতে যন্ত্রণার জন্য অভিশপ্ত। এক অর্থে আমি তাকে দয়া করি, কারণ তাঁর প্রকৃত আবির্ভাবের ক্ষণে, আমি তাকে মৃত্যুর দয়া দান করব।"
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "চ্যাট: মিরিয়াম সম্পর্কে"
  },
  Voice_5727_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」 অর্জনের পর আনলক হবে"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "রক্তে রঞ্জিত হও!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "প্রতিশোধ...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "ব্যথা করছে..."
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(দমিত যন্ত্রণার আর্টনাদ)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(দমিত যন্ত্রণার আর্টনাদ)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5733_AwakerVoiceContent = {Text = "আহ..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "তুমি কি আমার সঙ্গে একসঙ্গে ডুবে যেতে চাও?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5735_AwakerVoiceContent = {
    Text = "দূরে সরে যাও!"
  },
  Voice_5735_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "যে জিনিসগুলো আমি ঘৃণা করি... অগোছালো ডেস্ক, এলোমেলো পোশাকের আলমারি, ধুলোমাখা জানালার কার্নিশ—হ্যাঁ, আমি তোমার ঘরটার কথাই বলছি। কাল সকাল 7টার মধ্যে আমি এটাকে তোমার থাকার আগের অবস্থায় ফেরত দেখতে চাই।"
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(কৌতূহলী সুরে গুনগুন করছে)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "মজার!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(ঘৃণাভরে ঠোঁট উল্টে হাসে)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "প্রয়োজনে আমিও দোলনা ছেড়ে বেরিয়ে আসতে পারি..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "খুব দরকার হয়ে গেছে, তাই না?"
  },
  Voice_5741_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5742_AwakerVoiceContent = {
    Text = "এই নাও!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "দুগুণ করো! আবারও দুগুণ করো!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "এটা আমাকে মনে করিয়ে দেয়, আমি যখন আট বছর বয়সে প্রথম যে লাল নাচের জুতোর জোড়া পেয়েছিলাম, তার কথা। আমি ওগুলো ভীষণ ভালোবাসি। ধন্যবাদ, রক্ষক।"
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5744_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "বন্ধু... কী? প্রভু? মা?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "তাই আমার সুরক্ষাও, কখনো কখনো ব্যর্থ হতে পারে..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5749_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "পছন্দ? পেলোপনেশাসের যুদ্ধক্ষেত্রে কেউ একবার আমাকে এই জিজ্ঞাসা করেছিল... এখন অনেক দেরি হয়ে গেছে। ব্যক্তিগত পছন্দ-অপছন্দ আমি বহু আগেই ত্যাগ করেছি।"
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "শ্‌... দয়া করে 「ওদের」 যেন টের না হয় যে আমি আরও শক্তিশালী হয়ে উঠছি।"
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "「তারা」 সবাই বলেছিল... ধন্যবাদ।"
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "উহ... এটা কী?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "এটি কেবল আমাকে অতলের আরও কাছে নিয়ে যাবে।"
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5754_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "তুমি আমার প্রিয় দাস। তুমি একে বন্ধু, সঙ্গী, সহযোদ্ধা—যা খুশি বলতে পারো।"
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "আমি আমার উত্তর পেয়েছি। যে উত্তর আমি চেয়েছিলাম তা নয়... তবু, এক উত্তর বটে।"
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5756_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "ওটা কি ভয় তোমার মুখে? নাকি শোক? সত্যিই মোহিত করে।"
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5757_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "মৃত্যু আর বিলয়ের গন্ধ... কতটাই না স্পষ্ট, কতটাই না তীব্র।"
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5758_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "এখানে আমার কেমন লাগে? ভ-ভালোই তো। যতক্ষণ আমি কিছু যান্ত্রিক বিজ্ঞান আর আত্মা-সংক্রান্ত গবেষণার জ্ঞান মিস ডলের সঙ্গে ভাগ করে নিই, তিনি আমাকে আলো জ্বালিয়ে রাখতে দেন।"
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "আশা করি জেনকিন আর ব্রাউন একাডেমিতে তাদের সময়টা উপভোগ করছে। বাবার কাফলিংকসগুলো তেমন কিছুই না। জেনকিন যদি ওগুলো চাই, ওরই থাকুক। আমি নিশ্চিত, ওনার কাছে বাড়তি একটা পুরো বাক্স ভরা আছে।"
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_5760_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "ত্যাগ করতে পারব না এ স্থান..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "নিকৃষ্ট জাতিগুলোর সীমা অতিক্রম করে আমি এমন প্রভাবকে ভয় করি না। পোষক দেহ চূর্ণবিচূর্ণ হলেও, সম্ভ্রান্ত রক্তধারা কখনো বিলুপ্ত হবে না।"
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "আমি ভুয়া হাসি-ওয়ালা মানুষদের ঘৃণা করি! তাদের কাছ থেকে কোনো অনুভূতিই চুরি করা যায় না!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "হুঁ? সকলে চুপচাপ কেন? কারেন এই নীরবতা একদম পছন্দ করে না। আমি তোমাদের একটা গল্প শোনাই। এক ছিল পাহাড়..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "লিলি ভবিষ্যৎ ছিনিয়ে আনবে... তেকেলি—লি!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "লিলি ভবিষ্যৎ ছিনিয়ে আনবে... তেকেলি—লি!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "তুমি যদি তাঁর অস্তিত্ব অনুভব করার জন্যই এটি করে থাকো, তবে আপাতত তোমার ঔদ্ধত্যকে ক্ষমা করছি।"
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "ইচ্ছা নেই আমার এ কাজে..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "পিছিয়ে থাকো।"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "ধীরে ধীরে, তোমার আদেশের সঙ্গে তাল মিলিয়ে নিজের ছন্দ খুঁজে পাচ্ছি!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "আমি একজন প্রকৃত নাইট হওয়ার আরও কাছে চলে আসছি!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "এই সম্মানের জন্য কৃতজ্ঞ, প্রভু আমার। এটি আমার কাছে অপরিসীম মূল্যবান।"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "স্নানাগার সময় কাটানোর দারুণ জায়গা! খাবার সুস্বাদু, আর তারা পেশি শিথিল করার সেবাও দেয়! প্রলোভন লাগছে? তাহলে এই স্কুলেই তাড়াতাড়ি একটা বানিয়ে ফেলো!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "না... আ-আমাকে ছেড়ে যেও না!"
  },
  Voice_5774_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5775_AwakerVoiceContent = {
    Text = "প্রস্তুত।"
  },
  Voice_5775_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
