  Voice_57820_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "এই হত্যাযজ্ঞের মহাভোজ উপভোগ করো! পরিপূর্ণভাবে!"
