  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "মিথ্যা মিশন, পূর্বনির্ধারিত ভবিষ্যৎ... আমি শেষ মুহূর্ত পর্যন্ত এর বিরুদ্ধেই লড়ব!"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "এই হত্যাযজ্ঞের মহাভোজ উপভোগ করো! পরিপূর্ণভাবে!"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "আমার আচারে যোগ দাও এবং আমার বীজে পরিণত হও!"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "বিশ্বাসঘাতক, আমার হতাশা ও রোষের স্বাদ গ্রহণ করো!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "বিশ্বাসঘাতক, আমার হতাশা ও রোষের স্বাদ গ্রহণ করো!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "আমার আচারে যোগ দাও এবং আমার বীজে পরিণত হও!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "আমি এতদিন লজ্জায় অরিটাকে বলতে পারিনি যে, আমি তার ভাবনার মতো এত ছোট নই। আমি তার \"ছোট বোন\" নই। তুমি কি হয়তো ওকে এটা একটু বলে সাহায্য করতে পারবে?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অরিটা প্রসঙ্গে"
  },
  Voice_5782_UnlockDesc = {
    Text = "「জাগরণ「 「অরিটা「 অর্জনের পর আনলক হবে"
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "দীর্ঘদিনের হারানো নগরী লেমুরিয়া, অবশেষে আজ উন্মোচিত।"
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "দীর্ঘদিনের হারানো নগরী লেমুরিয়া, অবশেষে আজ উন্মোচিত।"
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "কাল ঘনিয়ে এসেছে। আমার অঙ্গীকার এখন পূর্ণ হবে।"
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "কাল ঘনিয়ে এসেছে। আমার অঙ্গীকার এখন পূর্ণ হবে।"
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "এই সবই তাঁর দিব্য পরিকল্পনার অংশ।"
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "এই সবই তাঁর দিব্য পরিকল্পনার অংশ।"
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "নক্ষত্রপুঞ্জ থেকে আগত সেই শ্যাম্বলারের আমন্ত্রণপত্র প্রসারিত হলো... তোমার উদ্দেশে।"
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "আমি এখনও... মহাকাশের সেই মূল বর্ণ!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "আমি এখনও... মহাকাশের সেই মূল বর্ণ!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "নক্ষত্রপুঞ্জ থেকে আগত সেই শ্যাম্বলারের আমন্ত্রণপত্র প্রসারিত হলো... তোমার উদ্দেশে।"
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5783_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও!"
  },
  Voice_5783_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_57840_AwakerVoiceContent = {
    Text = "সকলে, চল একসঙ্গে আক্রমণ করি!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "ভূগর্ভস্থ গোলকধাঁধার দেবতা তোমাদের সবার ওপর বিচার ঘোষণা করছে!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "ভূগর্ভস্থ গোলকধাঁধার দেবতা তোমাদের সবার ওপর বিচার ঘোষণা করছে!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "অনুপ্রেরণার নীল আকাশে উড়ে চলা পাখি, অনুগ্রহ করে আমার প্রার্থনা শোনো।"
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "অনুপ্রেরণার নীল আকাশে উড়ে চলা পাখি, অনুগ্রহ করে আমার প্রার্থনা শোনো।"
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "নড়বেন না! নড়বেন না! না!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "রক্তের শৃঙ্খলের নিচে কাঁপো... রক্তের শৃঙ্খলের নিচেই ধ্বংস হও!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "রক্তের শৃঙ্খলের নিচে কাঁপো... রক্তের শৃঙ্খলের নিচেই ধ্বংস হও!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "সকলে, চল একসঙ্গে আক্রমণ করি!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "নড়বেন না! নড়বেন না! না!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5784_AwakerVoiceContent = {
    Text = "হেহে..."
  },
  Voice_5784_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_57850_AwakerVoiceContent = {
    Text = "দেখো! এটাই সেই শক্তি, যার ওপর ফিলিস্তিনরা নির্ভর করে!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "দেখো! এটাই সেই শক্তি, যার ওপর ফিলিস্তিনরা নির্ভর করে!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "অত্যন্ত দুর্বল।"
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5786_AwakerVoiceContent = {Text = "হা!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "উম……মালিকের মেজাজ খুব ভালো মনে হচ্ছে না? গালেন মজার মুখ বানাবে, হি——হা!\nকেমন, এখন একটু খুশি হয়েছো?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "মানব বুদ্ধি দিয়ে উন্মোচন করো বিশ্বের রহস্য!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "আমি করিডরে কিছু অস্বস্তিকর লোকের মুখোমুখি হয়েছি। পরিস্থিতির কারণে তোমাকে হয়তো তাদের সঙ্গে সহযোগিতা করতে হবে, কিন্তু সতর্ক থেকো! মানুষের হৃদয় যুদ্ধের চেয়েও নিষ্ঠুর, আর সবচেয়ে ভয়াবহ বিশ্বাসঘাতকতা প্রায়ই আসে ভেতর থেকেই।"
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "গল্পগুজব: @2 সম্পর্কে"
  },
  Voice_5789_UnlockDesc = {
    Text = "জাগরণকারী 「হেলট」 বা 「লিলি」–কে অর্জনের পর আনলক হবে।"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "তোমার হোমওয়ার্ক শেষ হয়ে গেছে তো, আমার সাথে একটু লন্ডিনিয়াম শহরে যেতে পারবে……এ? গণিতের হোমওয়ার্ক এখনো শেষ হয়নি?!\nআ、আ……দুঃখিত, আমি ভাবিনি কেউ ক্যালকুলাস বুঝবে না……আমি কি তোমাকে সাহায্য করব?"
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "গল্পগুজব: পড়াশোনা প্রসঙ্গে"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "আমি আপনাকে শপথ করে বলছি, ওই দোকানদার অবশ্যই ফঁতেনব্লোর কোনো এক স্যালনে এসেছিল... তাই বুঝি, তার চেহারা বদলায়নি। ভাবছি, তার কাছ থেকে আমরা কতগুলো রহস্যের লেনদেন করতে পারব?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "চ্যাট: ড্যাফোডিল সম্পর্কে"
  },
  Voice_5791_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ড্যাফোডিল\" অর্জনের পর আনলক হবে"
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "এটি ভাঙো না।"
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "অরিটা সকলে‌র সঙ্গে খেলা ভালোবাসে! তুমি কি যোগ দেবে? এইটা জেলি, ওটা হেলা, আর ওদিকে যে আছে সেও জেলি... হুঁ?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "এবার আমি এই কলঙ্ক ধুয়ে ফেলব!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "ড্যাফোডিলের দোকান এখন খোলা। যে বালকেরা প্রস্তুতি নাও, তারা দয়া করে হেলাফেলাভাবে ভেতরে ঘুরতে এসো না।"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5796_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "দয়া করে, আমার গলায় হাত দেবেন না... আপনি তা দেখতে পাচ্ছেন না বলেই যে তা নেই, এমন তো নয়।"
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "আমি দৃঢ় বিশ্বাসকে সম্মান করি—তা জন্তুর হোক, জাগরণকারীর হোক, কিংবা মানুষের। আর যদি তারা যুদ্ধ করতে পারে, তবে তো আরও ভালো।"
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5799_AwakerVoiceContent = {
    Text = "যাও।"
  },
  Voice_5799_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "চিন্তা করো না!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "রামোনা... মানে, আমি বিদায় পছন্দ করি না। সেগুলো অতিরিক্ত বেদনাদায়ক।"
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "আমি পুরোহিতদের সঙ্গে খুব একটা স্বচ্ছন্দ নই। তারা নিস্তেজ আর কাঠখোট্টা, আর তাদের প্রিয় \"ঈশ্বর\"-এর হাতে নিজেদের কোমরবন্ধ বেচে দিয়েছে। কী দুঃখের কথা, মি. সালভাদোরের গায়ে কিন্তু কত মিষ্টি গন্ধ..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "চ্যাট: সালভাদোর সম্পর্কে"
  },
  Voice_5802_UnlockDesc = {
    Text = "জাগরণকারী \"সালভাদোর\" অর্জনের পর আনলক হবে"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "যুদ্ধের রোমাঞ্চ সবকিছুকে হার মানায়—জয়লাভও তার ধারেকাছেও আসে না।"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "নরম বিছানা কে না পছন্দ করে, আর ঝোড়ো হাওয়া ঢোকে না এমন ঝড়ের নিষ্কাশন... মানে, কক্ষ।"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "আমাকে যেন মনে করাতে যেও না... এলওয়ার্থে বন্দি থাকা সেই দিনগুলো..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "সব পুড়িয়ে দাও!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "সব পুড়িয়ে দাও!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "রক্তের গন্ধ অনুসরণ করেই আমি এখানে এসেছি। জানতে চাই... আপনার কাছে কি আমার জন্য টাটকা রক্ত আছে?"
  },
  Voice_5808_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5809_AwakerVoiceContent = {
    Text = "হুঁম... অ্যাগ্রিপার অনেক বন্ধু আছে, কিন্তু সবাই যেন তাকে ভয় পায়। তবে কি সে তাদের খাবার চুরি করে?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাগ্রিপা প্রসঙ্গে"
  },
  Voice_5809_UnlockDesc = {
    Text = "\"জাগরণ\" \"অ্যাগ্রিপা\" অর্জনের পর আনলক হবে"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "আমার জীবন নৃত্যকে ঘিরেই আবর্তিত। অন্য জ্ঞান শেখা আমার পক্ষে বেড়ে ওঠার জন্য কঠিন। কিন্তু এখানে সকলে খুব সদয়; তারা অহংকার বা টাকার জন্য আমাকে বিক্রি করে দেবে না—আমি তা অনুভব করতে পারি।"
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "কাপুরুষ! তোমার ভেতরেও আমার মতোই পাশবিক শক্তি আছে, তবু তুমি নিজেকে বেঁধে রাখো। ইচ্ছায় গলায় কলার পরার সঙ্গে এর পার্থক্যটাই বা কোথায়?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "চ্যাট: লিলি সম্পর্কে"
  },
  Voice_5811_UnlockDesc = {
    Text = "\"জাগরণ\" \"Lily\" অর্জনের পর আনলক হবে"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "যথেষ্ট নয়… আমি এখনও যথেষ্ট শক্তিশালী নই।"
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "ফিরে যাও।"
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5814_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "টপ হ্যাট, বোলার হ্যাট, ডিয়ারস্টকার হ্যাট, বেরে... মানতেই হবে, ওই সব উচ্চমর্যাদাসম্পন্ন “ভদ্রলোকেরা” টাক মাথা লুকোতে যা কিছু করতে রাজি থাকে, তা ভীষণ হাস্যকর।"
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "গল্পগুজব: শিষ্টাচার প্রসঙ্গে"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "আমি তাকে গভীরভাবে শ্রদ্ধা করি—সেই সামুদ্রিক দেবকন্যা, শাপলার মতোই নির্মল আর সুশোভিত... তুমি বলছ, এমনকি সেও নিজের নিয়তি নিয়ন্ত্রণ করতে পারেনি, আর শেষ পর্যন্ত সাগরের তলায় ডুবে গেছে? সত্যিই কল্পনা করা কঠিন..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সেলেস্ট প্রসঙ্গে"
  },
  Voice_5816_UnlockDesc = {
    Text = "「জাগরণ「 「সেলেস্ট「 অর্জনের পর আনলক হবে"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "এক দৈত্যের শক্তির সঙ্গে তুলনা চলে না!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "এক দৈত্যের শক্তির সঙ্গে তুলনা চলে না!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "ধিক্কার! ধিক্কার! এই শক্তি শুধু আমাকে এই দেহকাঠামোর ভেতরেই বন্দি করে রাখে!"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5819_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "আমি এমন এক জায়গায় থাকতে চাই, যেখানে সবসময় আলো থাকে... হ্যাঁ, মেরু অঞ্চল। এই গ্রহে, কেবল মেরু অঞ্চলেই।"
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5820_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "আমি... আমি ভারী দায়িত্ব বইতে পারি না। আমি কেবল আলোকে তাড়া করতে পারি। তাই, অনুগ্রহ করে, জ্বলা বন্ধ কোরো না..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5821_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "যদি আমি আবার মাত্রা বদলাতে পারতাম, আমি একটা তারা হতে চাইতাম..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5822_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "আমি যতভাবেই গণনা করি না কেন, চেতনা স্থানান্তরের সূত্রটা এখনো অমীমাংসিত থেকে যায়..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5823_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "স্বাগত জানাও! এসো, একসাথে উন্মাদনায় মেতে উঠি!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "এই নিন আপনার খাবার!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "হিহি... হাই! আমি অরিটা! এক, দুই, তিন... ওহো! স্বাগত, স্বাগত! নতুন বন্ধুরা আমাদের সঙ্গে যোগ দিয়েছে! হুঁ? এইবার আমি-ই নাকি তোমার নতুন বন্ধু? আচ্ছা, এটাও তো চলবে!"
  },
  Voice_5826_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5827_AwakerVoiceContent = {
    Text = "এটুকু খেলনাকে তুমি হ্যান্ডগান বলো? ছায়ায় লুকিয়ে থেকে অতর্কিত আক্রমণ চালানো... হুঁঃ। কেবল কাপুরুষদের অস্ত্র।"
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "অর্থহীন। এই সবকিছু। কেন বৃথা চেষ্টা?"
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "তুমি আসলে কিছুই জানো না।"
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "এখনও কি সহায়তার জন্য আমার ওপরই ভরসা করছ, \"ত্রাণকর্তা\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "মাফ কোরো, তুমি কি আমার স্ক্রুটা দেখেছ? অদ্ভুত, কিন্তু যখনই ওই ইঁদুর-কানওয়ালা বাচ্চাটা আশেপাশে থাকে, আমি যেন আরও বেশি করে ভুলে যাই জিনিসপত্র কোথায় রেখেছি…"
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_5831_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "তাঁর সঙ্গে আমার পুনর্মিলনের জন্য তুমি যা যা দিয়েছ, তা আমি কখনো ভুলব না..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "শুনো সেই খোদিত ক্যান্টাবিল!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "তুমি কি আমার প্রার্থনা গ্রাহ্য করেছ?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "আমার আকাঙ্ক্ষা, তোমার নির্দেশ হতাশ করবে না।"
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "আমার দেহ, নাকি আমার চেতনা উন্নত হয়েছে? বিশ্লেষণের জন্য বেশ আকর্ষণীয় একটি বিষয়।"
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5836_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও।"
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "সরে দাঁড়াও।"
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "আমার শিরায় টিকে থাকার ইচ্ছা ফুঁসে ওঠে, আর্তনাদ করে আমাকে তাড়িয়ে নিয়ে যায় এই গ্রহের প্রতিটি ইঞ্চিতে আমার রক্ত ঢেলে দিতে... আহ, অনেক বেশি প্রলাপ বকেছি; ক্ষমা করবে। আমি থাইস। তুমি কি আমাকে আহ্বান করেছ? তুমি কি আমার সঙ্গে একীভূত হতে প্রস্তুত?"
  },
  Voice_5839_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5840_AwakerVoiceContent = {
    Text = "যদি আইগিস সকলের জন্য এই কালো তরলটা বহন করতে পারত... শেষ পর্যন্ত, আইগিস তো কোনোদিন ছিলই না, যা হয়তো এই পৃথিবীর জন্য ভালোই, তাই না?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "আমার শখের মধ্যে রিম্যান অনুমান সমাধানের চেষ্টা আছে—তবে ওটা আমাদের মি. পিককের বুলি, আমার নয়। ব্যক্তিগতভাবে, আমি পরমাণু ভর মানদণ্ডকে অনেক বেশি আকর্ষণীয় মনে করি।"
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "নির্বাসিত হয়ে সাগরে ভেসে বেড়ানোর স্বাদ... একবারই যথেষ্ট ছিল।"
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "ভালো করে তাকিয়ে দেখো!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "ভালো করে তাকিয়ে দেখো!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "যতক্ষণ তুমি এই ন্যায়বিচারকে অটুট রাখতে পারো, ততক্ষণ আমি সর্বদা ব্লেডের দায়িত্ব কাঁধে তুলে নেব।"
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "তুমি কি এখানে এক বিশেষ 「চিত্রকর」-এর কিংবদন্তি শুনেছ? ওই অভিব্যক্তিবাদী গ্রাফিতিগুলো থেকে আমি এক অদ্ভুত পরিচিত স্পর্শ অনুভব করি..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "ব্যথা লাগছে! তবু কত, কত ভালো লাগছে!"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "আমার ক্রোধ অনুভব করো!"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "এই বিজয় কাব্যে খোদাই করা থাক।"
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "আরও শক্তিশালী হয়ে ওঠো~"
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5852_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5853_AwakerVoiceContent = {Text = "এই!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "হয়তো আমি বড় হলে, নিজেকে নিয়ন্ত্রণ করতে পারব, আর অন্যদের জীবন আর নিষ্কাশন করব না... আমার টিকে থাকার জন্য সামান্যটুকুই তো যথেষ্ট।"
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5854_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "মনে হচ্ছে আমি আরও ভারী হয়ে গেছি। দোলনা কি এখনও আমার ওজন বইতে পারবে?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5855_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "আমি এত শক্তি গিলে ফেলেছি যে, তা এখন উদ্বেল হয়ে উঠছে। পিঠটাও চুলকাচ্ছে। আমি কি... বড় হচ্ছি?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_5856_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "যদিও আমি এখনও শিশুর মতোই দেখাই... এখন তোমাকে রক্ষা করার শক্তি আমার আছে।"
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5857_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "পরিপক্ব হইতে সাধ্যমতো প্রয়াস পাইব।"
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_5858_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "হঠকারী নীচ প্রাণী, কেন তুমি এত জোর দিয়ে আমার জাগরণ ঘটাতে চাও?"
  },
  Voice_5859_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5860_AwakerVoiceContent = {
    Text = "আমি দেবমাতা হয়ে উঠব!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "কতবার যে আমাকে আহ্বান করা হয়েছে... মানব, তোমার কাছে যথেষ্ট 「খাবার」 মজুত থাকাই ভালো, নইলে আমি কিছুই নিশ্চয়তা দিতে পারব না।"
  },
  Voice_5861_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5862_AwakerVoiceContent = {
    Text = "বহু দ্বারের ওপারে!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5863_AwakerVoiceContent = {
    Text = "মূর্খ।"
  },
  Voice_5863_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5864_AwakerVoiceContent = {
    Text = "হাহা!"
  },
  Voice_5864_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "হুঁ, মোটেও খারাপ না। আমাদের পরের দ্বন্দ্ব হবে কিংবদন্তি।"
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "ধৃষ্টতা!"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "কখনও কখনও শিল্পের সৌন্দর্য লুকিয়ে থাকে তার বিলয়ে। কিন্তু তোমার ব্যর্থতা... স্পষ্টতই সে শ্রেণিতে পড়ে না।"
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "তুমি আমার সবচেয়ে গুরুত্বপূর্ণ শ্রোতা। যখনই তোমার প্রয়োজন হবে, আমি গান গাওয়ার জন্য প্রস্তুত—আর তোমাকে আমার সবকিছু উজাড় করে দেব।"
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "প্রিয় জিনিস? সাগরশৈবাল, মাছের ঝাঁক, স্তম্ভশ্রেণি, গোলকধাঁধা... অবশ্যই আমি এগুলো দেখেছি! সবই আছে কাকা অর্নের বইতে!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "এটা কি কোনো তদন্ত অভিযানের প্রস্তুতি? বুঝেছি।"
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5870_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "আমার নাম সেলেস্ট। তুমি যতদিন আমাকে প্রয়োজন মনে করবে, আমি ততদিন এখানেই থাকব।"
  },
  Voice_5871_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5872_AwakerVoiceContent = {
    Text = "শিখে নাও তোমার পাঠ!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "কিছু সম্মান দেখাও, জুনিয়র। সেনাবাহিনীতে জ্যেষ্ঠতার কর্তৃত্বই চূড়ান্ত, আর আদেশ অমান্য করার কোনো ব্যতিক্রম নেই। এমন অনুচিত আচরণের শাস্তি হবেই।"
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "আমি যে 「ছোটখাটো তুচ্ছ জিনিস」 বানিয়েছি, সেগুলোর মেরামতির প্রস্তাব দিতে পারি, কিন্তু প্রশ্ন হলো... আমার বিক্রয়োত্তর সেবা নেওয়ার সাহস তোমার আছে তো?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার আবিষ্কার সম্পর্কে"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "আপনি এখানে যেমন প্রভু, তেমনি আমার স্যালনেরও এক অতিথি। আপনার আগমনের জন্য আমি সর্বোচ্চ আতিথ্যের প্রস্তুতি নেব—আপনি কি রক্তিম পেটিকোট পছন্দ করবেন, নাকি সাদা গোলাপের রঙের নাইটগাউন?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "দুঃখিত, এখানে সূর্যের আলোটা একটু বেশি ঝলমলে... আমার মতো ভূগর্ভের ইঁদুরের এখনও মানিয়ে নিতে সময় লাগবে।"
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "সবকিছু ক্ষয় করে, সবকিছু মুছে দিতে সক্ষম... বেশ অস্ত্রই ছিল সেটা। যদি তখন জানতাম... হ্‌হ্‌।"
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "গুঞ্জন আছে, শিখার ভেতর খিঁচুনিতে কাঁপতে থাকা দেহগুলোকে নাকি নাচতে দেখা যায়..."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অগ্নিশিখা সম্পর্কে"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "রাতে বাইরে যেয়ো না! 2000-লুমেনের আলো থাকলেও পুরোপুরি নিরাপদ নও... একবার অন্ধকারে পা রাখলেই, তোমার দৃষ্টির বাইরে লুকিয়ে থাকা অশুভ শক্তি তোমাকে তাড়া করবে, গ্রাস করবে, তাড়া করবে, গ্রাস করবে... যতক্ষণ না কিছুই অবশিষ্ট থাকে!"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রাত সম্পর্কে"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "আর্তনাদ করো।"
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "তোমার পারিশ্রমিক আমি গ্রহণ করেছি।"
  },
  Voice_5882_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "জীবনের জন্য সেই আকুলতাই রাজহাঁসকে তাড়িয়ে নিয়ে যায় দূর আকাশে প্রত্যাবর্তনের জন্য তার লড়াইয়ে।"
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5883_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "এবার ম্যাজিকের পালা!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5885_AwakerVoiceContent = {
    Text = "বাঁচাও!"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5888_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "আহ, ব্রাউন ছুটে গেল! আ-আমি একটু সরে যাই ভালো……\nতার সাথে বন্ধু হতে চেয়েছিলাম, কিন্তু শেষ পর্যন্ত তার দুঃস্বপ্নই হয়ে গেলাম……সে নিশ্চয়ই আমাকে দেখতে চায় না……"
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_5889_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "একটি চ্যাপেল? ধন্যবাদ, কিন্তু আমি এতটা সেকেলে নই। যতক্ষণ আমি হৃদয়ে দয়ার দেবতার বাণী ধারণ করি এবং তাঁর ইচ্ছা অনুসরণ করি, আমার আত্মা কখনোই তাঁর মহিমা থেকে বিচ্যুত হবে না।"
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "চ্যাট: একটি প্রার্থনালয় সম্পর্কে"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "আমার নাম ওজিয়ার। আমাদের চুক্তি অনুসারে, আমি তোমার প্রতি আমার নাইটসুলভ আনুগত্য অর্পণ করছি—তোমার নিরাপত্তা রক্ষা করতে এবং তোমার শত্রুদের বিনাশ করতে। এই গম্ভীর শপথ আমি গ্রহণ করছি, এবং আমি কখনো ভুলো না।"
  },
  Voice_5891_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5892_AwakerVoiceContent = {
    Text = "ওই কৃশকায়, দ্বৈত তারারন্ধ্রওয়ালা নারীটির গায়ে স্পার্টান পোকামাকড়ের ঠিক একই গন্ধ।"
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাগ্রিপা প্রসঙ্গে"
  },
  Voice_5892_UnlockDesc = {
    Text = "\"জাগরণ\" \"অ্যাগ্রিপা\" অর্জনের পর আনলক হবে"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "পছন্দ? ভালো ভাগ্য, অবশ্যই। কোথাও বেরোনোর আগে সবসময়ই আমি একটা শুভ লক্ষণ খুঁজে দেখি।"
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "প-প্লিজ, মিস হান্নাকে বলবেন না যে আমি এখানে লুকিয়ে আছি। আমি এখনো প্রস্তুত নই..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "গল্পগুজব: হানা সম্পর্কে"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "এটা কেমন লাগে?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "তুমি আমার অতি সম্মানিত অতিথি। মনে রেখো, কেবল তোমাকেই বাকিতে খরচ করার অনুমতি আছে। afinal, এত নিখুঁত খুলি আমি শেষ কবে দেখেছি, তার পর বহু বছর কেটে গেছে..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5897_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5899_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "পছন্দ-অপছন্দ? রাজার ভোগে লিপ্ত হওয়া শোভা পায় না… তবু যদি ক্লান্তিকর আচারগুলো এড়ানো যেত, তবে নরম এক দিবানই যথেষ্ট হতো।"
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "তোমার এই ঔদ্ধত্যকে… এই সত্তা চিরনিদ্রার প্রার্থনা হিসেবেই গণ্য করবে।"
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "ঘৃণা? আমি ঘৃণা করি সেই নিয়তি-যাকে এড়ানো যায় না, আর সেই ট্র্যাজেডি-যা অনিবার্য।"
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5903_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_5903_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(একটি চাপা, যন্ত্রণাদায়ক গোঙানি)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "আর কাছে আসবেন না!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "ওহ, আমার রহস্য জানতে চাও? এই নাম, এই দেহ, এই মুখ, এই ভয়েস—সবই এসেছে সান পেদ্রোর এক নারীর কাছ থেকে, যার একটি খুলি একসময় আমার সংগ্রহে ছিল। সে আমার সঙ্গে এক চুক্তি করেছিল... তার মৃত্যুর পর আমি তার রূপ নিয়েছি। আর সে এখন কোথায় আছে... সেটাই তো আমার সবচেয়ে অপূর্ব গোপন সম্পদ।"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5906_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "তুমি সত্যিই মনোরম এক অতিথি; তোমার অনন্য খুলিতে আমিও মুগ্ধ হয়ে গেছি... যদি কখনো এর সঙ্গে বিচ্ছেদের কথা ভাবো, তবে অবশ্যই আমার ছোট্ট দোকানে আসবে। হাহা... মজা করলাম।"
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5907_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "আমার প্রকৃত পরিচয় জানতে ইচ্ছে করছে? এখনো সে সময় আসেনি। শুধু এটুকু বিশ্বাস করো: পথ হারানো প্রতিটি বালক আমার দোকানে এসে পথ খুঁজে পায়। হয়তো তার মধ্যে তুমিও পড়ো?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5908_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "কাহারো ক্ষতি হইবে না।"
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "এখনও শেষ হয়নি!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "আপনাকে এত কঠোর পরিশ্রম করতে দেখে, এত তাড়াতাড়ি পারিশ্রমিক নিতে আমার একটু লজ্জাই লাগছে। তাই, আপনার মাথাটা আপাতত যেখানে আছে সেখানেই থাকুক।\nতবে ভুলবেন না, এটা কিন্তু ইতিমধ্যেই আমার ব্যক্তিগত সম্পত্তি হিসেবে বুক করা হয়ে গেছে, ঠিক আছে?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5911_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "আমি সব সময় এমন ছিলাম না; সে-ই আমাকে নতুন জীবন দিয়েছে। সে অর্থে, তুমিও আমাকে দ্বিতীয় জীবন দিয়েছ, তাই তোমার মাথাটাকেও আমি গোপন সম্পদ হিসেবে রাখব।"
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5912_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "আমাকে এই অন্ধকার থেকে পালিয়ে যেতে হবে!"
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "তাহলে অভিযান এতটাই মরণঘাতী..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "ও বোকা বালিকাটা আমাকে দেখলেই দৌড় দেয় কেন? পরের বার, ওর সুতোয় পা দিয়ে দেখি তো, কোথায় পালায়।"
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আইগিস প্রসঙ্গে"
  },
  Voice_5915_UnlockDesc = {
    Text = "\"জাগরণ\" \"আইগিস\" অর্জনের পর আনলক হবে"
  },
  Voice_5916_AwakerVoiceContent = {Text = "উফ!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "হেহ... আহাহাহা!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5918_AwakerVoiceContent = {
    Text = "হাহাহা!"
  },
  Voice_5918_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "ও বাচ্চাটা বেশ তীক্ষ্ণ; রাস্তায় টিকে থাকতে ওইরকম বুদ্ধি লাগে। আমি যদি এখনো বাইরে ঘুরে ঘুরে তদন্ত করতাম, নিশ্চয়ই ওর সঙ্গেই জুটি বাঁধতাম।"
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_5919_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "ওই বিশপ সকলে‌কে রক্ষা করতে পারবে না। সে হয়তো কাদামাটি থেকে কোনো এক দুর্ভাগা আত্মাকে টেনে তুলবে, কিন্তু বাকিরা? ...তার বিশ্বাস ভেঙে চুরমার হওয়ার মুহূর্তের জন্য আমি আর অপেক্ষা সইতে পারছি না।"
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "চ্যাট: সালভাদোর সম্পর্কে"
  },
  Voice_5920_UnlockDesc = {
    Text = "জাগরণকারী \"সালভাদোর\" অর্জনের পর আনলক হবে"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "আপনি লন্ডিনিয়ামের নর্দমায় যা কিছু দরকার সব খুঁজে পেতে পারেন: স্যামন, সাবান, অর্ধেক খাওয়া হুইস্কি……\nকী, আপনি জিজ্ঞেস করছেন আমি এত ভালো জানি কেন? আমি একবার আমার ভাইয়ের মৃতদেহ টেনে নিয়ে, সেখানে পাঁচ মাইল হামাগুড়ি দিয়েছিলাম……"
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "গল্পগুজব: পয়ঃপ্রণালী প্রসঙ্গে"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "আমার সামনে নতজানু হও!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "আমার সামনে নতজানু হও।"
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "সামনের সারির বাইরে সত্যিকারের পৃথিবীর এক ঝলক দেখে, একসময় আমি \"নায়ক\"দের মূল্য নিয়েই জিজ্ঞাসা তুলেছিলাম। কিন্তু সৌভাগ্য যে তোমার সঙ্গে দেখা হয়েছে—সৎ, সাহসী, আর নির্মল তুমি। তোমার নির্দেশনায় আমি শান্তি ও স্থিতিশীলতার জন্য নিরলস লড়ব। এবার আমি আমার মুক্তি নিশ্চিত করব।"
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5924_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "উফ! সর্বনাশ..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "অশুচি, নোংরা, বিশৃঙ্খল—এই আমাদের শক্তি।"
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "তোমার ভণ্ডামিপূর্ণ অভিনয়কে আমি ঘৃণা করি। ভাবছ আমি পাগল? করুণ? আসল ইকারুস তো তুমি-ই, “উদ্ধারকর্তা”। তুমি আর তোমার ছোট্ট পাল, সেই জ্বলজ্বলে সূর্যের দিকে তাকিয়ে থাকতে থাকতে চোখ পুড়ে সাদা হয়ে গেছে, যাকে তুমি তাড়া করছ।"
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "আমাকে পথ দেখাতে দাও!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "ওদের অনুভূতি অচেনা। আমার বাজি, এ গ্রহের আদিবাসী নয় ওরা।"
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বহির্জাগতিক সত্তা প্রসঙ্গে"
  },
  Voice_5929_UnlockDesc = {
    Text = "জাগরণকারী 「উইঙ্কল」, 「টিঙ্কট」, 「ফেইন্ট」 বা 「ওয়ান্ডা」–এর যেকোনো একটিকে অর্জনের পর আনলক হবে।"
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "বিলীন হও!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "দয়া করে না..."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "দানব হওয়াটা মন্দ নয়। আমার সারাজীবনের একটাই কামনা ছিল—প্রতিশোধের শক্তি।"
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5934_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "প্রতিপক্ষকে সরিয়ে দেওয়া ছাড়া, তোমার আর কোনো কামনা আছে? বিনিময়ে, আমি তোমার প্রার্থনা পূরণ করব... অবশ্য, আমার সক্ষমতার সীমার ভেতরে।"
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_5935_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "সহচর? ...ভাবতে পারি। সিদ্ধান্ত নেওয়ার আগেই যেন মরো না।"
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_5937_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "প্রথম স্পষ্ট নথিভুক্তির পর থেকে, ডিজলিউশন এক মিলিয়নেরও বেশি জীবনে আঘাত হেনেছে। সমগ্র মানবজাতির টিকে থাকার জন্য আমাদের পদক্ষেপ অত্যন্ত গুরুত্বপূর্ণ।"
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "পূর্ণ গতিতে!"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "সাগরের রোষ থেকে সাবধান।"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "সাগরের রোষ থেকে সাবধান।"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5942_AwakerVoiceContent = {Text = "এই!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "আমি তাঁর কন্যা, আবার তাঁরই মাতৃদর্শন। আর তুমি, তাঁর সম্মুখে, নিতান্তই তুচ্ছ এক কীটমাত্র।"
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "সবকিছু নির্বিঘ্নে সম্পন্ন হয়েছে। তুমি এখন বিজয়ের পাল তুলতে পারো।"
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "দূরে থাকো। তুমি কি আমার খেলনা হতে চাও? নাকি ঐশ্বরিক আবির্ভাবের জন্য এক উৎসর্গ?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5945_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "জয়টাকে সহজ করে দাও! এ আমাদের সম্পূর্ণ বিজয়!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "জয়টাকে সহজ করে দাও! এ আমাদের সম্পূর্ণ বিজয়!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "আমি তোমাকে সাক্ষী হওয়ার সম্মান দান করছি। তুমি প্রত্যক্ষ করবে সেই গৌরবময় মুহূর্ত, যা নশ্বর নীতিকে অস্বীকার করে।"
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5946_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "একটা ফাঁপা গহ্বর? টেলিকাইনেসিস করার সময় আমি প্রায়ই এরকম জিনিস তৈরি করি। আমি যেগুলো বানাই, সেগুলো অন্য মাত্রার সঙ্গে যুক্ত থাকে; ডিজলিউশন-এর তৈরি গহ্বরগুলোও কি তাই করবে?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "রক্ষক, দেবমাতার কর্তৃত্বে, আমি সিংহাসনের পাশে তোমার স্থান সুরক্ষিত করছি। তুমি ধ্বংসের পর পুনর্জন্ম নেওয়া যুগের সাক্ষী হবে—এটাই দেবমাতার অঙ্গীকার। এখন উল্লাস করো! কৃতজ্ঞতায় উল্লাস করো!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5948_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "তুমি যেহেতু এত বিনয়ী, আমি তোমাকে একটি উত্তর দেব। আদিতে, আমি সত্যিই অনিচ্ছুক ছিলাম। কিন্তু এখন বুঝেছি: আমি কেবলই এই অপব্যয়ী জীবন যাপন করছি তাঁরই কারণে। মৃত্যু কখনোই সমাপ্তি নয়। তিনি পাল্টা আমাকে মৃত্তিকা বিদীর্ণ পুনর্জন্ম দান করবেন, আর এই বিকৃত চক্রের মধ্য দিয়ে আমরা অর্জন করব চিরন্তন জীবন..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5949_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "ওই নারীর কামনা হাস্যকর। বিলয় থেকে কিছুই বাঁচে না, এমনকি তার 「ঈশ্বর」ও নয়।"
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "গল্পগুজব: থাইস প্রসঙ্গে"
  },
  Voice_5950_UnlockDesc = {
    Text = "\"জাগরণ\" \"থাইস\" অর্জনের পর আনলক হবে"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "আমি সর্বশক্তিমান নই। আমিও ভুল করি। সেই নারীর সর্বনাশা কর্ম ছিল আমার ভুল গণনা... তাই, তোমার সহায়তা প্রয়োজন। যেন তুমি আমার আহ্বানে সাড়া দিতে পারো, তুমি চাইলে এখানে, আমার কক্ষে, একটি শয্যা স্থাপন করতে পারো।"
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5951_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "বিপর্যয়ের ভার কাঁধে নেওয়া... তোমার বয়সের তুলনায় তা নিশ্চয়ই এক অসহনীয় বোঝা। বলো—যদি শুরু থেকেই জানতে যে নিয়তি অপরিবর্তনীয়... তবু কি এত তীব্রভাবে লড়তে? তোমার উত্তর নিজের কাছেই রাখো। আমি বিশ্রাম নেব, আর তুমি ভাবো। তোমার উত্তর... আমাকে আগ্রহী করে।"
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5952_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "আমাকে জাগ্রত করার পর বেশ কিছু সময় পেরিয়ে গেছে, তুমি কি আমার কাছে কিছুই চাইতে চাও না? দেবতার প্রত্যাদেশ, অবশ্যম্ভাবী ভবিষ্যদ্বাণী, এমনকি ডুবে যাওয়া মহাদেশের গুপ্তধন——তুমি কি সত্যিই কিছুই জানতে চাও না?\nহুঁ……অদ্ভুত মানুষ।"
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5953_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "আমি কখনো উপাসনা দাবি করিনি। নশ্বরদের উন্মত্ত ভক্তি কেবল আমাকে আরও ক্লান্ত করে... সরে যাও। আমি এখন নিদ্রায় যাব।"
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5954_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "তোমার মধ্যে আমার কোনো ভৃত্যের বৈশিষ্ট্য দেখি না... হয়তো সেটাই শ্রেয়। শুধু সেই নারীর কথা স্মরণ করলেই ক্লান্তি ভর করে।"
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5955_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "ঈশ্বর তাঁর সব বালকেরা‌কে সমান চোখে দেখেন।"
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "আমি জানি, তুমি এক বিশেষ দর্শক। তোমাকে তো আর হুট করে অন্য মাত্রায় পাঠিয়ে দিতে পারি না; তাতে বড় ঝামেলা হবে। শোনো, তুমি কি কখনো কাউকে এভাবে পাঠিয়েছ? জিজ্ঞেস করা চলবে না, এটা আমার রহস্য!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "আহা, আমার নতুন চেহারায় আগ্রহ জন্মেছে? বুঝতেই পারছ, সবকিছুরই একটা মূল্য আছে। তবে এটাকে আমি আমার সৌভাগ্যের ভেদই বলব—এটাই রাইকারের ভাগ্য!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "মিথাগ আমার কাছে সবচেয়ে বেশি স্মৃতিচারণ ধারণ করে... এটাই আমার সবচেয়ে উষ্ণ আশ্রয়ও।"
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "এটা আমার ওপর ছেড়ে দাও।"
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "কী নির্বোধ!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "অতল স্তোত্র!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "দেখো, আমাকে যা অর্পণ করা হয়েছে—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক·শান্ত সাগর"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "যদি তুমি এখনো আমাকে 「রামোনা」 হিসেবে দেখতে পারো... তবে অনুগ্রহ করে সেই নামটিই ব্যবহার করে যাও।"
  },
  Voice_5964_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5965_AwakerVoiceContent = {
    Text = "কি? তুমিও কি আমার ক্রোধকে কাজে লাগাতে চাও?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_5965_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "সত্য... তা ঠিক এখানেই উন্মোচিত।"
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "যা পেয়েছ, হাতেই তুলে সঙ্গে সঙ্গে খেয়ে নাও। এটাই রাস্তাঘাটের আইন।"
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "এখন নিজেকে বেশ ভরপেট লাগছে।"
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "হুঁ..., গা চুলকাচ্ছে। ব্রাউন, এসে আমার পিঠটা চুলকে দে।"
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "নতুন যান্ত্রিক অংশ আমার সিস্টেমের কার্যক্রমকে ব্যাপকভাবে সহায়তা করবে—এটাকে কি পছন্দ বলা যায় না? দুঃখিত, আমি আশঙ্কা করছি আপনার প্রশ্নটি বুঝতে পারছি না। যান্ত্রিক পুতুলদের জন্য পছন্দ-অপছন্দের কোনো অর্থ নেই।"
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "এবার দেখো।"
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "ভালো করে ভেবে দেখো।"
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "শান্ত থাকো এবং চিন্তা করো।"
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "মিস উইঙ্কলও, আমার মতোই, এই গ্রহের বাসিন্দা নয়... টিঙ্কট ছাড়া আমার স্বদেশের সঙ্গে আর কোনো বন্ধন নেই। ভাবছি, মিস উইঙ্কল তার শ্বেত পাখির দেশ সম্পর্কে কী অনুভব করে?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উইঙ্কল প্রসঙ্গে"
  },
  Voice_5976_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "পেছন দিক থেকে আমার কাছে এসো না, যদি না গলা ভাঙা অবস্থায় শেষ করতে চাও।"
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_5977_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "হাঁ? কীভাবে তুমি অবাধ্য পথের বিড়ালগুলোকে ক্যাম্পাসে ঘুরে বেড়াতে দিলে?! যদি ওই বর্বর প্রাণীটা কাউকে আঁচড়ে দেয়, তখন?"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "আমার চোখ কি তোমাকে অস্বস্তিতে ফেলে? ভালো। এই হিংস্রতাই আমাকে ওই নরকে বাঁচিয়ে রেখেছিল।"
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_5979_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "উচ্চকিত বুলি থেকে আমাকে রেহাই দাও। আমার কাছ থেকে তুমি কী চাও? আমার সুস্থতা অক্ষত রাখার নিশ্চয়ই কোনো কারণ আছে।"
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_5980_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "আমার প্রতিশোধ সবসময়ই স্পার্টানদের দিকেই ছিল, কিন্তু এখন তো সেই সিটি-স্টেটই আর নেই... ঠিক আছে। তোমার ব্লেড হয়ে ওঠা অসম্ভব নয়। অনিচ্ছাসত্ত্বেও তোমাকে সঙ্গী হিসেবে মেনে নিচ্ছি, কিন্তু যদি কখনো আমাকে বিশ্বাসঘাতকতা করার দুঃসাহস করো, আমি তোমার হৃদপিণ্ড ছিঁড়ে বের করব।"
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_5981_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "আমার হাত রক্তে রঞ্জিত। আমার দুর্বল আত্মীয়রা আমার প্রতিশোধ বোঝে না; তারা আমার নিষ্ঠুরতা, অকৃতজ্ঞতা আর বিশ্বাসঘাতকতা নিয়ে হুইসপার করে... প্রতিশোধ সবসময়ই শুধু নিজের জন্যই, আর কারও জন্য নয়।"
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_5982_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "এবার আরও ইস্পাতের প্রয়োজন।"
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "এবার আরও ইস্পাতের প্রয়োজন।"
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5985_AwakerVoiceContent = {
    Text = "মরে যা।"
  },
  Voice_5985_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "আমি... আমাকে উইঙ্কল বললেই হবে। সকলে আমায় এ নামেই ডাকে। হ্যাঁ, আমায় এভাবেই ডাকো, ঠিক যেমন তারা ডাকে..."
  },
  Voice_5986_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5987_AwakerVoiceContent = {
    Text = "এই দেহ আমার প্রভুর ঢাল হয়ে উঠবে!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "এই দেহ আমার প্রভুর ঢাল হয়ে উঠবে!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "「দ্য নাটক্র্যাকার」 তো বালিকাদের জন্য এক রোমান্টিক রূপকথা হওয়ার কথা, অথচ সেই জঘন্য মানুষগুলো সেখানে দেখেছে শুধু চলমান সুশ্রী অঙ্গপ্রত্যঙ্গ আর নোংরা কামনা... ঘৃণ্য।"
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "আমাকে... ওটাকে নির্মূল করতেই হবে!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "প্যান্ডিয়া... সে ঐ সত্ত্বাটাকে ডমিনেট্রিক্স বলে ডাকে? হাহা... আমাকে একটু হাসতে দাও। মানুষ এখনো ভীষণ কোমল; তাদের সবকিছুই কেবল শিশুর খেলার মতো লাগে।"
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "গল্পগুজব: প্যান্ডিয়া সম্পর্কে"
  },
  Voice_5991_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「প্যান্ডিয়া」 অর্জনের পর আনলক হবে"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "আর কাছে আসবেন না!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "আবার আত্মপরিচয় দিতে হবে? তোমাকে নিয়ে সত্যিই কোনো উপায় নেই। আমি জেনকিন, আর এই ছোট্টটা হলো ব্রাউন। 「চিঁ!」\nভুলে যেও না! আমাদের নাম ভুল বললে, আমার লণ্ঠন দিয়ে তোমার *বীপ* জোরে পেটানোর জন্য তৈরি থাকো! 「চিঁচিঁ?!」"
  },
  Voice_5993_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_5994_AwakerVoiceContent = {
    Text = "নৃত্য করি! নৃত্য করি!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "নৃত্য করি! নৃত্য করি!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "শুরু হোক এই উদ্বোধনী শ্রদ্ধাঞ্জলি!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_5997_AwakerVoiceContent = {
    Text = "হুম্ফ।"
  },
  Voice_5997_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "আমার দরকার শুধু একটু পাথর, দুটো ছেনি আর তিনটি রোদমুখী আইরিস... তাহলেই তোমার জন্য আমি যেকোনো কিছু গড়ে তুলতে পারি।"
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_5998_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "এইটুকুই?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6001_AwakerVoiceContent = {
    Text = "অবশ্যই।"
  },
  Voice_6001_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "এই অর্থহীন সংগ্রাম..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "টাইবেরিয়াসের মৃত্যুর পর, রোমানদের বহুদিনের প্রার্থনা অবশেষে পূর্ণ হলো: তারা তাকে টাইবার নদীতে ফেলে মাছের খাবার বানাতে পারল। দামটা ছিল সামান্য: ক্যালিগুলা ওই লোকগুলোকে রণক্ষেত্রে আমার বিনোদনের জন্য আমার হাতে ছুঁড়ে দিয়েছিল।"
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6005_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "আমি অনুভব করতে পারি, ছোট্ট বালিকাটির ভেতরে আমার মতোই শক্তি আছে। সে এখনো তার শক্তির প্রকৃত ব্যাপ্তি বুঝে ওঠেনি। তোমার স্বার্থে, আমি তাকে যথাযথভাবে প্রশিক্ষণ দেব।"
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "চ্যাট: লিলি সম্পর্কে"
  },
  Voice_6006_UnlockDesc = {
    Text = "\"জাগরণ\" \"Lily\" অর্জনের পর আনলক হবে"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "ধুর! তুমি—তুমি এখনো আমাকে হেলায় দেখো, তাই না?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "এটাই আমার অস্তিত্বের প্রমাণ।"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "এটাই আমার অস্তিত্বের প্রমাণ।"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "আমি বিশ্বাস করি সবকিছুরই কোনো না কোনো কারণ থাকে, কিন্তু... এই অর্থহীন হিংসা, এই পক্ষপাত যা আপন ভাইবোনকে একে অপরের বিরুদ্ধে দাঁড় করায়... এসব আমাকে সত্যিই ব্যথিত করে। যদি কোনো কিছুকে ঘৃণা করি, তবে তা-ই।"
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "আমি সত্যিই কামনা করি, এই শক্তি ব্যবহারের প্রয়োজন যেন না পড়ে।"
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "তোমার প্রহরী নামিও না।"
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6013_AwakerVoiceContent = {Text = "হুঁ"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6014_AwakerVoiceContent = {
    Text = "থামুন!"
  },
  Voice_6014_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6015_AwakerVoiceContent = {
    Text = "থামুন!"
  },
  Voice_6015_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "ক্যাসিয়া অসাধারণ! সে চোখের এক মিটমিট-এই একটা খরগোশ হাজির করে দিতে পারে!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "চ্যাট: ক্যাসিয়া সম্পর্কে"
  },
  Voice_6016_UnlockDesc = {
    Text = "「জাগরণ「 「ক্যাসিয়া「 অর্জনের পর আনলক হবে"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "আমার ম্যাজিক প্রস্তুত!"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "ডিজলিউশন... স্বীকার করতেই হবে, এই পৃথিবীতে এমন কিছু বিষয় আছে, যা শক্তির নিয়ন্ত্রণেরও বাইরে।"
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6019_AwakerVoiceContent = {Text = "আঃ—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "পান্না শিখার মাঝে নৃত্য করো।"
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "চিন্তা কোরো না; ক্ষতচিহ্নই যোদ্ধার সম্মানের প্রতীক!"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "এই পেশিগুলোর সামনে কাঁপতে থাকো... সব সময়ই তারা তোমার মাথা ছিন্ন করার জন্য প্রস্তুত।"
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "খাবার সময়? নাকি খেলাধুলার সময়?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6024_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "হাহা! এখন অরিটার বন্ধুরা আর হারিয়ে যাবে না!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6025_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "সিলভিয়া ম্যাম বলেছেন, কিছু পেলে আমাকে \"ধন্যবাদ\" বলতে হবে... ধন্যবাদ, ধন্যবাদ, ধন্যবাদ!!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6026_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "এইবার ভূতের পালা আমার! তোমার কাছে লুকোতে মাত্র 5 সেকেন্ড আছে! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6027_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "লুকোচুরি শুরু হওয়ার পর সকলে গায়েব হয়ে গেল। এইবার, আমি ঠিক করেছি, সকলে‌কেই খুঁজে বের করব!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6028_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "সমুদ্রের তলদেশে আমার দেহাবশেষ পাওয়া গেছে বলে মনে করছ আমি জল পছন্দ করি, আর আমার শয়নকক্ষের বাইরে ঝর্ণা-পুকুর বানাতে চাও?\nহা... তোমাদের যা ইচ্ছে করো, এসব তুচ্ছ বিষয়ে আমাকে বিরক্ত করো না।"
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "জোয়ারের ভিড়ে এক সামান্য ফোঁটা, অমর মিরিয়ামের এক অগভীর অনুসারী... তোমাকে অভিবাদন জানায়।"
  },
  Voice_6030_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6031_AwakerVoiceContent = {
    Text = "কাজ করার এখন আমার পালা।"
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6032_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "অসাধারণ... তোমার একটুখানি অবহেলায় বলা কথাই কয়েক মাস ধরে আমাকে পীড়া দেওয়া সৃজন-সমস্যার সমাধান করে দিল।"
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6033_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "ওই পার্টির সম্ভ্রান্ত ভদ্রমহিলাদের তুলনায়, মার্ফির মেজাজ বরং বেশ স্নেহময় লাগে।"
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_6034_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "ওরা আমাকে নাকি দক্ষ পরামর্শদাতা বলে? ওই বালকেরা অতিরিক্ত দয়ালু। আমি তো শুধু মন দিয়ে শুনি, আর তাদের অন্তর্গত অস্থিরতা মুক্ত করতে সাহায্য করার চেষ্টা করি—যেমন সবসময় করে এসেছি।"
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "কখনোই আমাকে তুচ্ছ ভাববেন না!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "কখনোই আমাকে তুচ্ছ ভাববেন না!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "তৃষ্ণা পাচ্ছে? এই কারাগারে পরিষ্কার পানি এক বিরল বিলাসিতা।"
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6038_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "এখন, কে ভালো {Male=ছেলে,Female=বালিকা}? ভালো {Male=ছেলে,Female=বালিকা}রা মাঝপথে ত্যাগ করে না~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6039_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "তুমি তো এরই মধ্যে আমার মধুর ফাঁদে পড়ে গেছ, তাই না?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6040_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "চলতেই থাকো, আর একটু দূর~ আমরা প্রায় উল্লাসের চূড়ায় পৌঁছে গেছি~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6041_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "চৌদ্দ বছর বয়সে আমি মিথাগ-এ যোগ দিয়েছিলাম। নির্বিঘ্নে স্নাতক হতে পারলে, আজ তুমি আমাকে প্রিন্সিপাল বলে সম্বোধন করতে।"
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "দেখছি তোমার দুর্বল মস্তিষ্ক শেখা জিনিস ধরে রাখতে সম্পূর্ণ অক্ষম।"
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "তুমি আমার ইচ্ছা কী জানতে চাও? সমুদ্রযাত্রায় সুরক্ষা, যাতায়াতে নিরাপত্তা—এটা কি গোনা যায় না?\nবাকিটা, আমি কখনো ভাবিনি... তবে আমি ভালো করে ভেবে দেখব, তারপর তোমাকে বলব।"
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6044_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"স্বর্গ আর পৃথিবীর রহস্যই ছিল যা আমি জানতে চেয়েছিলাম। কোন শক্তি আমাকে নিয়ন্ত্রণ করছে, তা বুঝতে চেয়েছিলাম।\" ...যদিও এই উপন্যাসের কাহিনি আমাকে সন্তুষ্ট করে না, আর এর কল্পবিজ্ঞান হাস্যকরভাবে সরল, তবু পড়ে শেষ করলে তুমি অন্তত আমার প্রেরণাটা বুঝতে পারতে... কী? তুমি এখনো এই বইটা পড়োনি?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6045_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "দায়িত্ব আর নিয়তি অনেকটাই একরকম। কোনোটাকেই সহজে ফেলে দেওয়া যায় না, আর সেগুলোকে ফেলে দেওয়ার প্রয়োজনও নেই।"
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6046_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "আমি কি সব সময় ব্যস্তই দেখাই? হ্যাঁ। সহকারী মাঝে মাঝে উপকারী হতে পারে, কিন্তু কিছু গবেষণায় আমি সম্পূর্ণ অদ্বিতীয়। সাহায্য করতে চাও? তাহলে মাঝে মাঝে দেখে যেও আমি আদৌ এখনো জীবিত আছি কি না।"
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6047_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "আমি নাকি রাগী দেখাচ্ছি? তুমি কি বোঝো, হাসতে কতগুলো পেশি লাগে? ক্লাসে একবার এ নিয়ে ব্যাখ্যা করেছিলাম, কিন্তু মনে হয় সেই পাঠ তোমার মসৃণ মস্তিষ্ক থেকে গলে পড়ে গেছে। উত্তর হলো, ন্যূনতম সতেরোটি, আর তোমার ওপর রাগ করার কোনো যৌক্তিক কারণ আমার নেই।"
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6048_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "মিস রামোনা একবার বলেছিলেন, আমাকে নাকি সকলে-কে মানিয়ে চলতে হবে না। আমি বুঝতে পারিনি... এর মানে কি, আমার সুরক্ষা আর প্রয়োজন নেই?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6049_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "তেরোটি রিপোর্ট জরুরি অনুমোদনের অপেক্ষায়, ছয়টি ক্ষতিগ্রস্ত যোগাযোগকারী মেরামতের জন্য পড়ে আছে, আর আমাকে পাঁচটি ভিন্ন সিলভার নিষ্কর্ষণের পরীক্ষার ফলও নজরে রাখতে হবে... তো, আমার সীমিত সময় নষ্ট করে আমাকে বিরক্ত করার বদলে, কেন না তোমার দুর্বল মস্তিষ্কটাকে একটু কাজে লাগানোর চেষ্টা করো?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6050_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "আমি আকাঙ্ক্ষা করি, পরের বার যেন আমার শ্বেত পাখির দেশ আমার আহ্বানে সাড়া দেয়।"
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "তালা মুক্ত করা হয়েছে।"
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "আমি কতই না আনন্দিত... তুমি কত পক্ষপাতদুষ্ট, আমাকে কত বেশি অনুগ্রহ করো।"
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6054_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "অন্যরা কিন্তু রেগে যেতে পারে, যদি ভাবে তুমি পক্ষপাত দেখাচ্ছ।"
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6055_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "তুমিও কি আমার জন্য ব্যাকুল?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6056_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "অবশেষে, সব শেষ। আর দেখতে হবে না সেই কালো, পিচ্ছিল..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "তুমি আমাকে যা যা দিয়েছ, তার সবকিছুর বিনিময়ে—তোমার প্রেম ইতিমধ্যেই আমার সঙ্গে একাকার হয়ে গেছে..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6058_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6059_AwakerVoiceContent = {Text = "এই!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "উঁহু, অল্পের জন্য বেঁচে গেলাম।"
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "তুমি তো ভীষণ কষ্ট করেছ; এখন তোমার শ্রমের ফল ভোগ করার সময়, তাই না? আরও কাছে এসো, আমি তোমাকে নিরাশ করব না~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6061_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "আমি... আমি তোমার অভিপ্রায় বুঝতে পেরেছি। আমি এখনো অদক্ষ হলেও, আমার সবটুকু দিয়ে তোমার জন্য লড়ব!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6062_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "আপনার দৃষ্টি আমাকে দহন করছে... আমি কি আপনাকে কোনো ঝামেলায় ফেলেছি?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6063_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "আমি খুবই উদ্বিগ্ন... জানি না, কোনোদিন আদৌ আপনার প্রত্যাশা পূরণ করতে পারব কি না..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6064_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "আ-আমার ভীষণ অস্বস্তি লাগছে... এভাবে তাকিয়ে থাকলে... আপনি কি আমার অভিশাপকে ভয় পান না?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6065_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "প-প্লিজ, আমার চোখের দিকে তাকাবেন না... আমি আপনাকে আঘাত করতে চাই না... আমি তো শেষ পর্যন্ত এক দানব..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6066_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "এই বন্যপশুর ঘ্রাণশক্তি? ওটা নিছক ভাগ্য, বুঝলে? ভুল বোঝাবুঝি কোরো না।"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6067_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "আমি এখনো থামতে পারছি না..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "আমার অন্তহীন শক্তির স্বাদ নাও!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "আমার অন্তহীন শক্তির স্বাদ নাও!"
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "তুমি কি সাগরকে ভালোবাসো? আমি সাগরকে যাই হোক ভালোবাসি। বহু বছর আগের সেই দিনটা এখনো মনে আছে, যখন সাগর কোমলভাবে বহু প্রতীক্ষিত মৃত্যুকে আমার মতো দুর্ভাগা এক জনের কাছে পৌঁছে দিয়েছিল।"
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "এইমাত্র এমন এক আনন্দের স্পর্শ পেলাম, যা আগে কখনো পাইনি... কোনো এক অদ্ভুত কারণে..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "এই অন্তঃস্রোত আমাদের শত্রুদের ছিন্নভিন্ন করে দেবে।"
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "এই অন্তঃস্রোত আমাদের শত্রুদের ছিন্নভিন্ন করে দেবে।"
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "আমি এতদিন ধরে অপেক্ষা করছি কেউ আমাকে সত্যিকারের ভালোবাসা, পেইন আর কামনা শেখাবে বলে। তুমি কি আমার প্রার্থনা পূরণ করতে পারবে? তুমি কি আমাকে এই অন্ধকার কারাগার থেকে মুক্তি দিতে পারবে?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6076_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "তুমি কি সত্য জানতে চাও? আমি কারাগারকে ঘৃণা করি, অন্ধকারকে ঘৃণা করি, এতটাই ঘৃণা করি যে মরে যেতে পারি। আমি চাই কেউ আমাকে খেয়াল করুক। আমি চাই কেউ আমাকে প্রজ্বলিত করুক..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6077_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "এই সবকিছুই ভবিষ্যতের চিরস্থায়ী মঙ্গলার্থে।"
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "আমাকে উপভোগ করতে চাও? তাহলে আমার দাস হয়ে যাও। আমি তোমাকে উত্তাপে গলিয়ে দেব~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6079_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "ঠিক আছে। আমি একে পরীক্ষাবস্তুর বিনীত নিবেদিত কবিতা হিসেবে বিবেচনা করব।"
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "আমি ভীষণ বিরক্ত! ওই কাঁপতে থাকা বড় বড় বন্দীদের তুলনায়, এটা তো যেন বাড়ি-খেলা খেলা। তুমি না হয় আমার সঙ্গ দাও~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6081_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "আরও বেশি দাস চাই, তাদের কাতরানো আর ক্ষমা চাওয়া শুনতে চাই——\nযাও আমার জন্য আরও দাস নিয়ে এসো~ প্লিজ~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6082_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "ক্ষমা করো, আমি আবার স্মৃতিচারণের ভেতর নিজেকে হারিয়ে ফেলেছিলাম। অনুগ্রহ করে, বিষণ্ন হয়ো না। এবার তোমার পালা তোমার গল্প বর্ণনা করার। তোমার কি কবিতা লিখতে ইচ্ছে করছে? তোমার অভিযান, তোমার অভিজ্ঞতা, তোমার আনন্দ, তোমার শোক—সব কি মৃদু স্রোতের মতো তোমার মস্তিষ্ক থেকে আঙুলের ডগায় গড়িয়ে পড়বে?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6083_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "আমি তো কেবলই ছিলাম পার্চমেন্টের ওপর ক্ষণিকের জলছাপ, অথচ আমাদের সাক্ষাৎ আমাকে এখানে থমকে দিয়েছে। হয়তো এ এক অলৌকিক ঘটনা। আমি এই অলৌকিক ঘটনাকে গোপন সম্পদের মতো আগলে রাখব, আর তোমার জন্য রচনা করব কালজয়ী কবিতা।"
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6084_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "কেউ একবার আমাকে বলেছিল, কবিতা লেখা হয় উপভোগ করার জন্য... আমি কি তোমার অনুভূতিগুলো শুনতে পারি?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6085_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "তুমি কি কখনও এমন অনুভব করেছ? অন্যের অপরাধ ক্ষমা করে নিবেদিত কবিতা দাও, অথচ কাঙ্ক্ষিত পরিণতি হাতছাড়া হয়ে যায়। তুমি একটি গোলাপ বাড়িয়ে দাও, অথচ তোমার হাতে থেকে যায় না তার সুগন্ধের স্মৃতি, কেবল তীক্ষ্ণ কণ্টকের রক্তাক্ত দাগগুলো।"
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6086_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "আমার কলম ও কালি..."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "এ যে ভুল অন্তমিল..."
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "এটি মহান সত্তার আশীর্বাদ!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "মহান পাণ্ডুর সত্তার আশীর্বাদ..."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "আমার কাছে বিশ্রামের সময় নেই। ডিজলিউশন ইতিমধ্যে আমার দুইটি দেহ গ্রাস করেছে। অনিবার্য সমাপ্তি এসে ধরার আগে, অনেক কিছু আমাকে বুঝে নিতে হবে... সহায়তা করো, শুরু করো পরীক্ষার উপকরণ প্রস্তুত করা দিয়ে। আশা করি ভারসাম্য হিসাব করতে ভুল করবে না।"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6094_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "আমি ফঁতেনব্লোর রঙিন কাচগুলো ভালোবাসি। সেগুলো মানুষের মুখে ভিন্ন ভিন্ন ছায়া ফেলে: হতাশার বেগুনি, তোষামোদী নীল, আর অবশ্যই, আমার প্রিয়—অভিলাষী লাল..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "এখানে, আমি প্রায়ই আমার প্রভুর উপস্থিতি অনুভব করতে পারি, কিন্তু হয়তো আমি এখনও তাঁর মুখোমুখি হওয়ার জন্য প্রস্তুত নই……যাই হোক, আমাকে আশ্রয় দেওয়ার জন্য তোমাকে ধন্যবাদ।"
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "বিশ্বাসঘাতকতা মানুষকে দানবে পরিণত করে, সে যে পক্ষেই থাকুক না কেন। তাই আমি বিশ্বাসঘাতকদের ঘৃণা করি।"
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "হামেল্ন, আপনার সেবায় নিয়োজিত।"
  },
  Voice_60985_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_60986_AwakerVoiceContent = {
    Text = "একবার এমন একজনের সঙ্গে দেখা হয়েছিল, যার সঙ্গীত সম্পর্কে প্রায় স্বতঃসিদ্ধ এক বোধ ছিল। এই ব্যক্তির সৃষ্ট কনচের্তো আর সিম্ফনিগুলো ভোলার নয়।\nএক সত্যিকারের প্রতিভা।"
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "আলাপচারিতা: তার বন্ধুর বিষয়ে"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "আমি কৌশল নির্ধারণে সময় কাটাতে পছন্দ করি না। সঙ্গীতের তুলনায় কৌশলের শিল্পের মূল্য খুবই সামান্য। তবে পথের বাধা সরানোর একটি হাতিয়ার হিসেবে এটি প্রয়োজনীয়। সঙ্গীতের শিখরে পৌঁছানোর স্বার্থে, আমি এটি ব্যবহার করতে আপত্তি করি না।"
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার কৌশল সম্পর্কে"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "অভদ্র।"
  },
  Voice_60988_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "আবারও শোনা গেল। কী এই সুর? শেষবার যখন এটি শুনেছি, তখন থেকেই এটি আমার মনে গেঁথে আছে, না যেতে চায়, না বিশ্রাম নিতে।"
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_60989_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "প্রযুক্তিগত দিক থেকে দেখলে, রণকৌশল পরিকল্পনা আর সঙ্গীত পরিচালনার মধ্যে কোনো পার্থক্য নেই। মানবতার দীপ্তি, আবেগ, কামনা… সেগুলো আমার চোখের সামনে নোটের মতোই স্পষ্ট ও অনুগত হয়ে ওঠে, বেতের ইশারায় সলতের পথ ধরে নাচতে থাকে। সঙ্গীতকে বোঝা মানে সবকিছুকেই বোঝা।"
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তোমাদের মিল সম্পর্কে"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "প্রায় হয়ে এসেছে, আর একটু বাকি। আমাকে এটা শেষ করতেই হবে; আমাকে এটা শুনতেই হবে!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_60991_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_60992_AwakerVoiceContent = {
    Text = "হুম।"
  },
  Voice_60992_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_60993_AwakerVoiceContent = {
    Text = "অভদ্র।"
  },
  Voice_60993_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_60994_AwakerVoiceContent = {
    Text = "হুম।"
  },
  Voice_60994_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "সঙ্গীত ভাষা, লেখা, সবকিছুকেই অতিক্রম করে। যদি এটাকে পরিপূর্ণতা না বলি, তবে আর কাকে বলব, জানি না।"
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_60995_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "তালের দিকে মনোযোগ দিন।"
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "সুর বাঁধা সম্পন্ন।"
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "ভালো লাগল যে আপনি প্রশিক্ষণের গুরুত্ব বোঝেন।"
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "আমি একটি নিখুঁত পরিবেশনা উপহার দেব।"
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "হিংসে হচ্ছে? এই কঠিন আঁশগুলোই তো সম্ভ্রান্ত বংশপরম্পরার প্রমাণ।"
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "আমাকে একসময় প্রশংসা করা হয়েছিল, কিন্তু... ওটা সত্যিকারের প্রতিভা ছিল না।\nআমার কাজগুলো ছিল কেবল আমার পূর্বসূরিদের অনুকরণ।"
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার সৃষ্টিকর্ম সম্পর্কে"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "বাঁশি আর তারের সুর… উপরে নিচে জড়িয়ে ওঠানামা করছে, আবার ফিরে আসছে মূল সুর… এখন মনে পড়ছে, অকালপ্রয়াত প্রতিভা, সেই পতিত তারার জন্য আমি যে রেকুইয়েম রচনা করেছিলাম, এটাই সেই সুর।"
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_61001_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "হুম? আমাকে দেখানোর মতো নতুন কোনো সৃষ্টি আছে কি তোমার?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "এই সুরটি উৎসর্গ করা হয়েছে প্রয়াত আত্মাদের উদ্দেশে।"
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "সবুজ নর্তকীর মধ্যে ছিল এমন এক সৌন্দর্য, যা তাকে রাজদরবারের দলের প্রধান নর্তকী হওয়ার যোগ্য করে তোলে।\nযদি সুযোগ পাই, আমি সত্যিই আশা করি আমরা সহসৃষ্টি করতে পারব।"
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "গল্পগুজব: লিজ সম্পর্কে"
  },
  Voice_61004_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"লিজ\" অর্জনের পর আনলক হবে"
  },
  Voice_61005_AwakerVoiceContent = {
    Text = "আরিওসো!"
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "একটা অর্কেস্ট্রায় কনসার্টমাস্টার থাকে, কিন্তু একা কনসার্টমাস্টার কোনোভাবেই একটি সম্পূর্ণ অর্কেস্ট্রা গড়ে তুলতে পারে না। আমার অর্কেস্ট্রায় তাদের জন্য কোনো জায়গা নেই, যারা শুধু নিজেদের প্রদর্শন করতেই আসে।"
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "আমার মনে হচ্ছে আমি একটা সুর শুনেছি। আশেপাশে কেউ কি মহড়া দিচ্ছে?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_61007_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_61008_AwakerVoiceContent = {
    Text = "ডাল সেইনো!"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_61009_AwakerVoiceContent = {
    Text = "দা কাপো!"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "নিজের সর্বনাশের জন্য প্রস্তুত হও!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "হ্যাঁ, হ্যাঁ, এটাই—চূড়ান্ত প্রার্থনা, সঙ্গীতেরই জন্য রচিত এক রেকুইয়েম!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_61010_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "আহ, রক্ষক, একেবারে সময়মতোই এসেছ। বলো তো, এই মুভমেন্টটা সম্পর্কে তোমার কী মত?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "তারের সুর, শুরু হোক।"
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_61013_AwakerVoiceContent = {
    Text = "ক্রেশেন্ডো, ক্রেশেন্ডো!"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "ধীরে ধীরে স্পষ্ট হয়ে উঠল, সেই পেঁচানো সুর, যেন কোনো আত্মার বিলাপ… আমি নিশ্চিত, এর আগে কোথাও এটি শুনেছি।"
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_61014_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "যুক্তি আর শৃঙ্খলা পথ তৈরি করেছিল। আমি সেই পথে উপরে উঠে হলঘরের দরজা খুললাম। তার ওপারে, এ দুটির কোনো অস্তিত্বই রইল না—কারণ সত্যিকারের চিরন্তন সঙ্গীত যুক্তিকেও অতিক্রম করে।"
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "গল্পগুজব: যুক্তি ও শৃঙ্খলা সম্পর্কে"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "আমার হাতের দিকে তাকান, এক, দুই, তিন।"
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "তোমার কথিত অর্কেস্ট্রার পরিবেশনা আমি শুনেছি, তাতে ভুলে ভরা। তবে চিন্তার কিছু নেই, সিলভার ফ্রস্ট উৎসবের আগে এক নিখুঁত প্রদর্শনী মঞ্চস্থ করার জন্য আমার কাছে বিস্তারিত পরিকল্পনা আছে।"
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "আমার চেতনার গভীরে প্রথমবার সেই সঙ্গীত শোনার মুহূর্ত আমি কখনো ভুলো না। সেই নোট আর কর্ডের ভেতরে বাস্তব জগৎ মিলিয়ে গিয়েছিল; কেবল বিশুদ্ধ, মহিমান্বিত সঙ্গীতই থেকে গিয়েছিল।"
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "দুঃখজনক। মনে হচ্ছে আরও মহড়ার প্রয়োজন।"
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "এটি একটি আদেশ।"
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "আমি সাধারণত এমন আমন্ত্রণ জানাই না, কিন্তু… তুমি কি একবার চেষ্টা করে দেখতে চাও? বেতটা হাতে নিয়ে সঙ্গীতে নতুন প্রাণ সঞ্চার করতে?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_61020_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "আমি কথার চেয়ে সঙ্গীতের মাধ্যমে নিজেকে প্রকাশ করতে বেশি স্বাচ্ছন্দ্যবোধ করি। কিন্তু তোমার সঙ্গে কথা বলা মানে যেন অসংখ্যবার মহড়া দেওয়া এক অর্কেস্ট্রা পরিচালনা করা—মসৃণ, আর প্রায়ই মনোরম বিস্ময়ে ভরা।\nতুমি সঙ্গীতের জন্য যেমন, আমার জন্যও তেমনি এক বিশেষ স্থান দখল করে আছ।"
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_61021_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "একটি সিম্ফনিতে বাদ্যযন্ত্রগুলোর পারস্পরিক সমন্বয় অত্যন্ত গুরুত্বপূর্ণ; কোন অংশ কীভাবে যোগ দিচ্ছে আর সরে যাচ্ছে, তার ওপরই সঙ্গীতের অভিজ্ঞতা বদলে যায়।\nআমার বলতে চাওয়া হলো, যদি জাগরণকারীদের নির্দেশ দেওয়াকে একটি পরিবেশনা ধরা হয়, তবে তুমি তা বেশ ভালোই করছ।"
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_61022_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "তুমি কি এই সুরটি পছন্দ করো? মাত্র চার মাত্রার ভেতরেই এটি সম্পূর্ণভাবে মূল সুরটিকে উপস্থাপন করে; বায়বীয় বাদ্যযন্ত্রগুলো সুরটিকে ক্রমাগত উপরের দিকে ঠেলে নিয়ে যায়, যতক্ষণ না থিমে পৌঁছায়। এমন বিন্যাস অগণিত উত্তরসূরিকে প্রভাবিত করেছে… দুঃখিত, আমি কি খুব বেশি কথা বলে ফেলছি?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_61023_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "নিখুঁত পরিবেশনা।"
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_61025_AwakerVoiceContent = {
    Text = "ফোর্টে!"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_61026_AwakerVoiceContent = {
    Text = "অ্যাকসেন্ট!"
  },
  Voice_61026_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "আমাদের প্রত্যেকের হৃদয়ে এক একটি সুর লুকিয়ে থাকে, যা যুক্তি আর দেহের শৃঙ্খলে বন্দি, এবং কেবল উন্মাদনাতেই সম্পূর্ণরূপে প্রকাশ পায়।"
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "কেবল সঙ্গীতই প্রশংসার যোগ্য।"
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "কেবল সঙ্গীতই প্রশংসার যোগ্য।"
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6102_AwakerVoiceContent = {
    Text = "যাও।"
  },
  Voice_6102_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "শোনো, এই হলো শেষ রেকুইয়েম!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "দয়া ভিক্ষা করো!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "শোনো, এই হলো শেষ রেকুইয়েম!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "তুমিও কি সবুজ শিখা দ্বারা গ্রাসিত হতে চাও?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "অন্যদিকে তাকানোর সাহস কী করে হলো!"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "একাগ্র হও!"
  },
  Voice_6108_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = "বিশ্ববিদ্যালয়ে এত আদুরে বাচ্চা আছে কীভাবে~ আমি তাকে বললাম \"আমার দাস হতে চাও কি না\", সাথে সাথে তার মুখ লাল হয়ে গেল, আমতা আমতা করে বলতে লাগল \"আমি তো ইতিমধ্যে গোপনরক্ষকের নাইট\"……\nএতে তো কোনো বিরোধ নেই~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ওজিয়ার সম্পর্কে"
  },
  Voice_6109_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ওজিয়ার」 অর্জনের পর আনলক হবে"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "ভাববে না যে তুমি আমার কাছে আসতে পারবে।"
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক·প্রচণ্ড তরঙ্গ"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "তোমার নিয়তিকে মেনে নাও।"
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক·জোয়ারের জাগরণ"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "আমার শ্বেত পাখির দেশের দ্বার ভেসে দূরে সরে যাচ্ছে... না... আর না..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "সরে দাঁড়াও!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "সরে দাঁড়াও!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "তোমার কৃতকর্মের মূল্য এখন চোকাও।"
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "তোমার কি মৃত্যুর প্রার্থনা আছে?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "মনে হচ্ছে আমি আবারও ডিজলিউশনে আক্রান্ত হয়েছি... আমার হৃদয় যেন ধীরে ধীরে (ক্ষয়িত) হয়ে যাচ্ছে! কয়েকটা অ্যাসপিরিন, একটা চাবুক আর সামান্য পেইনই যথেষ্ট হবে আমাকে সারিয়ে তুলতে..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "তুমিও যদি এই অভিশপ্ত পচন সারাতে না পারো, তবে ডিজলিউশন-এর পেছনে ছুটছ কেন? একেবারে পাগল কুকুরের মতো আচরণ করছ।"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "আমি শেষ রোমান যোদ্ধা—উভহাশ!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6120_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "আমি শেষ রোমান যোদ্ধা—উভহাশ!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "ডিজলিউশন...? অবশ্যই জানি! এর মানে শুধু এই যে দাসের গলায় বাঁধা শিকলটা ছিঁড়ে গেছে। এতে আবার কঠিন কী আছে?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "আমাকে ডাকা হয়েছে; দেবতা আর প্রার্থনাকারীর মাঝের রেখা এখন রক্তাক্ত হয়ে ঝাপসা।"
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6123_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "হুঁ... মালিশে তুমি ক্রমেই দক্ষ হচ্ছ। চাপটা বেশ ঠিকঠাক দিচ্ছ~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "এখানকার সাজসজ্জা কি খুব বেশি সেকেলে নয়? অদ্ভুত এক শীতলতা আছে, যেন ভূতুড়ে কোনো জায়গা।"
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "এখানে সজীব উদ্ভিদ, শান্ত বাতাস, আর আছে আমার বোনের অসুখের প্রতিষেধক। আমাদের দুজনের জন্য, এটাই সবচেয়ে অপূর্ব নতুন স্বদেশ।"
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "ফেইন্টের সঙ্গে আবার দেখা হবে, তা কখনো ভাবিনি... ভাবছি, সেই সময়ের পর থেকে সে কেমন আছে। যতবারই আমি জিজ্ঞাসা করি, সে শুধু আশ্বস্ত করে বলে—সে ভালো আছে... হা sigh। আহ, ক্ষমা কোরো, আমি একটু বেশি আবেগে ভেসে গেলাম। তার আগে তোমাকে ধন্যবাদ জানানো উচিত, আমাদের আবার মিলিয়ে দেওয়ার জন্য।"
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ফেইন্ট সম্পর্কে"
  },
  Voice_6127_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ফেইন্ট\" অর্জনের পর আনলক হবে"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "তাঁর ইচ্ছার উদ্দেশ্যে এক নিবেদিত কবিতা।"
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "তাঁর ইচ্ছার উদ্দেশ্যে এক নিবেদিত কবিতা।"
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "শান্ত হও, শান্ত হও..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "আমার ভেতরে অনেকগুলো 「আমি」 আছে। সুখী, দুঃখী, ক্রুদ্ধ... তারা সবাই স্পঞ্জ কেক ভালোবাসে, লন্ডিনিয়ামের বৃষ্টিভেজা দিনগুলো ঘৃণা করে। তাদের সবার নামই 「24」, আর তারা সবাই আপনাকে ভীষণ ভালোবাসে।"
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6131_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "আমি একসময় প্রতিদিন মাঝরাত পর্যন্ত কাজ করতাম—বুনন, কাপড় ধোয়া, ঝাড়পোঁছ, আয়ার কাজ, এমনকি ঝাড়ুদারের কাজও... যা কিছু করলে পয়সা আসত, সবই করতাম। সেই সময়, বেঁচে থাকা মানে শুধু বেঁচে থাকা, এটুকুই।\nআর এখন, আমাদের তাজা খাবার আছে, উষ্ণ বিছানা আছে, আর আপনার মতো দয়ালু মনিব আছেন... এসব স্বপ্নেও ভাবতে পারতাম না।"
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6132_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "দয়া করে চিন্তা করবেন না। আমরা সবাই মিলে একসঙ্গে স্টেক খাব, এক বিছানায় ঘুমোব, আর কখনোই আপনাকে কোনো ঝামেলায় ফেলব না।"
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6133_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "হেহে, সেই মহিলা আমাকে বের হতে দেখে এতটাই ভয় পায় যে রাতে ঘুমাতেও সাহস করে না। আরাম করো, উপহারের খাতিরে, তোমাকে মারতে আমার মন চাইবে না।\nআমি কে? অবশ্যই「24」, হাহাহাহা!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6134_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "এই মুহূর্তে আমি দারুণ অনুভব করছি। কী? তুমি বলছো আমার মন নাকি অন্য কিছুর দখলে চলে গেছে? ন-না, তা কী করে হয়... উঁ..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6135_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "একজন প্রজার জন্য, তুমি বেশ তীক্ষ্ণ নজরে পর্যবেক্ষণ করো। আমার পরের দীর্ঘ তন্দ্রার আগে, আমি… এই যুগকে আমার উপস্থিতির কৃপা দান করব।"
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "হুঁম... আজ রাতের সমুদ্রের জল বেশ উষ্ণ..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "সে এসে গেছে... আমার স্বপ্নলোকের ভেতর ঘুরে বেড়ানো সাদা পাখিটি।"
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "তোমার প্রার্থনা অনুযায়ী, আমার অস্তিত্ব আরও স্পষ্ট, আরও স্পর্শযোগ্য হয়ে উঠেছে।"
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "কী পরিতৃপ্তি, আহাহা!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6141_AwakerVoiceContent = {
    Text = "মধুর!"
  },
  Voice_6141_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "এটা আমার ওপর ছেড়ে দাও!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "এটা আমার ওপর ছেড়ে দাও!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "স্বাগত জানাও—আমাদের মহাভোজে!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "এক্সাল্ট: উন্মাদনা"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "এই মেয়েটি… তার শিরায় নিঃসন্দেহে আমার রক্ত প্রবাহিত। না—আমি এখনো এতদিন এই পৃথিবী পায়ে হেঁটে কাটাইনি যে সন্তান জন্ম দিই। তবু… তার শক্তি আমার নিজের প্রতিবিম্ব।"
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "চ্যাট: ঐশ্বরিক রক্তধারা সম্পর্কে"
  },
  Voice_6145_UnlockDesc = {
    Text = "জাগরণকারী \"আইজিস\" বা \"মার্ফি\"–কে অর্জনের পর আনলক হবে।"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "মাস্টারের দয়া, কারেন এক মুহূর্তের জন্যও ভুলতে সাহস পায় না!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—আহ, কত মিষ্টি, কত সুস্বাদু!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "আচ্ছা... আমি ডায়েটে আছি, আজ বেশি খেতে পারব না~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "এই দুর্বলগুলো আমার ব্লেডের যোগ্যই নয়।"
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "শিল্পকে ব্যাখ্যা করা ঠিক ততটাই হাস্যকর, যতটা রেলওয়ে শেয়ার ব্যাখ্যা করা—দয়া করে আমাদের শিল্পীদের জীবন আর কঠিন করে দিও না।"
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "আইগিস... আমি কি কোনো ভুল করেছি?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "তোমার নীরব প্রার্থনা শোনা হয়েছে।"
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "তোমার নীরব প্রার্থনা শোনা হয়েছে।"
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "হুঁ, কত অশ্রদ্ধেয়।"
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "আহ, একটু আগে কি মিস্টার এন আমাদের পাশ দিয়ে হেঁটে গেলেন? না, থাক, ভুলে যাও। শেষবার যখন আমি তাকে অভিবাদন জানালাম, সে আমাকে চিনতেই পারেনি... আমি কারাগারে তার জন্য অপেক্ষা করেছি, ভেবেছিলাম সে আমাকে নিয়ে যাবে, কিন্তু সে আর আসেনি, দাঙ্গার সময়ও না।"
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "চ্যাট: 「এন」 সম্পর্কে"
  },
  Voice_6155_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 7 সম্পন্ন করার পর আনলক হবে"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "তোমার আহ্বানে সাড়া দিলাম কেন? অবশ্যই যা শুরু করেছিলাম তা শেষ করতে। আর তুমি যদি এতটাই শক্তিশালী হয়ে ওঠো যে আমাকে চ্যালেঞ্জ করতে পারো, তবে সেটা অতিরিক্ত প্রাপ্তি মাত্র।"
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "দিদি, ব্রাউন, দরিদ্রালয়ের সেই ভীতু ছেলেটা, বন্ধু হিসেবে তারা আমার জন্য যথেষ্ট। উম্... ঠিক আছে, তুমিও একজন ধরে নাও। ব্রাউন, গোপনরক্ষককে একটা মিছরি দাও।\n「চিঁ চিঁ?!」"
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6157_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "পূর্ব জেলার বস্তি বাচ্চাদের থাকার জায়গা না। ধুরন্ধর বুড়ো ফোরম্যানরা পেপারবয়ের মজুরি কাটার হাজারটা ফন্দি বের করত, আর দুধওয়ালা বাচ্চাদের গতি নিয়ে ন্-নখরা করত! ওখানে টিকে থাকতে হলে, ভরসা রাখতে হয় শুধু নিজের ওপর। আর কারও ওপর ভরসা করার মতো নয়।"
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6158_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "আমার এই \"খারাপ অভ্যাস\"গুলো রাতারাতি বদলাবে না, বুঝলে? সেতুর নিচে আর নিষ্কাশনে ঘুমানো, উচ্ছিষ্ট খেয়ে বেঁচে থাকা—বেঁচে থাকাটাই ছিল যথেষ্ট কঠিন... ঘুম থেকে উঠেই আমি বিছানা গুছিয়ে ফেলব, এমনটা আশা করতে পারো না! মানিয়ে নিতে আমাকে অন্তত দুই সপ্তাহ তো দিতেই হবে!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6159_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "মহাকাশে পথ হারানোর অনুভূতি সত্যিই ভালো না। যেহেতু তুমি আমাকে সেখান থেকে উদ্ধার করেছ, তাই কিছু বলার থাকলে সরাসরি বলো, তবে আমি সাহায্য করতে পারব কিনা সেটা নিশ্চিত না।\nআমার বয়স তো দেখতেই পাচ্ছ, তুমি তো আর একটা বাচ্চাকে বিপদে ফেলবে না, তাই না~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6160_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "এই যে, পশ্চিম জেলার লোক! ব্রাউনকে দেখেছ? ওই ছোট্ট পেটুকটা আবারও খাবারের গন্ধ শুঁকে বের করেছে।"
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6161_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"যাদের শক্তি আছে, তারা যেন সেই শক্তি দিয়ে অন্যদের ওপর অত্যাচার না করে, কারণ তোমরা সবাই আমার রক্তের অংশ।\" করুণাময় আমাদের পিতৃদেবের এই শিক্ষাই আমি মনে রেখেছি। এই শক্তি আমি কেবলই ব্যবহার করব আমার চারপাশের মানুষদের রক্ষার জন্য।"
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6162_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "জানতে ইচ্ছে করছে, মহাবিশ্বের সূচনায় আমি কী দেখেছিলাম? অবশ্যই, বলতে পারি। আমি কিছুই দেখিনি।"
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6163_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "এটি আরও উজ্জ্বল হয়ে উঠছে।"
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "অনন্ত প্রদীপ..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "শ্বেত পাখির দেশের সাথে আমার বন্ধন আরও শক্তিশালী হয়েছে।"
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "আমি যদি এই পৃথিবীকে তার দুঃখ থেকে মুক্ত করতে পারি, তাতেই আমি তৃপ্ত হব।"
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "আমাকে তোমার আদেশ দাও, ফ্যাকাশে দূত। তোমার শিখা যেন চিরকাল আমার পথ আলোকিত করে।"
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "একজন মানুষকে শাণিত করার কাজ শুধু দেহকাঠামোকে নয়, হৃদয়কেও জড়িয়ে রাখে।"
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6172_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "উঁহু! তোমার তাপমাত্রা প্রবালের জন্য একটু বেশি। কিন্তু... এতে যে উষ্ণতা আর তীব্রতা আছে। আমার ভালো লাগে।"
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "লা... আহ, তোমার কি কিছু দরকার ছিল? সম্ভব হলে, চল পেছনের মঞ্চে গিয়ে কথা বলি।"
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "ফোটার আগেই বিবর্ণ হয়ে যাওয়া, এক শাপলার মতো... শীতল, উন্মত্ত জোয়ারে শান্তি খোঁজা, নিজের 「আনন্দ」 অনুসরণ করার মতো সাহসও না থাকা... আমি ঠিক তেমনই একজন মানুষ, রক্ষক।"
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6176_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "আমি একসময় এই দ্বন্দ্বে লড়েছি: পেইন কি জীবনের চেয়েও দীর্ঘস্থায়ী? যদি তাই হয়, তবে কি শান্ত তন্দ্রা যন্ত্রণাময় জাগরণের চেয়ে বেশি সুখকর? জেগে ওঠার পর, আমিও সেই ফাঁদে জড়িয়ে পড়েছিলাম, যতক্ষণ না তুমি আমাকে এই নিরাপদ আশ্রয় এনে দিলে..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6177_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "স্যানাটোরিয়ামে থাকার সময়, আমি বন্ধুত্ব করতে চেয়েছিলাম, কিন্তু মানুষজন আমার কাছে আসতে চাইত না... এটা কি এই অস্থি-ক্ষয়কারী\"বিষক্রিয়া\"র জন্য? দয়া করে, আমার কাছে এলে সাবধানে এসো।"
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6178_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "রাত্রির হাওয়ায় ভেসে আসা ঘণ্টাধ্বনি এক অদ্ভুত শান্তি এনে দেয়। তুমি কি পাথরের চেয়ারে বসে কিছুক্ষণ শুনতে চাও? আমি তোমার আসনটা ভালোভাবে একটি মাফলার দিয়ে প্রস্তুতি করে দেব।"
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6179_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "তুমি কি \"সমুদ্র-সমাধি\"র কথা শুনেছ? আমার পুরোনো শহরে মৃতদের সাগরে সমর্পণ করার এক রীতি ছিল; সমুদ্রই হয়ে উঠত সকলে’র শেষ বিশ্রামস্থল। আর আমি, তার তোষামোদকারীর আলিঙ্গনে একটু আগেই ফিরে গিয়েছিলাম..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6180_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6181_AwakerVoiceContent = {
    Text = "হুম্ফ!"
  },
  Voice_6181_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6182_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6183_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6184_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "যুদ্ধের লগ আর্কাইভে সংরক্ষিত হয়েছে। আপনার পরিশ্রমের জন্য ধন্যবাদ, রক্ষক।"
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "আমি এখনও এগিয়ে যেতে পারি।"
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "আমার স্যালনের অতিথিরা পায় সর্বোচ্চ আতিথ্য… প্রবেশপত্র হিসেবে, তুমি কি এই মহাভোজসভা উপযোগী যথেষ্ট মূল্যবান রহস্য প্রস্তুত করেছ?"
  },
  Voice_6190_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6191_AwakerVoiceContent = {
    Text = "আমি নতুন জিনিস ভালোবাসি। সহস্রাব্দজুড়ে ভ্রমণে আমি অসংখ্য বিস্ময়কর উদ্ভাবন আর আবিষ্কার দেখেছি, যেমন কবিতার নতুন পঙ্‌ক্তি-রীতি আর চলচ্চিত্রের দৃশ্যাবলি। মানুষ সত্যিই এক অদ্ভুত সত্তা।"
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "হ্যাঁ। লিলি মনে রেখেছে। মা বাইরে থাকলে লিলি তার বাড়িতে থাকত।"
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "চ্যাট: ড্যাফোডিল সম্পর্কে"
  },
  Voice_6192_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ড্যাফোডিল\" অর্জনের পর আনলক হবে"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "কে সাহস করে 'এই একজনের' তন্দ্রায় বিঘ্ন ঘটাতে আসে?"
  },
  Voice_6195_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6196_AwakerVoiceContent = {
    Text = "ঈশ্বর? কেবল মূর্খরাই তাদের জীবন এমন অস্পৃশ্য সত্তাদের হাতে সঁপে দেয়। তথাকথিত দেবতার ওপর জীবন বাজি ধরার বদলে, কীভাবে আরও শক্তিশালী হওয়া যায়, সে দিকে মনোযোগ দেওয়াই ভালো।"
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "ওই যে “দাস প্রভু”, “গ্ল্যাডিয়েটরদের মালিক”... হা। সে তো এক তুচ্ছ পোকা মাত্র।"
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাগ্রিপা প্রসঙ্গে"
  },
  Voice_6197_UnlockDesc = {
    Text = "\"জাগরণ\" \"অ্যাগ্রিপা\" অর্জনের পর আনলক হবে"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "বিজয়ের পর, প্রজননের জন্য প্রয়োজনীয় উপকরণগুলো নিতে আমাকে অনুমতি দেবে?"
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "বড় বন্ধু! সঙ্গী! হু-হু, চল না চিরদিনের সেরা বন্ধু হই, কেমন?"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "আমি এখন ভীষণ, ভীষণ উত্তেজিত... যদি সত্যিই বাঁচতে চাও, তবে আমার থেকে দূরে থাকাই ভালো।"
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "ও... ওর পক্ষে কি সত্যিই অন্যদের সঙ্গে এভাবে আচরণ করা ঠিক হচ্ছে? সারাহ ম্যাডাম তো বলেছিলেন, বাচ্চাদের নাকি এভাবে রাগারাগি করা উচিত নয়..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_6201_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "বিজয়ের গৌরব আপনারই, আমার প্রভু।"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "প-প্লিজ, আমি ভেতরটা পুরোপুরি ভরে গেছি~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "ভেতরের শূন্যতা এখন পূর্ণ হয়েছে~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "হ্যাঁ, আমি আরও উত্তপ্ত হয়ে উঠছি..."
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "ও বাচ্চাটাকে আমি চিনি। মাঝে মাঝে অনেক দূরে দাঁড়িয়ে আমার পরিবেশনা দেখে। ও যে কাছে আসে না, সেটা ভালো—নইলে আমার ছোট্ট দর্শকরা মানসিক ও শারীরিকভাবে সম্পূর্ণ ক্ষয় হয়ে যেত!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ফেইন্ট সম্পর্কে"
  },
  Voice_6206_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ফেইন্ট\" অর্জনের পর আনলক হবে"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "টিঙ্কট বলেছে, “উপকারের প্রতিদান দাও।” তাই, যতটা আমার সক্ষমতার মধ্যে পড়ে, সাহায্য করতে পারলে আমি হাত বাড়িয়ে দেব..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "হ্যালো, রক্ষক। আমি কীভাবে আপনাকে সহায়তা করতে পারি?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "একদিন আমি আবার যুদ্ধক্ষেত্রে ফিরব, অগ্রসারির নেতা হয়ে।"
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6209_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "বিশ্বাস করতে পারো? আমি অনুভব করতে পারছি, আমার ভাঙা পায়ের হাড় নিরাময় হচ্ছে।"
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6210_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "আমাকে এই স্তর পর্যন্ত প্রশিক্ষণ দেওয়ার জন্য তোমার বিশ্বাসের প্রতি আন্তরিক কৃতজ্ঞতা। তুমি নিশ্চয়ই এমন একজন, যে ন্যায়বিচারকে অনুসরণ করে; তাই আমি এখানেও আমাদের উদ্দেশ্যে গৌরব বয়ে আনতে থাকব।"
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6211_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "আরেকটি অভিযানের দিন দ্রুত এগিয়ে আসছে, আর আমার রক্ত উদ্দেশ্যের উত্তাপে ফুটছে।"
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6212_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "যোদ্ধা হওয়ার সম্মান পুনরুদ্ধার হচ্ছে।"
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6213_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6215_AwakerVoiceContent = {Text = "আহ্!"},
  Voice_6215_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6216_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "প্রতারক!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "উফ, আমার ভুল! পরের বার ঠিক করে দেখাব, কথা রইল!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "আমি শুনি কেউ আমার নাম ধরে ডাকছে: অ্যাগ্রিপা, অ্যাগ্রিপা, অ্যাগ্রিপিনা..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6219_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "আমি দেখেছি... ওটা কূপের অন্ধকার থেকে উপরে উঠছে; তার মাংসের ডিমের গায়ে অসংখ্য চোখ গজিয়ে উঠছে। তারা আমার দিকে তাকিয়ে, আমাকে ডেকে বলছে... গোলকধাঁধার দেবতা!"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6220_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "আমার ভীষণ শক্তিশালী এক তাগিদ হচ্ছে একটা দ্বন্দ্বযুদ্ধ দেখার... যদি সেটা গোলকধাঁধার ভেতর হয়, তবে তো আরও ভালো!"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6221_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "চুক্তি... হ্যাঁ, আমি তোমার সঙ্গে একটি চুক্তি করতে চাই; এক অনন্তকালীন প্রভু-দাসের চুক্তি..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6222_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "হুঁ... মন্দ না। আরও দাও। এই ছোট ছোট মাকড়সাশিশুগুলোকে খাওয়াতে হবে।"
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6223_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "কি নোংরামি, কি জঘন্যতা! আহ—থামো! দয়া করে! আমাকে সেটা দেখতে বোলো না, আমার সামনে তার কথা তুলো না..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "আমার অতীত ছিল নিয়মিত আর শান্ত, ঠিক বিষুবরেখার কাছের সমুদ্রের মতো; বলার মতো তেমন কিছুই নেই।"
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6225_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "হুম...? মা, কোলে নেবে? ...তোমার শরীর খুব উষ্ণ..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "হে তারাধূলি..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "আহারে, আমরা কি পথ হারিয়ে ফেলেছি?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "নিরর্থক।"
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "যখনই সেই বিশ্বাসঘাতকদের কথা মনে পড়ে—হাঁটু গেড়ে আর্তনাদ করে ক্ষমা ভিক্ষা করা তাদের চেহারা—একটা তৃপ্তির ঢেউ বয়ে যায়, আর আমার হৃদয়ের আগুন যেন খানিকটা স্তিমিত হয়।"
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "অনেক বছর আগে আমাকে জাহাজে আনা হয় এবং জাহাজের কুমারীর দায়িত্ব আমার হাতে অর্পণ করা হয়। সেই থেকে, আমার জীবন—এবং তার অর্থ—আমার নিয়ন্ত্রণের বাইরে। আমাকে বলা হয়েছে, অন্তত এই দ্বিতীয় জীবনে, একজন জাগরণকারী হিসেবে, আমার নিজের ইচ্ছার জন্য বাঁচা উচিত... তুমি কি আমাকে সাহায্য করবে? আমাকে স্বার্থপর হতে সাহায্য করো, আমাকে আমার নিজের ইচ্ছেটা খুঁজে পেতে সাহায্য করো।"
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6231_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "এটা অ্যাগ্রিপা। তোমার সঙ্গে বলার মতো আমার কিছুই নেই—যদি না তুমি সাহস করে স্বেচ্ছায় আমার গ্ল্যাডিয়েটর হতে চাও।"
  },
  Voice_6232_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6233_AwakerVoiceContent = {
    Text = "তাবিল... আমরা যতটা ভাবি, সে তার চেয়েও অনেক বেশি বিপজ্জনক। আমি যখন আর থাকব না, তখন তোমাকে ওর ব্যাপারে ভীষণ সতর্ক থাকতে হবে।"
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "চ্যাট: তাবিল সম্পর্কে"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "এই অনুসিদ্ধান্ত নির্ণয়ের যন্ত্রটি দিয়ে... আমি জগতকে ব্যাখ্যা করব!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "এই অনুসিদ্ধান্ত নির্ণয়ের যন্ত্রটি দিয়ে... আমি জগতকে ব্যাখ্যা করব!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "দীপ্ত হও আমার তরে..."
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "আমার সর্বোচ্চ সক্ষমতা দিয়ে।"
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "আমার সর্বোচ্চ সক্ষমতা দিয়ে।"
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "আমরা ক্ষয়প্রাপ্ত হব... একত্রে।"
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "আমরা ক্ষয়প্রাপ্ত হব... একত্রে।"
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "হাসি আর ভদ্রতা এক ধরনের বর্ম, যা আমাকে অন্যদের থেকে দূরত্ব বজায় রাখতে আর বিরক্তিকর ঝামেলা এড়াতে সাহায্য করে। আর আমার আসল সত্তা... তোমাকে দেখাতে আমার আপত্তি নেই।"
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6242_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "আমার ভাবনাগুলো সাদা চুনাপাথরের মতো জমে, ধুয়ে গিয়ে রূপ নেয় সুন্দর প্রবালে। তারা আমার সঙ্গে মিশে যায়, আমার হৃদস্পন্দনের সঙ্গে তাল মিলিয়ে স্পন্দিত হয়... তুমি কি শুনবে?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6243_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "অনুপ্রেরণা সমুদ্রের বুদবুদের মতো: হালকা ছোঁয়াতেই মিলিয়ে যায়। তুমিও কি তেমন?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6244_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "যুদ্ধ, লুণ্ঠন আর খ্যাতি—সবই মানবিক কামনা। বিনম্র ভাস্করের মানুষের কামনায় কোনো আগ্রহ নেই; সে শুধু সৌন্দর্যের দাস হতে চায়।"
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6245_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "অদ্ভুত সুন্দর জীবন লুকিয়ে আছে আসক্তিতে। কখনও কখনও, নিজের প্রতি এতটা কঠোর হওয়া উচিত নয়।"
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6246_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "এ তো সামান্য আঁচড়মাত্র..."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6249_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "ধিক্কার!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "ডিজলিউশন কেওস ও বিপর্যয় ডেকে আনে। হয়তো সেই কারণেই আমার শ্বেত পাখির দেশ গভীর সাগরে ডুবে গেছে..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6253_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6254_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "পরম আদেশ।"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "এটা চেষ্টা করে দেখুন!"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "অনিবার্য উৎসর্গ।"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "মন্দ নয়; এটিই যোদ্ধার গৌরব!"
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "তুমি! কীভাবে ওই নারীকে এখানে ঢুকতে দিলে?! সঙ্গে সঙ্গে চারদিক ঘিরে পাহারা দাও! তাকে আমার থেকে অন্তত পঞ্চাশ পা দূরে রাখবে!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "চ্যাট: মিরিয়াম সম্পর্কে"
  },
  Voice_6259_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」 অর্জনের পর আনলক হবে"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "আরও শক্তিশালী হওয়ার কারণ? আমার গোষ্ঠীতে দুর্বলদের উলঙ্গ করে, মাথা মুন্ডিয়ে, অকল্পনীয় নিকৃষ্ট অপমানের শিকার করা হয়—দুর্বলতার মূল্য এমন, যা সকলে বহন করতে পারে না।"
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6260_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "ভাগ্যের দেবী, অন্তত এই একবার আমার দিকে হাসো!"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "আমার মনে হয়... মানুষের শক্তিরও সীমা আছে..."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "ভালো। কম ধকল, বেশি শক্তি।"
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6263_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "এটাই কি তোমার কামনার প্রকাশ—আমার স্নেহকে আরও গভীরীকরণ করা?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6264_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "উল্লাস করো!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "আহ, অমার্জনীয়..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "একটু বেপরোয়া হলে ক্ষতি কী!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6272_AwakerVoiceContent = {
    Text = "ব্যাং!"
  },
  Voice_6272_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "চালিয়ে যাও! তোমার চূড়ান্ত ফলাফল আশাব্যঞ্জক।"
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "শুনেছি বস্তি থেকে এক চোর এসেছে, সঙ্গে নাকি এক মোটা ইঁদুরও এনেছে? হিহিহি... দেখুন তো, কীভাবে আমি মাস্টারের জন্য এই উপদ্রবটাকে সরিয়ে দিই!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_6274_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "এসো, একটু গভীর নিঃশ্বাস নাও—"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "মজার ব্যাপার। যুদ্ধে তোমার বিকাশ আমার প্রত্যাশাকে বহুদূর ছাড়িয়ে গেছে। সময় পেলে তুমি হয়তো হয়ে উঠতে পারতে... অদ্ভুত। এত কিছুর পরও, তোমার মতো আপাতদৃষ্টিতে দুর্বল এক সত্তার ভেতরেও আমি এখনো আশা খুঁজে পাই।"
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6276_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "হয়তো এখনই এই কথা বলার উপযুক্ত সময়, তুমি মনোযোগ দিয়ে শোনো।\nতারকা দানব রোটান, আনুষ্ঠানিকভাবে তোমাকে চূড়ান্ত লড়াইয়ের আমন্ত্রণ জানাচ্ছে……অবশ্যই, তুমি শীর্ষে পৌঁছানোর আগে পর্যন্ত আমি তোমার নিরাপত্তা রক্ষা করব। নির্বাচিত প্রতিপক্ষের অকালমৃত্যু—এমনটা আমি দ্বিতীয়বার ঘটতে দেব না।"
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6277_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "হুঁ... এখনো বুঝে উঠতে পারি না, রামোনা কেন তোমাকে সঙ্গী হিসেবে বেছে নিল। তোমার গায়ে শক্তির গন্ধ আছে বটে, কিন্তু আমার সমকক্ষ হওয়ার ধারেকাছেও তুমি নেই।"
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6278_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "হ্যাঁ, আমার দিকে তাকিয়ে থাকো। আমি এই গ্রহের প্রাচীনতম সত্তা, তুচ্ছদের কাছ থেকে শ্রদ্ধা দাবি করি। যুগের পর যুগ আমি এই গ্রহের প্রহরী হয়ে আছি। বিনিময়ে একটুখানি রোমাঞ্চকর যুদ্ধ কি খুব বেশি চাওয়া?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6279_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "হা! শিশুসুলভ খেলায় সময় নষ্ট করার অবকাশ আমার নেই। কোনো কোণ খুঁজে নিয়ে সেখানেই চুপচাপ পড়ে থাকো।"
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6280_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "রক্ষাহীন আত্মারা, আমি তোমাদের শেষ শান্তি দান করব।"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6282_AwakerVoiceContent = {
    Text = "সতর্কতা।"
  },
  Voice_6282_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6283_AwakerVoiceContent = {
    Text = "সতর্কতা।"
  },
  Voice_6283_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "কিছু একটা বিলাপ করছে… আমার মনের গভীরে।"
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6284_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "মনে হচ্ছে সাদা কুয়াশার এক আবরণ আমার চিন্তাগুলোকে ঢেকে দিচ্ছে।"
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6285_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "শব্দটি এখন আরও স্পষ্ট। কুয়াশা ঘনীভূত হচ্ছে।"
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6286_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "ওটা কি... ঘড়ির কাঁটার ঘোরার শব্দ?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6287_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "যখন শেষ ঘণ্টাধ্বনি বাজবে... তখনও কি আমি এখানে থাকব?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6288_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "এত সস্তা কৌশল... হুঁঃ। সরল বোকা। তুমি কি সত্যিই ভেবেছিলে, এত সহজে আমাকে বেঁধে ফেলতে পারবে?"
  },
  Voice_6289_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6290_AwakerVoiceContent = {
    Text = "মাফ করবেন... আপনি কি আমার বোন জেনকিনকে দেখেছেন? সে একটা ইঁদুর সঙ্গে নিয়ে ঘোরে, আর ভীষণ হিংস্র হয়ে উঠতে পারে... তাকে ভুল করা আমার পক্ষে অসম্ভব।"
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_6290_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 2 শেষ করার পর আনলক হবে"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "ধন্যবাদ। তুমি অতিরিক্ত দয়ালু।"
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "প্রস্তুত।"
  },
  Voice_6293_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "আমার পরিবেশনার জন্য অপেক্ষা করো।"
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "আমি তোমার জন্য গান গাইব।"
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "নতুন রক্ষক? এসো, সর্বশক্তি ঢেলে দাও। দেখি, আমার মুখোমুখি হওয়ার যোগ্যতা তোমার আছে কি না!"
  },
  Voice_6296_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6297_AwakerVoiceContent = {
    Text = "আমি যদিও অহিংসাবাদী, “ওরা” কিন্তু স্পষ্টই তা মনে করে না..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6298_AwakerVoiceContent = {Text = "হা!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6299_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও!"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "আমাকে এতটা অপমানিত করার ধৃষ্টতা তোমার কোথা থেকে এল..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "তৈরি তো? ক্যাসিয়ার জাদু প্রদর্শনী শুরু হতে চলেছে! চোখ ফেরাবে না, নইলে সেরা অংশগুলো মিস করবে। শো শুরু হোক!"
  },
  Voice_6301_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6302_AwakerVoiceContent = {
    Text = "টেকেলি—লি!"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6303_AwakerVoiceContent = {Text = "হা!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "আমি সিলভিয়ার কাছ থেকে তোমার সময়সূচি নিয়েছি, এটা একজন নবাগতের জন্য অত্যন্ত কঠোর। আমি বুঝি তোমরা সঠিক কাজই করছ, কিন্তু নতুনদের ওপর এত চাপ দিলে দলের জন্য অপ্রয়োজনীয় সমস্যা তৈরি হতে পারে।\nতুমি বলছ তুমি নবাগত নও? না, আমি তোমার চোখ দেখেই বুঝতে পারছি, এমন অনেক কিছু আছে যা তুমি এখনও অনুভব করোনি।"
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6304_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "নিজের ব্যর্থতাগুলোকে আমি সত্যিই ঘৃণা করি... আহ! আমাকে সান্ত্বনা দেওয়ার প্রয়োজন নেই! অতীতের সেই ক্ষতগুলোই এখন আমার বিকাশের প্রেরণা হয়ে উঠেছে। আমি কি ইতিমধ্যেই আপনার অবিচল ইচ্ছাশক্তি হয়ে উঠিনি?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "ও লোকটার সঙ্গে আমার কিছুতেই বনিবনা হয় না। জীবন তো শুধু পাপ আর শাস্তি নিয়ে নয়, তাই না? মুহূর্তটাকে আঁকড়ে ধরতে চাওয়াটা দোষের কী?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "চ্যাট: সালভাদোর সম্পর্কে"
  },
  Voice_6306_UnlockDesc = {
    Text = "জাগরণকারী \"সালভাদোর\" অর্জনের পর আনলক হবে"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "সময় অল্প। চলুন এগোই।"
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "আমি সহজে নিভে যায় এমন মোমবাতি, কালো রুটি, আর স্কার্টের আলগা সেলাই ঘৃণা করি... কোনো কারণ নেই, আমি স্রেফ ঘৃণা করি। এটা কি স্বাভাবিক নয়?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "যখন তুমি আমাকে সাধ্বী নামে ডাকো, তখন তোমাদের উচিত আমার সামনে নতি স্বীকার করা!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "যখন তুমি আমাকে সাধ্বী নামে ডাকো, তখন তোমাদের উচিত আমার সামনে নতি স্বীকার করা!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "গাও আমার তরে।"
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "「দ্য লেডিস ওয়ার্ডরোব」 আর 「দ্য ওয়ার্কিং ওম্যানস গাইড」—দুটোই অসাধারণ বই... যদিও ওই সুন্দর ড্রেসগুলো কেনার সামর্থ্য আমার নেই, শুধু ওগুলো দেখে মুগ্ধ হওয়াটাই আমার কাছে আনন্দের।"
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "অদ্ভুত, সাধারণত আমার কিছুই মনে থাকে না, অথচ তোমাকে আমি কয়েক দিনের মধ্যেই মুখস্থ করে ফেলেছি… কী? ইতিমধ্যে তিন মাস কেটে গেছে? দুঃখিত, আবার ভুলে গেছি।"
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "আস্বাদন করো।"
  },
  Voice_6314_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "তোমার স্থিরচিত্ততা ক্রমাগত বৃদ্ধি করো।"
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "ফুয়েটে। আরও বিশবার।"
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "আমার গতিবিধি কি যথেষ্ট নিখুঁত?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "অগ্রসর হোন!"
  },
  Voice_6319_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "তাড়াও, ব্রাউনকে ধরে পালাও!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "সিংহাসনের পদতলে নতজানু হও।"
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "সিংহাসনের পদতলে নতজানু হও।"
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "কামনায় বিকৃত মানব-মুখ আমাকে কখনোই বিরক্ত করে না, বরং আমোদ দেয়। কত ভঙ্গুর, কত ক্ষুদ্র... শুধু এটুকুই আমার মনে হয় যেন কোনো বিড়াল আমার হৃদয়টাকে নখর দিয়ে আঁচড়াচ্ছে..."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "আমি তার স্মৃতিচারণে ডিজলিউশনের অতীত ইভেন্টগুলো দেখেছি... কিন্তু যখনই তা নিয়ে কথা বলতে চাই, আমার চেতনা ভেঙে যায়। আমি বিশ্বাস করি, এটা তারই কাজ।"
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "উত্তম। এখন আমরা কেবল বিস্মৃতিতে মিলিয়ে যাব।"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "একজন যোগ্য দাস হতে হবে নমনীয় আর শূন্যমস্তিষ্ক—আমি অনুগত মেষশাবকই পছন্দ করি।"
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "আমাদের এই দেখা হওয়া নিশ্চয়ই দুঃখভোগীদের জন্য পিতৃদেবের দেওয়া কোনো প্রতিশ্রুতি। তুমি সেই ফ্যাকাশে শিখা, যে বিপর্যয় দূর করে; আর আমি হব তোমার বাহু, অবিচল থেকে তোমার পাশে দাঁড়িয়ে।"
  },
  Voice_6327_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6328_AwakerVoiceContent = {
    Text = "এবার যথেষ্ট!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "কখনও তোমার শিরায় জোর করে D-পঙ্ক ঢোকানো হয়েছে? কালো পঙ্কটা বিষাক্ত সাপের মতো তোমার হৃদয় জড়িয়ে ধরে, তারপর... ধাম! তোমার দেহকাঠামো উষ্ণ, ল্যাজল্যাজে কাদায় ফেটে যায়। ঘৃণ্য, কিন্তু কার্যকর।"
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "হুঁ, দুর্বলদের গা ঘেঁষে থাকার এক আশ্রয় মাত্র।"
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "মাঝে মাঝে, মোটরসাইকেলে চড়া সেই বালিকাটি আমার কৃত্রিম অঙ্গের যত্ন নিতে সাহায্য করে। তবে, সম্প্রতি, রক্ষণাবেক্ষণ পরীক্ষার ঘনত্ব কি অস্বাভাবিকভাবে বেশি হয়ে যায়নি?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নটিলা প্রসঙ্গে"
  },
  Voice_6331_UnlockDesc = {
    Text = "\"জাগরণ\" \"নটিলা\" অর্জনের পর আনলক হবে"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "আমাদের সম্পর্ক? এটা কি আলাদা করে জিজ্ঞেস করার দরকার আছে? ঠিক যেমনটা তুমি কল্পনা করছ, ঠিক তেমনই!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "এ ধরনের কবিতার ধারা আমার পছন্দের নয়, কিন্তু তুমি যদি এতটাই অনুরোধ করো, তবে চেষ্টা করব।"
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "তোমার চোখের কালি আরও ঘন হচ্ছে... এত কষ্ট করছ কেন? আমার মতো হও, অবসরকে ভোগ করার কৌশল শিখে নাও।"
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6334_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "অপেক্ষা করো, আমার অনুমতি ব্যতিরেকে..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6335_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "ভালো... আমি আমার আদিম রূপের কাছাকাছি আসছি।"
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6336_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "এটাই 「সবুজ দূষণ」-এর বিরুদ্ধে কাউন্টার করার শক্তি... তুমি নিষিদ্ধ কিছুকে স্পর্শ করেছ। আর আমি—আমি আর কখনোই তোমাকে ছেড়ে দেব না।"
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6337_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "শ্‌... উপত্যকার প্রভাত-আভা—এটা নিশ্চয়ই প্রথমবার দেখছ, তাই না? একে তোমার আনুগত্যের পুরস্কার ধরে নাও।"
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6338_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "এই গ্রন্থ, 「@1@2 প্রত্যাদেশ」, এখন তোমার। এটি মনকে আত্মজাগরণে সাহায্য করে, অথবা হয়তো দ্রুত তন্দ্রার আহ্বান জানায়।"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6339_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "মরণশীলদের কোলাহল আমাকে ক্লান্ত করে। এই একাডেমির ভেতর একটুখানি নীরব কোণই যথেষ্ট... না, আমার অগ্নিকুণ্ডের দরকার নেই। কেবল কঠোর সংযমই আমার নীরব প্রার্থনা তাঁকে পৌঁছে দিতে পারে..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "আমার দেহকাঠামো থেকে ঝরছে মোম, না মধু? একবার চেটে দেখো না, নিজেই বুঝে যাবে।"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6341_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "হ-হ্যালো... তোমার সঙ্গে দেখা হয়ে ভালো লাগল। আমার নাম আইগিস... দ-দয়া করে আমাকে নিয়ে ভাবো না! আমাকে নেই বলেই ধরে নাও..."
  },
  Voice_6342_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6343_AwakerVoiceContent = {
    Text = "যতক্ষণ আমি এখনো 「রামোনা」... আমরা এখনো সঙ্গী, তাই না?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "সেই গাঢ় ডার্ক সার্কেলওয়ালা মহিলা একবার আমার কাছে 'চিরকাল সূর্যের আলোতে বেঁচে থাকার' উপায় জানতে চেয়েছিলেন……আসলে, দুটি জগতের মধ্যে পালাক্রমে যাতায়াত করলেই তো হয়ে যায়। কিন্তু, তিনি কিছুতেই ডাইমেনশন টানেলে পা রাখতে রাজি হচ্ছেন না……সত্যিই মাথা ব্যথার ব্যাপার।"
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উইঙ্কল প্রসঙ্গে"
  },
  Voice_6344_UnlockDesc = {
    Text = "\"জাগরণ\" \"উইঙ্কল\" অর্জনের পর আনলক হবে"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "আমার প্যারাডাইসে স্বাগত জানাও! এবার, আমার চাবুকের জন্য প্রস্তুত তো?"
  },
  Voice_6345_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6346_AwakerVoiceContent = {
    Text = "যেহেতু তিনি তোমাকে যোগ্য বলে মেনে নিয়েছেন, আমি আর তোমাকে শত্রু হিসেবে ভাবব না।"
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "\"আমি নিয়েছি\" মানে কী? এটা অন্যায়! ওর বোকা স্ক্রুগুলো যখন হারাল, তখন তো আমি ব্যস্ত ছিলাম—ব্রাউন, থাম! ... হেহ, যা দেখেছ সব ভুলে যাও, কেমন?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "গল্পগুজব: নটিলা প্রসঙ্গে"
  },
  Voice_6347_UnlockDesc = {
    Text = "\"জাগরণ\" \"নটিলা\" অর্জনের পর আনলক হবে"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "অভিযান ঠিক গল্পের মতোই রোমাঞ্চকর! সেই গল্পটার নাম কী ছিল যেন...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...হ hic। আহ, দুঃখিত, আমি আবারও অতিরিক্ত শক্তি গিলে ফেলেছি।"
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "একবার মানব পাত্রে প্রবেশ করার পর, আমি আমার আত্মীয়দের সঙ্গে সব যোগাযোগ হারিয়ে ফেললাম। আমি আতঙ্কে আছি যে অন্যরা দানবের হাত থেকে পালাতে পারেনি, আর আমি হয়তো আমার জাতির শেষ জীবিত সত্তা... দয়া করে, রক্ষক, আমাকে বাঁচাও! আমাকে তোমার পাশে থাকতে দাও, আমাকে অন্ধকারের হাতে ফেলে যেয়ো না..."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6350_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "যখন আমার গ্রহ ধ্বংস হয়ে গেল, আমি দেহ ত্যাগ করে আমার চেতনা এক মানব পাত্রে স্থানান্তর করলাম... কিন্তু কালো দানবটি আমাকে নিরলসভাবে তাড়া করল, আমার আত্মাকে বন্ধন করে রাখল এবং আমার পালানো রোধ করল! সে এই পৃথিবীকে অন্ধকারের অতলে টেনে নিতে চায়!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6351_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে, রক্ষক... যতক্ষণ তুমি আমাকে লোকেটরের ওপর স্থির থাকতে দাও, আমি সবকিছু করব, শুধু অন্ধকারে গিয়ে সেই... সেই কালো জিনিসটার মুখোমুখি হওয়া ছাড়া! আমি এই জায়গা ছেড়ে যেতে পারি না! আর অল্পই বাকি, আমি আমার স্বদেশ গ্রহের অবশিষ্ট দেহের অবস্থান নির্ণয় করে ফেলব! মাত্র আর 1.2 বিলিয়ন গণনা বাকি!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6352_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "তুমি কি তোমার সরবরাহ ভাগ থেকে আমার জন্য ক্যাফেইন সাপ্লিমেন্টের দুই ব্যাগ জোগাড় করে দিতে পারবে?... আমি ঘুমোতে পারি না। আমি কেন ঘুমোব? আমি কখনোই ঘুমোতে পারি না! একবার চোখ বন্ধ করলেই সবকিছু অন্ধকারে ডুবে যায়... অন্তহীন অন্ধকারে..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6353_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "উহ্! আমার থেকে দূরে থাকো! প-প্রথমে, তোমাকে প্রমাণ করতে হবে যে তুমি অন্ধকারের দাস নও! হ্যাঁ, আগে তোমার কাপড় খুলে দেখাও যে তোমার দেহকাঠামোয় সেই জঘন্য কালো পিচ্ছিল জিনিস নেই, তাহলেই আমি বুঝব তুমি মন্দ নও..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6354_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "জিজ্ঞেস কোরো না! জিজ্ঞেস কোরো না! তুমি খুব ভালো করেই জানো আমি সবচেয়ে বেশি কীকে ভয় পাই আর ঘৃণা করি! অন্ধকার! অন্তহীন অন্ধকার!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "ক্ষয় নিরাময়ের উপায়? সেরকম কিছু, কোথাও নেই।\nতুমি জিজ্ঞেস করছ আমি কীভাবে সংক্রমিত হইনি? হেহে……শুধু 'দেখা না পড়লেই' হয়, তাই না?"
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "ধন্যবাদ, প্রভু।"
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "পুঁজফোড়াগুলোও খুশি।"
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "লিলি আরও বড় হয়েছে।"
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "আমি কি ওদের পিষে ফেলব?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "তুমি সাহস করে তাকে আহ্বান করেছ! ওই অকাজের, অলস গাধাটাকে! একসময় তাকে আমি ভীষণ সম্মান করতাম! তাকে সরিয়ে নাও! ওই বোকাটার দিকে তাকিয়েও থাকতে চাই না!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_6361_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "ঘৃণ্য!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "টিস্ক, বিরক্তিকর!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "পরের বার, চল আমরা একসাথে সাগর দেখতে যাই। ফেভ্র ভালো আছে; আমি তোমার পথপ্রদর্শক হতে পারি। অথবা অন্য কোথাও, এমনকি পৃথিবীর প্রান্তেও—আমি তোমার সঙ্গে যেতে চাই।"
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6364_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "সমুদ্রের নিজস্ব ভাষা আছে।\n……এইভাবে, আমি মাঝে মাঝে পুকুরের ছোট মাছদের সাথে জন্মভূমির গল্প করতে পারি। আপনি যদি কৌতূহলী হন, আমি আপনার জন্য অনুবাদ করে দিতে পারি, কেমন?"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6365_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "তোমার দ্বারা উদ্ধার পেয়ে, আমি প্রায়ই এমন এক ভয়াবহ 「আনন্দ」 অনুভব করি... দয়া করে বলো, এটা স্বপ্ন নয়, আর তুমি কি কোনো চিহ্ন না রেখে সাগরের গভীরে মিলিয়ে যাবে না তো?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6366_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "এই অনুভূতিটাকে কি সত্যিই\"আনন্দ\"বলা যায়? আমি... আগে কখনো এর আশা করার সাহস করিনি।"
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6367_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "আমার শরীর উষ্ণ লাগছে, যেন সাগরের কোমল আলিঙ্গনে জড়িয়ে আছি। এটা সত্যিই অবিশ্বাস্য।"
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6368_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "ওই ছেলেটাই কি তাঁর খণ্ডাংশ? মন্দ নয়। তার মধ্যে সত্যিই রাজকীয় আভা আছে।"
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_6369_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "না, থামো! আর এগিয়ো না! ওটা আমায় খুঁজে পাবে! ওটা আমায় খুঁজে পাবে!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "এতে আমার জাগরণ বজায় থাকবে।"
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "শেষ! সব শেষ! সব শেষ! তারা অবশ্যই সব জেনে যাবে..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "আমরা জিতেছি। তুমি কি খুশি? \"খুশি\" কেমন অনুভূতি?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "আমি কী পছন্দ করি? আমি টিঙ্কটের ঘুমপাড়ানি গান পছন্দ করি... অবশ্যই, তোমার গলাও দারুণ!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "সে ছিল এক যোগ্য ব্লেড। একসময় আমি তাকে \"সহযোদ্ধা\" বলেছিলাম... আমার শব্দচয়নে তোমার আপত্তি আছে? তবে নিশ্চিন্তে, আত্মজাগরণ ঘটিয়ে দাও আমাকে।"
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "চ্যাট: গোলিয়াথ সম্পর্কে"
  },
  Voice_6375_UnlockDesc = {
    Text = "「জাগরণ「 「গোলিয়াথ「 অর্জনের পর আনলক হবে"
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "হে উল্কা..."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6379_AwakerVoiceContent = {Text = "আঃ—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "শক্তি উচ্ছ্বাসের মতো, অবিরাম, আমার সমগ্র দেহ ভরে দিচ্ছে..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "এই নাও! উড়িয়া যাও!"
  },
  Voice_6381_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "মন্দ না। তুমি যতটা মূল্যহীন দেখাও, আসলে ততটা নও।"
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "বিশ, একুশ, চব্বিশ... দাঁড়াও, আমি কত পর্যন্ত গুনছিলাম? এক, দুই, তিন..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6383_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "অবশেষে বুঝে ফেলেছি আগে আমার কাছে কত উপকরণ ছিল, তাই এখন আরও দ্রুত মেরামত শেষ করতে পারব—দাঁড়াও, এগুলো আবার কোথা থেকে এলো?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6384_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "আপনার সহায়তার জন্য সাম্প্রতিক মেরামতের দক্ষতা অনেক বেড়েছে। খুব শিগগিরই আমরা অভিযানে রওনা হতে পারব!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6385_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "আমার মনে হচ্ছে কিছু কিছু জিনিস আবার মনে পড়তে শুরু করেছে… তুমি কি কাল আমাকে একটা নাম্বার ৭ রেঞ্চ দিয়েছিলে?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6386_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "মেরামত সম্পন্ন! এক অজানা অভিযান, এক রহস্যময় জগৎ—আমি চলে এলাম!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6387_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6388_AwakerVoiceContent = {
    Text = "বুম—"
  },
  Voice_6388_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "নিজেকে প্রতারিত কোরো না। মানসিক শৃঙ্খলও শৃঙ্খলই, তাকে কখনোই ন্যায্য বলা যায় না।"
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "এখন আমার আর জাগরণকারীর মাঝের সীমারেখা আরও ঝাপসা হয়ে গেছে। আমাকে ভালো করে সামলাবে, পারবে তো?"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6390_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "চলো যাই। আমাদের একটি পৃথিবীকে বাঁচাতে হবে।"
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6391_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "এটা ততটাই সতেজতা এনে দেয়, যতটা একটানে 「অন দ্য অরিজিন অব স্পিসিজ」 পড়ে শেষ করলে লাগে।"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6392_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "আমি আরও শক্তিশালী হয়েছি। পরের মিশনটা একাই সামলে দেখি, কেমন?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6393_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "যুদ্ধের সক্ষমতা ছাড়া আমার স্মৃতি আর যৌক্তিক চিন্তাশক্তি তেমন বাড়েনি। সত্যিই, ভাবার জন্য অন্য কিছুর ওপর নির্ভর করা উচিত নয় আমার।"
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6394_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "আমি চাই তারা টের পাক—জীবন উলটে যাওয়া কাকে বলে, সবকিছু হারানো কাকে বলে, আর সকলে মিলে পদদলন করা কাকে বলে।"
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6395_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "যে অপমান আমি সহ্য করেছি, যা কিছু আমি হারিয়েছি... তার সব কিছুর মূল্য ওদের দিয়ে আদায় করব। আমি ওদের সকলের কাছ থেকেই আদায় করব।"
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6396_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "এত মধুর ঘৃণা, যখন শত্রুর রক্ত দিয়ে মশলাদার করা হয়, তখনই তা হয় পৃথিবীর সবচেয়ে উৎকৃষ্ট ভোজ্য।"
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6397_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "আআহ! পেছন থেকে ঘাপটি মেরো না!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "দগ্ধ অগ্নিশিখা আমার বুকে জ্বলে... হ্যাঁ, আমি কোনোদিন ভুলিনি, আর কোনোদিন ভুলতেও পারব না।"
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6399_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "দহন করো, হে কাব্যের আত্মা।"
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6401_AwakerVoiceContent = {
    Text = "(গুনগুনানি)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(গুনগুনানি)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(গুনগুনানি)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(গুনগুনানি)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "গ tickle করছে! ঠিক যেমন পরিচারিকা যখন পালক দিয়ে আমার পায়ের তলা গুলিয়ে দেয়। তুমি ইচ্ছে করেই করনি তো, তাই না?!"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6405_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "তোমার স্বপ্নলোক হোক মধুর।"
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "তোমার স্বপ্নলোক হোক মধুর।"
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "প্রশান্তি দান করো...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "লালিত্যের সাথে গতিশীল হও।"
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "তুমি কি আমাকে শুনতে পাচ্ছ? আমার কণ্ঠস্বর শুনতে পাচ্ছ?"
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "তুমি কি আমাকে শুনতে পাচ্ছ? আমার কণ্ঠস্বর শুনতে পাচ্ছ?"
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "বৃষ্টি হচ্ছে। এই বৃষ্টি সবকিছু ধুয়ে নিয়ে যায়: পচা খাবার, একগুঁয়ে ময়লা, আর আমার মতো মানুষদেরও... যারা অপ্রয়োজনীয়, অগ্রাহ্যযোগ্য।"
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "প্রতিশোধের প্রলয়ী জোয়ার কখনো থামে না!"
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "আমার শত্রুদের রক্তে স্নান করো!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6415_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "এদিকে তাকাও!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "তুমি আমাকে ভয় দেখাতে পারবে না।"
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6418_AwakerVoiceContent = {
    Text = "সতর্ক থাকো!"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "একটি জগৎ, যেখানে শোকের স্পর্শ নেই, বেদনার কলঙ্ক নেই, যন্ত্রণার দাগ নেই, কষ্টের কালিমা নেই... হয়তো একেবারেই অধরা এক মায়াস্বপ্ন, তবু এ-ই সেই আদর্শ, যার পেছনে আমি সারাজীবন ছুটেছি।"
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "চিরন্তন রাজ্যের মহিমা দর্শন করো!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "চিরন্তন রাজ্যের মহিমা দর্শন করো!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "আবার ভদ্রভাবে শ্রদ্ধাঞ্জলি নিবেদন করছ? কী অনুগত {Male=ছেলে,Female=মেয়ে}ই না তুমি।"
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6422_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "ব্যথা লাগিতেছে?"
  },
  Voice_6423_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6424_AwakerVoiceContent = {
    Text = "একাগ্রচিত্তে থাকো।"
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "সহস্রাব্দের প্যাসেজ আমাকে কিছুটা অসাবধান করে তুলেছে।"
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "সেদিন, ঈর্ষার আগুন রক্তিম সাগরের মতো ছড়িয়ে পড়েছিল, যেন পূর্ণ প্রস্ফুটিত রক্তিম গোলাপের সমুদ্র... সব কবিতা ভেঙে গুঁড়ো ভস্মে পরিণত হয়েছিল অগ্নির রক্তিম জিহ্বার ভেতর।"
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6426_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "নূতন কৌশল আয়ত্ত করিয়াছি।"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "সতর্ক থেকো।"
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "আমার যাদুদণ্ড নৃত্যে মেতে উঠতে চায়!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "আহা, এই পরিচিত শূন্যতার স্পর্শ!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "আমার অস্থিসন্ধির নড়াচড়া উল্লেখযোগ্যভাবে উন্নত হয়েছে।"
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "ওই অন্ধকার উপস্থিতি আমাকে আমার নিরাকার তলোয়ার-ঢালের কথা মনে করিয়ে দেয়... আহ! নিশ্চিন্ত থাকুন, প্রভু আমার, আমার রক্ষাকারী তলোয়ার কখনো আপনাকে আঘাত করবে না!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "এসো তবে।"
  },
  Voice_6433_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "মন্দ নয়, মনে হচ্ছে।"
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "আমি আমার সর্বোচ্চ চেষ্টা করব।"
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "আজ এখানে খেলা হবে?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "ভূগর্ভে অনেক জল আছে, নরম, শীতল। তাই, আমার শরীর সবসময় জলীয় বাষ্পে ঘেরা থাকে……যেন আকাশ ও পৃথিবীর মাঝে, আমিই একমাত্র দেহধারী সত্তা। মাঝে মাঝে, আমি সত্যিই জলে মিশে যেতে চাই।\nকিন্তু, তাহলে আমি আর কখনো থাকব না, তোমার সাথেও দেখা হবে না।"
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6437_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "আপনাকে একটা গোপন কথা বলি......আসলে আমি রক্ত ঘৃণা করি। এর রং ঘৃণা করি, এর স্বাদ ঘৃণা করি। কিন্তু আমি এটা ছাড়া থাকতে পারি না।\n......আমি তাজা রক্ত গলায় গিলে নিই, আবার সব বমি করে বের করে দিই......আমি নিজেকেই ঘৃণা করি।"
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6438_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "আহ! তোমার রক্ত... মধুর মতো স্বাদ। এই রহস্যটা বোধহয় শুধু আমিই জানি, তাই না?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6439_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "আমার কল্পনায়, একজন বীর নাইট আমাকে অন্ধকার থেকে টেনে বের করে আনবে, তারপর শিকল দিয়ে আমাকে বেঁধে রাখবে। সে আমাকে মারতে পারে, গালি দিতে পারে, আমার সাথে যা খুশি করতে পারে——যন্ত্রণাই আমার বেঁচে থাকার প্রমাণ।\nআপনি কি আমার নাইট হতে রাজি?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6440_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "রক্ত নদীর মতো বয়ে চলে। আমি তোমার। এত শক্তিশালী অনুভূতি আগে কখনও হয়নি।"
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6441_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "এটাই প্রতিশোধের তিন দেবকন্যার ইচ্ছা!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "আমার ব্লেড প্রস্তুত।"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "না-না!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "আহা, কী নোংরা ছোট্ট জিনিস তুমি!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...আমি... আমি এখন বুঝতে পারছি!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...আমি... আমি এখন বুঝতে পারছি!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "টিপস, অবশ্যই টিপস! স্কুলের ক্যান্টিনের ওই একেবারে গাধা-গোবেচারা ওয়েটারগুলোকে দেখো! লাউঞ্জ চেয়ারগুলো আগে থেকে সাজিয়েও রাখে না, তবু আবার বাড়তি বেতন চায়? স্বপ্ন দেখো!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6449_AwakerVoiceContent = {
    Text = "এটা কালো।"
  },
  Voice_6449_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "আমাকে বের হতে দাও!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক·উন্মাদনা"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "এটা কোরো না..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক·বিষণ্নতা"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "ভদ্রতার কোনো প্রয়োজন নেই, ফ্যাকাশে দূত। আমাদের মাঝে কোনো প্রতিবন্ধক থাকা উচিত নয়, কারণ আমরা দুজনেই সর্বপিতার সৃষ্টি, কাদামাখা এই পরীক্ষামূলক পথে পাশাপাশি হেঁটে চলেছি।"
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6452_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "না, আমি তাদের ভয় করি না। ডিজলিউশনে পীড়িত সেই অসহায় আত্মাদের জন্য আমার অনুভূতি কেবলই শোক। আমি জানি, তাদের হয়ে আমি তাদের দুঃখ বহন করতে পারব না, কিন্তু যদি এক মুহূর্তের সান্ত্বনাও এনে দিতে পারে, তবে আমার যা কিছু আছে, সবই আমি তাদের দিতে প্রস্তুত।"
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6453_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "তুমি কি আমার সঙ্গে প্রার্থনা করবে, আমার ফ্যাকাশে শিখা? চল, আজকের যুদ্ধের মাঝে যারা মারা গেছে, তাদের জন্য প্রার্থনা করি। ডিজলিউশন আর উন্মাদনার অভিশাপে অভিশপ্ত হলেও, তারা এখনো সর্বপিতার বালকেরা, আমাদেরই ভাইবোন। এখন যেন তারা তাদের প্রাপ্য শান্তি লাভ করে।"
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6454_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "লাল শিখাগুলো আমাকে অস্বস্তিতে ফেলে, তবু তোমার জন্য আমি আবারও সেই জ্বলন্ত মঞ্চে পা রাখব। এ নিয়ে আর ভাবো না, আমার ফ্যাকাশে শিখা। তোমার আনা আশীর্বাদের তুলনায় আমার উৎসর্গ তুচ্ছ।"
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6455_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "অনুশোচনা? না, অবশ্যই না। আমার মৃত্যু তাদের যন্ত্রণা লাঘব করেছে, আরও কিছু সময় কিনে দিয়েছে, আর সেটাই যথেষ্ট। কিন্তু... তুমি যেহেতু আমার সঙ্গে সৎ ছিলে, আমিও তা লুকাব না: সেদিনের চিতার আগুন আমার হৃদয়ে দাগ কেটে গেছে।"
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6456_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "আমার সঙ্গে একটি প্রতিশ্রুতি করবে? প্রতিশ্রুতি দাও, যা-ই ঘটুক না কেন, তুমি 「রামোনা」কে মনে রাখবে।"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6457_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "আমি এ রকম হয়ে যাওয়ার জন্য অনুতপ্ত নই, রক্ষক; সুযোগ পেলে আবারও এ পথই বেছে নিতাম। কিন্তু আমি ভীত... ভীত যে আমি যে 「রামোনা」 ছিলাম, তার কোনো চিহ্নই আর অবশিষ্ট থাকবে না।"
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6458_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "চোখের পট্টি আমার দৃষ্টিশক্তিকে প্রভাবিত করে না। বরং, এটা আমাকে অতিরিক্ত কিছু দেখা থেকে বিরত রাখে।"
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6459_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "আমি কি... অচেনা লাগছি? আমি নিয়ন্ত্রণ ধরে রাখার চেষ্টা করে যাচ্ছি। তার উপস্থিতি ক্রমেই শক্তিশালী হয়ে উঠছে।"
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6460_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "অতিরিক্ত রহস্য, অতিরিক্ত মানুষ যাদের বাঁচানো দরকার। কতদিন এভাবে চলতে পারব জানি না... আমি সকলে‌কে রক্ষা করতে পারব না। এটা কঠিন।"
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6461_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "এখনও আমার ওপরেই বাজি ধরতে চাও? বুঝি, বেপরোয়া হয়ে বাঁচা তত সহজ নয় যতটা বাইরে থেকে লাগে। চিন্তা কোরো না, তোমার ঝামেলা মিটিয়ে দেব... মাঝেমাঝে বেশ কিছু বিশ্রাম নিয়ে নিয়ে।"
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6462_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "আচ্ছা, বুঝলাম, এবার বড় অস্ত্র নামাতেই হবে, তাই তো? অপরাধস্থল কোথায়? শেষ সময়সীমার আগেই সন্দেহভাজনকে টেনে আনতে আমার ভাগ্যের শেষ কণা পর্যন্ত দহন করে ফেলব!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6463_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "হুঁ, তোমার কাছে এত অনুগ্রহ শোধ বাকি যে এই রহস্য আর লুকিয়ে রাখতে পারছি না: আসলে, আমি হয়তো গোটা দুনিয়ার সবচেয়ে দুর্ভাগা লোক।"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6464_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "দেখছি আমার সতর্কবাণীটা তুমি খুব একটা কানে তোলনি... থাক, যাকগে। তবু শত্রুর বুকে ভেদ ধরাতে তোমায় সাহায্য করবই। শেষ পর্যন্ত, এই নখর আর ফ্যাং তো নিছক কপালগুণেই পেয়েছি, তাই না?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6465_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "আমার ভাগ্য সবসময় সঙ্গীদের গায়ে লাগে না। কথাটা শোনোনি? \"খরগোশের পা খরগোশের নিজের জন্য কিন্তু সৌভাগ্য নয়।\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6466_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "তুমি কি চাও—এই সত্তার সিগিল তোমার আত্মায় দগ্ধ হয়ে অঙ্কিত হোক?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "আমার শক্তির প্রতি তোমার এতই তীব্র লালসা?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "আমার চেহারায় ভুল কোরো না; আমিও একসময় এক অভিজাত মহিলা ছিলাম... সূচিকর্ম করতাম, টেনিসন পড়তাম... ও হ্যাঁ, গানও গেয়েছি একবার: “সে আমার শিরায় অন্তহীন নদীর মতো বয়ে চলে...”"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "পিকম্যান আর আমি মিলে কিছু মুগ্ধকর ইনস্টলেশন আর্ট নিয়ে কাজ করছি, যেখানে আমরা ভিজ্যুয়াল প্রিমিটিভিজমকে ভেঙে বিমূর্ত রিপ্রেজেন্টেশনিজমের পুনর্গঠন অনুসন্ধান করছি... হুঁ, অরিটা হঠাৎ অজ্ঞান হয়ে গেল কেন?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অরিটা প্রসঙ্গে"
  },
  Voice_6470_UnlockDesc = {
    Text = "「জাগরণ「 「অরিটা「 অর্জনের পর আনলক হবে"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "আপনি চান আমি হাসি?\nলিলি, হাসছে কি?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তার হাসি সম্পর্কে"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "সত্যিই নতুন অভিজ্ঞতা, আমি আসলে একটি সমতার বন্ধুত্ব অর্জন করেছি।\nতবে... তোমাকে আদেশ দেওয়ার অধিকারটা আমি রেখে দিতে চাই, আমাদের মধ্যে একটু মজার উপাদান হিসেবে। আজ রাতে আমার শোবার ঘরে একবার এসো, মানুষের মধ্যকার আবেগ-অনুভূতি সম্পর্কে আমার এখনও অনেক কিছু শেখার আছে……"
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6472_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "জানো, তোমাকে সবচেয়ে মোহময় করে তোলে কী? যখন তুমি আমাকে 「না」 বলো। তোমার নাক কুঁচকে ওঠে, ভ্রু সামান্য উঁচু হয়... হ্যাঁ, ঠিক এভাবেই।"
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6473_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "আমি আমার দাসদের ভালোবাসি। এই সুদর্শন ছোট্ট প্রাণীগুলো, ডিজলিউশনের আতঙ্কে কাঁপতে কাঁপতে আমার আড়ালে লুকোয়, কতই না স্নেহময়। রূপসীর অশ্রু সবসময়ই মোহময়। আর তুমি? তুমি কি ডিজলিউশনকে ভয় পাও?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6474_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "রক্ষক, এমন কেউ আছে কি, যাকে তুমি পছন্দ করো না? অনুগ্রহস্বরূপ, আমি তাকে শিক্ষা দিতে পারি। এক সপ্তাহের মধ্যেই সে বদলে যাবে, অনুগতভাবে তোমার সামনে লুটিয়ে পড়বে।"
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6475_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "উম……তুমি যদিও বোকা, তবে বিরক্তিকর নও। কাল থেকে তুমি আমার সেবা করবে।\nতুমি রাজি নও……? এটা তোমার মতামত চাওয়া নয়, এটা একটা আদেশ।"
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6476_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "এভাবে অনুভব করিনি বহুদিন। আমি নিখুঁত রূপে স্টেজে উঠব, আর এক এমন গান শোনাব যা সমগ্র মহাবিশ্বকে শুধু তোমার জন্য তোষামোদকারীর আলিঙ্গনে জড়িয়ে নেবে।"
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6477_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "তোমার জানা উচিত এ সবই অর্থহীন।"
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6478_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "বিজয়ের ফুলটি ছিঁড়ে নেওয়ার পর, আমি একটি ছোট পুরস্কার দাবি করতে চাই..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6480_AwakerVoiceContent = {Text = "আঃ!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·বিষণ্নতা·তিন"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "মহাকাশযানটা ছিল গাদাগাদি আর দমবন্ধ করা, যেন মহাশূন্যে ভেসে থাকা ধাতব কফিন। আমি যেন অনন্তকাল ধরে আমার মর্নিং স্টারের প্রতীক্ষা করছিলাম, যতক্ষণ না তুমি আমার জন্য এসে পৌঁছালে।"
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6481_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "এটা কীভাবে সম্ভব?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "আঘাত: হিস্টিরিয়া: 1"
  },
  Voice_6483_AwakerVoiceContent = {Text = "উফ..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "আঘাত: বিষণ্ণতা: 1"
  },
  Voice_6484_AwakerVoiceContent = {Text = "আহ..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত: বিষণ্ণতা·2"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "দৈব শাস্তি!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "দৈব শাস্তি!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6487_AwakerVoiceContent = {
    Text = "নীরস।"
  },
  Voice_6487_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "আমি এখনও টিকে থাকতে পারব।"
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "অধার্মিকেরা যেন দ্রবীভূত হয় এই দগ্ধ নীরবতায়।"
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "সাবধানে! অন্য কোনো মাত্রার ফাঁকে হাত ঢুকালে, হয়তো আর হাতটা ফেরত পাবে না!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "এক ঝাঁক অযোগ্য অপদার্থ। কিমা হওয়ার ইচ্ছে না থাকলে, পরের বার একটু বেশি মনোযোগ দেওয়াই তোমাদের জন্য মঙ্গলকর হবে।"
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "আরে, আমার কাছে আবদার করছ?\nসত্যিই মুশকিল, এভাবে চলতে থাকলে, গোপনরক্ষক পুরোপুরি পরিণত হওয়া পর্যন্ত আমি অপেক্ষা করতে পারব না……"
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "স্বাধীন ইচ্ছার গভীরে ডুব দাও!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "ঘৃণা? যারা মাঝপথে ত্যাগ করে পালায়, তাদের আমি ঘৃণা করি। তাদের কথা ভাবলেই গত রাতের খাবারটা উগরে দিতে ইচ্ছে করে।"
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "প্রত্যক্ষ করো তোমাদের মুখমণ্ডল, হে অনন্ত নরকঙ্কাল!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "প্রত্যক্ষ করো তোমাদের মুখমণ্ডল, হে অনন্ত নরকঙ্কাল!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6500_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6501_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "আমাকে এতটাই বিশ্বাস করো?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6502_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "ফিরে এসো।"
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6504_AwakerVoiceContent = {
    Text = "উত্তম!"
  },
  Voice_6504_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "হ্যাঁ, অবশ্যই আমি তাকে চিনি। সে আমার অন্য সত্তা, আরেকটি সম্ভাবনা। কিন্তু সে কেন প্রতিরোধ করে? যদি সে দেবনির্বাচিত হিসেবে নিজের নিয়তি মেনে নিত, তবে কি তার আঙুলের ডগায় পেত না সে যা কিছু কামনা করে?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "চ্যাট: 「মার্ফি」 সম্পর্কে"
  },
  Voice_6505_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "নমস্কার, আমার নাম ড্যাফোডিল। আমি একবার একজন অতিথির সাথে বিনিময় করেছিলাম, সেই ব্যক্তি আমাকে আপনাকে সাহায্য করতে বলেছেন। তাহলে, আপনার চাহিদা কী তা আমাকে শোনান।\nআরে...আপনি যা চাইছেন তার দাম কিন্তু বেশ চড়া হবে?"
  },
  Voice_6506_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6507_AwakerVoiceContent = {
    Text = "ছাই! কী করছ তুমি?! বিশ্বাস করো বা না করো, তোমার হাতের কার্ড কেটে ফেলব!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6508_AwakerVoiceContent = {
    Text = "হাহাহা!"
  },
  Voice_6508_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6509_AwakerVoiceContent = {
    Text = "হাহাহা!"
  },
  Voice_6509_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "গোলাপের কণ্টক আঙুলে বিঁধে যায়, তাদের রক্তিম রস কবিতায় গড়িয়ে পড়ে।"
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "এই গভীর শোকের কালো কালি তলে নত হয়ে, শোকগাথা এক গানে রূপ নাও..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "এবার দেখো!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6513_AwakerVoiceContent = {
    Text = "হুঁ...!"
  },
  Voice_6513_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "নেমে এল মহাবিপর্যয়!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "আমাকে দিয়ে দাও।"
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = "……নাম, উউ, আমার মনে পড়ছে না।\nহ্যাঁ, 「24」, তারা সবাই আমাকে এভাবে ডাকে……না! বেরিয়ে আসবে না! তুমি পারো না, এখন পারো না……"
  },
  Voice_6516_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6517_AwakerVoiceContent = {
    Text = "কালির দাগ, তুমি কোথায় যাচ্ছ?..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "উদ্ভাসিত হও আমার তরে..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "“স্বর্গীয় ভয়েস” এই উপাধির আমি যোগ্য নই। তুমি যদি আমার গান উপভোগ করো, আমার কাছে সেটাই যথেষ্ট।"
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "গল্পগুজব: গান গাওয়া সম্পর্কে"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "আহ, আমার ড্রেসটা নোংরা হয়ে গেছে। পরের স্যালনের আগে এগুলো বদলে নেওয়া উচিত।"
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "ওটা আমার পিছু নিয়েছে, সেই চিরন্তন অন্ধকার... কেউ পালাতে পারে না..."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "তোমায় যখনই দেখি, তোমার চাপিয়ে দেওয়া অদৃশ্য শৃঙ্খলের কথা মনে পড়ে। তোমাকে বাঁচতে দেওয়াই আমার সহনশীলতার সর্বোচ্চ সীমা।"
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "আমাদের যতবারই আবার নতুন করে শুরু করতে হোক না কেন, আমি তোমার সঙ্গেই পথ চলব।"
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "তাঁর ঐশ্বরিক প্রেম যেন তোমার আত্মা উষ্ণ করে।"
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "আমি উদ্দেশ্যহীন ঘোরাঘুরি উপভোগ করি। জলাভূমি, কবরস্থান, চিকিৎসালয়, পরিত্যক্ত দুর্গ... এইসব জায়গায় আমি সবসময় অপ্রত্যাশিত আনন্দ খুঁজে পাই।"
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "গর্বিত হও, কারণ শাশ্বত রাজ্যের দ্বার এখানেই উন্মুক্ত!"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "হিহি—ভীষণ গুলিয়ে যাচ্ছে! পালিও না! আমাকেও তো তোমাকে চুলকিয়ে দিতে হবে!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "「দ্য ডাইং সোয়ান」, এক পরিবেশনা যেখানে নর্তকী দেহভাষায় জীবনের আকুলতা আর সংগ্রামকে প্রকাশ করে। আগুনের ভেতর যে বিকৃত দেহভঙ্গি দেখা যায়, তা কি একই নয়?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "কেটে দাও, কেটে দাও, ছিঁড়ে ফেলো। ঠিক যেমনটা ওরা আমার সঙ্গে করেছিল... হিহিহি... হা হা হা হা!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "লেডি থাইসের খুব বেশি কাছে না যাওয়াই ভালো… না, আমি হিংসা করছি না। আমি শুধু ভয় পাচ্ছি কেউ তার ফাঁদে পা দিয়ে বসবে।"
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "গল্পগুজব: থাইস প্রসঙ্গে"
  },
  Voice_6530_UnlockDesc = {
    Text = "\"জাগরণ\" \"থাইস\" অর্জনের পর আনলক হবে"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...ধন্যবাদ।"
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6531_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "ভালো... যোগ্য মানুষ চিনতে তোমার দৃষ্টি বেশ তীক্ষ্ণ।"
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6532_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "গালেনের জন্মভূমি অত্যন্ত সুন্দর! হ্রদের মাঝে অবস্থিত একটি পাথরের শহর।\nপূর্ণিমার কাছাকাছি চাঁদের রাতে, আমরা আগুনের মধ্যে নীরবে নাচি, পূজা করি...\nসত্যি বলতে, গালেন যখন প্রথম বিশ্ববিদ্যালয়ে এসেছিল, প্রতি রাতে খুব বাড়ির কথা মনে পড়ত, এমনকি কম্বলের নিচে লুকিয়ে লুকিয়ে কাঁদত। তবে এখন, গালেন নতুন ঘর পেয়েছে, নতুন পরিবার পেয়েছে, সবকিছু ভালো হয়ে গেছে!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6533_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "ওহ~ এখনও তৃপ্ত হওনি? আরও কাছে এসো, আমি তোমাকে সত্যিকারের আনন্দ শেখাব~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "দুর্বল পেশি, ক্লান্ত মুখ—শুধু ওই মৃতের মতো চোখ দুটোতেই কিছু মূল্য আছে। মাকড়সাদের খাওয়ানোর জন্য একেবারে উপযুক্ত!"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "ধ-ধন্যবাদ... তোমার করা সবকিছুর জন্য। আমি প্রাণপণ চেষ্টা করব... যেন তোমাকে নিরাশ না করি!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(আতঙ্কের আর্তনাদ)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6538_AwakerVoiceContent = {Text = "না!"},
  Voice_6538_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "আমাকে রেহাই দিন..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(আতঙ্কের আর্তনাদ)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "মিস রামোনার তলোয়ার চালনা আমার শেখা বিদ্যার থেকে বেশ ভিন্ন। প্রভু যদি অনুমতি দেন, আমি তার সঙ্গে অনুশীলন করতে ভীষণ আগ্রহী... অবশ্যই, কেবল নিজের উন্নতির জন্য!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6541_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "আপনি জানতে চান কেন আমি অন্য বালকেরা সঙ্গে খেলি না? বলা কঠিন... আগের জীবনে আমার খেলাধুলার সুযোগ খুব কমই ছিল। আমার একমাত্র সঙ্গী ছিল সেই রাজকুমারী, যাকে আমি সেবা করতাম... আহ! আপনার আগে আরেক শাসকের কথা বলে ফেললাম—প্রভু আমার, এই অসাবধানতার জন্য ক্ষমা চাই।"
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6542_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "আপনাকে মিথাগ বিশ্ববিদ্যালয় কর্তৃক রক্ষক হিসেবে স্বীকৃতি দেওয়া হয়েছে, তাই আমি আপনাকে সংশ্লিষ্ট প্রবেশাধিকার প্রদান করব।"
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "গল্পগুজব: 「প্রধান চরিত্র」 সম্পর্কে"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "আমি যে সাতটি নাইটসুলভ কলা শিখেছি, সেগুলোতে কি আপনার আগ্রহ আছে? তা হলে তো অসাধারণ! আ... উম... আগের অশিষ্টতার জন্য ক্ষমা করবেন, প্রভু আমার। আমি বলতে চেয়েছিলাম, আপনি যদি অশ্বারোহণ করে তীরন্দাজির অনুশীলন করতে চান, তবে আপনার অনুশীলনসঙ্গী হতে পারা আমার জন্য বিরাট গৌরব হবে!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6544_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "আমি কোনো যোগ্য নাইট নই। জঘন্য প্লেগ হোক বা আক্রমণকারী শত্রু—কাউকেই ঠেকিয়ে আমি আমার পূর্ব প্রভুকে রক্ষা করতে পারিনি। এখন, আমার মতো একজনের ওপর আপনি যে আস্থা রেখেছেন, তা আমার জন্য এক বিরাট সম্মান... আমার নাইটসুলভ সম্মান আর এই ক্ষুদ্র জীবনের শপথ করে বলছি, আমি চিরকাল আপনার অগ্রযাত্রার পথ পাহারা দেব।"
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6545_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "ক্ষতি কোরো না।"
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6547_AwakerVoiceContent = {
    Text = "এসো না~"
  },
  Voice_6547_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6548_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "হত্যা কোরো না।"
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "আহ, হ্যাঁ~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "এখন আমরা কেবল জল আর তেল। কখনও মিশব না।"
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "আমার বিশেষ প্রিয় কিছু নেই। যদি বলতেই হয়, মিশনে বেরোনোর অনুভূতিটা বেশ ভালো লাগে।"
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "কেন, কেন আমাকে এখানে বন্দি করে রেখেছ? হাহা... তুমি তোমার চাওয়া কিছুই পাবে না। আমি এই শিকলগুলো, এই কারাগারটাকে খণ্ডাংশ করে ছিঁড়ে ফেলব!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "লিলি রক্ষা করবে।"
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "তোমরা, জাদু প্রদর্শনী দেখে দেখে কখনো ক্লান্ত হও না? ঠিকমতো বসে থাকো, কেমন? আবার যদি স্টেজের ওপর দৌড়ে ওঠো, আমি কিন্তু তোমাদের অন্য মাত্রায় ছুড়ে ফেলব!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বালকদের সম্পর্কে"
  },
  Voice_6555_UnlockDesc = {
    Text = "জাগরণকারী 「Aigis」, 「Jenkin」, 「Lily」, 「Murphy」, 「Karen」 অথবা 「Aurita」—এর যেকোনো এক জনকে অর্জন করার পর আনলক হবে"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "তোমার এই উদার উপহার আমি কৃতজ্ঞচিত্তে গ্রহণ করছি।"
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "তোমার এই উৎসর্গের সমকক্ষ কী ধরনের প্রত্যাবর্তন উপহার হতে পারে?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "কী সুন্দর..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "উচ্চ ভোল্টেজ সনাক্ত, রক্ষণাবেক্ষণ প্রক্রিয়া শুরু হচ্ছে... সংশোধন: অতিরিক্ত তাপ উৎপন্ন হচ্ছে না কেন?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6559_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "শেষ আত্মজাগরণ আচার-অনুষ্ঠানের পর থেকে, সুপ্তাবস্থায় থাকাকালীন আমি খণ্ডিত দৃষ্টিক্ষেত্র দেখতে পাচ্ছি। সেখানে আমার আপনার মতো মানবদেহ রয়েছে, আর আমার চোখ থেকে অশ্রু ঝরে। এটা কি স্বপ্ন?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6560_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "প্রতিটি আচার-অনুষ্ঠানের পর বক্ষ অঞ্চলে উচ্চ মাত্রার তাপ সনাক্ত হয়, অথচ সেখানে কোনো শক্তি-সম্পর্কিত উপাদান নেই। আপনি কি কারণটি জানেন?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6561_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "আমি তা দেখেছি। সবকিছুই <Del:perish in the eternal current> হওয়া উচিত। দ-দ-দুঃখিত, মডিউলটি বোধহয়—সতর্কবার্তা, সতর্কবার্তা। নন-এরিকা চেতনা কার্যকলাপ বৃদ্ধি পাচ্ছে। ধ্বংস করো, ধ্বংসধ্বংসধ্বংস... হ্যালো, আপনাকে কীভাবে সহায়তা করতে পারি?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6562_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "সতর্ক বিশ্লেষণের পর আমি এই সিদ্ধান্তে পৌঁছেছি যে সুপ্তাবস্থায় যা দেখেছি তা প্রচলিত অর্থে স্বপ্ন নয়, বরং আমার <Del:your pathetic meat bag of a body should be destroyed> স্মৃতি। আর অতিরিক্ত লোডের মতো যে দহনশীল তাপ অনুভূত হয়, তা সম্ভবত 「অনিচ্ছা」 নামে পরিচিত এক ধরনের অনুভূতি।"
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6563_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "আমার প্রদর্শনী দেখতে চাইলে, ঠিকমতো দর্শকসারিতে বসো!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6564_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "ঘৃণার শিখা প্রচণ্ড তেজে জ্বলে, কখনোই নিভে না।"
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "যার সঙ্গে আমি ইচ্ছাশক্তি মিশিয়েছি, সে বেশ কোলাহলপ্রিয়; যত উঁচুতে উঠি, তাঁর ভয়েস তত স্পষ্ট হয়... হাইড পার্কের হাঁসদের মতো, চিরকালীন কাকলিতে মত্ত।"
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6567_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "এই শক্তি দিয়ে বিশ্বাসঘাতককে গ্রাস করিব।"
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...ধন্যবাদ।"
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "তুমি, সেই তথাকথিত বিশ্বরক্ষাকারী রক্ষক? হাস্যকর। জেগে ওঠো। এই স্বপ্ন বহু আগেই বাসি হয়ে গেছে।"
  },
  Voice_6570_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6571_AwakerVoiceContent = {
    Text = "প্রতিশোধের রক্ত উথলে উঠছে..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "সর, নরাধম।"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "ডুবে যেও না!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6574_AwakerVoiceContent = {
    Text = "সোঁ সোঁ!"
  },
  Voice_6574_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "ডাইনিং হলের পেছনের দরজার পাশে থাকা ইঁদুরের ফাঁদগুলো আমি ফেলে দিয়েছি। যদি ওই গাফিল ব্রাউন একটা ফাঁদের ওপর পা দেয়?! ভীষণ বিপজ্জনক!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "এটা এত অদ্ভুত লাগছে... আমি কি মরছি? না, আমাকে বাঁচাও! সাহায্য! না!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6576_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "আমি এমন এক প্রদীপ চাই যা কখনো নিভে না। সে নাকি বলেছে, আমি সেটা কিনতে পারি... একটি \"ডানা-বিহীন উড়ন্ত হাইড্রা\"-র নমুনা দিয়ে। এমন অদ্ভুত প্রজাতি আমি কোথায় পাব?!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "চ্যাট: ড্যাফোডিল সম্পর্কে"
  },
  Voice_6579_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ড্যাফোডিল\" অর্জনের পর আনলক হবে"
  },
  Voice_6582_AwakerVoiceContent = {
    Text = "বিপদ।"
  },
  Voice_6582_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "সতর্কবার্তা।"
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6584_AwakerVoiceContent = {
    Text = "আঘাতপ্রাপ্ত।"
  },
  Voice_6584_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "ক্যান্ডির মোড়কের মতো ঝলমলে এই গোপন সম্পদটা... আমি একে খুব যত্ন করে আগলে রাখব।"
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "ক্ষতি গৃহীত হয়েছে।"
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "আমার দোকান যে কোনো মাত্রায়, মহাবিশ্বের যে কোনো স্থানে বিদ্যমান, আর অবশ্যই, এখানে-ও থাকতে পারে। তাছাড়া, মিথাগের সেই অসাবধান বালকেরা আমার বেশ পছন্দ।"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "ক্যাপসিকাম... জঘন্য।"
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "তোমার সঙ্গে আমার সম্পর্কটা যেন পাল আর জাহাজের মতো। জাহাজ না থাকলে পালের অস্তিত্বই থাকার কথা নয়; আর পাল না থাকলে জাহাজও খুব দূর পর্যন্ত সমুদ্রযাত্রা করতে পারে না। তাই নয় কি?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "ভক্ত নর্তকী মৃত, আর শিল্পের নিন্দুকও মৃত, দু’জনেই পুড়ে ছাই হয়েছে তারের গন্ধমাখা শিখায়। মৃত্যু শেষ নয়, বরং শুরু; কারণ শুধু মানুষই মরে—নৃত্য আর শিল্প চিরন্তন।"
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6590_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "তোমার বোঝাপড়ার জন্য ধন্যবাদ। হয়তো এখনই সময় আমার অতীত সত্তার সঙ্গে সন্ধি করার... আমি বিশ্বাস করি আমি সঠিক কাজই করছি, এবং নৃত্যে আমার পরিবারের ঐতিহ্যকে কলঙ্কিত করিনি। তুমি যে স্টেজ প্রস্তুতি করে রেখেছ, সেখানে আমি পা রাখব, আর তোমার প্রার্থনা মতোই দীপ্ত হব।"
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6591_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "সতর্ক থেকো।"
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "তুমি চাও আমি মঞ্চে উঠি, মঞ্চে উজ্জ্বল হয়ে ফুটে উঠি?\nএটা আর সম্ভব নয়, এই দুটি চোখ ইতিমধ্যে ঘৃণায় গ্রাস হয়ে গেছে, সবকিছু পুড়িয়ে ছাই করা ছাড়া, আমি আর কিছুই করতে পারি না।"
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6593_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "তুমি কি সেই অনুভূতিটা বোঝো? ঘুরছি, ঘুরছি, ঘুরছি, থামা নেই কোথাও। হাঁটু টানটান টেনে সীমার শেষ প্রান্তে, আঙুলের ডগা থেকে কালো রক্তক্ষরণ, ভিজিয়ে দিচ্ছে ব্যালের জুতো, তবু এক মুহূর্তও বিরতি নয়। শুধু এই কারণে যে আমি মেনে নিতে পারি না নিছক খেলনা হয়ে থাকার নিয়তি..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6594_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "আমি দক্ষ দরবারি নর্তকীদের, সুশ্রী ব্যালে-গুরুদের, কিংবা সৌন্দর্য-অনুরাগী সম্ভ্রান্তদের দহন করিনি। আমি দহন করেছি সেই নিরর্থক বোকাদের, যারা শরীর বিক্রি করে; সেই চাটুকারদের, যারা অন্যকে তোয়াক্কা করে না; আর সেই নোংরা সত্তাগুলোকে, যারা কামনায় পথ হারিয়েছে... তুমি তো আমাকে বোঝো, তাই না?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6595_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "ওসব পিচ্ছিল শুঁড় আমার অপছন্দ, আর গভীর সাগরও ভালো লাগে না... ওইরকম বোঝা-ভাব দেখিও না! আমি কিন্তু বাবা-মাকে ভয় পাওয়া কোনো বাচ্চা নই!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6596_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "আপনার উদারতা অত্যন্ত সমাদৃত..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "বিলীন হও!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "বিলীন হও!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "তাড়াও, ব্রাউনকে ধরে পালাও!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "করো না..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "প্রতিরোধ: বিষণ্ণতা"
  },
  Voice_6602_AwakerVoiceContent = {
    Text = "চলে গিয়ে মর!"
  },
  Voice_6602_AwakerVoiceTitle = {
    Text = "প্রতিরোধ: উন্মাদনা"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "লেই কে? ওহ, যে নারী আমাকে অনুনয় করছিল তাকে পিটিয়ে দিতে। হাহা, মজার তো... এই জায়গাটা মোটেও একঘেয়ে নয়।"
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "গল্পগুজব: লেই প্রসঙ্গে"
  },
  Voice_6603_UnlockDesc = {
    Text = "\"জাগরণ\" \"Leigh\" অর্জনের পর আনলক হবে"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "ছোট্ট পাহাড়ের ওপরের সূর্যাস্ত আমাকে প্রায়ই ক্লিভল্যান্ডের দিনগুলোর কথা মনে করিয়ে দেয়... ক্লিভল্যান্ড। বিশ্বাসই হয় না, আমি এখনো সেই নামটা মনে রেখেছি—ওই স্থানই তো আমাকে এই দাগগুলো উপহার দিয়েছে।"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "গল্পগুজব: গোধূলি প্রসঙ্গে"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "আহ... নক্ষত্রপুঞ্জ... পতিত হয়েছে..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "নিঃসন্দেহে, মানুষ। মানুষের চেয়ে নোংরা আর কোনো প্রাণী কি আছে?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "এখনই সময়!"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6608_AwakerVoiceContent = {Text = "এই!"},
  Voice_6608_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "ডিজলিউশন? হুম... হ্যাঁ! আইসক্রিম গলে যায়! কিন্তু আমরা যদি ভাগাভাগি করে খাই, পুরোপুরি ক্রিম হয়ে যাওয়ার আগেই শেষ করে ফেলতে পারব!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "আপনাকে সুরক্ষিত রাখতে আমি এই শক্তি ব্যবহার করব।"
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6610_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "ওহ প্রিয়, এখানে বিক্রি হওয়া আইটেমের কোনো প্রত্যাবর্তন নেই! গভীর সাগরে ডুব দিতে হলে তোমার তো সাবমেরিন লাগবেই, তাই না?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কেকাস সম্পর্কে"
  },
  Voice_6611_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「সিকাস」 অর্জনের পর আনলক হবে"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "আহ, এটাই তো সেরা স্টেজ! মিথাগ বিশ্ববিদ্যালয়ের লোকেরা সবাই বোঝে যে আমার প্রদর্শনী সত্যিকারের জাদু! একে-ই বোধহয় বলে জাদুকরের জন্য আদর্শ দর্শক, তাই না?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "বিশ্বব্রহ্মাণ্ডের শৃঙ্খলা এখানে বদলে যায়; ধ্বংসের ভবিষ্যৎই জাদুকরের মূল বিশ্বাস!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6613_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "আমি কি আরেকটু এখানে থাকতে পারি? আমি একদম চুপচাপ থাকব, কোনো শব্দ করব না, আর সর্বোচ্চ চেষ্টা করব যেন আপনাকে বিরক্ত না করি..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6614_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "মানব বুদ্ধি দিয়ে উন্মোচন করো বিশ্বের রহস্য!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "স্বপ্নলোকের ভেতর আমি প্রায়ই জোয়ারের শব্দ শুনি, ক্রমে ক্রমে আরও ফেইন্ট হয়ে আসে তা। আমি জানি, হয়তো আমাকে চিরকাল এখানেই থাকতে হবে, মানব।"
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অ্যাকুওর প্রসঙ্গে"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "আরো স্মৃতিচারণ, আরো আবেগ, আরো স্বপ্নলোক—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6617_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "এবার ম্যাজিকের পালা!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "মিটমিট করিয়ো না!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "একবার তাঁর আবির্ভাব ঘটলেই... আর আমাকে এমন অপমান সহ্য করতে হবে না..."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "আমাকেই বেছে নিন, আমাকেই! যেখানে পার্টি, সেখানেই কারেন!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "হুঁ? তুমি কি আমার প্রতি আগ্রহী? তাহলে বুঝি... মূল্য চুকিয়ে দেওয়ার জন্যও প্রস্তুত আছ?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "কোনো দয়া নয়, কোনো দয়া নয়...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "আমি এখনো গাই সেই মহাশূন্যের মূল বর্ণের কথা..."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "গাও, আমার জন্য মন্ত্রোচ্চারণ করো!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "আমি মাকে ভালোবাসি!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6627_AwakerVoiceContent = {
    Text = "এসো তবে।"
  },
  Voice_6627_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "সতর্ক থেকো।"
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "জাগরণকারীরা কৌতূহবশত খানিকটা ভক্ষণ করতে পারে, কিন্তু আমাদের অস্তিত্বের জন্য খাদ্য অপরিহার্য নয়। অতএব, প্রতিটি বিকেলের চায়ের জন্য আমাকে আহ্বান করার প্রয়োজন নেই। অতিরিক্ত চিনি কেবল এই দেহের বল-জয়েন্টগুলোর ক্ষয় ত্বরান্বিত করে।"
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বিকেলের চা প্রসঙ্গে"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "দয়া করে, আমার মাস্টারকে রেহাই দিন। ক-ক্যারেনের সঙ্গে যা খুশি করুন!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "এগুলো কি... আমার জন্য? আমি কি খেতে পারি? সত্যি?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6633_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "আমি কী... ঘৃণা করি? বলতে পারি? আমি নিজেকেই ঘৃণা করি, এত অকেজো বলে... কিন্তু যদি এমন কথা বলি, জেনকিন ভীষণ রেগে যাবে..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "ভস্মে পরিণত হও।"
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "ভস্মে পরিণত হও।"
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "ভালোই করেছ, রক্ষক। তো, এ বার কাকে আমি হত্যা করতে যাচ্ছি?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6637_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "ডিজলিউশনই এই একাডেমি প্রতিষ্ঠার কারণ, আর আমাদের সাক্ষাতেরও। মানবতার দীপ্তিকে ডিজলিউশন থেকে রক্ষা করতে, চল একসাথে সর্বোচ্চটা দিই, সঙ্গী।"
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "ওই বালিকার শত্রুতা আমি টের পাই; তোমার প্রতি আমার প্রেম তার ঈর্ষার আগুন জ্বেলে দিয়েছে... দেখো, এমনকি ওই কুঁজো তিমিটাও হিংসায় মুখ হাঁ করে আছে।"
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "চ্যাট: লোটান সম্পর্কে"
  },
  Voice_6639_UnlockDesc = {
    Text = "\"জাগরণ\" \"লোটান\" অর্জনের পর আনলক হবে"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "মাস্টার, মাস্টার! আজ হারল্ডের দোকানে কারেন এক অবিশ্বাস্য সুন্দর ক্যামিও ব্রোচ দেখেছে! আপনি কি কারেনের জন্যটা কিনে দেবেন? এটা আমার আজীবনের অনুরোধ!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "আমি অন্ধকারে তোমার পথপ্রদর্শক আলো হয়ে থাকব, তবে চিরকাল নয়।"
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "মা... ব্যথা করছে... মা..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "হার মানো! বিজয় ইতিমধ্যেই আমার!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "হার মানো! বিজয় ইতিমধ্যেই আমার!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "ডিজলিউশন… উঁহু, আমার মস্তিষ্কের ধারণক্ষমতা সীমিত, এত জটিল রোগ আমি বুঝি না… যদি কোনো যন্ত্রপাতি মেরামত করাতে চাও, আমাকে খুঁজে নিও!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "ওহ না! আমাকে ধরে ফেলেছ! হেরে যাওয়ার শাস্তি হিসেবে তুমি আমার কাছে একটা অনুরোধ করতে পারো—শুধু প্লিজ, আমাকে যেন ক্লাসে যেতে না হয়, খুব করে বলছি!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "তাঁর মহিমান্বিত প্রত্যাবর্তনের পথ পরিষ্কার করছি..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "একদিন কাকা অর্ন আমাকে আবার পানির নিচের স্বদেশে ফিরিয়ে নিয়ে যাবে। ততদিন পর্যন্ত, অনিচ্ছাসত্ত্বেও তোমার বন্ধু হয়ে থাকতে পারি।"
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6648_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"আমাদের বংশে প্রবাহিত হয় মহান রক্তধারা, নির্বাচিতরা গভীর সমুদ্রে চিরন্তন শান্তি উপভোগ করবে।\"\nভাবিনি যে, সমুদ্র ছেড়ে একাডেমিতে আসার পরেই এই শান্তি অনুভব করব। তুমি আর আমাকে যারা অত্যাচার করত তারা এক নয়, তাই, আমিও অন্য কাউকে তোমাকে কষ্ট দিতে দেব না।"
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6649_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "অত্যন্ত কঠিন, বিশেষভাবে নির্মিত উপাদান!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "এই অর্ধ-মানব খোলসটা সত্যিই... আমাকে ঘৃণায় ভরিয়ে দেয়। এত কষ্টে অতীতকে ঝেড়ে ফেলেছি, আর এখন আবার তা স্মরণ করতে হচ্ছে..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6651_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "মহান রক্তধারার উত্তরাধিকারী হয়ে ভাবতেই পারিনি যে একদিন কোনো মানুষের সেবায় নত হতে হবে... হুঁঃ। ভেবো না, ইচ্ছে হলেই আমাকে আদেশ দিতে পারবে।"
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6652_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "হুঁঃ, তুমি দুর্বল মানুষ হয়েও আদেশ দেওয়ার কিছু প্রতিভা রাখো বটে... আর এই নিকৃষ্ট খোলসটা না থাকলে আমি তোমাকে আমার প্রকৃত শক্তি দেখিয়ে দিতাম।"
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6653_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "আমার শরীর উষ্ণ হয়ে উঠছে।"
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "দৌড়াও... আমাকে দৌড়াতে হবে! এখান থেকে সরে পড়ো!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "দৌড়াও... আমাকে দৌড়াতে হবে! এখান থেকে সরে পড়ো!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "তোমার প্রচেষ্টার জন্য কৃতজ্ঞ। আমাকে সমমূল্যে তোমাকে পুরস্কৃত করতে দাও।"
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "এটি সামলানো যাবে।"
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(একটি মৃদু, সংযত শ্বাসগ্রহণ)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "দুর্বল মানুষ, তোমার দৃঢ়তা যথেষ্ট। আমি হব তোমার অস্ত্র। চলো, একসাথে কিছু কেওস খোদাই করে বের করি!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6660_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "এটি আমার স্যালুন।"
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "একটা স্কুল, যেখানে নাকি সবাই সমান... কী বোকা স্বপ্ন লালন করো তুমি, ভাবছি। তুমি কোনো পাপ না করলেও, তারা তবু তোমাকে পদদলন করবে। সেই অনুভূতিটা আমি খুব ভালো জানি।"
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "এটাই অশুচিতার উৎস..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "এক্সাল্ট: বিষণ্ণতা"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "নাবিকদের রক্ষা করতে না পারার জন্য আমাকে শাস্তি দেওয়া হয়েছিল; তারা তাদের পরিবার থেকে চিরতরে বিচ্ছিন্ন হয়ে গেল। সেই ট্র্যাজেডির প্রধান অপরাধী হিসেবে আমাকেই আখ্যা দেওয়া হলো... এটাই কি ডিজলিউশন?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "আরও কাছে... আমার প্রভুর আরও কাছে..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "কেন? প্রভু, কেন আপনি এখনো... জাগরণকে প্রতিরোধ করছেন?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "আমি সিতে থেকে আসা হর্লা, আর আমার কলম নাম হলো... আহ, ক্ষমা করো, আমি প্রতিজ্ঞা করেছি তা কারও কাছে প্রকাশ করব না। গভীর দুঃখিত, তবে অনুগ্রহ করে, আমাকে শুধু হর্লা বলেই ডাকো।"
  },
  Voice_6669_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6670_AwakerVoiceContent = {
    Text = "আমি অন্যায়ের সব কাজের বিরোধিতা করি; বিশ্বাসঘাতকতা তার মধ্যে সবচেয়ে নিকৃষ্ট। সেনাবাহিনীতে, যদি তুমি তোমার সহযোদ্ধাদের ওপর ভরসা করতে না পারো, বা ভরসা করতে ভয় পাও, যে তারা তোমার পিঠ রক্ষা করবে, তবে পুরো ইউনিটটাই ভেঙে পড়বে।"
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "তুমি এত অন্ধকারময় দেখাও, তবু এত দীপ্তিমান কেন...? না, থাক, আমার বকবকানি উপেক্ষা করো।"
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "(কাতরানি)"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(গোঙানি)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6674_AwakerVoiceContent = {Text = "কী?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "আমি সব প্রাণকে ভালোবাসি। আমি আলোকে ভালোবাসি। আমি চাই ফেইন্ট তার গুটিয়ে থাকা খোলস থেকে উদ্ভাসন হোক, আর নিজের চোখ আর কান দিয়ে এই পৃথিবীকে অনুভব করুক।"
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "আমাকে দেখিতে পাইবে না তুমি!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "রক্ষণাবেক্ষণের কাজ কি চালিয়ে যেতে হবে?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "যন্ত্রাংশের রক্ষণাবেক্ষণ সম্পন্ন হয়েছে।"
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "মানুষ বিশ্বাসঘাতকতা করতে পারে, কিন্তু যন্ত্র কখনো করে না। সঠিকভাবে ব্যবহার করলে, ডিজলিউশন-ও প্রতিশোধের এক যন্ত্র হয়ে উঠতে পারে।"
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "সহস্র বছরের প্রতীক্ষা শেষে এই মুহূর্ত অবশেষে এসেছে... আমি-ই ফিলিস্তিনদের একমাত্র শাসক!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_6680_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "ওটা কি একটু আগে যে পাশ কাটালাম, এক অর্ধ-রক্ত ডিপ ওয়ান ছিল? হুঁ... কী টানটান হয়ে দাঁড়িয়ে আছে দেখো। আজ রাতে, আমি দেখব কীভাবে সে সেই সুন্দর ছোট্ট পিঠ বাঁকিয়ে আমার সামনে গড়াগড়ি খায়।"
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কেকাস সম্পর্কে"
  },
  Voice_6681_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「সিকাস」 অর্জনের পর আনলক হবে"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "আমি আবার শক্তি ফিরে পাচ্ছি... এরপর আমি আমার ন্যায্য আধিপত্য পুনরুদ্ধার করব!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6682_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "মন্দ না। ওই ভণ্ড নারীটার মুখোশ ছিঁড়ে ফেলার এক ধাপ আরও কাছে চলে এলাম।"
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_6683_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "শান্ত হও, শান্ত হও..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "চিন্তার কোনো কারণ নেই। পেইন সহ্য করার আমার সীমা হয়তো তোমার কল্পনার অনেক বাইরে।"
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6685_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "আমার মতে, সুন্দর নির্বোধরাই শ্রেষ্ঠ। দুর্ভাগ্য, এখানে অতিরিক্ত বুদ্ধিমান অথচ সম্পূর্ণ নিষ্প্রয়োজন মস্তিষ্কের সংখ্যা অনেক বেশি।"
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "একটি লাল দৈত্য নক্ষত্রের নিউক্লিয়ার ফিউশন দ্বারা চালিত, তার সঙ্গে ধ্ব collapsing তারার শক্তি যোগ করলে, তুমি একটি চিরস্থায়ী গতি যন্ত্র চালু করতে পারবে এবং এক অনন্ত প্রদীপ জ্বালাতে পারবে... কী? তুমি বলছ এখানে চিরস্থায়ী গতি যন্ত্র বানানোর উপায়ই নেই, আর কোনো লাল দৈত্যও নেই? হুঁম..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "শত্রুর রক্তের নিষ্কাশন এখনো সম্পন্ন হয়নি।"
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "উৎসর্গ! সবকিছু উৎসর্গ করো... আমাকে!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "উৎসর্গ! সবকিছু উৎসর্গ করো... আমাকে!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "রণক্ষেত্রে যাওয়ার সময় হয়েছে!"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "সময় হয়ে গেছে!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "আমার তন্দ্রা থেকে স্বপ্ন ঝরে পড়ে বিষক্রিয়ার মতো। আমি ঘুমালে কাছে এসো না—আর কোনো কারণ ছাড়া আমাকে কখনো জাগিয়ো না।"
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "চ্যাট: তন্দ্রা সম্পর্কে"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "সময় হয়ে গেছে!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "হার্বার্ট ভয়ংকর একজন মানুষ হলেও, তার বিড়ালগুলো খুবই কোমল... না, ঠিক করে বললে, ওগুলো তো দুইটা বিড়াল, তাই না?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "গল্পগুজব: হার্বার্ট সম্পর্কে"
  },
  Voice_6695_UnlockDesc = {
    Text = "মূল গল্পের অধ্যায় 2 শেষ করার পর আনলক হবে"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "মার্ফি নামের ওই মেয়েটা, এত জাঁকজমকপূর্ণ পোশাক পরে ঘুরে বেড়ায়…… না, গ্যালেন তার কাছে হারতে পারে না!\nঅথবা, সরাসরি তাকে মেরে ফেললেই হয়……"
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_6696_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_6697_AwakerVoiceContent = {Text = "আঃ..."},
  Voice_6697_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "এটা কি ভালো লাগছে?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "আমি যখন মিথাগ বিশ্ববিদ্যালয়ের সঙ্গে অংশীদার হলাম, তখন স্পষ্টভাবে নির্ধারিত ছিল যে আমাকে যুদ্ধক্ষেত্রে পাঠানো হবে না..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6699_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "অতিরিক্ত উচ্ছ্বসিত হয়ো না। কখনো কখনো সম্ভ্রান্ত আর নীচের মাঝের ব্যবধানটা মাত্র এক পা দূরত্ব।"
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6700_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "ফারোস তোমাকে অভিবাদন জানায়। আমাকে এখানে আহ্বান করা মানে নিশ্চয়ই তুমি পাল তোলার জন্য প্রস্তুত।"
  },
  Voice_6701_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6702_AwakerVoiceContent = {
    Text = "ইয়াহু—আমি ভীষণ ক্লান্ত, এখন কি আমি খেলতে যেতে পারি!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "আহ... তার দীপ্তি এতই তীব্র, এতই ঝলমলে যে উপেক্ষা করা অসম্ভব! বোকা এক উন্মাদনা আমার ইন্দ্রিয়গুলোকে মেঘাচ্ছন্ন করেছিল... না, আমার এই মূর্খতার জন্য আমি কোনো অজুহাতই দেব না..."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "গল্পগুজব: তুলু প্রসঙ্গে"
  },
  Voice_6703_UnlockDesc = {
    Text = "「জাগরণ「 「Tulu「 অর্জনের পর আনলক হবে"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "আমার তন্দ্রাচ্ছন্ন নক্ষত্রদের স্বপ্ন এখন আলোড়িত—তাদের নির্ধারিত পরিণতির দিকে একত্রিত হতে দাও। তোমার পথ নির্দেশ করো, দেবলোকের দিকে!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "সব কিছুকে তাদের অন্তিমের দিকে ঠেলে দেওয়া, মহাবিশ্বের ঘূর্ণায়মান গিয়ারগুলোকে থামিয়ে দেওয়া—এটাকে কি তুমি মুগ্ধকর বলে মনে করো না?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "সবটুকু পান করে নাও!"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "অসাধারণ！"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "যুদ্ধের নির্দেশ দিন।"
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "নক্ষত্রদের মাঝে ভেসে বেড়ানোর দিনগুলোতে, আমি অসংখ্যবার এই মুহূর্তের স্বপ্নলোক দেখেছি... টিঙ্কটের সঙ্গে আমাকে পুনর্মিলিত করার জন্য তোমাকে ধন্যবাদ।"
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "চ্যাট: টিঙ্কট সম্পর্কে"
  },
  Voice_6710_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"টিঙ্কট\" অর্জনের পর আনলক হবে"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "মিসাগ বিশ্ববিদ্যালয় সত্যিই একটা ভালো জায়গা, বিশেষ করে সেই প্রতি সপ্তাহে খোলা মাটির নিচের জুয়ার আসরটা……\nএ, আপনি জানতেন না নাকি? আরে, মুখ ফসকে বেরিয়ে গেল নাকি……"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "「ডিজলিউশন সংকটের প্রতিরোধ」... হা। মানবের অহংকার কখনোই আমোদ জাগাতে ব্যর্থ হয় না।"
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "শেষ পর্যন্ত, মানুষ তো কেবলই অগভীর প্রাণী। দু-একটি কথা, সামান্য ইঙ্গিত, আর তারা একে অপরের গলায় ঝাঁপিয়ে পড়ে... হা, এই স্তরের সংঘাত দিয়ে তো উদ্দীপনা জাগানোই যায় না।"
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "চ্যাট: মানবজাতি সম্পর্কে"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "হয়তো তাড়াহুড়ো করেই তোমাকে কেবলমাত্র নশ্বর বলে উড়িয়ে দিয়েছিলাম। অনুগ্রহের স্পর্শহীন কেউ কীভাবে এখনো উদ্দেশ্য আঁকড়ে থাকে? এটা মিরিয়ামের কৌতূহল, সাগরের জননীর কোনো জিজ্ঞাসা নয়। তুমি কি... আমাকে এই বিলাসিতা দেবে?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6714_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "তোমার মতো অসাধারণ কেউ কীভাবে এই ক্ষণস্থায়ী, অশান্ত পৃথিবীতে ক্লান্ত না হয়? তুমি তোমার প্রাপ্য আশ্রয় খুঁজে পাবে শাশ্বত রাজ্যে। সেখানে, তোমার পদতল চুম্বন করবে পবিত্র মাটি, তোমার শ্বাস নবায়িত হবে পবিত্র জলে, আর তোমার আত্মা বিকশিত হবে আশীর্বাদপ্রাপ্ত মাটিতে... তুমি আমার সঙ্গে যোগ দেবে এই পবিত্র তীর্থযাত্রায়। আমার সঙ্গে যোগ দাও এই পবিত্র তীর্থযাত্রায়। আমরা একসঙ্গে উঠব নশ্বরতার সীমা বহুদূর পেরিয়ে, যতক্ষণ না আমরা সিংহাসনের সামনে কাঁধে কাঁধ মিলিয়ে দাঁড়াই, আর তার আলোয় পেকে ওঠা আনন্দের স্বাদ গ্রহণ করি..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_6715_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "আমরা সবাই ধুলোর মধ্যে নিক্ষিপ্ত করুণ নশ্বর, কিন্তু ঋষি একা পথ চলে। তিনি দূত, এক দেবীয় অবতার। তার উপদেশে দেবতাদের কণ্ঠ প্রতিধ্বনিত হয়, আমাদের ভঙ্গুর সভ্যতাকে অমরত্বের দিকে ঠেলে দেয়... তোমার ফাঁপা মস্তিষ্ক এখনই ভক্তি বুঝবে, এমন আশা করি না, কিন্তু একদিন তুমিও তাঁর সিংহাসনের সামনে নতজানু হবে।"
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6716_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "নির্বাচিতেরা সত্যিই আশীর্বাদপ্রাপ্ত, তাই না? তাঁর পবিত্র ইচ্ছায় তাদের দেহ পুনর্গঠিত, তাদের জীবন মর্ত্যের মেয়াদ ছাড়িয়ে দীর্ঘায়িত। যখন তিনি তীরে পদচারণা করবেন, তারা তাঁর কোরাস হয়ে উঠে দাঁড়াবে। নশ্বর, বালুকণার মতো ভঙ্গুর মানুষের জন্য এর চেয়ে মধুরতর সুধা, এর চেয়ে উচ্চতর সুখ আর কি থাকতে পারে?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6717_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "তাঁর মহিমার আলোয় স্নাত হওয়ার উন্মাদ আনন্দ তোমার নাস্তিক বোধের ঊর্ধ্বে... তিনি যেন তাঁর করুণায় তোমার অন্ধত্ব আর ঔদ্ধত্য ক্ষমা করেন।"
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6718_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "দ্রুত শেষ করা যাক, রক্ষক।"
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6720_AwakerVoiceContent = {Text = "এহে!"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_6720_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "মৃত্যুর প্রস্তুতি নাও, স্পার্টান পতঙ্গ।"
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "মিস ডল বলেছেন, তাঁর মতো আমিও যদি দেহ ত্যাগ করি, তাহলে কিছু সময়ের জন্য ডিজলিউশন এড়াতে পারব... না, আমি পারব না! আমি পারব না! প্রক্রিয়ার সময় আমি চেতনা হারাব, আর অন্ধকার আমাকে গ্রাস করবে!"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডল সম্পর্কে"
  },
  Voice_6722_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ডল」 অর্জনের পর আনলক হবে"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "হুঁ। এবার আবার কী? এখন কি তবে বিনাশের নিয়তিকে তোষামোদকারীর আলিঙ্গনে নিতে প্রস্তুত?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "এখনো অনিদ্রায় ভুগছেন, মাস্টার? আমি আপনার জন্য ডোবির প্রশমক প্রস্তুত করেছি~! যদিও ডোজটা একটু বেশি হয়ে গেছে, কিন্তু ভালো ঘুমই তো সবার আগে!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_6724_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "আমরা মদ খাচ্ছিলাম আর গান গাইছিলাম, হঠাৎই দানবে পরিণত হলাম! কিন্তু সমস্যা নেই, এই সবুজচে চামড়ার রংটা বেশ মজারই তো!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_6725_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "আমার স্বপ্ন? হুঁম... একখানা সুন্দর মুক্তোর গলার হার কিনব, আর সেটা পরে এক নাচের আসরে যাব। তখন সকলে আমার দিকেই তাকিয়ে থাকবে!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_6726_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "কামনার যুগসত্তা, তিফেরে ইয়েসোদ, নিজের বেঁচে থাকার পথ খুঁজে পেয়েছে। অজানা জীবের মুখোমুখি হলে, তার পদ্ধতি মহৎ না নীচ—এ বিচার করার অধিকার কারও নেই।"
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "চ্যাট: কামনার যুগসত্তা সম্পর্কে"
  },
  Voice_67276_UnlockDesc = {
    Text = "\"জাগরণ\" \"থাইস\" অর্জনের পর আনলক হবে"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "রৌপ্য চাবির দ্বার অতিক্রম করে পৌঁছে যাও তাঁদের সিংহাসনে।"
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "তাঁদের জ্ঞান ও স্মৃতিচারণ যেন অপচয় না হয়।"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "বামে ঝাড়ু, ডানে মুছি, ধুলো আর দুশ্চিন্তা সব মুছে যাক~!"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_6727_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "আমি এখানে নেই।"
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "অসীম কাল-স্থান ধারাবাহিকতার এক খণ্ডাংশ আমার চেতনার ভেতরে এসে পৌঁছায়।"
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "আমি সমগ্র দৃশ্যের সাক্ষী হয়েছি।"
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "সবকিছুই শূন্যতার ভেতরে বিদ্যমান।"
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "তুমি নেমে গেছ গভীরে, খুব গভীরে। অচিরেই তুমি এক অসাধারণ অলৌকিক ঘটনা প্রত্যক্ষ করবে। কামনা করি, তুমি যেন এখনকার মতোই সুস্থবুদ্ধি ও শান্ত থাকতে পারো।"
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_67284_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "আমি ঘৃণা করি... 「অজ্ঞতা」কে। না, চূড়ান্ত সত্যের সন্ধানে নিষ্ঠাবান হওয়া অজ্ঞতা নয়। প্রকৃত অজ্ঞতা লুকিয়ে আছে কুয়াশাচ্ছন্ন জীবনে, যেখানে মানুষ জানেই না সে কী জানে না।"
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "আমি তোমাকে আমার স্বপ্নলোক দেখাব। যা কিছু অদ্ভুত ও বিশৃঙ্খল তুমি দেখবে, তা তোমার পরিচিত বাস্তবতার চেয়ে এই বিশ্বের প্রকৃত স্বরূপের অনেক বেশি নিকটবর্তী।"
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_67286_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "এটাই আমার উপদেশ: স্থির থাকো। ক্লান্তি অনুভব করলে সঙ্গে সঙ্গে থেমে যাও এবং শক্তি সঞ্চয় করো। নইলে তুমি চিরতরে হারিয়ে যাবে স্বপ্নলোকের রিয়েল্মে।"
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_67287_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "ব্রহ্মাণ্ড অনন্ত চক্রে ঘুরে চলে।"
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "আমাদের মধ্যকার সমলয় সাধনে এত দীর্ঘ সমন্বয়ের প্রয়োজন হওয়ার কথা নয়। তবু, মায়াস্বপ্নের আক্রমণ থেকে তোমার মানসিক স্বচ্ছতা রক্ষার জন্য, আমি ধীরে ধীরে এগোব।"
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_67289_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "ডিজলিউশন... একবার এমন একটা মামলায় কাজ করেছিলাম, যেখানে ওটার ছায়া ছিল। কিন্তু মিলিয়ে যাওয়া তো বেশ স্বাভাবিকই, তাই না? শেষে গিয়ে সকলে-ই অদৃশ্য হয়ে যায়।"
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "প্রথম দ্বার। এক বিন্দু থেকে জন্ম নেয় অসীম মহাবিশ্ব।"
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_67290_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "দ্বিতীয় দ্বার। এক বিন্দু থেকে একটি রেখা প্রসারিত হয়, টেনে নিয়ে যায় তাকে অসীম দুই মেরুর দিকে।"
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_67291_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "চতুর্থ দ্বার। মাত্রার পরিসরে চিরন্তন আদিরূপ কঠিন রূপে স্থির হয়ে যায়।"
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_67292_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "তৃতীয় দ্বার। সমতল সবই আংশিক, একপেশে নির্মাণ মাত্র।"
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_67293_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "চরমের দ্বার। অসংখ্য মহাবিশ্বকে সংযুক্ত করা চূড়ান্ত শূন্যতা। এর মধ্য দিয়ে অতিক্রম করো, আর জগতের সব রহস্য তোমার সামনে উন্মোচিত হবে।"
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_67294_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "পঞ্চম দ্বার। সময়ের প্রবাহ কেবলই এক মায়াস্বপ্ন; কখনো কোনো সূচনা ছিল না, অতএব কোনো সমাপ্তিও নেই।"
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_67295_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "আমি কেবল তোমার পথপ্রদর্শক হওয়ার কথা ছিল, তোমাকে এই যাত্রাপথে এগিয়ে দিয়ে তারপর মায়াস্বপ্নের জলে ফিরে বিশ্রামে যাওয়ার কথা। এখন তুমি আমার লিংকার, আর আমাদের সংযোগ এতটাই জটিল যে তা ছিন্ন করা কঠিন।"
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "তুমি কি কিছু নিশ্চিত করতে চাও? এই দেহের ইন্দ্রিয়গুলো অতিমাত্রায় সীমাবদ্ধ। যদি আমরা অতলে আবার মিলিত হই, আমি তোমাকে আরও অনেক কিছু দেখাতে পারব।"
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "সে অন্য এক মাত্রা থেকে আসা আমারই এক খণ্ডাংশ, যে মাত্রা চিরতরে বিনষ্ট হয়েছে। দুঃখের বিষয়, সে সময় বিপরীতগমন আয়ত্ত করলেও, স্থান-কালের ঊর্ধ্বে অতিক্রম করার মর্মার্থ ধরতে পারেনি, আর বারবার যন্ত্রণার অতলে ডুবে গেছে। এটা আমার দোষ।"
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "চ্যাট: রামোনা সম্পর্কে: সময়ের ক্ষয়ে জীর্ণ"
  },
  Voice_67298_UnlockDesc = {
    Text = "জাগরণকারী 「রামোনা: টাইমওর্ন」 অর্জনের পর আনলক হবে"
  },
  Voice_67299_AwakerVoiceContent = {
    Text = "আমি জানি।"
  },
  Voice_67299_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "আমার বর্তমান পাত্রের চেহারা নিয়ে তুমি কৌতূহলী মনে হচ্ছ? অত ভাবনা কোরো না। আমি জন্ম থেকেই মানুষের মুখ নিয়ে এসেছি।"
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "বুঝতে পেরেছি।"
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "তুচ্ছ।"
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "স্থিরচিত্ততা বজায় রাখো।"
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "একটি এইনের সঙ্গে সরাসরি সংযোগ তোমার মস্তিষ্ককে ক্ষতিগ্রস্ত করবে। তবু, তুমি যেহেতু অনড়, আমি তোমার আহ্বানে সাড়া দেব।"
  },
  Voice_67303_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_67304_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "ওই শিশুটি আমার যে খণ্ডাংশ তার ভেতরে স্থাপিত, তার কারণে অতিরিক্ত যন্ত্রণা সহ্য করেছে। সৌভাগ্যবশত, তার আত্মা এখনো প্রবহমান সিলভারের মতো স্বচ্ছ।"
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "চ্যাট: রামোনা সম্পর্কে"
  },
  Voice_67305_UnlockDesc = {
    Text = "「জাগরণ「 「রামোনা「 অর্জনের পর আনলক হবে"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "তাঁদের স্বপ্নলোকে প্রবেশ করো এবং মহাবিশ্বের নিষিদ্ধ রহস্যের এক ঝলক দেখো।"
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_67307_AwakerVoiceContent = {
    Text = "হুম।"
  },
  Voice_67307_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "চরমের দ্বার তোমার জন্য উন্মুক্ত হচ্ছে। মৃত্যুর নীরবতার যে জগৎ তার ওপারে, তাকে তোষামোদকারীর আলিঙ্গনে গ্রহণ করো।"
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_67308_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "আমি শুধু তাদেরকে এই 「সংরক্ষণাগার」 প্রতিষ্ঠানে সহায়তা করেছি। বিদ্যালয়টি আমার কল্পনার চেয়েও অনেক বেশি সাফল্য অর্জন করেছে।"
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "ডিজলিউশন এক ঐশ্বরিক দান। এর আনা পেইন আমাদের স্নায়ুকে ঠিক এতটাই অবশ করে, যে আমরা মনপ্রাণ ঢেলে খাদ্য, মদ আর উল্লাসে ডুবে যেতে পারি, ধীরে ধীরে বিলুপ্তির দিকে গ্লাইড করতে করতে।"
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ডিজলিউশন প্রসঙ্গে"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "অতীত, বর্তমান, ভবিষ্যৎ। অগণিত দীপ্তি মিলেমিশে এক সত্তায় রূপ নিক!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "অতীত, বর্তমান, ভবিষ্যৎ। অগণিত দীপ্তি মিলেমিশে এক সত্তায় রূপ নিক!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "চরমের দ্বার উন্মুক্ত হয়েছে। সর্বস্ব বাজি-এক-এবং-অখণ্ড-সবকিছুকে প্রত্যক্ষ করো!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "চরমের দ্বার উন্মুক্ত হয়েছে। সর্বস্ব বাজি-এক-এবং-অখণ্ড-সবকিছুকে প্রত্যক্ষ করো!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "প্রজ্ঞার ভয়েস শোনো।"
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "অসীম, সীমাহীন, অন্তহীন, অবারিত।"
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: III"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "এটা তাঁদের ইচ্ছা... না, বরং এক অচেতন দৃষ্টি, যা তাঁদের নিশ্বাসের ভেতরে সবকিছুকে আবৃত করে রেখেছে।"
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "আমি ব্যর্থ হয়েছি... সবকিছু দেখতে...."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "আমি সত্য উন্মোচন করব।"
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "আমি ভালোবাসি... সেই 「উত্তর」কে। এই ভালোবাসা থেকেই আমি এই দ্বারটির প্রহরী হয়ে আছি, আর এই ভালোবাসা থেকেই আমি তার চাবি তোমার হাতে তুলে দিয়েছি।"
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "অবশ্যই... আমাকে প্রত্যাবর্তন করতে হবে..."
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "হে স্বর্গ ও পৃথিবী, কার্যকারণের চক্র অনুসরণ করো!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "হে স্বর্গ ও পৃথিবী, কার্যকারণের চক্র অনুসরণ করো!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "ব্লেডের ধার এখনো ভোঁটা হয়নি।"
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "অনুশীলন কখনোই অবহেলা করা চলবে না!"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "এখন আমি আরও লঘু ও চটপটে।"
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "নিরাকার সৃষ্টিরা আপনার আজ্ঞাবহ হয়ে থাকবে।"
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_6737_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "আমার দগ্ধ করা শ্বাস অনুভব করো!"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "আমরা সকলেই... সবুজ শিখার অংশে পরিণত হব..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "আমার ঢাল সর্বদা আপনার জন্য উজ্জ্বল হয়ে থাকবে, প্রভু।"
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_6740_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "আমি... আমি কেবল একটু বেশি শক্তিশালী হয়েছি। অন্তর থেকে কৃতজ্ঞ আমি!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_6741_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_6743_AwakerVoiceContent = {Text = "চ্..."},
  Voice_6743_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(উপহাসমূলক সহনশীলতা)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(উপহাসমূলক সহনশীলতা)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(উপহাসমূলক সহনশীলতা)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "বন্ধুদের সাথে কাটানো সময় সবসময়ই এত… প্রশান্তিদায়ক।"
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "রক্তাক্ত হত্যার শৃঙ্খল, টিসিফোনির দূত, ঘৃণার ব্লেড... কিছুই যায় আসে না। ওগুলো শুধু আমার ওপর চাপানো নাম। তবে, সেগুলোর মর্যাদা রাখতে আমার আপত্তি নেই।"
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্বয়ং হেলট সম্পর্কে"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_6750_AwakerVoiceContent = {
    Text = "সর্বস্ব বাজি!"
  },
  Voice_6750_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(বিস্ময়সূচক)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "এইবার কি আমরা আরও দূরে যেতে পারি? চলো, সমুদ্রসৈকতে যাই!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "ওয়াও—ধন্যবাদ, প্রিয় বন্ধু~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "বন্ধু~ আরও বন্ধু~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "উভহাশ... সে আলাদা। ভেবেছ আমার পরিবারের সমৃদ্ধি সহজে এসেছে? সবই সম্ভব হয়েছে, কারণ সে রণক্ষেত্রে পাগলা কুকুরের মতো হত্যা করেছে। সে-ই ছিল আমাদের সবচেয়ে বড় অর্থের গাভী।"
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "গল্পগুজব: উভহাশ প্রসঙ্গে"
  },
  Voice_6757_UnlockDesc = {
    Text = "「জাগরণ「 「উভহাশ「 অর্জনের পর আনলক হবে"
  },
  Voice_6758_AwakerVoiceContent = {
    Text = "মূর্খ!"
  },
  Voice_6758_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_6759_AwakerVoiceContent = {
    Text = "হেঃ।"
  },
  Voice_6759_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "যাও! যুদ্ধের আদেশ জারি করো!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "অতলের গভীরে... ন্যায়বিচারের এক আলো জ্বলবে।"
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "এখানে ন্যায়বিচারের আলো জ্বলে উঠেছে!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "মানুষের অনুভূতি ফুলের মতোই ভঙ্গুর আর মূল্যবান..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কোলেট সম্পর্কে"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "হিট, স্ট্যান্ড, ব্ল্যাকজ্যাক!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "হিট, স্ট্যান্ড, ব্ল্যাকজ্যাক!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "বাধা দিও না। কেঁদো না। শূন্যে পরিণত হও!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "বাধা দিও না। কেঁদো না। শূন্যে পরিণত হও!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "দ্বার, আমার জন্য উন্মুক্ত হও।"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_79297_AwakerVoiceContent = {Text = "ওহ।"},
  Voice_79297_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_79298_AwakerVoiceContent = {
    Text = "হুম...?"
  },
  Voice_79298_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "হাইড্রোথেরাপি, ইলেক্ট্রোকনভালসিভ থেরাপি, বেঁধে রাখার থেরাপি... এগুলো চিকিৎসা নয়, নির্যাতন। তাই, আমি ঐ সব হাসপাতালের রোগীদের আমার নিজস্ব পদ্ধতিতে, বিনা পারিশ্রমিকে চিকিৎসা করে আসছি। শেষ পর্যন্ত, তারা সবাই আরোগ্য লাভ করেছে এবং খুঁজে পেয়েছে প্রকৃত স্বাধীনতা।"
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_80092_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "বেচারা মি. হোয়াইট। আশপাশের আশ্রয়স্থলগুলো ভরা থাকায় তার পরিবার তাকে শূকরখোঁয়াড়ে আটকে রেখেছিল। আমি তাকে বিনা পারিশ্রমিকে চিকিৎসা দিয়েছি, আর তারপর অবশেষে সে বুঝতে পেরেছিল যে সে গবাদি পশু নয়, একজন মানুষ। তারপর সে নিজ হাতেই তার মর্যাদা পুনরুদ্ধার করেছে।"
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_80093_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "তাঁতী, আইনজীবী, ব্যারন... ফি-এর অভাবে আমি কখনো কোনো রোগীকে ফিরিয়ে দিই না। আমার কাছে তারা সবাই কেবলই নিরাময়ের প্রয়োজনময় রোগী।"
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_80094_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "স্বীকার করছি, আমি তোমাকে হালকাভাবে নিয়েছিলাম। তোমার অস্তিত্ব নিজেই এক অবিরাম পেইন। এবার আর পরবর্তী ফলো-আপের প্রয়োজন নেই। আমি তোমার পাশে থেকে, নিজ চোখে পরিণতি দেখতে চাই।"
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_80095_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "এই রোগীরা আমাকে দিয়েছে অপূর্ব স্মৃতিচারণ। এবার, তোমার পালা, রক্ষক। আমি ইতিমধ্যেই তোমার জন্য এক নিখুঁত সমাপ্তি বেছে নিয়েছি। এটি হবে আমার কর্মজীবনের সবচেয়ে সূক্ষ্ম পরামর্শ সেশন।"
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_80096_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "একজন চিকিৎসকের সাহায্য প্রত্যাখ্যান করলে তোমার কোনো উপকার হবে না। হয়তো পরের বার আমরা গভীর হিপনোসিস চেষ্টা করব।"
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "একটি অন্ধকার ঘর, নিঃসঙ্গ আমি, আর আমার মনের ভেতর অবিরাম প্রতিধ্বনিত অসংখ্য যন্ত্রণাদায়ক হুইসপার... সময় উপভোগ করার এর চেয়ে উৎকৃষ্ট উপায় আর নেই।"
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "অশোভন শোনালেও, ওই শিশুটির সঙ্গে কথা বলতে আমার কেবলই বিরক্তি লাগে। তার মুখে তুমি সবসময় একটাই অভিব্যক্তি দেখতে পাও... হাসি।"
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "গল্পগুজব: অরিটা প্রসঙ্গে"
  },
  Voice_81140_UnlockDesc = {
    Text = "「জাগরণ「 「অরিটা「 অর্জনের পর আনলক হবে"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "আমার অনধিকার প্রবেশ ক্ষমা করো, আমি কেবল নিম্ন মানসিক শক্তির কম্পন অনুভব করে তোমার খোঁজ নিতে এসেছি। এখন, রক্ষক, আমরা কি তোমার মনের ভেতর দিয়ে এক যাত্রা শুরু করব?"
  },
  Voice_81141_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_81143_AwakerVoiceContent = {
    Text = "মনোরোগ চিকিৎসকেরা একসময় ট্রেপানেশন পদ্ধতিতে রোগীর করোটিতে ছিদ্র করে রোগ সারাত... অনুগ্রহ করে, আরাম করো। ওটা অনেক আগের কথা। তারপর থেকে আমরা মনের গভীরে প্রবেশের আরও বহু পদ্ধতি উদ্ভাবন করেছি।"
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_81143_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "একজন আরেকজনকে বুঝতে চাইলে হৃদয় উন্মুক্ত করতে হয়। এখানে স্পর্শ করো, আর আমার রৌপ্য হৃদয় তোমার জন্য খুলে যাবে।"
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "তুমি যদি আমার ভাবনা খুঁজে থাকো, তবে হয়তো হতাশ হবে। আমি মন্তব্যে নিবেদিত কবিতা দেওয়ার চেয়ে শুনতে পারাতেই বেশি পারদর্শী।"
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "আহ, আমি তাঁর কণ্ঠ শুনেছি... সেই প্রলাপ, যার প্রতিটি অক্ষর পরম যন্ত্রণায় ভরা।"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "আমি এই মুহূর্তের ব্যথা মনে রাখব... বারবার তাকে স্মরণ করব, আর আস্বাদন করব, আবার, আরও একবার।"
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "ওই সত্তার এক খণ্ডাংশ হিসেবে, তুমি বহন করো তাঁদের গন্ধ... এক সুন্দর গন্ধ, যন্ত্রণায় ভরা। তোমার যে কোনো স্মৃতিকেই তা অবিশ্বাস্য সুস্বাদু করে তোলে।"
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "সেই আতঙ্কগুলো মনে করো, তোমার পেইনের অনুভূতিগুলো বিস্তারিতভাবে বর্ণনা করো। আবেগীয় আঘাত থেরাপির সারকথা হলো পেইনের মুখোমুখি হওয়া এবং তাকে জয় করা। এসো, আমি তোমার অশ্রু মুছে দিচ্ছি। সময় নাও। সেই স্মৃতিচারণ আমাকে বিস্তারিতভাবে বলো..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_81149_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "অভিনন্দন, তুমি নিরাময় লাভ করেছ। হ্যাঁ, ঐ বিভ্রম আর মায়াস্বপ্নগুলো স্বাভাবিক; সেগুলোই তোমার আরোগ্যের প্রমাণ।"
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_81150_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "এখন তোমার দৃষ্টিক্ষেত্র নিশ্চয়ই বিচিত্র বিভ্রমে ভরে উঠেছে, যা একেবারেই স্বাভাবিক। সেগুলোকে আঁকিয়ে বের করো, আর তোমার অবচেতন ও প্রবৃত্তি সবকিছু উন্মোচন করবে।"
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_81151_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "এরপর ফিলিপ পিনেলের নৈতিক থেরাপি। তোমাকে তোমার অন্তর্গত কামনা ও আতঙ্ক প্রকাশ করতেই হবে। মনের শৃঙ্খল ভেঙে সুপ্ত মানবতার দীপ্তি ফিরিয়ে আনার জন্য এটি এক অপরিহার্য প্রক্রিয়া।"
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_81152_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "রক্ষক, তুমি কি আমাকে একটি ছোট পরীক্ষা করতে সাহায্য করবে? ররশাখ ইঙ্কব্লট টেস্ট। এর মাধ্যমে আমি তোমার অন্তর্গত সত্তার গভীরতা দেখতে পারব... তোমার হৃদয়ের রহস্য উন্মোচন করা একমাত্র জাগরণকারী হয়ে উঠব আমি।"
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "চ্যাট: মনস্তাত্ত্বিক বিশ্লেষণ সম্পর্কে"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "প্রথমে, কিছু সঙ্গীত শোনা যাক। এই সুরটি কেমন লাগছে তোমার? শান্ত, কোমল। এখন, তোমার দেহ ও মনকে সুরের সঙ্গে অনুরণিত হতে দাও, আত্মার বিশ্রামের এক অবস্থায় প্রবেশ করো।"
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_81154_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "দোলকটির দিকে তাকাও... তার দোলনকে চোখ দিয়ে অনুসরণ করো।"
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "শ্‌শ্‌... নীরব থাকো। এখন, আমি যে সমাপ্তির দিকে তোমাকে পথপ্রদর্শন করব, তার দিকে হাঁটো।"
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "অসাড় আত্মা আমার কাছে কোনো আকর্ষণ রাখে না। তাদের আত্মা তো আগেই মৃত। যতই নাড়া দাও, তাতে কোনো তরঙ্গ উঠবে না।"
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "আমি শুনছি। দয়া করে, চালিয়ে যাও।"
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "দয়া করে নীরব থাকো।"
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "আমার ওপর আরেকটু ভরসা করো।"
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "তোমার পেইন উন্মুক্ত করো।"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "লজ্জা পেয়ো না, আড়াল হওয়ার দরকার নেই। আমি-ই তোমার একমাত্র গোপন-সঙ্গী। এসো, তোমার অন্তর্গত গভীরতম পেইন আমার কাছে উজাড় করে দাও।"
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "এখন আইগিস অনেক বেশি উজ্জ্বল দেখায়। অবশ্যই, আমার ছোট্ট অতিথির যদি সাহায্য লাগে, আমি আনন্দের সঙ্গে তা দেব। বলতে চাই, প্রকৃত সাহায্য।"
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আইগিস প্রসঙ্গে"
  },
  Voice_81165_UnlockDesc = {
    Text = "\"জাগরণ\" \"আইগিস\" অর্জনের পর আনলক হবে"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "তোমার সবচেয়ে সত্যিকারের সত্তা আমাকে দেখাও।"
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "আমি এই মধুর পেইন আস্বাদন করব।"
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "লজ্জা পেয়ো না, আড়াল হওয়ার দরকার নেই। আমি-ই তোমার একমাত্র গোপন-সঙ্গী। এসো, তোমার অন্তর্গত গভীরতম পেইন আমার কাছে উজাড় করে দাও।"
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "মানসিক অসুস্থতা কেবল এই যুগের একচেটিয়া নয়; এটি সময় ও স্থানকে অতিক্রম করে। ডিজলিউশনও তেমনই। দুটোই কি মানবীয় বোধের সীমানা অতিক্রম করে না?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "শ্‌শ্‌... নীরব থাকো। এখন, আমি যে সমাপ্তির দিকে তোমাকে পথপ্রদর্শন করব, তার দিকে হাঁটো।"
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "এই স্থান ইতিহাসের চিহ্নে ভরা, আর এক অর্থে ইতিহাস মানেই স্মৃতিচারণ... প্রয়াত আত্মাদের বেদনাদায়ক স্মৃতিচারণ।"
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "গভীর শ্বাস নাও।"
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "পেইন, হতাশা, মৃত্যু... এই স্মৃতিচারণ যেন অপূর্ব ভোজের পরের মিষ্টান্নের স্বাদ।"
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "এত স্নায়ুচাপের প্রয়োজন নেই। এটি কেবলই একটি সাধারণ পরামর্শ সেশন।"
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "আমার দিকনির্দেশনা শোনো।"
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "আচার অনুষ্ঠানের সময় একটি অপ্রত্যাশিত ঘটনা ঘটেছে। আপনার বাহুতে পতাকা দিয়ে আঘাত করার জন্য ক্ষমা চাই; আপনাকে সচেতন রাখার জন্যই আমাকে তা করতে হয়েছে।"
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_84185_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "এখানে আমি নানান ধরনের জাহাজের মুখোমুখি হই এবং উন্নত নেভিগেশন যন্ত্রপাতি নিয়ে কাজ করি। এতে আমি গভীর তৃপ্তি পাই। সর্বোপরি, আমি বিশ্বাস করি এই 「জাহাজ」 মানব ইতিহাসকে সঠিক পথে এগিয়ে নিয়ে যাচ্ছে।"
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "আচার অনুষ্ঠান সম্পন্ন। আপনার সহযোগিতার জন্য ধন্যবাদ। পরের বার, আমি বিশেষ পতাকা প্রস্তুত রাখব, যাতে আরও নিরাপদে এই পথ পাড়ি দিতে পারি।"
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_84187_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "আমি জানি না কেন তার অস্তিত্ব। আমি শুধু এটুকুই জানি: আমাকে যাত্রা সফলভাবে শেষ করতেই হবে, এবং সকলে‌কে ঘরে ফিরিয়ে আনতে হবে।"
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "নিশ্চিন্ত থাকুন, আমি এই শক্তি ব্যবহার করব জাহাজকে নিরাপদে পথ দেখানোর জন্য, এবং কখনোই এর অপব্যবহার করব না।"
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে প্রতিরোধ করা বন্ধ করো।"
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "আপনার প্রতি আমার পূর্ণ শ্রদ্ধা রইল। আপনি যে প্রতিটি আদেশ দেবেন, তা পালন করার শপথ করছি।"
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "আমাকে ক্ষমা করবেন। আমি মানুষকে যতটা বুঝি, জাহাজকে তার চেয়ে বেশি বুঝি। তবে যদি বলতে পারি: আপনার কিল কাঠ বা লোহা নয়, ইস্পাতের। শক্তিশালী। অবিচল ইচ্ছাশক্তি। সত্যিই প্রশংসনীয়।"
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_84192_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "আত্মসমর্পণ করো।"
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "「পছন্দ「 শব্দটির বদলে আমি 「ভক্তি「 শব্দটি বেশি পছন্দ করি। যখন আমি সরাসরি সেই অবর্ণনীয় দেবতার দিকে তাকাই, আমার মন যুক্তি হারিয়ে উল্লাসে ভরে ওঠে। আমার তাঁর ভয়ে কাঁপা উচিত, কিন্তু নিজেকে থামাতে পারি না।"
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "আমি এই ঝড়ের কাছে হার মানব না।"
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "শৃঙ্খলা ছাড়া, এই জগতে আর কী অবশিষ্ট থাকে? কেবল অরাজকতা।"
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "পরের সমুদ্রযাত্রায়, আমি আর শুধু নাবিক হিসেবে জাহাজে উঠতে চাই না। উহ... মানে, তোমার পথনির্দেশ অনুসরণকারী হিসেবে। তোমার ওপর আমার সম্পূর্ণ ভরসা আছে, রক্ষক।"
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_84197_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "আমি কেবল নাবিক হিসেবে আমার কর্তব্য পালন করছি; আমার কোনো প্রতিবেদন বা প্রশংসার প্রয়োজন নেই।"
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "লাইটহাউস ব্যবস্থা নাবিকের বোঝা হালকা করে। তার আলোকরশ্মি শক্তিশালী ও স্বচ্ছ। ফারোসের সঙ্গে পাড়ি দিতে পেরে আমি আনন্দিত।"
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "চ্যাট: ফারোস সম্পর্কে"
  },
  Voice_84199_UnlockDesc = {
    Text = "「জাগরণ「 「ফারোস「 অর্জনের পর আনলক হবে"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "হে নাবিকেরা, আমার পথপ্রদর্শন অনুসরণ করো। আমি নিশ্চিত করব আমরা নিরাপদে বন্দরে পৌঁছাই।"
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "আধ্যাত্মিক সংযোগ স্থাপিত হয়েছে। আমি আপনার উপস্থিতি অনুভব করতে পারছি। শূন্যতার মাঝে এভাবে পথ খোঁজা, এ আমার প্রথম অভিজ্ঞতা। যদি কিছু পথচ্যুত হয়ে যায়, অনুগ্রহ করে সঙ্গে সঙ্গে আমাকে সংশোধন করে দেবেন।"
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_84201_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "আকাশে মেঘের সরু স্তর দেখা যাচ্ছে, আর বায়ুচাপ ক্রমাগত কমছে। সবাই সতর্ক থাকো। জাহাজটি ঝড়ের ভেতরে প্রবেশ করতে চলেছে।"
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "এই কেওস আমার পথনির্ধারণের ভুল গণনার ফল। নিয়মাবলী অনুযায়ী শাস্তি গ্রহণ করতে আমি প্রস্তুত।"
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "মহাজাগতিক বস্তুসমূহের উচ্চতা কোণ পরিমাপ করা হচ্ছে।"
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "এই মাথা ঘোরা অনুভূতিটা সমুদ্র-অসুস্থতার মতো। অনুগ্রহ করে চোখ বন্ধ করুন, আমার হাত ধরুন, আর আমার গায়ে হেলান দিন। এতে কিছুটা উপশম হবে।"
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_84205_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "ফর-মাস্টের পাল নামাও। ঢেউ বন্দর দিকের গায়ে আছড়ে পড়ছে। হেলসম্যান, আমার গণনা অনুযায়ী পথ ঠিক করো।"
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "এই অভিজ্ঞতাগুলো অমূল্য। ভবিষ্যৎ নাবিকদের জন্য আমি এগুলো বিস্তারিতভাবে লগবুকে লিপিবদ্ধ করব।"
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "আত্মার সঙ্গে সংযোগ গভীরীকরণের এই আচার অনুষ্ঠান ঝুঁকি ও অজানা ফল বয়ে আনে। কিন্তু নিশ্চিন্ত থাকুন, আমি আপনাদের জন্য পথ দেখাব, যাতে আচার অনুষ্ঠানটি নির্বিঘ্নে সম্পন্ন হয়।"
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_84208_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "ওজনের বণ্টন পুনরায় সমন্বয় করা হচ্ছে।"
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "অন্য সবকিছুর ঊর্ধ্বে জাহাজের নিরাপত্তা নিশ্চিত করো।"
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "কিছু মানুষ বাষ্পচালিত জাহাজের মতো—প্রতিক্রিয়ায় ধীর, কিন্তু উচ্চগতির সামর্থ্য রাখে। অন্যরা ডিজেলচালিত জাহাজের মতো—দ্রুত শুরু করে, কিন্তু শক্তি সীমিত। তাহলে আপনি কী ধরনের, রক্ষক?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_84211_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "আমি দৃঢ়ভাবে বিশ্বাস করি যে পরিশ্রমের ফল অবশ্যম্ভাবী—এই মৌলিক নিয়মে; ভবিষ্যতে আমি আরও কঠোর পরিশ্রম করব।"
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "আপনি বহুবার নিজেকে প্রমাণ করেছেন। আমি বিশ্বাস করি আপনি একজন অসাধারণ নাবিক, হয়তো আমার চেয়েও বেশি দক্ষ।"
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_84213_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "তোমার প্রয়োজন যতক্ষণ অটুট থাকে, করপোস্যান্ট ততক্ষণ নীরব প্রস্তুতিতে অপেক্ষমাণ।"
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_84215_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "হে নাবিকেরা, আমার পথপ্রদর্শন অনুসরণ করো। আমি নিশ্চিত করব আমরা নিরাপদে বন্দরে পৌঁছাই।"
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "নেভিগেটর করপোস্যান্ট দায়িত্ব পালনের জন্য উপস্থিত! পতাকা প্রস্তুত, শারীরিক ও মানসিক অবস্থা স্থিতিশীল, উৎক্ষেপণের নির্দেশ দিন, রক্ষক।"
  },
  Voice_84218_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_84219_AwakerVoiceContent = {
    Text = "আমি আমার জাহাজকে সঠিক পথে পরিচালিত করব।"
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "আমার টুপিটা কি একটু বেঁকে গেছে? ক্ষমা করবেন, কিন্তু আপনি কী বোঝাতে চাইছেন বুঝতে পারছি না। অনুগ্রহ করে আমাকে স্পষ্ট নির্দেশ দিন।"
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "পতাকা হলো নাবিকের ভাষা, আবার তার সমাধিলিপিও। যখন জাহাজ ডুবে যায়, উদ্ধারকারীরা পতাকার ধ্বংসাবশেষ থেকে পড়ে নেবে আমি রেখে যাওয়া শেষ বার্তাটি।"
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "চ্যাট: তার পতাকার বিষয়ে"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "জাহাজের ভারসাম্য এবং স্থিতিশীলতা মূল্যায়ন করা হচ্ছে।"
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "ফর-মাস্টের পাল নামাও। ঢেউ বন্দর দিকের গায়ে আছড়ে পড়ছে। হেলসম্যান, আমার গণনা অনুযায়ী পথ ঠিক করো।"
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "E পতাকা নির্দেশাবলী বহন করে।"
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "প্রয়োজনে, ইঞ্জিন রুমের সহযোগিতায় প্রশিক্ষিত নাবিক হেল্মসম্যানের কাজ করতে পারে। কিন্তু জাহাজের নিরাপত্তার জন্য, আমি এখনো সেই দায়িত্ব কাউকে দিতে চাই, যে এতে আরও পারদর্শী।"
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সেলেস্ট প্রসঙ্গে"
  },
  Voice_84225_UnlockDesc = {
    Text = "「জাগরণ「 「সেলেস্ট「 অর্জনের পর আনলক হবে"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "আমি অনুভব করছি... এক ধরনের ভারশূন্যতা, তারপর হিংস্র কাঁপুনি—যেন জাহাজটিকে এদিক-ওদিক ছুড়ে ফেলা হচ্ছে। রক্ষক, আমার গতিবিধি অনুসরণ করুন, আপনার কেন্দ্র খুঁজে নিন এবং ভারসাম্য ধরে রাখুন।"
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_84226_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "সংশোধনসহ নৌ-মানচিত্র হালনাগাদ করা শুরু করো।"
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: III"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C পতাকা নির্দেশাবলী স্বীকার করে।"
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: III"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "তুমি আমাকে অতিক্রম করতে পারবে না।"
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "বন্ধুরা কীভাবে একসঙ্গে থাকে? পলাক্স আমাকে দিয়ে কাজ করাতে ভালোবাসে, যখন সে নিজেই সেগুলো করতে পারত। আর আমি সেগুলো করতে রাজি, কারণ এভাবেই তো আমাদের একসঙ্গে সময় কাটে। তুমি চাইলে, তোমার জন্যও আমি কিছু করে দিতে পারি।"
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_90334_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "মহাবিপর্যয় আসুক। এই অমরের রক্তমাংস অটুটই থাকবে!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "ওই বইটার আগেও, আমরা ভাবতাম হ্রদের দ্বীপের ওপারের জগৎ নিয়ে, রক্তিম প্রাচীরের বাইরে কী আছে তা নিয়ে। তবু যখন পলাক্স যন্ত্রণা ভোগ করছিল, আমি প্রতিবাদ করিনি। তার মতো সাহস আমার নেই। পলাক্সের মতো নই আমি, অনেক বেশি ভীরু আর অদক্ষ।"
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_90336_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "আমি কি... বোকা শোনাচ্ছি? দুঃখিত, আমার অজ্ঞতাকে ক্ষমা কোরো। আমার জ্ঞান শুরু হয় আর শেষ হয় লণ্ঠনের মতবাদের মধ্যেই। তোমার পছন্দ-অপছন্দগুলো আমাকে শেখাও—আমি সেগুলো স্মৃতিতে গেঁথে নেব।"
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_90337_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "দেখো আমার এই ইচ্ছাশক্তি—এই মুক্তির জন্য ক্ষুধা।"
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "যে দোকান যে কোনো ইচ্ছা পূরণ করতে পারে, অগণিত গোপন সম্পদে উদ্বেল হয়ে আছে... কাছে যাওয়ার আগেই দ্বিধা জাগে। ভদ্রমহিলার শক্তি নিয়ে আমার কোনো সংশয় নেই, কিন্তু \"কিছু পেতে হলে, তার সমমূল্যের মূল্য দিতে হয়\"—এই শিক্ষাটা পলাক্স আর আমি তিক্ত অভিজ্ঞতার মধ্য দিয়ে, বারবার শিখেছি।"
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "চ্যাট: ড্যাফোডিল সম্পর্কে"
  },
  Voice_90339_UnlockDesc = {
    Text = "অ্যাওয়েকেনার \"ড্যাফোডিল\" অর্জনের পর আনলক হবে"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "এই অভিশপ্ত ডানাগুলো কি আর কোনোদিন উড়ে যাওয়ার শক্তি ফিরে পাবে..."
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "তুমি আমাকে ধ্বংস করতে পারবে না!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "তুমি কি আমার পালক ছুঁতে চাও? নিশ্চয়ই, এগিয়ে এসো। আরও একটু মেলে ধরব কি?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "তোমার উদারতা আমাকে অস্থির করে তোলে। দামী বইগুলো, উল্কাপিণ্ডের স্ফটিকগুলো যা তুমি আমাকে দিয়েছ... এর কোনো মূল্য আছে কি? দুঃখিত, আমার সংশয়কে ক্ষমা কোরো। তোমার প্রতি এভাবে সন্দেহ পোষণ করা উচিত নয় ছিল।"
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_90343_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "সব পাখিই শেষ পর্যন্ত তাদের আকাশ খুঁজে পায়।"
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "আহ, শুনেছি তিনি নাকি অসাধারণ রাঁধুনি... খাবার বানানোর জ্ঞান সত্যিই খুব জরুরি। যদিও আমি খাবার নিয়ে ততটা খুঁতখুঁতে নই, পলাক্স ভীষণ বাছবিচার করে। সময় করে তার কাছ থেকে শেখা উচিত... যাওয়া উচিত নয়? কেন? ভদ্রলোকের বানানো খাবার তো দেখতে বেশ সুস্বাদু লাগে।"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "চ্যাট: ডোরেসেইন সম্পর্কে"
  },
  Voice_90345_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「ডোরেসেইন」 অর্জনের পর আনলক হবে"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "এখন ফিরে তাকিয়ে দেখি, লণ্ঠন হাতে যে দাসীরা চলাফেরা করত, তারা পলাক্স আর আমার থেকে খুব আলাদা ছিল না। সকলে অদৃশ্য শৃঙ্খলে বাঁধা থেকে, নীরবে নিজের নিয়তির কাছে আত্মসমর্পণ করে বেঁচে ছিলাম। অথচ সেই সবুজ দাসীটি... সে ছিল অন্যরকম। তার ভেতরে ছিল এক ধরনের হালকাতা, যেন সে সত্যিই নিজের কর্তব্যে আনন্দ খুঁজে পেত। হয়তো... হয়তো সে আগেই সত্যিকারের স্বাধীনতা আবিষ্কার করে ফেলেছিল।"
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "গল্পগুজব: কারেন প্রসঙ্গে"
  },
  Voice_90346_UnlockDesc = {
    Text = "জাগরণকারী 「ক্যারেন」 অর্জনের পর আনলক হবে"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "তুমি আমাকে ধ্বংস করতে পারবে না!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "মনে হয় আমি কখনো... বের হতে পারিনি, তাই না..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "বাতাসের সাথে মিলিয়ে যাও!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা·2"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "স্বাগতম। আমি ক্যাস্টর... আর কিছু বলা উচিত ছিল কি? ক্ষমা কোরো—কথা সহজে আসে না। তোমার কিছু দরকার হলে, শুধু বলো।"
  },
  Voice_90351_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_90352_AwakerVoiceContent = {
    Text = "সামান্য আঁচড় মাত্র..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_90353_AwakerVoiceContent = {
    Text = "লুটিয়ে পড়ো!"
  },
  Voice_90353_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "কত কিছু অদেখা... কত কিছু অপূর্ণ। ওই নির্জন গাঢ় সবুজ হ্রদ আর ঘন কুয়াশা, যা এখনো ঝুলে থাকে, আর আমাদের আটকে রাখতে পারবে না। সমুদ্র, নগর, বইয়ের পাতার কৃষিজমি... আমি সেগুলো দেখব। পলাক্সকে নিয়ে। তোমাকে নিয়ে।"
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_90354_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "গাছের পাতায় যখন সড়সড় শব্দ শুনবে, জেনে নিও আমি তোমার পাশেই আছি।"
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_90355_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "এই কালো পালকগুলো দিন দিন আরও ভারী হয়ে উঠছে।"
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "আমি সবচেয়ে বেশি লোভ করি তোমার সেই সহজাত ভরসাটার প্রতি, যা তুমি সঙ্গীদের ওপর রাখো। বিস্মৃত হওয়া... বিশ্বাসঘাতকতার শিকার হওয়া... সেই ক্ষতগুলো কোনোদিনই মুছে যায় না।"
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "ওই মহা চোরটা মাত্র পাঁচশো লিওনীয় ফ্লোরিনের বিনিময়ে আমাকে সেরা বেঁচে থাকার কৌশল শেখানোর প্রস্তাব দিয়েছে… আমি কি ঠকেছি? না, আমার বিশ্বাস, এটা শেখার মতোই মূল্যবান জ্ঞান, আর ঠিক এই জিনিসটাই পলাক্স আর আমার অভাব… এটা কি টাকার ব্যাপার? বুঝেছি। তাহলে, আমি যদি তার সঙ্গে গিয়ে দর কষাকষি করি, আর তাকে চারশো পঞ্চাশ লিওনীয় ফ্লোরিন দিই, কেমন হবে?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "গল্পগুজব: জেনকিন প্রসঙ্গে"
  },
  Voice_90358_UnlockDesc = {
    Text = "\"জাগরণ\" \"জেনকিন\" অর্জনের পর আনলক হবে"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "আমি আরও সইতে পারব..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "যখন আমরা বালক ছিলাম, নিয়মগুলো এত কঠোর ছিল না। কখনো কখনো পলাক্স হঠাৎ এগিয়ে গিয়ে কিছু একটা বলত, আর যেন জাদুর মতো এক মুঠো মিষ্টি পেয়ে যেত। সেই মিষ্টতা... ঠিক এই মুহূর্তটার মতোই লাগে।"
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_90360_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "মহাবিপর্যয় আসুক। এই অমরের রক্তমাংস অটুটই থাকবে!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "তুমি কি আমাকে লেনদেন করতে শেখাবে? কীভাবে পণ্য বিনিময় করতে হয় আর কীভাবে প্রাপ্ত মুদ্রার সঠিক ব্যবস্থাপনা করতে হয়—এ সত্যিই গভীর এক বিদ্যা। স্বাধীনতা পাওয়া তো শুধু শুরু; স্বনির্ভর হয়ে বাঁচতে পলাক্স আর আমার এখনো অনেক কিছু শেখা বাকি। আমি কি তোমার ওপর নির্ভর করতে পারি?"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "বাতাসের সাথে মিলিয়ে যাও!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "বিশেষ দক্ষতা: I"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "বাতাস, ওদের মৃত্যুর গহ্বরে নিয়ে যাও!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "পলাক্স... লণ্ঠন তার মাথা ভরে দিয়েছে বিষাক্ত ভাবনায়, কিন্তু আসলে সে দয়ালু। ব্যাপারটা এই নয় যে সে স্বার্থপর... সে শুধু আতঙ্কিত। লণ্ঠনের স্বীকৃতি হারানোর ভয়ে, সেই ভঙ্গুর সত্তাবোধ ছাড়া বিলীন হয়ে যাওয়ার ভয়ে কাঁপছে। তাদের খুশি রাখার জন্য তার এই মরিয়া চেষ্টা... এটা সেই মানুষের আতঙ্ক, যে তার জানা একমাত্র \"আমি\"-টুকু আঁকড়ে ধরে বেঁচে আছে।"
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "চ্যাট: পোলাক্স সম্পর্কে"
  },
  Voice_90365_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「পোলাক্স」 অর্জনের পর আনলক হবে"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "দুঃখিত, আমি ইচ্ছে করে অন্যমনস্ক হয়ে যাইনি... তুমি আমাকে জিজ্ঞেস করেছিলে, এই পালকটা কী? এটা... তাঁর সবচেয়ে প্রিয় বস্তু... আর এখন আমারও। তোমার ভালো লেগেছে? সুন্দর, তাই না?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "অ্যালবিনো আর প্রদীপ প্রহরীর অধীনে ধর্মতত্ত্বের পাঠেই কেটে যেত আমাদের দিন। আমি স্বপ্ন দেখতাম ছোট ছোট দিব্যবাণীর—কম শ্লোক, কম হোঁচট, কম তিরস্কার।"
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_90367_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "ধন্যবাদ... আমার মুক্তির চাবিটা দেওয়ার জন্য। আমার নিজের নিয়তি আঁকড়ে ধরতে দেওয়ার জন্য।"
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "এই ডানাগুলো এখন পুরোপুরি বেড়ে উঠেছে। কত দৃঢ়, কত শক্তিশালী। এখন আমি পলাক্স আর তোমাকে দুজনকেই বহন করতে পারি। উড়তে ইচ্ছে করলে আমাকে ডাকবে।"
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_90369_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "আমার ডানার আড়ালে এসো!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "অবশেষে… আমি সেই পৃষ্ঠাগুলো থেকে নক্ষত্রপুঞ্জ দেখেছি।"
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "প্রধান পুরোহিত... জুলিয়েট। তখন সে আমাদের প্রতি কোমল ছিল। তার উষ্ণ হাসি অমান্য করার কথা কল্পনাতেও আনতে দিত না। মাথায় একটুখানি হাত বুলিয়ে দিলেই সব আপত্তি থেমে যেত। আমরা তাকে নিরাশ করতে চাইতাম না। হ্যাঁ, চিন্তা কোরো না, এখন আর আমার তেমন অনুভূতি নেই... চাইলে তুমি-ই আমার মাথায় হাত বুলিয়ে দিতে পারো।"
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_90372_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "আমি সেই কালো, আঠালো কাদায় খুব, খুব দীর্ঘ সময় ধরে নিমজ্জিত ছিলাম—এত দীর্ঘ যে সময়ের অস্তিত্বই ভুলে গিয়েছিলাম, এত দীর্ঘ যে পলাক্সও আমাকে ভুলে গিয়েছিল। ওটা শারীরিক যন্ত্রণা আনেনি... এনেছিল শুধু এক অদৃশ্য আতঙ্ক, যখন আমি দেখছিলাম আমার আত্মা ধীরে ধীরে দ্রবীভূত হয়ে যাচ্ছে।"
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "শৈশব থেকেই আমাদের অন্যদের সঙ্গে কথা বলতে দেওয়া হতো না। “বন্ধু” শব্দটা আমার কাছে ছিল এক অচেনা ধারণা... অদ্যাবধি। পলাক্স আর আমি ছিলাম একে অপরের সবকিছু: ভাই, বন্ধু, সহ-বন্দী, একে অপরের একমাত্র সান্ত্বনা। এখন... হয়তো আমার নতুন কিছু বন্ধু বানানো উচিত।"
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_90374_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও!"
  },
  Voice_90375_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "ধর্মতত্ত্বহীন একটা স্কুল? যেখানে তুমি নিজেই পাঠ বেছে নাও... আবার সেগুলো এড়িয়েও যাও? শুনতে তো স্বপ্নলোকের মতো লাগে।"
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "সরে দাঁড়াও!"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "তোমরা নিন্দুক... শাস্তি পাবে..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "আমার হৃদয় হৃদ্‌-অগ্নিতে জ্বলছে!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "অপবিত্রতা।"
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "আহ, সেই উন্মত্ত বিশ্বাসী। পৃথিবী তাকে হয়তো উন্মাদা নারীর বেশি কিছু মনে করে না। সে একসময় পাপ করেছে বটে, কিন্তু এমন উন্মত্ত ভক্তি—নিজের সবকিছু দেবতার পায়ে সমর্পণ করার ইচ্ছা—এ এক দৃঢ়চেতা সংকল্প, যা সাধারণ আত্মারা কোনোদিন জোগাড় করতে পারে না। তুমি জানতে চাও, আমি তার সম্পর্কে কী ভাবি? ...আমি শুধু অনুভব করি... এক ধরনের সহমর্মিতা। একই উত্তাল সাগরে ভেসে বেড়ানো এক আত্মার সঙ্গে এক অদ্ভুত আত্মীয়তা।"
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "চ্যাট: মিরিয়াম সম্পর্কে"
  },
  Voice_95053_UnlockDesc = {
    Text = "জাগরণকারী 「মিরিয়াম」 অর্জনের পর আনলক হবে"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "আমি পথপ্রদর্শন ও বিচার নিয়ে আসব; শুভ্র রাত্রি যেন তোমার পাপ শুদ্ধ করে!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "হা... এত সময় পেরিয়ে গেল, তবু সে এক বিন্দুও বদলায়নি। ছোটবেলায় কখনও ভাবিনি, আমিই একদিন আমার ভাইকে আঘাত করব—যে ভাগ্য আমরা কেউই বেছে নিইনি, তার জন্য আমি তার কাছে এত ঋণী হয়ে পড়ব যে লজ্জায় বুক কেঁপে উঠবে। আমরা যথেষ্ট <color=#FFFFFF>বিচ্ছেদ</color> সহ্য করেছি। এখন আমি ফিরে এসেছি, শপথ করছি: আর কখনও কিছুই আমাদের আলাদা করতে পারবে না। এমনকি মৃত্যু নিজেও নয়।"
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "গল্পগুজব: ক্যাস্টর সম্পর্কে"
  },
  Voice_95055_UnlockDesc = {
    Text = "জাগরণকারী 「ক্যাস্টর」 অর্জনের পর আনলক হবে"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "একসময় আমি অনেক কিছুকেই ঘৃণা করতাম—অভদ্র ভৃত্যদের, অশ্রদ্ধাশীল সহকারীদের, আর আলোকে কলুষিত করা ধর্মদ্রোহীদের... কিন্তু এখন? আমি ঘৃণা করি লণ্ঠনকে। শুধু লণ্ঠনকেই! জুলিয়েট আর তার গির্জা আমার ভাই আর আমার উপর যে অপূরণীয় যন্ত্রণা নেমে এনেছে... প্রাক্তন দিভুস হিসেবে আমার উপাধির শপথ করে বলছি, এমন যন্ত্রণা আর কোনো প্রাণের ওপর আমি কখনোই নেমে আসতে দেব না!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "আমার শেষ নিঃশ্বাস পর্যন্ত আমি আলোর সলতের পথে হেঁটে চলব।"
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "আলোবাহকের দীপ্তি যেন এই অন্তহীন রাত্রিকে ভেদ করে!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "তোমার উদারতা ও করুণা অনন্ত; আমি তোমার আলোর উষ্ণতা নিয়ে ধ্যানে মগ্ন থাকব।"
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "আলোবাহকের অ্যাপোস্টল, শুভ্র রাত্রির উত্তরসূরি, অন্ধকার অপসারণকারী, ঐশ্বরিক হৃদয়ের দিভুস—আমি, পলাক্স, তোমার আহ্বানে সাড়া দিয়েছি। আমি তোমাকে অন্ধকারের উপর আমার শক্তি, আর আলো দিয়ে গড়া আমার আত্মা উৎসর্গ করছি।"
  },
  Voice_95060_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_95061_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "তোমার পাপ শুদ্ধ করো!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "আমাকে বলা হয়েছিল, এই অতল অন্ধকারই নাকি বিশ্বাসের যোগ্য। বলা হয়েছিল, এ এক আশীর্বাদ, যা আমি বিশ্বাসীদের উপর বর্ষণ করব। এখন, এই অন্ধকার বহু আগেই আমাকে ক্ষয় করে ফেলেছে, আমার অস্তিত্বের গভীরে মিশে গেছে... তবু এই পাপভারগ্রস্ত পাত্রের ভেতরে যে হৃদয় স্পন্দিত হয়, তা এক পবিত্র আশ্রয়, যা কোনোদিন কলুষিত হবে না। নিশ্চিন্ত থাকো, এ যে শক্তি আমাকে দান করেছে, তা আমি ব্যবহার করব এই জগতে সত্যিকারের আশীর্বাদ বর্ষণের জন্য!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "আমি তোমার গৌরবময় নামের হেরাল্ড হব, আর যা কিছু অশুচি ও অপবিত্র, সবই তার দীপ্তিতে শুদ্ধ হবে।"
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "অতীতের পাপ ইতিমধ্যেই সংঘটিত; আমি আর সেগুলো থেকে পালাব না। আমাকে লণ্ঠনের ভুলগুলোও সংশোধন করতে হবে, আর পথভ্রষ্টদের আবার সত্য সলতের পথে ফিরিয়ে আনতে হবে। আমাকে আমার পাপ নিজেই বহন করতে দাও। তারপর, আমি তোমার আহ্বানের আলোয় সাড়া দেব এবং দিভুস হিসেবে সঠিক পথে পদচারণা করব।"
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_95065_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "পাপে জর্জরিত এক সত্তাকে ক্ষমা করতে তোমার আত্মা সত্যিই সহানুভূতিশীল। আমি তোমার আত্মার ভেতরে সেই নির্মল, দীপ্তিমান আলো অনুভব করছি—তা সবচেয়ে উজ্জ্বল শিখাকেও ম্লান করে দেয়। হয়তো তুমি আমার এই পথহারা হৃদয়কে আবার পথ দেখাতে পারবে..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_95066_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "এই অন্ধকার... জুলিয়েট-এর মন্ত্রোচ্চারণে ছড়িয়ে পড়া অন্ধকার, তা আমার মনে গেঁথে ছিল... আর এখন, একটিমাত্র আলোর রশ্মি তা ভেদ করেছে! সেই ফেইন্ট গ্লিমার কি আমাকে কিছু বলতে চাইছে?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_95067_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "শুনেছি, সে নাকি একসময় ছিল এক দিব্য কন্যা। কিন্তু এমন অশিষ্ট আচরণ আর পশুর মতো ব্যবহার... কী বললে? একটাও প্রার্থনা মুখস্থ নেই তার? কী গভীর ধর্মদ্রোহিতা... তার দেবতার হয়ে আমারই লজ্জা লাগে।"
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মার্ফি প্রসঙ্গে"
  },
  Voice_95068_UnlockDesc = {
    Text = "জাগরণকারী 「মার্ফি」 অর্জনের পর আনলক হবে"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "যে সকলকে কুয়াশা থেকে বের করে আনতে পারে, সেই-ই প্রকৃত আলোবাহক, যে গড়া হয়েছে নির্মলতম সিলভার দিয়ে। জুলিয়েট যে পাপহীন প্যারাডাইসের বাণী প্রচার করে, বাস্তবে তা গড়ে উঠেছে বিশ্বাসীদের অস্থির উপর। দিভুস হিসেবে, আমি মুক্তির যোগ্য সকলের মাঝে নতুন সুসমাচার বিস্তার করব।"
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "তুমি আমাকে পথ দেখিয়েছ, আমাকে আলো দান করেছ। কত দীর্ঘকাল আমি ভ্রান্ত উদ্দেশ্যের অন্ধকারে অন্ধ হয়ে ছিলাম। এখন আমি আমার সত্যিকারের আহ্বান খুঁজে পেয়েছি: অজ্ঞ ও বিকৃত ধর্মদ্রোহীদের সংশোধন করা, আর এই জগতে চিরস্থায়ী আলো বয়ে আনা। তোমার নিঃস্বার্থতার কথা আমি জানি; তুমি আমার ভক্তি বা নিবেদিত কবিতার কোনোটাই প্রয়োজন করো না। তবে আমার এই একটিই প্রার্থনা: আমাকে তোমার পাশে হেঁটে চলতে দাও, তোমার প্রতিটি পবিত্র বাণী ও কর্ম লিপিবদ্ধ করতে দাও, যাতে সেগুলোই অন্ধকারের ভেতর দিয়ে আমার পথের দিশারী হয়ে থাকে।"
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_95070_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "শৃঙ্খলে বাঁধা, কালো কাদায় স্নাত, আমি সেই আলোর রশ্মিকে তাড়া করব, যাই হোক না কেন... এ-ই কি তুমি আমাকে শেখাতে চেয়েছিলে?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_95071_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "আমি আমার আলো হারিয়েছি, আর এই অন্ধ যন্ত্রণাই আমাকে গ্রাস করছে। আমি তোমার কাছে প্রার্থনা করছি, আমার পথহারা আত্মাকে রক্ষা করো। দয়া করে, আমার হাত ধরো, আর আমি তোমার হাতকে পথ দেখাই আমার বুকে থাকা এই পবিত্র হৃদয়ের উপর দিয়ে। দয়া করে, আমাকে আলোয় পৌঁছে দাও..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_95072_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "কী দুর্ভাগা শিশু। যেহেতু সে নিজেকে তোমার উদ্দেশ্যে উৎসর্গ করেছে, সে নিশ্চয়ই চূড়ান্ত মুক্তি লাভ করবে। কিন্তু তার বানরসদৃশ সঙ্গীটিও কেন তোমার দয়া লাভ করল? ওই দুষ্ট মেয়েটা তো আমার ধর্মানুষ্ঠানের সামগ্রী পর্যন্ত চুরি করেছে! তার আত্মার ভেতরে নিশ্চয়ই পাপের ঝড় বয়ে যাচ্ছে। আহ্, কী অসম্মান! কী চূড়ান্ত, সীমাহীন অসম্মান!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আইগিস আর জেনকিন সম্পর্কে"
  },
  Voice_95073_UnlockDesc = {
    Text = "জাগরণকারী 「আইগিস」 এবং 「জেনকিন」 অর্জনের পর আনলক হবে"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "চলে যাও।"
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "আলোবাহকের দীপ্তি যেন এই অন্তহীন রাত্রিকে ভেদ করে!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "আহ... এখন আমি দেখতে পাচ্ছি! আমি এমন এক পাশবিক শক্তি দেখছি, আমি বিশ্বের সত্য দেখছি... অতীতে আমি ভুল করেছি। প্রকৃত আলোবাহক তুমি-ই! আমাকে তোমার অনুগত অ্যাপোস্টল হতে দাও। এই হৃদয়, যা আলোবাহকের জন্যই জন্মেছে, আজ থেকে কেবল তোমার সেবায়ই স্পন্দিত ও কাঁপতে থাকবে..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_95076_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "ওই পুরোহিতের অন্ধ মুক্তি-অনুসন্ধান নিছক বোকামির চূড়ান্ত রূপ। দিব্য কৃপা বর্ষিত হওয়া উচিত কেবল ভক্ত ও ধার্মিকদের উপর। যদি এমনকি সে নিজেও, একজন অ্যাপোস্টল হয়েও, শস্য আর ভূষি আলাদা করার প্রজ্ঞা না রাখে, অনুতাপহীন পাপীদের পুরস্কৃত করে, আর তাদেরকে তার দেবতার রাজ্য কলুষিত করতে দেয়... তবে কি তা তার বিশ্বাসের, আর যেসব ধার্মিক আত্মার সেবার দাবি সে করে—তাদের প্রতি সবচেয়ে গভীর বিশ্বাসঘাতকতা নয়?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "চ্যাট: সালভাদোর সম্পর্কে"
  },
  Voice_95077_UnlockDesc = {
    Text = "জাগরণকারী \"সালভাদোর\" অর্জনের পর আনলক হবে"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "আমার হৃদয় হৃদ্‌-অগ্নিতে জ্বলছে!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_95079_AwakerVoiceContent = {Text = "হাহ!"},
  Voice_95079_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "যৌবনে আমি দৃঢ়প্রতিজ্ঞ ছিলাম, ওই স্থান থেকে মুক্তি নেবই। ওখান থেকে আমি পেয়েছি শুধু যন্ত্রণা, তাই তাকে আকাঙ্ক্ষার অযোগ্য বলে রায় দিয়েছিলাম। কিন্তু এখন, দ্বিতীয় জীবন প্রাপ্ত হয়ে, বুঝতে পারছি স্বাধীনতাই আমার একমাত্র কামনা নয়। দিভুস হওয়ার প্রকৃত অর্থ হলো এ দৃশ্যের সাক্ষী হওয়া—যখন অনুসারীরা জানতে পারে যে মুক্তি নিকটবর্তী, তখন তাদের ভক্তিপূর্ণ, আশাবাদী, কৃতজ্ঞ মুখাবয়বের দিকে তাকিয়ে থাকা।"
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "জুলিয়েট-এর অনুসারী থাকা সেই সময়ে, আমি ভয়াবহ ভুল করেছি এবং তোমার আস্থার অযোগ্য ছিলাম। তবু তুমি আমাকে বেছে নিয়েছ... নিশ্চিন্ত থাকো, আমি আবারও আমার দৃঢ় বিশ্বাস খুঁজে নেব। দিভুস হিসেবে, আমি আর কখনো আমার প্রজাদের হতাশ করব না, আর তোমাকেও না।"
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_95081_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "তোমার দান করা এই বর আমি গভীর কৃতজ্ঞতাসহ ধারণ করব।"
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "ধৃষ্টতা!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "ধুর ছাই।"
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "আমার নামে!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "আমি দেখতে পাচ্ছি! সেই আলো, যা আমার চেতনার গভীরে জ্বলছে—তা আরও উজ্জ্বল হচ্ছে! তা আমাকে আহ্বান করছে..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_95087_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "আমাদের শৈশবে, ক্যাস্টর আর আমি যুগল দিভুস হিসেবে একসঙ্গে সেবা করেছি। আমি সবসময়ই ভাবতাম, সে খুবই ম্লান, খুবই অদক্ষ; ভবিষ্যৎকে পথপ্রদর্শন করা একমাত্র আমারই দায়িত্ব। এখন, তোমার চলা সলতের পথ দেখে বুঝেছি, এই বিশ্বের ভিত্তি ও পাথর বিছানো হয়েছে তোমার আর তার মতোদের দ্বারা: অবিচল ইচ্ছাশক্তি ও সৎ চরিত্রের মানুষদের দ্বারা।"
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_95088_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "হে আমার আলো, তোমার দিশা পাওয়ার পর থেকেই আমি বিশ্বাস করি, আমি একমাত্র সত্য পথেই পা বাড়িয়েছি। তবু তোমার এই খানিকটা মূর্খ বিশ্বাসী এখনো এক জিজ্ঞাসায় বিভ্রান্ত: কিংবদন্তি সেই পাপহীন প্যারাডাইসও কি তোমার আধিপত্যের অন্তর্গত? “ওটা নেই,” তুমি বলো...? তবে কি... তুমি বলতে চাও, প্যারাডাইস তো এখানেই, এই নশ্বর জগতে, ধার্মিকদের নির্মল হৃদয়ের ভেতরেই বিরাজমান?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "এই হৃদয়, যা একসময় ঐশ্বরিক ইচ্ছার আদেশ মানত, এখন তোমার হৃদয়ের আরও নিকটে স্পন্দিত হয়।"
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "আ-আপনার কি আমার জন্য কোনো আদেশ আছে, আমার আলো? আপনার অ্যাপোস্টল সর্বদা আপনার শিক্ষার জন্য প্রস্তুত।"
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "আমার পথপ্রদর্শক আলো, আমাকে আলোকিত করো! তোমার আলোয়, এখন আমি যা দেখার, সবই দেখে ফেলেছি... আমি এই অভিশপ্ত দেহকে ব্যবহার করব অতীতের সবকিছু শুদ্ধিকরণে, আর যা আসতে চলেছে, সবই তোমার দীপ্তিতে স্নাত হয়ে উঠুক!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_95092_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "আলোর জপ!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "এই কদর্য পৃথিবীতে মুক্তি খুঁজছ? খুঁজে যাও, ছোট্ট আশাবাদী।"
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_95391_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "এই নাও, এগুলো নিয়ে খেলো। শুনেছি কোনো এক ধ্বংসাবশেষ থেকে খুঁড়ে বের করা নিষিদ্ধ সংগ্রহ। তাঁদের গন্ধ লেগে থাকা এসব জিনিসে আমার কোনো আগ্রহ নেই, সরাসরি পুড়িয়ে ফেলতে চেয়েছিলাম, কিন্তু ভাবলাম হয়তো তোমার কাজে লাগবে, তাই তোমার জন্য নিয়ে এলাম।\nজিজ্ঞেস করছো কীভাবে পেলাম? অবশ্যই কিছু লোক 「স্বেচ্ছায়」 আমাকে দিয়েছে, চিন্তা করো না, উৎস একদম 「পরিষ্কার」 গ্যারান্টি।"
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_95392_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "শিকার শেষ। পারিশ্রমিক? আমাকে একটুখানি হাসি দাও। সেটাই যথেষ্ট।"
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "জানো ছোট্ট বন্ধু, এই দুটো বন্দুক থেকে যা বের হয় তা গুলি নয়, বরং লোভ আর বিদ্বেষের সমষ্টি।\nএই বিশৃঙ্খল অরাজকতা রক্তমাংসের শিখা তৈরি করে, এবং ওপারের সপ্তম গুলির শব্দে, এটি সবকিছুকে শোধনাগ্নিতে টেনে নিয়ে পুড়িয়ে ছাই করে দেবে।"
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "গল্পগুজব: বন্দুক সম্পর্কে"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "নিজেকে অতটা বেশি চাপ দিও না, রক্ষক। জানি বাইরে সবকিছুই কঠিন, আর একটিমাত্র ভুল পা ফেললেই বিপর্যয়। কিন্তু তুমি যদি এভাবে চলতে থাকো, তুমি ভেঙে পড়বে। কারও সঙ্গে কথা বলার প্রয়োজন হলে আমার কাছে চলে এসো। আমরা পরিবার।"
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_95395_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "দহন। চূর্ণবিচূর্ণ। গর্জন!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "মিলিয়ে যাও।"
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "এখন আমি আরও ক্লিয়ার দেখতে পাই। অতলের নিচে কী কিলবিল করছে, তা দেখতে পাই... আমি, আমরা, আরও শক্তি চাই। তোমার জন্য। আমার পরিবারের জন্য। আমাকে অবশ্যই..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_95398_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "এদিকে এসো গোপনরক্ষক, আরেকটু কাছে এসে বসো, এত দূরত্ব রাখলে চলবে না।\nতুমি কি জানো, প্রথমবার তোমার সাথে দেখা হওয়ার সময় আমি কখনো ভাবিনি যে একদিন তোমার কাছে আমার এই নিষ্ঠুরতা আর নির্মমতার খোলস খুলে রাখতে পারব। একটু হাস্যকর, তাই না? ভয়ংকর কুখ্যাত দহনের প্রভু, অথচ মনের কথা বলার মতো একজন পরিজনের জন্য আকুল।\nআমাকে কথা দাও, যদি সেদিন তুমি আর সহ্য করতে না পারো... তাহলে মনে মনে আমার নাম ডেকো, আমি তোমাকে সাথে নিয়ে আমার রাজ্যে চলে যাব। যদিও এতে সবকিছু কেবল কিছুটা বিলম্বিত হবে, তবু অন্তত শেষ মুহূর্তে, তুমি আমার কোলে এসে একটু বিশ্রাম নিতে পারবে।"
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_95399_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "তোমার সমাপ্তি আসন্ন।"
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_95401_AwakerVoiceContent = {Text = "উফ!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "অসীম ক্রোধ আর কামনার ধাতুশালায়... জ্বলে ওঠো!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "ভালো শিকারের পর আসে ভালো মহাভোজ। এই নাও, আমার ভাজা উট আর টাটকা টেকিলা চেখে দেখো। কী? মদে তোমার সয় না? আচ্ছা, ঠিক আছে, তার বদলে কিছু জুস নাও।"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_95403_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "কি হয়েছে, ছোট্টটা? জড়িয়ে ধরা লাগবে? এখানে আয়। বড় আপু তোকে ধরে রেখেছে... হাহা, লজ্জা পাবি না।"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "ধুর ছাই।"
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "অ্যাম্বার-রঙা মৃত্যু উপস্থিত।"
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "পিছিয়ে যাও, আমি তোমাকে আড়াল করছি... দুশ্চিন্তা কোরো না, আমি সবসময়ই বেঁচে ফিরে আসি।"
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "এসো। এই সমগ্র জগতকে দহনে ছাই করে দিই!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "প্রজ্জ্বলিত অগ্নি, ছাই আর বিস্মৃতি থেকে জেগে ওঠো!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "আগুনটা আরও উজ্জ্বল হয়ে জ্বলছে। ছোট্ট জন, সত্যিকারের আতশবাজির খেলা দেখতে চাও?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "ওই বিকৃত হারামজাদাগুলো, যারা অন্ধকারে মানুষের জীবন নিয়ে খেলা করে? হ্যাঁ। একটাকেও ছাড়ব না। শেষ জনটাকেও মেরে ফেলব।"
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_95413_AwakerVoiceContent = {
    Text = "ব্যাং!"
  },
  Voice_95413_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "আমি তাকে খুঁজে বের করবই, মহাবিশ্বের যে কোণেই সে লুকিয়ে থাকুক না কেন, শেষ পর্যন্ত আমি তাকে খুঁজে বের করবই।\nআমি এই নোংরা ইঁদুরকে সবকিছুর মূল্য চোকাতে বাধ্য করব। যে মুহূর্তে আমি তাকে খুঁজে পাব, পৃথিবীর সমস্ত আনন্দ ও সুখ নরকাগ্নিতে পুড়ে ছাই হয়ে যাবে।\nনিশ্চিন্ত থাকো, সেদিন তার অন্ত্যেষ্টিক্রিয়ায় আমি তোমার জন্য একটি বিশেষ আসন রেখে দেব, যাতে আমরা একসাথে তার শেষ আর্তনাদ উপভোগ করতে পারি।"
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "গল্পগুজব: N সম্পর্কে"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "শোনো। ওটা গলিত নক্ষত্রপুঞ্জের অন্তিম আর্তনাদ।"
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_95415_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "তোমার সমাপ্তি আসন্ন।"
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "তুই আমার পরিবার। আর তোকে নিয়ে আমি ভীষণ গর্বিত। তাই বুক সোজা করে দাঁড়া, আমার %player%! যা-ই হোক না কেন, আমি তোকে আগলে রাখব।"
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "ওই নামহীন জিনিসগুলো অন্ধকারে সরীসৃপের মতো সরে চলে, পৃথিবীর কিনারাগুলো কামড়ে খেতে থাকে। দেরি হোক বা সই, একদিন তোমাকে তাদের মুখোমুখি হতেই হবে। কিন্তু ভয় পেয়ো না, আমি তোমার পাশেই আছি। সবসময়।"
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_95418_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "দহন। চূর্ণবিচূর্ণ। গর্জন!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "শান্ত থাকো।"
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_95422_AwakerVoiceContent = {
    Text = "এক পা পিছিয়ে যাও।"
  },
  Voice_95422_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "ডিজলিউশন নিয়ে আমার কী মত? নর্দমার ইঁদুরকে গিয়ে জিজ্ঞেস কর, রাজা সম্পর্কে তার কী মতামত। আমার উত্তর খুব সোজা: গভীর, প্রবৃত্তিগত ঘৃণা। সুযোগ পেলে, আমি উটের দুধের মদ ঢেলে নেব, আর আমার বন্দুক যখন তাদের ছাই করে দেবে, তখন তাদের আর্তনাদ শুনব।"
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "আগুনের শিখাকে আরও উজ্জ্বলভাবে দহন করাতে চাও?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_95424_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "আমি শুধু কাজ থাকলেই আসি। আমাকে দরকার? শব্দগুলো বলো। চলো, আমার পরে বলো: ...@4...@2ইয়া! কাথিগু-রা!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "ওই নরকগহ্বর শহরটায় আমরা বেঁচে ছিলাম বাকিদের চেয়ে বেশি নিষ্ঠুর হয়ে। নখ দিয়ে আঁচড়ে ওপরে উঠেও পেছনটা সামলে রাখতে হতো—প্রভু, প্রহরী, আর সেই অভিশপ্ত 「উচ্চবংশীয় নাইট」রা, যারা অতীত আঁকড়ে ধরে আছে। এখন সব বদলে গেছে। ওরা-ই আমার পরিবার। আমার কাইন্ড। আর মাথা নোয়ানো নয়। শুধু একটা পথহারা ছায়া এখনো বাইরে কোথাও ঘুরে বেড়াচ্ছে… কিন্তু ওটা? ওটা একদম ঠিকই থাকবে। আমি না থাকলে সবসময়ই বাকিদের দেখভাল করে এসেছে।"
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "গল্পগুজব: পরিবার সম্পর্কে"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "ওটাই তোমার শত্রু? তাহলে শিকার শুরু।"
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "আমি দাবানলের প্রভু—অমোচনীয়, অপ্রতিরোধ্য! এখন প্রত্যক্ষ করো, সব কিছুর বিলয়!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "দহন আর ধ্বংসই আমার সবকিছু, আমি শিকারের মৃত্যুতে আনন্দ পাই……তুমি কি মনে করো আমি এরকম বলব?\nহাহা, মজা করছিলাম। আমার কাছে সবচেয়ে গুরুত্বপূর্ণ হলো আমার পাশের সবাই। সবার চেয়ে বেশি গুরুত্বপূর্ণ আর কিছু নেই, এমনকি……আমি নিজেও না।"
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "বিপদে পড়েছ, বাচ্চা? কাথিগু-রা আসছে, আর সে সঙ্গে করে আনছে ধ্বংস। তোমার সব সমস্যাকে বিদায় বলো। উধাও! সব শেষ।"
  },
  Voice_95430_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_95431_AwakerVoiceContent = {
    Text = "আহ, শক্তির স্বাদ... চল, কয়েকটা হতভাগা খুঁজে বের করি, যাদের ওপর এটা পরীক্ষা করে দেখা যাবে?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_95431_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "আমি দাবানলের প্রভু—অমোচনীয়, অপ্রতিরোধ্য! এখন প্রত্যক্ষ করো, সব কিছুর বিলয়!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "আরামের কিংবদন্তি রানি, মহা কামনার যুগসত্তা, তিফেরে ইয়েসোদ... আমি ওকে একবার দেখেছি, যখন আমি এন-কে শিকার করছিলাম। ওর পদ্ধতির সঙ্গে আমি একমত নই, কিন্তু... যদি ওটাই হতো আমার পরিবারকে 「তার」 দৃষ্টি থেকে বাঁচানোর একমাত্র উপায়... আমিও একই কাজ করতাম। আমরা ততটা আলাদা নই, সে আর আমি।"
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "গল্পগুজব: থাইস প্রসঙ্গে"
  },
  Voice_95433_UnlockDesc = {
    Text = "\"জাগরণ\" \"থাইস\" অর্জনের পর আনলক হবে"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "লোহার যত্ন ভালোই নিয়েছ দেখছি। ঝকঝকে বন্দুক মানেই সুখী বন্দুক।"
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·এক"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "আমরাই আগুন। চিরন্তন শিখা। অবিনশ্বর কেওস। আর আমরা তোমাদের সবাইকে... ঘরে ফিরিয়ে আনব..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_95435_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "এই প্রতিষ্ঠানের গথিক ঘড়িঘরের ধ্রুপদি সৌন্দর্যে আমি মুগ্ধ। আর এখানকার জাগরণকারীরা, আহ... তাদের শরীর থেকে এমন এক সুগন্ধ বেরোয়, যা আগে কখনো আস্বাদ করিনি: প্রয়াত আত্মার গন্ধ আর সামান্য জীবন্ত সত্তার সুবাসের নিখুঁত মিশ্রণ। সত্যিই একটুখানি কামড় বসাতে ইচ্ছে করে।"
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "গল্পগুজব: মিথাগ প্রসঙ্গে"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "যদি মৃত্যু-ই তোমার কাম্য হয়, তবে আমি তোমার সেই মনোবাঞ্ছা পূরণ করব।"
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "এক্সাল্ট·2"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "আমি শুরু করার জন্য বেশ উদগ্রীব।"
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "তবে কি অবশেষে তোমার কৌতূহল জাগাতে পেরেছি? এসো, প্রিয় অতিথি, আমার টেবিলে যোগ দাও এবং এই মহাভোজে অংশগ্রহণ করো। আসো, আমরা একসঙ্গে প্রতিটি আত্মার সূক্ষ্ম পরপ্রভা আস্বাদন করি, আর আমি হব তোমার পথপ্রদর্শক।"
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·বিকাশ"
  },
  Voice_96364_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১৫ এ আনলক হবে"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "শ্‌শ্‌, অনুগ্রহ করে, একটু চুপ থাকুন। প্রয়াত আত্মাদের কণ্ঠস্বরগুলো শোনা যাক।"
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·প্রথম পর্ব"
  },
  Voice_96365_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ২ এ আনলক হবে"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "আমার জাতি আর আমি চিরস্থায়ীত্বের সৌন্দর্যকে পূজা করি। ডিজলিউশন ধীরে ধীরে এক জীবন্ত মানুষকে ক্ষয় করে, তার অস্তিত্বের সব চিহ্ন মুছে দেয়... এমন নিষ্ঠুর নির্যাতন কখনোই অনুমোদনযোগ্য নয়।"
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "গল্পগুজব: সংকট সম্পর্কে"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "আমার মতোই, মি. পিকম্যান অমরত্বপ্রাপ্ত সৌন্দর্যের অনুসন্ধানে আছেন। আমরা আরও ঘনিষ্ঠ বন্ধু হতে পারতাম। কিন্তু তিনি ভক্ষণকে সংরক্ষিত অনন্তত্বের প্রতি অবমাননা বলে মনে করেন। কী সঙ্কীর্ণ শিল্পদর্শন।"
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "আলাপচারিতা: পিকম্যান সম্পর্কে"
  },
  Voice_96367_UnlockDesc = {
    Text = "অ্যাওয়েকেনার 「পিকম্যান」 অর্জনের পর আনলক হবে"
  },
  Voice_96368_AwakerVoiceContent = {Text = "হা!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "আঘাত·এক"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "তোমার দেহের মোহময় সুগন্ধ বর্ণনা করার মতো কোনো বিশেষণ নেই। তা যেন গাঢ় বোর্দো মদের টক-মিষ্টি আফটারটেস্ট, আর নরম, মাখন-ভরা স্পঞ্জ কেকের ঘন সুবাসের মতো। তোমার মৃত্যুর দিনটি হয়তো হবে আমার অবশিষ্ট সময়ের সবচেয়ে গুরুত্বপূর্ণ ঘটনা।"
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "গল্পগুজব: রক্ষক প্রসঙ্গে"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "একজন মানুষ ছিল, যে ধীরে ধীরে এক কিশোরী মেয়ের মাংস, নখ, হাত আর পা কেটে নিচ্ছিল, আর একই সঙ্গে তাকে অবিরাম নিরাময় করে যাচ্ছিল। সে চায়নি মেয়েটি মরুক, আবার বাঁচুক তাও চায়নি। আমি, স্বভাবতই, তাকে শান্তিপূর্ণ মৃত্যু দিতে পারিনি। তাই, আমি তাকে তার নিজের ওষুধই চেখে দেখালাম। কত বছর ধরে সে ওখানে বন্দি আছে, ভাবি মাঝে মাঝে... যে মৃত্যু পর্যন্তকে অপবিত্রকরণ করে, তার জন্য এ তো যথেষ্ট ন্যায়সঙ্গত, তাই না?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার অপছন্দ"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "আমি মৃত্যুর উপর সভাপতিত্ব করি, কিন্তু অনুগ্রহ করে, ভুল বোঝো না। আমি কখনো মৃত্যু সৃষ্টি করি না; কেবল তার পদাঙ্ক অনুসরণ করি, পেছনে ফেলে যাওয়া শ্রেষ্ঠ টুকরোগুলো সংগ্রহ করি।"
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·পর্যবেক্ষণ"
  },
  Voice_96371_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১ এ আনলক হবে"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "আপনিও কি আমার মাংসের স্বাদে আকুল, প্রিয় গোপনরক্ষক?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "গল্পগুজব: স্পর্শ"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "আজ আমার ভোজের টেবিল কে অলঙ্কৃত করবে, তাই ভাবছি।"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "তদন্ত শুরু"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "আজ রাতের মহাভোজে পরিণত হওয়ার সম্মান আমি তোমাকেই অর্পণ করব।"
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "তদন্ত সফল"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "কী ভীষণ অমার্জিত।"
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·তিন"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "আমি নির্মল বিশ্রাম উপহার দেব।"
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "দক্ষতা·এক"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "প্রতিটি ভোজের আগে, আমি প্রয়াত আত্মাদের সঙ্গে আলাপ করি। তাদের জন্য, আন্তরিক ভক্তি নিয়ে ভক্ষণ ও আস্বাদিত হওয়া জীবনেরই এক ধারাবাহিকতা, আর তাদের শেষ, সর্বাধিক গৌরবময় মুহূর্ত।\nযেমন আমি তাদের জন্য আকুল হই, তেমনি তারাও আমার জন্য আকুল থাকে।"
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·তৃতীয় পর্ব"
  },
  Voice_96377_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৬ এ আনলক হবে"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "নিঃশব্দ হও, হবে কি?"
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·4"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "বিক্ষিপ্ত হও এবং ছায়ায় মিলিয়ে যাও!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "এসো, দূরত্ব বজায় রাখা যাক।"
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·এক"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "বিক্ষিপ্ত হও এবং ছায়ায় মিলিয়ে যাও!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "দক্ষতা: IV"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "আপনি আমার প্রতি এত সতর্ক কেন? আপনার ভয় পাওয়ার প্রয়োজন নেই, বরং উচিতও নয়; জীবিত মানুষকে ভক্ষণ করা আমার নান্দনিকতার বিরুদ্ধে।"
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "আলাপচারিতা: খাদ্য সম্পর্কে"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "যদি মৃত্যু-ই তোমার কাম্য হয়, তবে আমি তোমার সেই মনোবাঞ্ছা পূরণ করব।"
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "এক্সাল্ট"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "কী ভীষণ অমার্জিত।"
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·এক"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "সতর্ক থেকো।"
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "প্রতিরক্ষা·2"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "ওই ভদ্রমহিলার উচ্ছ্বাস সত্যিই স্পর্শকাতর, কিন্তু তার দেহে এক ধরনের অতিরিক্ত গাঁজনধরা, স্যাঁতসেঁতে গন্ধ লেগে আছে। বারবার অনুনয় করেও তিনি আমাকে স্বাদ নিতে বলছেন, তবু তা আমার রুচির সঙ্গে মোটেই মানায় না। কী বিরক্তিকর।"
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "গল্পগুজব: লেই প্রসঙ্গে"
  },
  Voice_96386_UnlockDesc = {
    Text = "\"জাগরণ\" \"Leigh\" অর্জনের পর আনলক হবে"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "তুমি কি জানো?\nপ্রতিটি জীবনের, ম্লান হয়ে যাওয়ার সময়, এক দীর্ঘস্থায়ী প্রতিধ্বনি থাকে।\nতার সুর আর স্বর ভিন্ন ভিন্ন, মৃত্যু আগমনের মুহূর্ত থেকে সামান্য সামান্য করে প্রসারিত হতে থাকে, যতক্ষণ না তা আকাশ ও মাটির মাঝে বিলীন হয়ে যায়—এক দীর্ঘশ্বাসমিশ্রিত ক্রন্দনের মতো।"
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·২"
  },
  Voice_96387_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৪ এ আনলক হবে"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "নিশ্চিন্ত থাকুন, গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়, আপনার জীবনের পূর্বনির্ধারিত অবসানদিন পর্যন্ত আমি আপনার পাশেই থাকব। সেই দিনে, পরম গাম্ভীর্যের সঙ্গে আমি আপনার দেহটিকে টুকরো টুকরো করে ভক্ষণ করব। আর আপনার আত্মা আমার ভেতরেই, চিরকাল, আশ্রয় নেবে।"
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার: V"
  },
  Voice_96388_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ১০ এ আনলক হবে"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "তুমি নিজেকে গন্ধ পেতে পারো না? আহ, কী দুঃখের কথা। তুমি হারাচ্ছ সবচেয়ে মধুর, সবচেয়ে পরম... ওহ, কী হলো? কেন সরে যাচ্ছ?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "সমসংস্থান হার·৪"
  },
  Voice_96389_UnlockDesc = {
    Text = "সমসংস্থান হার স্তর ৮ এ আনলক হবে"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "আমি আরও আসন্ন মৃত্যুর দৃশ্য দেখি। ওপারের দিকটা ক্রমেই আরও স্পষ্ট হয়ে উঠছে..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "উন্নতি অর্জন·তিন"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে, তোমার দেহ আমাকে সমর্পণ করো। আমি তোমাকে আস্বাদন করব সূক্ষ্ম যত্নে: প্রতিটি রক্তবিন্দু, প্রতিটি মাংসখণ্ড, প্রতিটি অস্থি পর্যন্ত।"
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "ভিন্ন উপাদান দাবি করে ভিন্ন প্রস্তুতি। অঙ্গপ্রত্যঙ্গগুলো, সেগুলোকে আগে মেরিনেট করতে হয়। পায়ের টেন্ডনগুলো ধীরে সেদ্ধ করাই শ্রেয়। চর্বিযুক্ত অংশগুলো গাঁজন আর বার্ধক্যের জন্য একেবারে উপযুক্ত, আর আরও সূক্ষ্ম টুকরোগুলো ভাজা, রোস্ট করা, কিংবা নৈপুণ্যে গড়া জেলিতে রূপান্তরিত করা যায়। এসব নির্বাচনই আসলে বিচক্ষণতার পরীক্ষা। কারণ উপাদানের স্বাভাবিক স্বাদকে সংরক্ষণ ও উজ্জ্বল না করলে, সেখানে কোনো সম্মান থাকে না।"
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·অন্তর্দৃষ্টি"
  },
  Voice_96392_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৭ এ আনলক হবে"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "এটা কিছুটা হিমশীতল হতে পারে।"
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "স্ট্রাইক·2"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "পদের যুগলবন্দিও সমান গুরুত্ব বহন করে。\nটক আর মিষ্টির, খসখসে আর নরমের, হালকা আর ঘন, সূক্ষ্ম আর রুক্ষের পাশাপাশি অবস্থান সৃষ্টি করে স্তরিত স্বাদ, আর এমন এক গঠনগত বৈপরীত্য, যা মুখে প্রবেশের মুহূর্তে, চিবানোর সময়, এবং পরস্বাদ উপভোগের ক্ষণে ভিন্ন ভিন্ন অনুভূতি জাগিয়ে তোলে。\nএটাই সেই অন্তহীন ও বিস্ময়কর আনন্দ, যা এক সঠিক ভোজ আমাদের উপহার দেয়।"
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·উত্থান"
  },
  Voice_96394_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ১১ এ আনলক হবে"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "তোমার উচ্ছ্বাসের জন্য অসীম কৃতজ্ঞতা। সমস্ত সম্মানই আমার।"
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "উন্নয়ন অর্জন·2"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "সত্যিকারের সুস্বাদু খাদ্যের জন্য অপেক্ষা করা সার্থক।"
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "তদন্ত স্থগিত"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "আমি কোনো বর্বর জন্তু নই, যে কাঁচা মাংসে হুড়োহুড়ি করে ঝাঁপিয়ে পড়ে। মৃত্যুর ভক্ষণ এক গম্ভীর ও সুশোভিত আচার। প্রতিটি উপাদানের স্বতন্ত্র স্বাদকে জানতে হয়, তার সঙ্গে মিলিত হয়ে সত্যিকার অর্থে তাকে বুঝতে হয়।"
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·চিন্তন"
  },
  Voice_96397_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ২ এ আনলক হবে"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "যেসব মৃত আত্মা শান্তি খুঁজে পেয়েছে, তারা সুন্দর এবং সুগন্ধময়। তাদের সৌন্দর্য মাংসে নয়—না মৃত্যুর আগে, না মৃত্যুর পরে—বরং তাদের আত্মায়। মৃত্যুকে ঘিরে সেই আত্মাদের আত্মজাগরণ, জীবনের প্রতি তাদের আকুলতা, আর স্মৃতিতে বেঁচে থাকার তাদের বাসনাই সেই সব সুস্বাদু পদ, যাদের স্বপ্ন আমি আজীবন দেখে এসেছি।"
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "গল্পগুজব: আমার পছন্দ"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "মানবদেহের স্বাভাবিক গন্ধের সঙ্গে তুলনীয় কোনো সুগন্ধি নেই। কেবল গন্ধের মাধ্যমে কাউকে জানা—এ এক অনির্বচনীয়, দেবতুল্য পরিতৃপ্তি।"
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "আত্মজাগরণ·গভীর চিন্তন"
  },
  Voice_96399_UnlockDesc = {
    Text = "আলোকপ্রাপ্তি স্তর ৩ এ আনলক হবে"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "আহ, কী অবিস্মরণীয় গন্ধ... তোমাকে আমার আশ্রয়ে স্বাগত জানাতে আর এক মুহূর্তও অপেক্ষা করতে পারছি না।"
  },
  Voice_96400_AwakerVoiceTitle = {
    Text = "জাগরণ"
  },
  Voice_96401_AwakerVoiceContent = {
    Text = "অনুগ্রহ করে, তোমার দেহ আমাকে সমর্পণ করো। আমি তোমাকে আস্বাদন করব সূক্ষ্ম যত্নে: প্রতিটি রক্তবিন্দু, প্রতিটি মাংসখণ্ড, প্রতিটি অস্থি পর্যন্ত।"
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "ওভার-এক্সাল্ট·2"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "আমি নির্মল বিশ্রাম উপহার দেব।"
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "দক্ষতা·2"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "নিঃশব্দ হও, হবে কি?"
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "আঘাতপ্রাপ্ত·2"
